# ─── DB helper ───
_DB_TUNED = False

def get_conn():
    conn = sqlite3.connect(DB_PATH, timeout=30)   # wait on locks instead of erroring
    try:
        global _DB_TUNED
        if not _DB_TUNED:
            conn.execute("PRAGMA journal_mode=WAL")      # concurrent read while writing (set once, persists)
            # perf indexes (2026-07-19): options_openbb had ZERO indexes (1.97M rows) so
            # _bb_quote/_plan_prem full-scanned ~0.9s each. Composite idx -> microseconds.
            # IF NOT EXISTS = instant no-op once built; re-creates if a rebuild drops them.
            for _ix in (
                "CREATE INDEX IF NOT EXISTS idx_oo_lookup ON options_openbb(ticker, strike, expiry_date, trade_date)",
                "CREATE INDEX IF NOT EXISTS idx_oc_lookup ON options_change(ticker, strike, expiry_date, trade_date_now)",
                # DATE-LEADING index (2026-08-28). idx_oo_lookup leads with `ticker`, so any query
                # filtering on trade_date alone cannot use it as a prefix and SCANs all 7.1M rows.
                # That was the real cause of the sluggish dashboard, not cache size -- a bigger
                # cache was measured 4-20% SLOWER, because you cannot cache your way out of
                # reading every row. Measured on the VM after adding this: latest-day count
                # 1,105ms -> 15ms, per-ticker day 13ms -> 1ms, GEX-style group-by 779ms -> 75ms.
                # Costs ~400 MB and 18s to build.
                "CREATE INDEX IF NOT EXISTS idx_oo_date ON options_openbb(trade_date, ticker)",
                "CREATE INDEX IF NOT EXISTS idx_oc_date ON options_change(trade_date_now, ticker)",
            ):
                try:
                    conn.execute(_ix)
                except Exception:
                    log.debug("perf index ensure failed", exc_info=True)
            _DB_TUNED = True
        conn.execute("PRAGMA synchronous=NORMAL")        # faster writes, still crash-safe under WAL
        conn.execute("PRAGMA temp_store=MEMORY")
        conn.execute("PRAGMA mmap_size=268435456")       # 256MB memory-mapped reads
    except Exception:
        log.debug("db pragma setup failed", exc_info=True)
    return conn


# ── yfinance TTL cache + DB helpers (streamline: dedupe network + ensure close) ──
import time as _time, threading as _threading
from contextlib import contextmanager as _contextmanager

_RAW_YF = yf.Ticker          # un-wrapped originals (call sites are renamed to the
_RAW_YF_DL = yf.download      # cached versions below; keep raw refs for the wrapper)
_YF_TTL = 60                  # seconds — matches dashboard @st.cache_data(ttl=60)
_yf_cache = {}
_yf_lock = _threading.Lock()


def _yf_get(key, producer):
    """Return cached value for key within TTL, else call producer() (network) once."""
    try:
        now = _time.time()
        with _yf_lock:
            hit = _yf_cache.get(key)
            if hit is not None and hit[0] > now:
                return hit[1]
    except TypeError:
        return producer()      # unhashable key — skip cache
    val = producer()
    with _yf_lock:
        _yf_cache[key] = (_time.time() + _YF_TTL, val)
    return val


class _CachedTicker:
    """Drop-in for yf.Ticker that caches network-bound calls for _YF_TTL seconds."""
    __slots__ = ("_sym", "_t")

    def __init__(self, sym):
        self._sym = str(sym).upper()
        self._t = _RAW_YF(self._sym)

    def history(self, *a, **k):
        df = _yf_get(("hist", self._sym, a, tuple(sorted(k.items()))),
                     lambda: self._t.history(*a, **k))
        return df.copy() if hasattr(df, "copy") else df   # guard cached frame from in-place mutation

    def option_chain(self, *a, **k):
        return _yf_get(("oc", self._sym, a, tuple(sorted(k.items()))),
                       lambda: self._t.option_chain(*a, **k))

    @property
    def options(self):
        return _yf_get(("opts", self._sym), lambda: self._t.options)

    @property
    def calendar(self):
        return _yf_get(("cal", self._sym), lambda: self._t.calendar)

    @property
    def info(self):
        return _yf_get(("info", self._sym), lambda: self._t.info)

    @property
    def fast_info(self):
        return _yf_get(("finfo", self._sym), lambda: self._t.fast_info)

    def __getattr__(self, name):
        # uncached fall-through for any other yf.Ticker attribute/method
        return getattr(object.__getattribute__(self, "_t"), name)


def _yf_ticker(sym):
    """Cached yf.Ticker factory — repeated lookups of the same symbol are deduped."""
    s = str(sym).upper()
    return _yf_get(("tk", s), lambda: _CachedTicker(s))


def _yf_download(*a, **k):
    """Cached yf.download."""
    df = _yf_get(("dl", a, tuple(sorted(k.items()))),
                 lambda: _RAW_YF_DL(*a, **k))
    return df.copy() if hasattr(df, "copy") else df


def _yf_warm(tickers, **kw):
    """Parallel-prefetch .history(**kw) for many tickers into the cache (best-effort).
    Turns a serial per-ticker loop into one concurrent burst; uncached misses only.
    Pass the SAME kwargs the loop's .history() call uses so keys match."""
    keyitems = tuple(sorted(kw.items()))
    now = _time.time()
    todo = {}
    for t in tickers:
        s = str(t).upper()
        key = ("hist", s, (), keyitems)
        with _yf_lock:
            hit = _yf_cache.get(key)
        if not (hit and hit[0] > now):
            todo[s] = key
    if not todo:
        return
    def _fetch(s):
        return s, _RAW_YF(s).history(**kw)
    for fut in [_EXECUTOR.submit(_fetch, s) for s in todo]:
        try:
            s, df = fut.result(timeout=25)
            with _yf_lock:
                _yf_cache[todo[s]] = (_time.time() + _YF_TTL, df)
        except Exception:
            log.debug("warm history failed", exc_info=True)


def _yf_warm_info(tickers):
    """Parallel-prefetch .info for many tickers into the cache (best-effort)."""
    now = _time.time()
    todo = {}
    for t in tickers:
        s = str(t).upper()
        key = ("info", s)
        with _yf_lock:
            hit = _yf_cache.get(key)
        if not (hit and hit[0] > now):
            todo[s] = key
    if not todo:
        return
    def _fetch(s):
        return s, _RAW_YF(s).info
    for fut in [_EXECUTOR.submit(_fetch, s) for s in todo]:
        try:
            s, info = fut.result(timeout=25)
            with _yf_lock:
                _yf_cache[todo[s]] = (_time.time() + _YF_TTL, info)
        except Exception:
            log.debug("warm info failed", exc_info=True)


@_contextmanager
def db():
    """Context manager that always closes the SQLite connection."""
    conn = get_conn()
    try:
        yield conn
    finally:
        conn.close()


_SPOT_LIVE_CACHE: dict = {}


def _spot_price(sym):
    """LIVE last price (fast_info, 60s cache); after hours this equals the close.
    Falls back to daily-history close. 0.0 on failure. (Live-everywhere 2026-07-17.)"""
    import time as _t
    k = str(sym).upper()
    v = _SPOT_LIVE_CACHE.get(k)
    if v and _t.time() - v[1] < 60:
        return v[0]
    px = 0.0
    try:
        fi = _yf_ticker(sym).fast_info
        px = float(fi.get("lastPrice") or fi.get("regularMarketPrice") or 0)
    except Exception:
        px = 0.0
    if px <= 0:
        try:
            h = _yf_ticker(sym).history(period="2d")
            px = float(h["Close"].iloc[-1]) if len(h) else 0.0
        except Exception:
            px = 0.0
    if px > 0:
        _SPOT_LIVE_CACHE[k] = (px, _t.time())
    return px


def _et_now():
    """Current time in US/Eastern (falls back to a UTC-5 approximation)."""
    try:
        from zoneinfo import ZoneInfo
        return datetime.now(ZoneInfo("America/New_York"))
    except Exception:
        return datetime.now(timezone.utc).replace(tzinfo=None) - timedelta(hours=5)


def _market_is_open():
    """True during the US equity regular session (Mon-Fri 09:30-16:00 ET). Weekday+time
    only (holiday-agnostic) — enough to switch a LIVE vs EOD price display."""
    now = _et_now()
    if now.weekday() >= 5:
        return False
    mins = now.hour * 60 + now.minute
    return 570 <= mins < 960          # 09:30 .. 16:00 ET


def _intraday_last(tk, max_age_min=3.0):
    """Latest 1m bar (close, age_min) for tk from US_intraday.db, or None. The bars are
    yfinance data already captured each minute for positions + leaders, so reading them is
    a free, batched cache — no redundant per-ticker live call. Only returns a value that is
    FRESH (bar age <= max_age_min); ts in the DB is ET market time."""
    try:
        import os as _os, sqlite3 as _sql
        _p = _os.path.join(DATA_DIR, "US_intraday.db")
        if not _os.path.exists(_p):
            return None
        _c = _sql.connect(_p, timeout=2)
        row = _c.execute(
            "SELECT ts, close FROM intraday_bars WHERE ticker=? AND "
            "trade_date=(SELECT MAX(trade_date) FROM intraday_bars WHERE ticker=?) "
            "ORDER BY ts DESC LIMIT 1", (tk.upper(), tk.upper())).fetchone()
        _c.close()
        if not row or not row[1]:
            return None
        px = float(row[1])
        if px <= 0:
            return None
        try:
            bar_ts = datetime.strptime(str(row[0])[:16], "%Y-%m-%d %H:%M")
            age = (_et_now().replace(tzinfo=None) - bar_ts).total_seconds() / 60.0
        except Exception:
            age = 1e9
        return (px, age) if age <= max_age_min else None
    except Exception:
        return None


def _cur_price(tk, db_close=0.0):
    """The price to DISPLAY for a ticker, resolving live-vs-EOD correctly:
      market open  -> intraday-DB last bar (covered tickers, fresh) else live fast_info,
                      labelled 'LIVE HH:MM ET'
      market closed-> the EOD close, labelled 'EOD'
    Returns (price, is_live, asof_label). Never raises."""
    dbc = 0.0
    try:
        dbc = float(db_close or 0)
    except Exception:
        dbc = 0.0
    if _market_is_open():
        _stamp = f"LIVE {_et_now().strftime('%H:%M ET')}"
        _id = _intraday_last(tk)                     # covered ticker, fresh bar -> free & fast
        if _id and _id[0] > 0:
            return (_id[0], True, _stamp)
        px = _last_price(tk) or 0.0                  # else pull the live tick from yahoo
        if px > 0:
            return (px, True, _stamp)
    if dbc > 0:
        return (dbc, False, "EOD")
    return (_last_price(tk) or 0.0, False, "EOD")


def _iv_rank(sym):
    """(iv_rank_pct, label, advice) from 1y 20d HV range; None if unavailable."""
    try:
        h = _yf_ticker(sym).history(period="1y")
        if len(h) < 60:
            return None
        lr = np.log(h["Close"] / h["Close"].shift(1)).dropna()
        hv = (lr.rolling(20).std() * np.sqrt(252)).dropna()
        if hv.empty:
            return None
        cur, lo, hi = float(hv.iloc[-1]), float(hv.min()), float(hv.max())
        ivr = (cur - lo) / (hi - lo + 1e-9) * 100
        label = "HIGH" if ivr > 75 else ("LOW" if ivr < 25 else "MID")
        advice = "sell premium" if ivr > 75 else ("buy premium" if ivr < 25 else "standard approach")
        return ivr, label, advice
    except Exception:
        return None


def _earnings_days(sym):
    """Calendar days until next earnings (int) or None."""
    try:
        cal = _yf_ticker(sym).calendar
        ed = None
        if isinstance(cal, dict):
            v = cal.get("Earnings Date")
            if v:
                ed = pd.to_datetime(v[0] if isinstance(v, list) else v)
        elif hasattr(cal, "loc") and "Earnings Date" in getattr(cal, "index", []):
            ed = pd.to_datetime(cal.loc["Earnings Date"].iloc[0])
        if ed is not None:
            return (ed.date() - datetime.now().date()).days
    except Exception:
        log.debug("suppressed exception", exc_info=True)
    return None


def _safe_float(v, d=0.0):
    try:
        return float(v)
    except Exception:
        return d


def _safe_int(v, d=0):
    try:
        return int(v)
    except Exception:
        return d


def _fetch_trade(trade_id):
    conn = get_conn()
    try:
        df = pd.read_sql("SELECT * FROM trades WHERE trade_id = ? LIMIT 1", conn, params=(int(trade_id),))
    except Exception:
        df = pd.DataFrame()
    conn.close()
    if df.empty:
        return None
    return df.iloc[0].to_dict()


def _estimate_option_mark(ticker, opt_type, strike, expiry, fallback=0.0):
    """Best-effort option price estimate for exit/pair actions."""
    try:
        tk = _yf_ticker(str(ticker).upper())
        chain = tk.option_chain(str(expiry))
        oc = chain.calls if str(opt_type).lower() == "call" else chain.puts
        if oc.empty:
            return float(fallback)

        target = float(strike)
        m = oc[oc["strike"] == target]
        if m.empty:
            oc2 = oc.copy()
            oc2["_d"] = (oc2["strike"] - target).abs()
            m = oc2.nsmallest(1, "_d")
        row = m.iloc[0]

        bid = _safe_float(row.get("bid", 0), 0)
        ask = _safe_float(row.get("ask", 0), 0)
        last = _safe_float(row.get("lastPrice", 0), 0)
        if bid > 0 and ask > 0:
            return (bid + ask) / 2.0
        if last > 0:
            return last
    except Exception:
        log.debug("suppressed exception", exc_info=True)
    return float(fallback)


def _option_chain_snapshot(ticker, expiry, opt_type):
    """Return nearest row and bid/ask/last/mark for selected chain leg."""
    tk = _yf_ticker(str(ticker).upper())
    chain = tk.option_chain(str(expiry))
    oc = chain.calls if str(opt_type).lower() == "call" else chain.puts
    if oc.empty:
        return None
    return oc


def _option_price_by_mode(ticker, opt_type, strike, expiry, mode="mid", fallback=0.0):
    """Price option using bid/ask/mid/last with nearest-strike fallback."""
    try:
        oc = _option_chain_snapshot(ticker, expiry, opt_type)
        if oc is None or oc.empty:
            return float(fallback)
        target = float(strike)
        m = oc[oc["strike"] == target]
        if m.empty:
            oc2 = oc.copy()
            oc2["_d"] = (oc2["strike"] - target).abs()
            m = oc2.nsmallest(1, "_d")
        row = m.iloc[0]
        bid = _safe_float(row.get("bid", 0), 0)
        ask = _safe_float(row.get("ask", 0), 0)
        last = _safe_float(row.get("lastPrice", 0), 0)
        mode = str(mode or "mid").lower()
        if mode == "bid" and bid > 0:
            return bid
        if mode == "ask" and ask > 0:
            return ask
        if bid > 0 and ask > 0:
            return (bid + ask) / 2.0
        if last > 0:
            return last
    except Exception:
        log.debug("suppressed exception", exc_info=True)
    return float(fallback)


def _get_option_expiries(ticker):
    """Return available option expiry dates from yfinance."""
    try:
        exps = list(_yf_ticker(str(ticker).upper()).options or [])
        # Ensure unique and sorted date strings
        return sorted(set([str(x) for x in exps if str(x).strip()]))
    except Exception:
        return []


def _get_option_strikes(ticker, expiry, opt_type):
    """Return sorted strikes for a ticker+expiry+type from option chain."""
    try:
        oc = _option_chain_snapshot(ticker, expiry, opt_type)
        if oc is None or oc.empty:
            return []
        strikes = pd.to_numeric(oc["strike"], errors="coerce").dropna().tolist()
        return sorted(set([float(s) for s in strikes]))
    except Exception:
        return []


def _nearest_strike_list(strikes, spot, radius=15):
    """Pick a centered slice of strikes around spot for mobile UX."""
    if not strikes:
        return []
    if spot is None or spot <= 0:
        return strikes[: min(len(strikes), radius)]
    arr = np.array(strikes, dtype=float)
    idx = int(np.argmin(np.abs(arr - float(spot))))
    half = max(1, radius // 2)
    lo = max(0, idx - half)
    hi = min(len(strikes), lo + radius)
    lo = max(0, hi - radius)
    return [float(x) for x in arr[lo:hi].tolist()]


def _option_leg_payoff(side, opt_type, strike, premium, qty, spots):
    """Return payoff vector for one option leg at expiry."""
    s = np.array(spots, dtype=float)
    k = float(strike)
    p = float(max(0.0, premium))
    q = float(max(1, qty))
    is_call = str(opt_type).lower() == "call"
    intrinsic = np.maximum(s - k, 0.0) if is_call else np.maximum(k - s, 0.0)
    if str(side).lower() == "sell":
        return (p - intrinsic) * q * 100.0
    return (intrinsic - p) * q * 100.0


def _breakeven_points(spots, pay):
    out = []
    for i in range(1, len(spots)):
        y1, y2 = pay[i - 1], pay[i]
        if y1 == 0:
            out.append(float(spots[i - 1]))
        elif y1 * y2 < 0:
            # Linear interpolation between points around zero crossing.
            x1, x2 = float(spots[i - 1]), float(spots[i])
            x0 = x1 - y1 * (x2 - x1) / (y2 - y1)
            out.append(float(x0))
    # de-dupe near-equal values
    dedup = []
    for x in out:
        if not dedup or abs(dedup[-1] - x) > 0.25:
            dedup.append(x)
    return dedup


def _render_payoff_chart(spot_grid, payoff_grid, title):
    """Render payoff chart to PNG bytes; returns None on failure."""
    try:
        import matplotlib.pyplot as plt

        fig, ax = plt.subplots(figsize=(7.0, 4.0), dpi=120)
        ax.plot(spot_grid, payoff_grid, linewidth=2.2)
        ax.axhline(0, color="#777", linewidth=1.0)
        ax.set_title(title)
        ax.set_xlabel("Underlying Price @ Expiry")
        ax.set_ylabel("P&L ($)")
        ax.grid(alpha=0.25)
        buf = BytesIO()
        fig.tight_layout()
        fig.savefig(buf, format="png")
        plt.close(fig)
        buf.seek(0)
        return buf
    except Exception:
        return None


def _update_trade_field(trade_id, field, value):
    conn = get_conn()
    try:
        conn.execute(
            f"UPDATE trades SET {field} = ?, updated_at = ? WHERE trade_id = ?",
            (value, datetime.now().isoformat(), int(trade_id)),
        )
        conn.commit()
        ok = True
    except Exception:
        ok = False
    conn.close()
    return ok


def _close_trade_now(trade_id, reason="telegram_quick_exit"):
    tr = _fetch_trade(trade_id)
    if not tr:
        return False, "Trade not found"
    if str(tr.get("status", "")).upper() != "OPEN":
        return False, "Trade is not OPEN"

    ticker = tr.get("ticker", "")
    opt_type = tr.get("option_type", "call")
    strike = _safe_float(tr.get("strike", 0), 0)
    expiry = tr.get("expiry", "")
    entry = _safe_float(tr.get("entry_price", 0), 0)
    qty = _safe_int(tr.get("quantity", 1), 1)

    exit_px = _estimate_option_mark(ticker, opt_type, strike, expiry, fallback=entry)
    pnl = (exit_px - entry) * qty * 100
    pnl_pct = ((exit_px - entry) / entry * 100) if entry > 0 else 0

    entry_date = str(tr.get("entry_date", ""))
    days_held = 0
    try:
        ed = datetime.strptime(entry_date, "%Y-%m-%d").date()
        days_held = (datetime.now().date() - ed).days
    except Exception:
        days_held = 0

    conn = get_conn()
    try:
        conn.execute(
            """
            UPDATE trades
            SET status='CLOSED',
                exit_date=?,
                exit_time=?,
                exit_price=?,
                exit_reason=?,
                pnl=?,
                pnl_pct=?,
                days_held=?,
                updated_at=?
            WHERE trade_id=?
            """,
            (
                datetime.now().strftime("%Y-%m-%d"),
                datetime.now().strftime("%H:%M:%S"),
                float(exit_px),
                reason,
                float(round(pnl, 2)),
                float(round(pnl_pct, 2)),
                int(days_held),
                datetime.now().isoformat(),
                int(trade_id),
            ),
        )
        conn.commit()
        ok = True
    except Exception:
        ok = False
    conn.close()

    if not ok:
        return False, "Failed to close trade"
    return True, f"Closed at ${exit_px:.2f} · P&L ${pnl:+,.2f} ({pnl_pct:+.2f}%)"


def _close_expired_positions() -> list:
    """Auto-close any OPEN trade whose expiry date has already passed (expired worthless).
    Called at startup and before every positions fetch. Returns list of (trade_id, ticker)."""
    today = datetime.now().strftime("%Y-%m-%d")
    conn  = get_conn()
    closed = []
    try:
        df = pd.read_sql(
            "SELECT trade_id, ticker, expiry, entry_price, quantity, entry_date "
            "FROM trades WHERE status='OPEN' AND UPPER(option_type)<>'STOCK' AND expiry IS NOT NULL AND expiry != '' AND expiry < ?",
            conn, params=(today,))
        for _, tr in df.iterrows():
            tid   = int(tr["trade_id"])
            tk    = str(tr["ticker"])
            expd  = str(tr["expiry"])[:10]
            entry = _safe_float(tr["entry_price"], 0)
            qty   = _safe_int(tr["quantity"], 0)
            cost  = entry * abs(qty) * 100

            # Settle at INTRINSIC with a SIGNED quantity.
            # Two bugs lived here (fixed 2026-07-22, both found by auditing CLOSED rows):
            #  1. `pnl = -(entry * abs(qty) * 100)` booked every expiry as a full loss. For a
            #     SHORT leg, expiring worthless is a full PROFIT -- that is the entire point of
            #     selling premium. It mis-booked AMZN 260C short as -$960 when it made +$960,
            #     and would have done the same to the open TSLA 365P / AMD 640C shorts.
            #  2. It assumed "worthless" regardless of moneyness, so an ITM expiry was wrong
            #     too. Settle off the real close at expiry, the same way _settle_recs does.
            strike = _safe_float(tr.get("strike", 0), 0)
            is_call = str(tr.get("option_type", "")).upper().startswith("C")
            intrinsic, settled_on = 0.0, None
            try:
                _px = conn.execute(
                    "SELECT close FROM stock_history WHERE ticker=? AND trade_date<=? "
                    "ORDER BY trade_date DESC LIMIT 1", (tk.upper(), expd)).fetchone()
                if _px and _px[0] and strike > 0:
                    S = float(_px[0])
                    intrinsic = max(0.0, S - strike) if is_call else max(0.0, strike - S)
                    settled_on = S
            except Exception:
                log.warning(f"expiry settle price lookup failed for {tk} {tid}", exc_info=True)

            pnl = (intrinsic - entry) * qty * 100          # qty carries the sign
            pnl_pct = (pnl / cost * 100) if cost > 0 else 0.0
            reason = ("Expired worthless" if intrinsic <= 0 else
                      f"Expired ITM (settled ${intrinsic:.2f}"
                      + (f" @ ${settled_on:.2f})" if settled_on else ")"))
            days_held = 0
            try:
                ed = datetime.strptime(str(tr.get("entry_date", ""))[:10], "%Y-%m-%d").date()
                ex = datetime.strptime(expd, "%Y-%m-%d").date()
                days_held = (ex - ed).days
            except Exception:
                log.debug("suppressed exception", exc_info=True)
            conn.execute("""
                UPDATE trades
                SET status='CLOSED',
                    exit_date=?,
                    exit_time='16:00:00',
                    exit_price=?,
                    exit_reason=?,
                    pnl=?,
                    pnl_pct=?,
                    days_held=?,
                    updated_at=?
                WHERE trade_id=?
            """, (expd, float(round(intrinsic, 2)), reason,
                  float(round(pnl, 2)), float(round(pnl_pct, 2)),
                  days_held, datetime.now().strftime("%Y-%m-%d %H:%M:%S"), tid))
            conn.commit()
            closed.append((tid, tk))
            log.info(f"Auto-closed expired position: {tk} trade_id={tid} expiry={expd}")
    except Exception as e:
        log.warning(f"_close_expired_positions error: {e}")
    finally:
        conn.close()
    return closed


def _insert_paired_trade(parent_trade_id, mode="buy"):
    """Create paired leg: buy add-on or sell credit leg (short option)."""
    tr = _fetch_trade(parent_trade_id)
    if not tr:
        return False, "Parent trade not found"
    if str(tr.get("status", "")).upper() != "OPEN":
        return False, "Parent trade is not OPEN"

    ticker = str(tr.get("ticker", "")).upper()
    opt_type = str(tr.get("option_type", "CALL")).upper()
    strike = _safe_float(tr.get("strike", 0), 0)
    expiry = str(tr.get("expiry", ""))
    base_qty = max(1, abs(_safe_int(tr.get("quantity", 1), 1)))
    acct = tr.get("account_type", "Taxable")

    if mode == "sell":
        # Selling-options leg: short option at a safer OTM strike.
        new_qty = -base_qty
        if opt_type == "CALL":
            new_strike = strike + 5
        else:
            new_strike = max(0.5, strike - 5)
        strategy = "paired_sell_credit"
        note = f"Paired SELL leg for trade #{parent_trade_id}"
    else:
        new_qty = base_qty
        new_strike = strike
        strategy = "paired_buy_add"
        note = f"Paired BUY add-on for trade #{parent_trade_id}"

    entry_px = _estimate_option_mark(ticker, opt_type, new_strike, expiry, fallback=_safe_float(tr.get("entry_price", 1), 1))
    now = datetime.now()

    conn = get_conn()
    try:
        nxt = pd.read_sql("SELECT COALESCE(MAX(trade_id), 0) AS m FROM trades", conn).iloc[0]["m"]
        new_id = int(nxt) + 1
        conn.execute(
            """
            INSERT INTO trades (
                trade_id, ticker, strategy, entry_date, entry_time,
                option_type, strike, expiry, entry_price, quantity,
                entry_cost, signal_source, status, notes,
                created_at, updated_at, account_type
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                new_id,
                ticker,
                strategy,
                now.strftime("%Y-%m-%d"),
                now.strftime("%H:%M:%S"),
                opt_type,
                float(new_strike),
                expiry,
                float(entry_px),
                int(new_qty),
                float(abs(new_qty) * entry_px * 100),
                "telegram",
                "OPEN",
                note,
                now.isoformat(),
                now.isoformat(),
                acct,
            ),
        )
        conn.commit()
        ok = True
    except Exception as e:
        ok = False
        msg = str(e)
    finally:
        conn.close()

    if not ok:
        return False, f"Failed to create paired leg: {msg}"
    side = "SELL (credit)" if mode == "sell" else "BUY"
    return True, f"Created paired {side} trade #{new_id}: {ticker} {opt_type} ${new_strike:.0f} x {new_qty} @ ${entry_px:.2f}"


def _insert_new_trade(
    ticker,
    opt_type,
    strike,
    expiry,
    quantity,
    strategy="telegram_manual_add",
    entry_price=None,
    entry_date=None,
    notes=None,
    account_type="Taxable",
    mult=100,
):
    """Insert a brand new OPEN trade from Telegram Add Position flow.
    mult=1 for STOCK legs (shares — no ×100 contract multiplier in entry_cost)."""
    tk = str(ticker).upper().strip()
    ot = str(opt_type).upper().strip()
    st = float(strike)
    qty = int(quantity)
    exp = str(expiry)
    now = datetime.now()

    if entry_price is None:
        entry_px = _estimate_option_mark(tk, ot, st, exp, fallback=1.00)
    else:
        entry_px = float(entry_price)

    if entry_date:
        try:
            ed = datetime.strptime(str(entry_date), "%Y-%m-%d")
        except Exception:
            ed = now
    else:
        ed = now

    conn = get_conn()
    try:
        nxt = pd.read_sql("SELECT COALESCE(MAX(trade_id), 0) AS m FROM trades", conn).iloc[0]["m"]
        new_id = int(nxt) + 1
        conn.execute(
            """
            INSERT INTO trades (
                trade_id, ticker, strategy, entry_date, entry_time,
                option_type, strike, expiry, entry_price, quantity,
                entry_cost, signal_source, status, notes,
                created_at, updated_at, account_type
            )
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                new_id,
                tk,
                strategy,
                ed.strftime("%Y-%m-%d"),
                ed.strftime("%H:%M:%S"),
                ot,
                st,
                exp,
                float(entry_px),
                qty,
                float(abs(qty) * entry_px * mult),
                "telegram",
                "OPEN",
                notes or "Added from Telegram Positions",
                now.isoformat(),
                now.isoformat(),
                account_type,
            ),
        )
        conn.commit()
        ok = True
    except Exception as e:
        ok = False
        msg = str(e)
    finally:
        conn.close()

    if not ok:
        return False, None, f"Failed to add position: {msg}"
    return True, new_id, f"Added trade #{new_id}: {tk} {ot} ${st:.0f} x {qty} @ ${entry_px:.2f} exp {exp}"

# ═══════════════════════════════════════════════════════════
#  DATABASE MIGRATION - Add group_id if not exists
# ═══════════════════════════════════════════════════════════
def _ensure_group_id_column():
    """Add group_id column to trades table if it doesn't exist."""
    conn = get_conn()
    try:
        cursor = conn.cursor()
        cursor.execute("PRAGMA table_info(trades)")
        cols = [row[1] for row in cursor.fetchall()]
        if "group_id" not in cols:
            log.info("Adding group_id column to trades table")
            cursor.execute("ALTER TABLE trades ADD COLUMN group_id INTEGER DEFAULT NULL")
            conn.commit()
            log.info("✅ group_id column added successfully")
    except Exception as e:
        log.error(f"Failed to add group_id column: {e}")
    finally:
        conn.close()

# Convert MM-DD-YYYY to sortable YYYYMMDD for SQLite ORDER/MAX
_DT = "{c}"
def _max_date_sql(col, table, where=""):
    """Return SQL subquery for chronological MAX of a MM-DD-YYYY column."""
    expr = _DT.format(c=col)
    w = f" WHERE {where}" if where else ""
    return f"(SELECT {col} FROM {table}{w} ORDER BY {expr} DESC LIMIT 1)"


# ═══════════════════════════════════════════════════════════
#  POSITION GROUPS - Manage multi-leg positions
# ═══════════════════════════════════════════════════════════
def _create_group_from_trades(trade_ids, group_name=None):
    """Link multiple trades into a position group."""
    if not trade_ids:
        return False, "No trade IDs provided"
    
    conn = get_conn()
    try:
        # Get next group_id
        result = pd.read_sql("SELECT COALESCE(MAX(group_id), 0) AS max_gid FROM trades WHERE group_id IS NOT NULL", conn)
        new_group_id = int(result.iloc[0]["max_gid"]) + 1
        
        # Update all trades with the new group_id
        placeholders = ",".join("?" * len(trade_ids))
        conn.execute(f"UPDATE trades SET group_id = ? WHERE trade_id IN ({placeholders})", 
                    [new_group_id] + list(trade_ids))
        conn.commit()
        ok = True
        msg = f"Created group #{new_group_id} with {len(trade_ids)} positions"
    except Exception as e:
        ok = False
        msg = f"Failed to create group: {e}"
    finally:
        conn.close()
    
    return ok, msg


def _ungroup_trade(trade_id):
    """Remove a trade from its group."""
    conn = get_conn()
    try:
        conn.execute("UPDATE trades SET group_id = NULL WHERE trade_id = ?", (int(trade_id),))
        conn.commit()
        ok, msg = True, f"Removed trade #{trade_id} from group"
    except Exception as e:
        ok, msg = False, f"Failed to ungroup: {e}"
    finally:
        conn.close()
    return ok, msg


def _calculate_group_pnl(group_id):
    """Calculate total P&L and risk metrics for a position group."""
    conn = get_conn()
    try:
        trades_df = pd.read_sql("SELECT * FROM trades WHERE group_id = ? AND status = 'OPEN'", 
                               conn, params=(int(group_id),))
    except Exception:
        trades_df = pd.DataFrame()
    finally:
        conn.close()
    
    if trades_df.empty:
        return {
            "total_cost": 0,
            "current_value": 0,
            "unrealized_pnl": 0,
            "max_profit": 0,
            "max_loss": 0,
            "breakevens": [],
            "num_legs": 0
        }
    
    # Build payoff chart for the group
    ticker = trades_df.iloc[0]["ticker"]
    spot = 100.0
    try:
        h = _yf_ticker(ticker).history(period="5d")
        if len(h) >= 1:
            spot = float(h["Close"].iloc[-1])
    except Exception:
        log.debug("suppressed exception", exc_info=True)
    
    spot_range = np.linspace(spot * 0.5, spot * 1.5, 101)
    total_payoff = np.zeros_like(spot_range)
    total_cost = 0
    current_value = 0
    
    for _, trade in trades_df.iterrows():
        qty = int(trade["quantity"])
        side = "buy" if qty > 0 else "sell"
        opt_type = str(trade["option_type"]).lower()
        strike = float(trade["strike"])
        entry_price = float(trade["entry_price"])
        expiry = trade["expiry"]
        
        # Calculate payoff for this leg
        leg_payoff = _option_leg_payoff(side, opt_type, strike, entry_price, abs(qty), spot_range)
        total_payoff += leg_payoff
        
        total_cost += float(abs(qty) * entry_price * 100)
        
        # Get current market price
        try:
            current_px = _estimate_option_mark(ticker, opt_type, strike, expiry, fallback=entry_price)
            current_value += float(abs(qty) * current_px * 100) * (1 if qty > 0 else -1)
        except Exception:
            current_value += float(abs(qty) * entry_price * 100) * (1 if qty > 0 else -1)
    
    max_profit = float(np.max(total_payoff))
    max_loss = float(np.min(total_payoff))
    breakevens = _breakeven_points(spot_range, total_payoff)
    unrealized_pnl = current_value - (total_cost if len([t for t in trades_df["quantity"] if t > 0]) > len([t for t in trades_df["quantity"] if t < 0]) else -total_cost)
    
    return {
        "total_cost": total_cost,
        "current_value": current_value,
        "unrealized_pnl": unrealized_pnl,
        "max_profit": max_profit,
        "max_loss": max_loss,
        "breakevens": breakevens,
        "num_legs": len(trades_df),
        "payoff_data": (spot_range, total_payoff)
    }

# ─── After-hours price helper ───────────────────────────────
def _get_spot_with_ah(ticker: str) -> dict:
    """Return regular close + after/pre-market price for a ticker.
    Keys: spot_reg, spot_ext, ext_src, ext_chg_pct, is_extended
    spot_ext == spot_reg when no extended-hours data is available.
    """
    result = {"spot_reg": 0.0, "spot_ext": 0.0, "ext_src": "EOD", "ext_chg_pct": 0.0, "is_extended": False}
    try:
        tkr = _yf_ticker(ticker)
        fi = tkr.fast_info
        # fast_info exposes snake_case ATTRIBUTES and carries NO pre/post-market fields --
        # those live on .info. The old code called fi.get("regularMarketPrice") /
        # fi.get("postMarketPrice") / fi.get("preMarketPrice"), none of which are fast_info
        # keys, so post/pre were ALWAYS 0 and is_extended ALWAYS False: after-hours support
        # never worked (verified 2026-07-22 16:24 ET -- TSLA printed 374.01 while the real
        # post-market was 361.39, a -3.4% earnings move that never reached the screen).
        reg = 0.0
        for _k in ("last_price", "previous_close"):
            try:
                reg = float(getattr(fi, _k, 0) or 0)
            except Exception:
                reg = 0.0
            if reg > 0:
                break
        # .info is slow, so only pay for it OUTSIDE regular trading hours -- during RTH
        # last_price already IS the live price. The post-market print persists on yfinance
        # well past the official 20:00 close (verified 2026-07-22 22:52 ET: TSLA still 358.80
        # after an earnings drop), so we keep showing that LAST post-market print all evening
        # rather than reverting to the stale 4pm close -- an earnings move that lands at 4:05pm
        # must stay visible at 10pm. Window: weekdays, anytime except 09:30-16:00 RTH.
        post = pre = 0.0
        _ny = _et_now()
        _tm = _ny.hour * 60 + _ny.minute
        if _ny.weekday() < 5 and not (9 * 60 + 30 <= _tm < 16 * 60):
            try:
                _inf = tkr.info or {}
                post = float(_inf.get("postMarketPrice") or 0)
                pre = float(_inf.get("preMarketPrice") or 0)
            except Exception:
                log.debug("extended-hours .info fetch failed", exc_info=True)
        if reg <= 0:
            h = tkr.history(period="5d")
            reg = float(h["Close"].iloc[-1]) if len(h) >= 1 else 0.0
        result["spot_reg"] = reg
        if post > 0:
            result["spot_ext"] = post
            result["ext_src"] = "Post-mkt"
            result["is_extended"] = True
        elif pre > 0:
            result["spot_ext"] = pre
            result["ext_src"] = "Pre-mkt"
            result["is_extended"] = True
        else:
            result["spot_ext"] = reg
            result["ext_src"] = "EOD close"
        if reg > 0:
            result["ext_chg_pct"] = (result["spot_ext"] - reg) / reg * 100
    except Exception:
        try:
            h = _yf_ticker(ticker).history(period="5d", prepost=True)
            if len(h) >= 1:
                result["spot_reg"] = float(h["Close"].iloc[-1])
                result["spot_ext"] = result["spot_reg"]
        except Exception:
            log.debug("suppressed exception", exc_info=True)
    return result


# ── Volatility gauge: VIX (broad market) vs VXN (Nasdaq-100 / tech) ──────────
# For Nasdaq-100 / mega-tech names, VXN is the correct fear gauge (it usually runs
# well above VIX). User ask 2026-07-20: use VXN for Nasdaq stocks wherever we show VIX.
_NASDAQ_VOL_SET = {
    "AAPL","MSFT","NVDA","GOOGL","GOOG","AMZN","META","TSLA","AVGO","AMD","NFLX","ADBE",
    "COST","PEP","CSCO","INTC","QCOM","TXN","AMAT","MU","LRCX","KLAC","ASML","ARM","PANW",
    "CRWD","SNPS","CDNS","MRVL","NXPI","ADI","MCHP","ON","SMCI","PLTR","MDB","DDOG","SNOW",
    "ZS","NOW","INTU","ORCL","MSTR","COIN","ABNB","PYPL","SHOP","TTD","APP","ARM",
    "QQQ","SOXX","SMH","TQQQ","SOXL","XLK","IXIC",
}
_VOL_CACHE = {"ts": 0.0, "vix": 0.0, "vxn": 0.0}

def _get_vol_indices():
    """{'vix':x, 'vxn':y} spot levels, cached 5 min (fetches ^VIX + ^VXN once)."""
    import time as _t
    now = _t.time()
    if now - _VOL_CACHE["ts"] < 300 and _VOL_CACHE["vix"] > 0:
        return {"vix": _VOL_CACHE["vix"], "vxn": _VOL_CACHE["vxn"]}
    for key, sym in (("vix", "^VIX"), ("vxn", "^VXN")):
        try:
            h = _yf_ticker(sym).history(period="3d")
            if len(h):
                _VOL_CACHE[key] = float(h["Close"].iloc[-1])
        except Exception:
            log.debug(f"{sym} fetch failed", exc_info=True)
    _VOL_CACHE["ts"] = now
    return {"vix": _VOL_CACHE["vix"], "vxn": _VOL_CACHE["vxn"]}

def _is_nasdaq_vol(ticker):
    """True if VXN (Nasdaq-100 vol) is the better fear gauge for this ticker."""
    return str(ticker or "").upper() in _NASDAQ_VOL_SET

def _vol_for(ticker):
    """(label, value): VXN for Nasdaq-100 / tech names, else VIX. Falls back to VIX."""
    vi = _get_vol_indices()
    if _is_nasdaq_vol(ticker) and vi.get("vxn", 0) > 0:
        return ("VXN", vi["vxn"])
    return ("VIX", vi.get("vix", 0) or 0.0)


# ═══════════════════════════════════════════════════════════════════════════
# MONEY-FLOW / ROTATION ENGINE  (where capital is rotating — sectors, geos,
# commodities, bonds). Free-data proxy for institutional flow, blending three
# standard signals: (1) Relative Strength vs SPY + RS-Momentum → de Kempenaer
# RRG quadrant (Leading/Weakening/Lagging/Improving); (2) Chaikin Money Flow
# (accumulation vs distribution); (3) dollar-volume participation. No paid
# fund-flow feed needed — all from OHLCV. (Built 2026-07-20 per user request.)
# ═══════════════════════════════════════════════════════════════════════════
_MONEYFLOW_UNIVERSE = {
    "US Sectors": [("XLK", "Tech"), ("XLF", "Financials"), ("XLE", "Energy"),
                   ("XLV", "Health"), ("XLI", "Industrials"), ("XLY", "Discretionary"),
                   ("XLP", "Staples"), ("XLU", "Utilities"), ("XLB", "Materials"),
                   ("XLRE", "RealEstate"), ("XLC", "CommSvcs")],
    # STYLE AND SIZE ARE TWO AXES, and this row used to mix them: IWM sat among Growth,
    # Value and Momentum as though "small" were a style. Splitting them is what makes the
    # size question answerable at all -- "is money going down the cap scale?" cannot be read
    # off a list where exactly one size appears (ID 388).
    "US Style": [("QQQ", "Nasdaq100"), ("IWF", "Growth"), ("IWD", "Value"),
                 ("MTUM", "Momentum")],
    # IWM MOVES here rather than being duplicated. Listing it in both blocks would have it
    # scored twice and counted twice in the risk-appetite tally -- the double-count this row
    # warned about. Ordered large to micro so the block reads as a scale.
    "US Market Cap": [("OEF", "MegaCap"), ("MDY", "MidCap"), ("IWM", "SmallCap"),
                      ("IWC", "MicroCap")],
    "Continents/Regions": [("EFA", "Developed"), ("EEM", "EmergMkt"), ("VGK", "Europe"),
                           ("AAXJ", "AsiaXJapan"), ("EPP", "AsiaPacific"), ("ILF", "LatinAmer")],
    "Countries": [("EWJ", "Japan"), ("FXI", "China"), ("INDA", "India"), ("EWZ", "Brazil"),
                  ("EWG", "Germany"), ("EWU", "UK"), ("EWC", "Canada"), ("EWY", "Korea"),
                  ("EWT", "Taiwan"), ("EWW", "Mexico")],
    "Currencies": [("UUP", "USDollar"), ("FXE", "Euro"), ("FXY", "Yen"),
                   ("FXB", "Pound"), ("CEW", "EM-FX")],
    "Commodities": [("GLD", "Gold"), ("SLV", "Silver"), ("USO", "Oil"),
                    ("CPER", "Copper"), ("DBA", "Agri"), ("DBC", "BroadCmdty")],
    "Bonds": [("TLT", "LongTsy"), ("IEF", "7-10yTsy"), ("HYG", "HighYield"),
              ("LQD", "InvGrade"), ("TIP", "TIPS")],
    "Crypto": [("BTC-USD", "Bitcoin"), ("ETH-USD", "Ethereum")],
}
# Risk-on assets (money in = risk appetite) vs risk-off / defensive (money in = fear)
_RISK_ON  = {"XLK", "XLY", "IWM", "QQQ", "IWF", "MTUM", "XLF", "XLC", "BTC-USD", "ETH-USD",
             "FXI", "EEM", "EWZ", "EWY", "EWT", "EWW", "ILF", "AAXJ", "EPP", "IWC"}
# OEF and MDY are deliberately NOT risk-on. Mega and mid caps are simply "the market" -- the
# risk-appetite end of the size scale is small and micro, and tagging the whole scale would
# make the appetite score move whenever ANY size rallied, which is no signal at all.
_RISK_OFF = {"XLU", "XLP", "XLV", "TLT", "IEF", "LQD", "TIP", "GLD", "UUP", "FXY"}

def _cmf_series(h, n=20):
    """Chaikin Money Flow(n): +ve = accumulation (money in), -ve = distribution (out)."""
    hi, lo, cl, vol = h["High"], h["Low"], h["Close"], h["Volume"]
    rng = (hi - lo).replace(0, np.nan)
    mfm = ((cl - lo) - (hi - cl)) / rng
    mfv = (mfm * vol).fillna(0.0)
    vsum = float(vol.tail(n).sum())
    return float(mfv.tail(n).sum() / vsum) if vsum > 0 else 0.0

def compute_money_flow():
    """Rank the universe by a money-flow composite. Returns
    {'cats': {category: [row,...]}, 'read': str, 'risk': float, 'asof': str}."""
    syms = [s for grp in _MONEYFLOW_UNIVERSE.values() for s, _ in grp] + ["SPY"]
    try:
        data = _yf_download(tickers=" ".join(sorted(set(syms))), period="4mo",
                            interval="1d", auto_adjust=False, progress=False)
    except Exception as e:
        log.warning(f"money_flow download failed: {e}")
        return {"cats": {}, "read": "", "risk": 0.0, "asof": ""}

    def _ohlcv(sym):
        try:
            if isinstance(data.columns, pd.MultiIndex):
                d = pd.DataFrame({k: data[k][sym] for k in ("High", "Low", "Close", "Volume")})
            else:  # single ticker
                d = data[["High", "Low", "Close", "Volume"]].copy()
            return d.dropna()
        except Exception:
            return pd.DataFrame()

    spy = _ohlcv("SPY")
    if spy.empty or len(spy) < 25:
        return {"cats": {}, "read": "", "risk": 0.0, "asof": ""}
    spy_c = spy["Close"]
    def _ret(c, n):
        return (float(c.iloc[-1]) / float(c.iloc[-1 - n]) - 1) * 100 if len(c) > n else 0.0
    spy_r20 = _ret(spy_c, 20)

    cats, risk_num, risk_den = {}, 0.0, 0.0
    for cat, members in _MONEYFLOW_UNIVERSE.items():
        rows = []
        for sym, name in members:
            h = _ohlcv(sym)
            if h.empty or len(h) < 25:
                continue
            c = h["Close"]
            r5, r20 = _ret(c, 5), _ret(c, 20)
            rel20 = r20 - spy_r20                       # excess return vs SPY (rotation edge)
            cmf = _cmf_series(h, 20)                    # accumulation/distribution
            # RS line vs SPY + RRG-style ratio/momentum
            rs = (c / spy_c.reindex(c.index).ffill()).dropna()
            rs_ma = rs.rolling(20).mean()
            rs_ratio = float(100 * rs.iloc[-1] / rs_ma.iloc[-1]) if rs_ma.iloc[-1] else 100.0
            rs_prev  = float(100 * rs.iloc[-6] / rs_ma.iloc[-6]) if len(rs) > 6 and rs_ma.iloc[-6] else rs_ratio
            rs_mom   = rs_ratio - rs_prev               # >0 = strengthening
            quad = ("Leading"   if rs_ratio >= 100 and rs_mom >= 0 else
                    "Weakening" if rs_ratio >= 100 and rs_mom <  0 else
                    "Improving" if rs_ratio <  100 and rs_mom >= 0 else "Lagging")
            # dollar-volume participation (5d vs 20d)
            dv = (c * h["Volume"])
            dvt = (float(dv.tail(5).mean()) / float(dv.tail(20).mean()) - 1) * 100 if float(dv.tail(20).mean()) else 0.0
            # composite score: excess return + CMF + RS momentum + participation
            score = rel20 * 1.0 + cmf * 60.0 + rs_mom * 1.2 + max(min(dvt, 60), -60) * 0.10
            flow = ("IN"  if (cmf > 0.03 and rel20 > 0) else
                    "OUT" if (cmf < -0.03 and rel20 < 0) else "MIXED")
            rows.append({"sym": sym, "name": name, "r5": r5, "r20": r20, "rel20": rel20,
                         "cmf": cmf, "rs_ratio": rs_ratio, "rs_mom": rs_mom, "quad": quad,
                         "dvt": dvt, "score": score, "flow": flow})
            if sym in _RISK_ON:
                risk_num += score; risk_den += abs(score) + 1
            elif sym in _RISK_OFF:
                risk_num -= score; risk_den += abs(score) + 1
        rows.sort(key=lambda x: x["score"], reverse=True)
        if rows:
            cats[cat] = rows

    risk = (risk_num / risk_den * 100) if risk_den else 0.0   # -100 risk-off .. +100 risk-on
    # rotation read
    allrows = [r for rs in cats.values() for r in rs]
    ins  = sorted([r for r in allrows if r["flow"] == "IN"],  key=lambda x: -x["score"])[:4]
    outs = sorted([r for r in allrows if r["flow"] == "OUT"], key=lambda x:  x["score"])[:4]
    tone = ("RISK-ON" if risk > 15 else "RISK-OFF" if risk < -15 else "MIXED/ROTATIONAL")
    read = f"{tone}: "
    if ins:  read += "money INTO " + ", ".join(r["name"] for r in ins)
    if outs: read += "  ·  OUT of " + ", ".join(r["name"] for r in outs)

    # ── data-driven relationships: what has HISTORICALLY moved together ──
    # (daily-return correlation over the fetched window; surfaces the 'most obvious'
    #  follow-on for whatever is leading the rotation now). User ask 2026-07-20.
    rels = []
    try:
        _valid = [r["sym"] for rs in cats.values() for r in rs]
        _closes = {}
        for s in _valid:
            _o = _ohlcv(s)
            if not _o.empty:
                _closes[s] = _o["Close"]
        _rets = pd.DataFrame(_closes).pct_change().dropna(how="all")
        _corr = _rets.corr()
        _nm = {s: n for grp in _MONEYFLOW_UNIVERSE.values() for s, n in grp}
        for r in (ins[:2] + outs[:2]):
            s = r["sym"]
            if s not in _corr.columns:
                continue
            col = _corr[s].drop(labels=[s], errors="ignore").dropna()
            pos = col.sort_values(ascending=False).head(3)
            neg = col.sort_values().head(2)
            rels.append({"name": r["name"], "dir": ("IN" if r["flow"] == "IN" else "OUT"),
                         "with": [(_nm.get(k, k), float(v)) for k, v in pos.items() if v > 0.2],
                         "opp":  [(_nm.get(k, k), float(v)) for k, v in neg.items() if v < -0.2]})
    except Exception as _e:
        log.debug(f"flow relationships: {_e}")

    return {"cats": cats, "read": read, "risk": risk, "asof": str(spy.index[-1])[:10],
            "ins": ins, "outs": outs, "rels": rels}


_MF_CACHE = {"ts": 0.0, "data": None}

def _money_flow_cached():
    import time as _t
    if _MF_CACHE["data"] and _t.time() - _MF_CACHE["ts"] < 900:   # 15-min cache (EOD-ish data)
        return _MF_CACHE["data"]
    d = compute_money_flow()
    if d.get("cats"):
        _MF_CACHE["data"] = d; _MF_CACHE["ts"] = _t.time()
    return d

def _money_flow_report(mf=None):
    """Telegram report: rotation read + per-category flow tables (RRG quadrant + CMF vs SPY)."""
    if mf is None:
        mf = _money_flow_cached()
    cats = mf.get("cats") or {}
    if not cats:
        return "⚠️ Money-flow data unavailable right now — feeds slow, try again shortly."
    risk = mf.get("risk", 0.0)
    tone_em = "🟢" if risk > 15 else ("🔴" if risk < -15 else "🟡")
    parts = [hdr(f"💸 MONEY FLOW / ROTATION · {mf.get('asof','')}")]
    parts.append(f"{tone_em} <b>{mf.get('read','')}</b>")
    parts.append(f"<i>Risk-appetite {risk:+.0f} (−100 risk-off … +100 risk-on). "
                 "Rank = Chaikin Money Flow + relative strength vs SPY + RS-momentum; "
                 "Q = RRG quadrant. ⚠️ Backtest: the RS-momentum edge is real but small and "
                 "only at ~20d (IC +0.03, t≈3) — a POSITIONING tilt, not short-term timing.</i>")
    if mf.get("rels"):
        parts.append("\n<b>🔗 What moves together</b> <i>(daily-return corr, ~4mo — the 'most obvious' follow-on)</i>")
        for rl in mf["rels"]:
            _w = ", ".join(f"{n}({c:+.2f})" for n, c in rl["with"]) or "—"
            _line = f"{rl['dir']} <b>{rl['name']}</b> → moves with: {_w}"
            if rl["opp"]:
                _line += " · opposite: " + ", ".join(f"{n}({c:+.2f})" for n, c in rl["opp"])
            parts.append(_line)
        parts.append("<i>When the leader moves, the 'with' names usually follow; 'opposite' names diverge.</i>")
    _qmap = {"Leading": "Ld", "Weakening": "Wk", "Improving": "Im", "Lagging": "Lg"}
    for cat, rows in cats.items():
        _r = []
        for r in rows:
            fe = "🟢" if r["flow"] == "IN" else ("🔴" if r["flow"] == "OUT" else "🟡")
            _r.append((fe, r["name"][:9], f"{r['rel20']:+.1f}%", _qmap.get(r["quad"], "")))
        parts.append(_pipe_table(("", "Name", "vSPY", "Q"), _r, right_cols={2}, title=cat))
    parts.append("<i>🟢 money in · 🔴 out · 🟡 mixed · Ld lead / Im improve / Wk weaken / Lg lag "
                 "· vSPY = 20d return vs S&P · educational, not advice</i>")
    return "\n".join(parts)

async def flow_view(query):
    _loading = await query.message.reply_text("💸 Computing money-flow rotation…", parse_mode=H)
    try:
        msg = _money_flow_report()
    except Exception as e:
        log.warning(f"flow_view: {e}"); msg = "⚠️ Money-flow error — try again."
    try: await _loading.delete()
    except Exception: pass
    kb = InlineKeyboardMarkup([[InlineKeyboardButton("🔄 Refresh", callback_data="flow_view"), BACK_BTN]])
    await _safe_reply(query.message, msg, reply_markup=kb)

async def flow_cmd(update, ctx):
    from types import SimpleNamespace
    await flow_view(SimpleNamespace(message=update.message))


