async def positions_view(query):
    log.info("positions_view ENTER (card renderer)")   # TRACE 2026-07-18
    _close_expired_positions()
    conn = get_conn()
    trades = pd.read_sql(
        "SELECT * FROM trades WHERE status='OPEN' AND UPPER(option_type)<>'STOCK' ORDER BY ticker, created_at DESC LIMIT 50", conn)
    conn.close()

    if trades.empty:
        await query.message.reply_text(
            hdr('💼 OPEN POSITIONS') + '\n\nNo open positions found.',
            parse_mode=H, reply_markup=InlineKeyboardMarkup([[BACK_BTN]]))
        return

    tickers_order = list(dict.fromkeys(trades['ticker'].astype(str).tolist()))
    # ONE card format everywhere (user 2026-07-18): menu Positions now renders the
    # SAME health card as the 10-min monitor push — live marks, P&L$/P%, colored
    # status, per-leg advice, HP Engine. Shared builder: _positions_card_parts.
    _loading = None
    try:
        _loading = await query.message.reply_text("⏳ Fetching live marks…", parse_mode=H)
    except Exception:
        pass
    now_et = _et_now().replace(tzinfo=None)   # DST-aware (was fixed UTC-5 = 1h slow in EDT)
    card = _positions_card_parts(trades, now_et.strftime("%H:%M ET"), now_et.date())
    parts = [card["full"]]
    try:
        if _loading:
            await _loading.delete()
    except Exception:
        pass

    # 📦 stock lots — SEPARATE table (user keeps stocks apart from options)
    try:
        _sconn = get_conn()
        _slots = _sconn.execute(
            "SELECT trade_id, ticker, quantity, entry_price, entry_date FROM trades "
            "WHERE status='OPEN' AND UPPER(option_type)='STOCK' ORDER BY ticker").fetchall()
        _sconn.close()
        if _slots:
            _srows = []
            for _sid, _stk, _sq, _sep, _sed in _slots:
                _spx = _last_price(_stk) or 0
                _spnl = f"{(_spx - float(_sep or 0)) * int(_sq or 0):+,.0f}" if _spx else "—"
                _srows.append(("🟢" if int(_sq or 0) > 0 else "🔴", _flag_tk(_stk),
                               f"{int(_sq or 0)}", _spnl))
            _sflags = _flag_legend([r[1] for r in _slots])
            parts.append(chr(10) + "📦 <b>Stock lots</b>" + chr(10)
                         + _pipe_table(("ST", "Tkr", "Sh", "P&L$"), _srows,
                                       right_cols={2, 3},
                                       legend=("tax clock & entries — /tax"
                                               + (f" · {_sflags}" if _sflags else ""))))
    except Exception:
        log.debug("stock lots block failed", exc_info=True)

    btn_rows = []
    for tk in tickers_order:
        btn_rows.append([
            InlineKeyboardButton(f'📊 {tk} Exit Plan', callback_data=f'exit_batch_tk|{tk}'),
            InlineKeyboardButton(f'🌙 {tk} AH Pred',   callback_data=f'ah_pred_tk|{tk}'),
        ])

    leg_btns = []
    for _, tr in trades.head(6).iterrows():
        tid_ = _safe_int(tr.get('trade_id', 0), 0)
        tk_  = str(tr.get('ticker', '?'))
        ot_  = str(tr.get('option_type', '?')).upper()
        st_  = _safe_float(tr.get('strike', 0), 0)
        leg_btns.append(InlineKeyboardButton(f'#{tid_} {tk_} {ot_[:3]} ${st_:.0f}', callback_data=f'pos_{tid_}'))
    for i in range(0, len(leg_btns), 2):
        btn_rows.append(leg_btns[i:i+2])

    btn_rows.append([InlineKeyboardButton('📊 All Positions Exit Plan', callback_data='exit_batch_all'),
                     InlineKeyboardButton('🌙 All AH Predictor',        callback_data='menu_aftermarket_predict')])
    btn_rows.append([InlineKeyboardButton('➕ Add Position', callback_data='posadd_start'),
                     InlineKeyboardButton('📦 Groups',       callback_data='menu_groups')])
    btn_rows.append([InlineKeyboardButton('🎨 Strategy Builder', callback_data='menu_strategy_builder'),
                     InlineKeyboardButton('🤖 MiroFish',         callback_data='menu_mirofish')])
    btn_rows.append([InlineKeyboardButton('🔄 Refresh', callback_data='menu_positions'), BACK_BTN])

    _txt = '\n'.join(parts)
    _kb = InlineKeyboardMarkup(btn_rows)
    log.info("positions_view SEND: %d chars, split=%s", len(_txt), len(_txt) > 4000)
    if len(_txt) <= 4000:
        await query.message.reply_text(_txt, parse_mode=H, reply_markup=_kb)
    else:
        # Split: header+cards first, then urgent+hp+footer (+stock lots) w/ buttons.
        # Neither half is _tg_cut any more (user 2026-08-10) — cutting here silently
        # dropped whatever came last, usually NEWS. If either half is still over the
        # limit the send wrapper splits it again rather than discarding the tail.
        await query.message.reply_text(card["head"], parse_mode=H)
        await query.message.reply_text('\n'.join([card["tail"].lstrip('\n')] + parts[1:]),
                                       parse_mode=H, reply_markup=_kb)


async def position_detail(query, trade_id, notice=None):
    tr = _fetch_trade(trade_id)
