        tx_type = str(r.get("transaction_type", "?"))
        emoji = "🟢" if "buy" in tx_type.lower() or "purchase" in tx_type.lower() else "🔴"
        tk = r.get("ticker", "?")
        name = r.get("insider_name", "?")
        title = r.get("position_title", "?")
