async def market_analytics_report(query):
    """Full market analytics report: futures, OI signals, strategy playbook — InsiderFinance style."""

    def _fmt_k(n):
        """Compact OI number: +2.8M / +752K / +845  (max ~7 chars)."""
        n = float(n or 0)
        s = "+" if n >= 0 else "-"
        a = abs(n)
        if a >= 1_000_000: return f"{s}{a/1_000_000:.1f}M"
        if a >= 1_000:     return f"{s}{a/1_000:.0f}K"
        return f"{s}{abs(n):.0f}"

    _loading = await query.message.reply_text("⏳ Building market analytics...", parse_mode=H)
    now_et = _et_now().replace(tzinfo=None)   # DST-aware (was fixed UTC-5 = 1h slow in EDT)
    parts = [hdr(f"📊 MARKET ANALYTICS  {now_et.strftime('%m-%d  %H:%M ET')}")]

    # ── 1. Futures & Indices ────────────────────────────────────────
    fut_syms = [
        ("ES",      "ES=F"),     ("NQ",      "NQ=F"),
        ("VIX",     "^VIX"),     ("VXN",     "^VXN"),   # Nasdaq-100 vol (tech fear gauge)
        ("Gold",    "GC=F"),     ("Oil",     "CL=F"),
        ("BTC",     "BTC-USD"),  ("EUR/USD", "EURUSD=X"), ("10Y", "^TNX"),
    ]
    # Each data row — compact 4-col, mobile-safe ≈28 chars (no Dir)
    _f_hdrs = ["ST", "Name", "Price", "Chg%"]
    _f_RIGHT = {2, 3, 4}
    _f_data  = []
    _f_chgs  = {}   # sym -> chg for macro correlations
    sentiment_score = 0
    vix_val = 0
    for name, sym in fut_syms:
        try:
            h = _yf_ticker(sym).history(period="5d")
            if len(h) >= 2:
                px   = float(h["Close"].iloc[-1])
                prev = float(h["Close"].iloc[-2])
                chg  = (px - prev) / prev * 100
                st    = "🟢" if chg > 0.5 else ("🔴" if chg < -0.5 else "🟡")
                if sym in ("ES=F", "^GSPC"): sentiment_score += chg * 8
                if sym == "^VIX":            vix_val = px
                px_s = f"{px:,.2f}" if px < 1000 else f"{px:,.0f}"
                _f_data.append([st, name, px_s, f"{chg:+.2f}%", _col_arrow(chg)])
                _f_chgs[name] = chg
            else:
                _f_data.append(["🟡", name, "N/A", "---", ""])
        except Exception:
            _f_data.append(["🔴", name, "ERR", "---", ""])

    if vix_val > 30:   vol_lbl = "EXTREME FEAR"
    elif vix_val > 25: vol_lbl = "HIGH FEAR"
    elif vix_val > 20: vol_lbl = "ELEVATED"
    else:              vol_lbl = "CALM"
    sent_label = "BULLISH" if sentiment_score > 10 else "BEARISH" if sentiment_score < -10 else "NEUTRAL"
    risk_label = "RISK-ON" if sentiment_score > 5  else "RISK-OFF" if sentiment_score < -5 else "MIXED"

    if _f_data:
        parts.append(_pipe_table(tuple(_f_hdrs[:4]), [tuple(r[:4]) for r in _f_data],
                                 right_cols={2, 3},
                                 legend=f"Sent:{sent_label[:4]} · {risk_label[:4]} · VIX:{vol_lbl[:4]}"))

    # ── 2. OI Signal Summary ───────────────────────────────────────
    conn = get_conn()
    bull_tickers, bear_tickers, unusual_tickers = [], [], []
    bull_rows_data, bear_rows_data = [], []
    latest_date = "?"
    try:
        lr = pd.read_sql("""
            SELECT DISTINCT trade_date_now FROM options_change
            ORDER BY trade_date_now DESC LIMIT 1
        """, conn)
        if not lr.empty:
            latest_date = lr["trade_date_now"].iloc[0]
            sig_df = pd.read_sql("""
                SELECT ticker,
                       SUM(change_OI_Call)   AS call_chg,
                       SUM(change_OI_Put)    AS put_chg,
                       SUM(openInt_Call_now) AS call_oi,
                       SUM(openInt_Put_now)  AS put_oi
                FROM options_change WHERE trade_date_now=?
                GROUP BY ticker
                HAVING (ABS(SUM(change_OI_Call)) + ABS(SUM(change_OI_Put))) > 100
                ORDER BY (ABS(SUM(change_OI_Call)) + ABS(SUM(change_OI_Put))) DESC
                LIMIT 30
            """, conn, params=(latest_date,))
            for _, r in sig_df.iterrows():
                tk   = str(r["ticker"])
                c    = float(r["call_chg"] or 0)
                p    = float(r["put_chg"]  or 0)
                c_oi = float(r["call_oi"]  or 1)
                p_oi = float(r["put_oi"]   or 0)
                pcr  = p_oi / c_oi if c_oi > 0 else 0
                _sig, _ = _oi_signal_light(c, p, pcr)
                if _sig == "BULLISH":
                    bull_tickers.append(tk);    bull_rows_data.append((tk, c, p, pcr))
                elif _sig in ("BEARISH", "MILD BEAR"):
                    bear_tickers.append(tk);    bear_rows_data.append((tk, c, p, pcr))
                elif _sig == "HEDGE":
                    unusual_tickers.append(f"{tk}[H]")   # hedge not directional
                elif _sig in ("STRADDLE", "BULL+HEDGE"):
                    unusual_tickers.append(tk)
    except Exception as ex:
        log.warning(f"market_analytics OI query failed: {ex}")
    conn.close()

    # OI signals — single <pre> table
    _oi_hdr  = ["Sig", "Ticker", "Call OI", "Put OI", "PCR"]
    _oi_RGHT = {2, 3, 4}
    _oi_rows = []
    for tk, c, p, pcr in bull_rows_data[:5]:
        _oi_rows.append(["🟢", tk[:7], _fmt_k(c), _fmt_k(p), f"{pcr:.2f}"])
    for tk, c, p, pcr in bear_rows_data[:5]:
        _oi_rows.append(["🔴", tk[:7], _fmt_k(c), _fmt_k(p), f"{pcr:.2f}"])
    if unusual_tickers:
        _oi_rows.append(["🟡", ", ".join(unusual_tickers[:3])[:7], "", "", ""])
    if _oi_rows:
        parts.append(f"<b>OI FLOW  {latest_date}</b>\n"
                     + _pipe_table(tuple(_oi_hdr), _oi_rows, right_cols=_oi_RGHT))

    # ── 3. Technical Signals (moondevonyt / Harvard RBI) ──────────
    try:
        import pandas_ta as pta
        _scan = ["SPY", "QQQ", "IWM", "NVDA", "AAPL", "TSLA", "AMZN", "META"]
        _t_hdr  = ["Sym ", "Sig ", "Sc ", "RSI", "MACD", "BB ", "EMA%  "]
        _t_RGHT = {2, 3, 6}
        _t_data = []
        _yf_warm(_scan, period="60d", interval="1d")   # parallel prefetch -> loop hits cache
        for sym in _scan:
            try:
                _h = _yf_ticker(sym).history(period="60d", interval="1d")
                if len(_h) < 26: continue
                _cl    = _h["Close"]
                px_now = float(_cl.iloc[-1])
                rsi_s  = pta.rsi(_cl, length=14)
                rsi_v  = float(rsi_s.iloc[-1]) if rsi_s is not None and not rsi_s.empty else 50.0
                macd_df = pta.macd(_cl, fast=12, slow=26, signal=9)
                cd = "BUY" if (macd_df is not None and not macd_df.empty and
                               float(macd_df.iloc[-1,0]) > float(macd_df.iloc[-1,1])) else "SELL"
                bb_pos = "MID"
                bb_df  = pta.bbands(_cl, length=20, std=2)
                if bb_df is not None and not bb_df.empty:
                    if px_now >= float(bb_df.iloc[-1,0])*0.995:   bb_pos = "TOP"
                    elif px_now <= float(bb_df.iloc[-1,2])*1.005: bb_pos = "BOT"
                ema_s   = pta.ema(_cl, length=20)
                ema_v   = float(ema_s.iloc[-1]) if ema_s is not None and not ema_s.empty else px_now
                ema_pct = (px_now - ema_v) / ema_v * 100
                bull_pts = sum([rsi_v < 70, rsi_v > 50, cd == "BUY", bb_pos != "TOP", ema_pct > 0])
                sig = "BULL" if bull_pts >= 4 else ("BEAR" if bull_pts <= 1 else "NEUT")
                rsi_flag = "OB" if rsi_v > 70 else ("OS" if rsi_v < 30 else "  ")
                _t_data.append([sym, sig, f"{bull_pts}/5", f"{rsi_v:.0f}", f"{cd}{'+'if cd=='BUY' else'-'}",
                                 bb_pos, f"{ema_pct:+.1f}%"])
            except Exception:
                continue
        if _t_data:
            parts.append("<b>TECH SIGNALS  RSI/MACD/BB/EMA</b>\n"
                         + _pipe_table(tuple(_t_hdr), _t_data, right_cols=_t_RGHT))
    except Exception as te_ex:
        log.warning(f"market_analytics tech signals failed: {te_ex}")

    # ── 3b. Market Regime (VIX Term Structure · Sector Rotation · Fear/Greed) ─
    try:
        _regime = ["<b>🎯 MARKET REGIME</b>"]

        # VIX Term Structure: spot vs 3-month
        try:
            _vix_s = float(_yf_ticker("^VIX").history(period="5d")["Close"].iloc[-1])
            _vx3m  = float(_yf_ticker("^VIX3M").history(period="5d")["Close"].iloc[-1])
            _vt_r  = _vix_s / _vx3m
            _vt_lb = "BACKWDTN ⚠️" if _vt_r > 1.05 else ("CONTANGO ✓" if _vt_r < 0.95 else "FLAT")
            _regime.append(f"🌡 <b>VIX Term:</b>  {_vix_s:.1f} / {_vx3m:.1f}  ({_vt_r:.2f}x)  {_vt_lb}")
            # VXN alongside, never instead (user 2026-08-08). The spread vs VIX is the read:
            # wide = risk concentrated in tech, narrow = broad.
            _vn = (_get_vol_indices() or {}).get("vxn") or 0
            if _vn > 0:
                _regime.append(f"🌡 <b>VXN (Nasdaq):</b>  {_vn:.1f}   "
                               f"spread vs VIX {_vn - _vix_s:+.1f} pts  "
                               f"{'tech-led risk' if _vn - _vix_s >= 4 else 'broad, not tech-specific' if _vn - _vix_s <= 1.5 else 'normal tech premium'}")
        except Exception:
            log.debug("suppressed exception", exc_info=True)

        # Sector Rotation: 5d leaders vs laggards
        try:
            _secs = [("XLK","Tech"),("XLF","Finl"),("XLE","Engy"),("XLV","Hlth"),
                     ("XLI","Inds"),("XLC","Comm"),("XLU","Util")]
            _sp = []
            for _sym, _lbl in _secs:
                _sh = _yf_ticker(_sym).history(period="7d")
                if len(_sh) >= 2:
                    _p = (float(_sh["Close"].iloc[-1]) - float(_sh["Close"].iloc[-2])) / float(_sh["Close"].iloc[-2]) * 100
                    _sp.append((_lbl, _p))
            if _sp:
                _sp.sort(key=lambda x: x[1], reverse=True)
                _top = " · ".join(f"{l} {p:+.1f}%" for l, p in _sp[:2])
                _bot = " · ".join(f"{l} {p:+.1f}%" for l, p in _sp[-2:])
                _regime.append(f"🏆 <b>Leaders:</b>  {_top}")
                _regime.append(f"⬇ <b>Laggards:</b>  {_bot}")
        except Exception:
            log.debug("suppressed exception", exc_info=True)

        # Fear & Greed Composite (0-100)
        try:
            _fg = 50
            # VIX: VIX=10→+25pts, VIX=20→neutral, VIX=30→-25pts
            if vix_val > 0:
                _fg += max(-25, min(25, int((20 - vix_val) * 2.5)))
            # Market momentum (ES sentiment_score proxy)
            _fg += max(-20, min(20, int(sentiment_score)))
            _fg = max(0, min(100, _fg))
            if _fg >= 75:   _fg_lb = "EXTREME GREED 🤑"
            elif _fg >= 55: _fg_lb = "GREED 😀"
            elif _fg >= 45: _fg_lb = "NEUTRAL 😐"
            elif _fg >= 25: _fg_lb = "FEAR 😨"
            else:           _fg_lb = "EXTREME FEAR 😱"
            _bar = "█" * (_fg // 10) + "░" * (10 - _fg // 10)
            _regime.append(f"😱 <b>Fear/Greed:</b>  {_fg}/100  {_fg_lb}")
            _regime.append(f"   <code>{_bar}</code>")
        except Exception:
            log.debug("suppressed exception", exc_info=True)

        # Market Breadth: SPY vs IWM vs QQQ 5d momentum
        try:
            _breadth = []
            for _bs, _bn in [("SPY","SPY"),("QQQ","QQQ"),("IWM","IWM"),("MDY","MDY")]:
                _bh = _yf_ticker(_bs).history(period="7d")
                if len(_bh) >= 2:
                    _bp = (float(_bh["Close"].iloc[-1]) - float(_bh["Close"].iloc[-2])) / float(_bh["Close"].iloc[-2]) * 100
                    _be = "🟢" if _bp > 0 else "🔴"
                    _breadth.append(f"{_bn} {_bp:+.1f}%")
            if _breadth:
                _regime.append(f"📊 <b>Breadth:</b>  {' · '.join(_breadth)}")
        except Exception:
            log.debug("suppressed exception", exc_info=True)

        if len(_regime) > 1:
            parts.append("\n".join(_regime))
    except Exception as _re_ex:
        log.warning(f"market_analytics regime signals failed: {_re_ex}")

    # ── 4. Market News ─────────────────────────────────────────────
    try:
        import feedparser, html as html_mod
        _neg = ["drop","fall","crash","sell","bear","down","loss","cut","tariff","fear",
                "decline","recession","warn","slump","plunge","sink","tumble"]
        _pos = ["rise","gain","rally","bull","up","beat","surge","strong","record",
                "high","boost","upgrade","growth","jump","soar"]
        news_items = []
        _feed_urls = (["https://www.benzinga.com/markets/feed"] +
                      [f"https://feeds.finance.yahoo.com/rss/2.0/headline?s={s}&region=US&lang=en-US"
                       for s in ["SPY", "^VIX", "^TNX", "AAPL", "NVDA"]])
        for feed_url in _feed_urls:
            try:
                feed = feedparser.parse(feed_url)
                for entry in feed.entries[:4]:
                    title = html_mod.unescape(entry.get("title", "")).strip()
                    link  = entry.get("link", "")
                    if not title or len(title) < 15: continue
                    tl   = title.lower()
                    tone = "Bear" if any(k in tl for k in _neg) else ("Bull" if any(k in tl for k in _pos) else "Neut")
                    if not any(title[:55] == x[1][:55] for x in news_items):
                        news_items.append((tone, title, link))
                    if len(news_items) >= 10: break
            except Exception: continue
            if len(news_items) >= 10: break

        if news_items:
            tone_em = {"Bull": "🟢", "Bear": "🔴", "Neut": "🟡"}
            n_lines = [f"<b>HEADLINES  {now_et.strftime('%m-%d')}</b>"]
            for tone, title, link in news_items[:7]:
                em2   = tone_em.get(tone, "🟡")
                short = html_mod.escape(title[:65] + ("…" if len(title) > 65 else ""))
                line  = f'{em2} <a href="{link}">{short}</a>' if link else f"{em2} {short}"
                n_lines.append(line)
            parts.append("\n".join(n_lines))
    except Exception as news_ex:
        log.warning(f"market_analytics news fetch failed: {news_ex}")

    # ── 5. Macro Cross-Asset Correlations & Trade Ideas ────────────
    try:
        macro_lines = ["<b>MACRO CORRELATIONS &amp; TRADE IDEAS</b>"]
        oil_chg  = _f_chgs.get("Oil",    0.0)
        gold_chg = _f_chgs.get("Gold",   0.0)
        vix_chg  = _f_chgs.get("VIX",    0.0)
        tnx_chg  = _f_chgs.get("10Y",    0.0)
        dxy_chg  = _f_chgs.get("EUR/USD",0.0) * -1   # EUR/USD inverse of DXY
        btc_chg  = _f_chgs.get("BTC",    0.0)

        macro_ideas = []   # (emoji, trade idea, rationale)

        # Oil relationships
        if oil_chg > 1.5:
            macro_ideas.append(("🟢", "LONG XLE / CVX / XOM", f"Oil +{oil_chg:.1f}% → Energy stocks benefit directly"))
            macro_ideas.append(("🔴", "SHORT DAL / UAL / AAL", f"Oil +{oil_chg:.1f}% → Airline fuel costs spike"))
            macro_ideas.append(("🔴", "CAUTION on XRT / AMZN", f"Higher oil → consumer spending pressure"))
        elif oil_chg < -1.5:
            macro_ideas.append(("🟢", "LONG DAL / UAL / LUV", f"Oil {oil_chg:.1f}% → Airline margins expand"))
            macro_ideas.append(("🟢", "LONG XLY / AMZN / TGT", f"Lower fuel → consumer discretionary benefits"))
            macro_ideas.append(("🔴", "SHORT XLE / CVX", f"Oil {oil_chg:.1f}% → Energy earnings pressure"))

        # Gold & DXY relationships
        if gold_chg > 1.0:
            macro_ideas.append(("🟢", "LONG GDX / NEM / AEM", f"Gold +{gold_chg:.1f}% → Gold miners leveraged to price"))
            macro_ideas.append(("🔴", "DXY likely WEAK — watch EEM/FXI", f"Gold up = USD down = EM outperform"))
        elif gold_chg < -1.0:
            macro_ideas.append(("🟢", "DXY STRONG — LONG UUP", f"Gold {gold_chg:.1f}% → Dollar strengthening"))
            macro_ideas.append(("🔴", "SHORT GDX miners", f"Gold {gold_chg:.1f}% → Miner earnings compress"))

        # 10Y yield relationships
        if tnx_chg > 0.5:
            macro_ideas.append(("🟢", "LONG KBE / JPM / BAC", f"10Y +{tnx_chg:.1f}% → Bank NIMs expand, steepening curve"))
            macro_ideas.append(("🔴", "CAUTION on XLU / XLRE", f"Rising rates → utilities & REITs compress"))
            macro_ideas.append(("🔴", "CAUTION on long-duration tech (ARKK)", f"Higher discount rate = lower NPV on growth"))
        elif tnx_chg < -0.5:
            macro_ideas.append(("🟢", "LONG XLU / VNQ / TLT", f"10Y {tnx_chg:.1f}% → Rate-sensitive sectors rally"))
            macro_ideas.append(("🟢", "LONG ARKK / PLTR / growth", f"Lower rates = multiple expansion for growth"))

        # VIX relationships
        if vix_chg > 5 or vix_val > 25:
            macro_ideas.append(("🔴", "Reduce naked short premium", f"VIX elevated — hedge with calls or close short puts"))
            macro_ideas.append(("🟢", "LONG UVXY / VXX hedge", f"VIX spike protection if portfolio is long"))
        elif vix_val < 15:
            macro_ideas.append(("🟢", "Sell premium — low VIX = cheap insurance", f"VIX {vix_val:.1f} → Condors, covered calls attractive"))

        # BTC / Risk-on signal
        if btc_chg > 3.0:
            macro_ideas.append(("🟢", "Risk-ON signal: LONG MSTR / COIN / RIOT", f"BTC +{btc_chg:.1f}% → Crypto proxies outperform"))
        elif btc_chg < -3.0:
            macro_ideas.append(("🔴", "Risk-OFF signal: reduce spec positions", f"BTC {btc_chg:.1f}% → Risk assets under pressure"))

        if macro_ideas:
            # Tabular format with fixed columns
            _mi_hdr  = ["Dir", "Trade Idea", "Rationale"]
            _mi_rows = [(em, idea, note) for em, idea, note in macro_ideas[:6]]
            max_idea = max(len(r[1]) for r in _mi_rows)
            max_note = min(40, max(len(r[2]) for r in _mi_rows))
            for em, idea, note in _mi_rows:
                short_note = note[:40] + "…" if len(note) > 40 else note
                macro_lines.append(f"{em} <b>{idea}</b>\n   <i>{short_note}</i>")
            parts.append("\n".join(macro_lines))
    except Exception as _mc_ex:
        log.warning(f"macro correlations failed: {_mc_ex}")

    # ── 6. Strategy Playbook ───────────────────────────────────────
    plays = []
    if sent_label == "BEARISH":
        plays += ["Puts / bear put spreads on SPY/QQQ", "Sell covered calls on longs"]
    elif sent_label == "BULLISH":
        plays += ["Bull call spreads / buy calls", "Sell CSPs on pullbacks"]
    else:
        plays.append("Iron condors / butterflies — range bound")
    if vix_val > 25:
        plays.append(f"VIX {vix_val:.1f} — premium EXPENSIVE → sell spreads")
    elif vix_val < 15:
        plays.append(f"VIX {vix_val:.1f} — premium CHEAP → buy debit spreads")
    if bull_tickers:
        plays.append(f"Call OI: {', '.join(bull_tickers[:3])} → bull spreads")
    if bear_tickers:
        plays.append(f"Put OI:  {', '.join(bear_tickers[:3])} → bear spreads")

    p_lines = [f"<b>STRATEGY PLAYBOOK</b>"]
    play_em = {"BULLISH": "🟢", "BEARISH": "🔴", "NEUTRAL": "🟡"}
    em_p = play_em.get(sent_label, "🟡")
    for p in plays[:5]:
        p_lines.append(f"{em_p} {p}")
    parts.append("\n".join(p_lines))

    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("🔄 Refresh", callback_data="menu_analytics"),
         InlineKeyboardButton("🔥 OI Signals", callback_data="menu_signals")],
        [InlineKeyboardButton("🌍 Market", callback_data="menu_market"), BACK_BTN],
    ])
    _pulled_ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    parts.append(f"<i>🕐 Data pulled at: {_pulled_ts}</i>")
    try: await _loading.delete()
    except Exception: pass
    await _safe_reply(query.message, "\n".join(parts), reply_markup=kb)


_LAST_OFFHOURS_PUSH = 0.0      # epoch of the last off-hours position push (15-min throttle)


async def position_monitor(ctx: ContextTypes.DEFAULT_TYPE, force=False):
    """Position table — pushed on a cadence, or on demand.

    force=True (from the manual button / adhoc trigger) BYPASSES the weekday gate and the
    cadence throttle: a user asking for positions must ALWAYS get a fresh render, never a
    silent return because a scheduled push happened to go out minutes ago. That throttle
    blocking the manual button is why the card looked 'stuck' on an old message (2026-07-22).
    """
    global _LAST_OFFHOURS_PUSH
    if not force:
        _now_et = _et_now()
        if _now_et.weekday() >= 5:                  # markets shut all weekend — nothing moves
            return
        hour_min = _now_et.hour * 60 + _now_et.minute
        # Cadence throttled HERE so one code path serves both sessions: RTH every 10 min,
        # off-hours every 15 min straight through to the next open. Job ticks every 5 min so
        # both periods land; 30s slack absorbs tick jitter. /freq (app_settings) overrides.
        _rth = (9 * 60 + 30 <= hour_min < 16 * 60)  # 9:30 AM - 4:00 PM ET
        _uf = 0
        try:
            _c2 = get_conn()
            _uf = int(float(_app_setting(_c2, "pos_alert_freq_min", "0") or 0))
            _c2.close()
        except Exception:
            _uf = 0
        _mins = _uf if _uf > 0 else (10 if _rth else 15)
        if time.time() - _LAST_OFFHOURS_PUSH < _mins * 60 - 30:
            return
        _LAST_OFFHOURS_PUSH = time.time()

    _close_expired_positions()   # auto-close anything past expiry before showing
    _, chat_id = load_creds()
    conn = get_conn()
    try:
        # BOTH books (ID 270) -- the real one is empty, the holdings are in paper.
        trades = _open_positions(conn)
    except Exception:
        conn.close(); return
    conn.close()

    if trades.empty:
        return

    now_et = _et_now().replace(tzinfo=None)   # DST-aware (was fixed UTC-5)
    # GUARDED (ID 217): this builder is SHARED with positions_view, so an edit made for the
    # menu card can throw here and kill the scheduled push -- and because this is a job, the
    # failure is completely silent: no message, no user-visible error, just a card that
    # "stopped arriving". That is one of the two failure modes in the original report, and it
    # was unguarded. A throw now surfaces as a real (notifying) message, deduped to once per
    # day so a persistent break does not spam every 10 minutes.
    try:
        parts = _positions_card_parts(trades, now_et.strftime("%H:%M ET"), now_et.date())
    except Exception as e:
        log.exception("positions card build FAILED — scheduled push cannot render")
        try:
            import html as _he
            _c = get_conn()
            _ensure_alert_dedup_table(_c)
            _first = not _alert_already_sent(_c, now_et.date().isoformat(),
                                             "position_monitor", "card_build_failed")
            _c.close()
            if _first:
                await ctx.bot.send_message(
                    chat_id=int(chat_id),
                    text=(f"⚠️ <b>Positions card is failing to build</b>\n"
                          f"The recurring positions update cannot render, so it will be "
                          f"missing until this is fixed.\n<code>{_he.escape(str(e)[:300])}</code>"),
                    parse_mode=H)
        except Exception:
            log.debug("could not send card-build failure notice", exc_info=True)
        return
    if force:
        # Manual/adhoc trigger: user tapped a button and wants the FULL rich card right
        # now, keyboard included -- the consolidated status message (A10) is for the
        # scheduled recurring tick only, never for an explicit on-demand ask.
        kb = _positions_card_kb(parts["first_tk"])
        try:
            if len(parts["full"]) <= 4000:
                await ctx.bot.send_message(chat_id=int(chat_id), text=parts["full"],
                                           parse_mode=H, reply_markup=kb)
            else:
                await ctx.bot.send_message(chat_id=int(chat_id), text=parts["head"], parse_mode=H)
                await ctx.bot.send_message(chat_id=int(chat_id), text=parts["tail"],
                                           parse_mode=H, reply_markup=kb)
        except Exception as e:
            log.warning(f"position_monitor send failed: {e}")
        return
    # ── Material change? Then NOTIFY, don't just edit (ID 217) ──────────────────────
    # The consolidated status card is edited in place, and Telegram fires no notification
    # on an edit -- so before this, a CUT LOSS could appear and scroll away unseen. Minor
    # ticks still edit silently (that consolidation is the point); only a material change
    # earns a fresh message.
    reason = None
    try:
        reason = _position_material_change(parts)
    except Exception as e:
        log.debug(f"materiality check failed, falling back to silent edit: {e}")
    if reason:
        try:
            await ctx.bot.send_message(
                chat_id=int(chat_id),
                text=f"{hdr('🔔 POSITION UPDATE')}\n<i>{reason}</i>\n\n{parts['full']}"[:4000],
                parse_mode=H, reply_markup=_positions_card_kb(parts["first_tk"]))
            return
        except Exception as e:
            log.warning(f"position_monitor material re-send failed: {e}")
    try:
        await _status_push(ctx, "position_monitor", parts["full"])
    except Exception as e:
        log.warning(f"position_monitor status_push failed: {e}")


# Materiality thresholds for the re-send rule (user 2026-08-14, ID 217).
_POS_RESEND_PCT = 20.0        # percentage POINTS of book P&L move since the last notify


def _position_material_change(parts):
    """Return a short reason string when the book has moved enough to deserve a NEW
    (notifying) message, else None. Baseline is persisted in app_settings so the rule
    survives a restart and cannot re-fire on the same event.

    Two triggers, both chosen by the user:
      * book P&L moves >= 20 percentage points since the last notification
      * a NEW action-required leg appears (EXIT NOW / CUT LOSS / TAKE PROFIT)

    Deliberately compares against the last NOTIFIED state, not the previous tick: a slow
    drift that accumulates to 20pts over an hour is material even though no single 10-min
    tick was, and a position sitting at CUT LOSS all afternoon must not re-alert every tick.
    """
    conn = get_conn()
    try:
        pct = float(parts.get("pnl_pct") or 0.0)
        keys = set(parts.get("urgent_keys") or [])
        prev_pct_raw = _app_setting(conn, "pos_notify_pnl_pct")
        prev_keys = set(filter(None, (_app_setting(conn, "pos_notify_keys") or "").split(",")))
        new_keys = keys - prev_keys

        reason = None
        if new_keys:
            _label = {"exit": "EXIT NOW", "cut": "CUT LOSS", "profit": "TAKE PROFIT"}
            hits = sorted({_label.get(k.split(":")[-1], k) for k in new_keys})
            reason = f"New action required: {', '.join(hits)}."
        elif prev_pct_raw is None or prev_pct_raw == "":
            # First run ever: seed the baseline silently rather than firing on nothing.
            pass
        else:
            try:
                move = pct - float(prev_pct_raw)
            except (TypeError, ValueError):
                move = 0.0
            if abs(move) >= _POS_RESEND_PCT:
                reason = (f"Book P&amp;L moved {move:+.1f} points since the last update "
                          f"(now {pct:+.1f}%).")

        # Persist the baseline whenever it is seeded or consumed. Urgent keys are stored on
        # EVERY tick, including quiet ones, so a leg that drops out of ACTION REQUIRED and
        # later returns is treated as new -- and one that simply persists is not.
        _set_app_setting(conn, "pos_notify_keys", ",".join(sorted(keys)))
        if reason or prev_pct_raw is None or prev_pct_raw == "":
            _set_app_setting(conn, "pos_notify_pnl_pct", f"{pct:.4f}")
        return reason
    finally:
        conn.close()


def _positions_card_kb(first_tk):
    return InlineKeyboardMarkup([[
        InlineKeyboardButton("💼 Positions", callback_data="menu_positions"),
        InlineKeyboardButton("🎯 Exit Plan", callback_data="menu_exit"),
        InlineKeyboardButton("🧠 HP Engine", callback_data=f"high_prob_{first_tk}"),
    ]])


_REC_KIND = {"PS": "Put credit spread (sell)", "CS": "Call credit spread (sell)",
             "CSP": "Cash-secured put (sell)", "CD": "ITM call debit spread (buy)",
             "PUT": "Cash-secured put (sell)"}


def _recs_ensure_src(conn):
    """Add the `src` provenance column if missing. LIVE = issued that day by the scanner;
    BACKFILL = reconstructed after the fact from captured chains. They must never be pooled:
    a reconstructed rec was never actually issued, so counting it in the track record would
    report hindsight as performance."""
    cols = [r[1] for r in conn.execute("PRAGMA table_info(hiprob_recs)")]
    if "src" not in cols:
        conn.execute("ALTER TABLE hiprob_recs ADD COLUMN src TEXT DEFAULT 'LIVE'")
        conn.execute("UPDATE hiprob_recs SET src='LIVE' WHERE src IS NULL")
        conn.commit()


# ── Liquidity gate + realistic fill, shared by both hiprob scanners (2026-08-02) ──────
_HP_MAX_SPREAD = 0.35      # reject a leg quoting wider than this fraction of its own mid
_HP_FILL_F     = 0.50      # give up this fraction of the half-spread on EACH leg


def _hp_fill(bid, ask):
    """Executable prices for one contract, or None if the leg fails the liquidity gate.

    Measured 2026-08-02 over 204 settled recs re-priced off their OWN real bid/ask: booking
    entry at the mid overstates mean return ~2x (+7.25% -> +3.81% at f=0.50). Win rate barely
    moves (94.6% -> 94.2%) — the point is not being wrong more often, it is that the credit
    IS the edge and the quoted spread eats half of it. Median short-leg spread was 17.6% of
    mid; the 75th percentile (35.8%) sets the gate below.

    Legs with no bid at all (BIIB/GILD/SPXS/EFA/FXI quoted spread = 200% of mid) are rejected
    outright rather than haircut — there is no price at which they fill. See ADOPTED.md 9.4.
    """
    b, a = float(bid or 0), float(ask or 0)
    if b <= 0 or a <= 0 or a < b:
        return None                                  # no two-sided market
    mid = (b + a) / 2.0
    if mid <= 0 or (a - b) / mid > _HP_MAX_SPREAD:
        return None                                  # quoted too wide to trade
    hs = (a - b) / 2.0
    return {"mid": mid, "sell": max(mid - _HP_FILL_F * hs, 0.0), "buy": mid + _HP_FILL_F * hs}


def _hiprob_scan_asof(conn, trade_date, tickers, dte_lo=20, dte_hi=45, min_pop=0.80, r=0.045):
    """`_hiprob_scan` replayed as-of a past date, from captured data instead of live yfinance.

    The live scanner is unusable for history: it calls `yf.Ticker(...).option_chain()` and
    `date.today()`, and yfinance only ever serves the CURRENT chain. This reads the same
    quantities out of `options_openbb` (real per-side bid/ask) + `stock_daily.close`.

    Verified 2026-07-22: replaying 2026-07-21 reproduced all 15 rows the live scanner wrote
    that day — same strikes, same expiry, same credit to the cent, same POP. Keep the maths
    below in lockstep with `_hiprob_scan`; if that changes, this must change with it.

    2026-08-02: credits DELIBERATELY no longer match those stored rows. Both scanners now
    price legs through `_hp_fill` (sell side for shorts, buy side for longs) instead of the
    mid, and reject legs failing the liquidity gate. Re-checked on the same 2026-07-21
    universe: all 15 setups still qualify, credits fall a median 7% (up to 31% on two-leg
    spreads, ~0.3% on single-leg index CSPs). Strikes and POP are unchanged.
    """
    from scipy.stats import norm as _nm

    def _pa(S, X, T, iv):
        if min(S, X, T, iv) <= 0:
            return None
        p = float(_nm.cdf((np.log(S / X) + (r - 0.5 * iv * iv) * T) / (iv * np.sqrt(T))))
        return min(p, 0.99)      # same 99% cap as _hiprob_scan — see note there (2026-07-31)

    def _mid(bid, ask, last):
        b, a = float(bid or 0), float(ask or 0)
        return (b + a) / 2.0 if (b > 0 and a > 0) else float(last or 0)

    td = _exp_iso(trade_date)
    td_d = datetime.strptime(td, "%Y-%m-%d").date()
    out = []
    for tk in tickers:
        tk = str(tk).strip().upper()
        if not tk:
            continue
        try:
            px = conn.execute("SELECT close FROM stock_daily WHERE ticker=? AND trade_date=?",
                              (tk, td)).fetchone()
            if not px or not px[0]:
                continue
            spot = float(px[0])
            exp = dte = None
            for (e,) in conn.execute(
                    "SELECT DISTINCT expiry_date FROM options_openbb WHERE ticker=? AND "
                    "trade_date=? ORDER BY expiry_date", (tk, td)):
                d = (datetime.strptime(_exp_iso(e), "%Y-%m-%d").date() - td_d).days
                if dte_lo <= d <= dte_hi:
                    exp, dte = _exp_iso(e), d
                    break
            if not exp:
                continue
            T = max(dte, 1) / 365.0
            chain = conn.execute(
                "SELECT strike, bid_Call, ask_Call, lastPrice_Call, bid_Put, ask_Put, "
                "lastPrice_Put FROM options_openbb WHERE ticker=? AND trade_date=? AND "
                "expiry_date=? ORDER BY strike", (tk, td, exp)).fetchall()
            if not chain:
                continue
            # (strike, mid, sell, buy) — `mid` still drives the ATM IV back-out, but every
            # tradeable price now comes from the liquidity gate, so illiquid strikes never
            # reach the candidate list at all (2026-08-02, see _hp_fill).
            def _leg(s, b, a):
                f = _hp_fill(b, a)
                return None if not f else (float(s), f["mid"], f["sell"], f["buy"])
            calls = [x for x in (_leg(s, bc, ac) for s, bc, ac, lc, _, _, _ in chain) if x]
            puts = [x for x in (_leg(s, bp, ap) for s, _, _, _, bp, ap, lp in chain) if x]

            iv_ref = 0.40                      # ATM-backed IV — same ladder as the live scanner
            atm = min(calls, key=lambda c: abs(c[0] - spot)) if calls else None
            if atm and atm[1] > 0:
                _iv = _implied_vol_hp(atm[1], spot, atm[0], T, r)
                if _iv and 0.05 < _iv < 3.0:
                    iv_ref = _iv
            iv_ref = max(iv_ref, 0.10)

            pl = sorted([p for p in puts if p[0] < spot and p[1] > 0.05], key=lambda p: -p[0])
            for i in range(len(pl)):
                K, cr = pl[i][0], pl[i][2]            # sell the short leg at the sell side
                pop = _pa(spot, K - cr, T, iv_ref)
                if pop is None or pop < min_pop:
                    continue
                out.append({"tk": tk, "kind": "CSP", "setup": f"{K:g}P", "credit": cr,
                            "risk": (K - cr) * 100,   # CSP collateral, see _hiprob_scan note
                            "be": K - cr, "pop": pop, "dte": dte, "exp": exp,
                            "spot": spot, "ret": cr / max(K - cr, 0.01) * 100})
                if i + 2 < len(pl):
                    Kl, cl = pl[i + 2][0], pl[i + 2][3]    # buy the long leg at the buy side
                    net, width = cr - cl, K - Kl
                    if 0.03 < net < width:
                        out.append({"tk": tk, "kind": "PS", "setup": f"{K:g}/{Kl:g}P",
                                    "credit": net, "risk": (width - net) * 100, "be": None,
                                    "pop": pop, "dte": dte, "exp": exp, "spot": spot,
                                    "ret": net / max(width - net, 0.01) * 100})
                break

            cu = sorted([c for c in calls if c[0] > spot and c[1] > 0.05], key=lambda c: c[0])
            for i in range(len(cu)):
                K, cr = cu[i][0], cu[i][2]            # sell the short leg at the sell side
                pa = _pa(spot, K + cr, T, iv_ref)
                if pa is None:
                    continue
                pop = 1 - pa
                if pop < min_pop:
                    continue
                if i + 2 < len(cu):
                    Kl, cl = cu[i + 2][0], cu[i + 2][3]   # buy the long leg at the buy side
                    net, width = cr - cl, Kl - K
                    if 0.03 < net < width:
                        out.append({"tk": tk, "kind": "CS", "setup": f"{K:g}/{Kl:g}C",
                                    "credit": net, "risk": (width - net) * 100, "be": None,
                                    "pop": pop, "dte": dte, "exp": exp, "spot": spot,
                                    "ret": net / max(width - net, 0.01) * 100})
                break
        except Exception:
            log.warning(f"_hiprob_scan_asof {tk} @ {td} failed", exc_info=True)
            continue
    out.sort(key=lambda d: (-d["pop"], -d["ret"]))
    return out


def backfill_hiprob_recs(conn=None, tickers=None, start=None, end=None):
    """Reconstruct the rec history for every captured date that has no rows yet.

    Bounded by `options_openbb` coverage (real bid/ask/IV). `options_daily` reaches back much
    further but carries lastPrice only — no bid/ask, no IV — and POP here is computed off an
    ATM-backed IV, so recs built from it would be fiction. That is the fidelity line: this
    refuses to cross it rather than manufacture a longer track record.

    Rows land with src='BACKFILL' and are reported separately from live recs.
    """
    own = conn is None
    if own:
        conn = get_conn()
    try:
        _recs_ensure_src(conn)
        tks = list(tickers or _hiprob_default_tickers())
        have = {r[0] for r in conn.execute("SELECT DISTINCT rec_date FROM hiprob_recs")}
        dates = [r[0] for r in conn.execute(
            "SELECT DISTINCT trade_date FROM options_openbb ORDER BY trade_date")]
        dates = [d for d in dates if d not in have
                 and (not start or d >= start) and (not end or d <= end)]
        total = 0
        for d in dates:
            rows = _hiprob_scan_asof(conn, d, tks) or []
            for it in rows:
                strat = _REC_KIND.get(it["kind"], it["kind"])
                if conn.execute("SELECT 1 FROM hiprob_recs WHERE rec_date=? AND ticker=? AND "
                                "strategy=? AND legs=? LIMIT 1",
                                (d, it["tk"], strat, it["setup"])).fetchone():
                    continue
                conn.execute(
                    "INSERT INTO hiprob_recs (rec_date,ticker,strategy,legs,expiry,dte,pop,ror,"
                    "k1,k2,net,spot0,capital,status,src) "
                    "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?, 'OPEN','BACKFILL')",
                    (d, it["tk"], strat, it["setup"], it["exp"], it["dte"],
                     float(it["pop"]) * 100, float(it["ret"]), *_rec_strikes(it["setup"]),
                     float(it["credit"]), float(it["spot"]), float(it["risk"] or 0)))
                total += 1
            log.info(f"backfill_hiprob_recs: {d} -> +{len(rows)} recs")
        _settle_recs(conn)
        conn.commit()
        log.info(f"backfill_hiprob_recs: {total} recs across {len(dates)} dates")
        return total, len(dates)
    finally:
        if own:
            conn.close()


def _rec_strikes(setup):
    """('450/440P') -> (450.0, 440.0); ('450P') -> (450.0, 0.0)."""
    import re as _re
    ks = [float(x) for x in _re.findall(r"\d+(?:\.\d+)?", str(setup or ""))]
    return (ks[0] if ks else 0.0), (ks[1] if len(ks) > 1 else 0.0)


async def record_hiprob_recs(context=None):
    """Persist today's high-probability setups into hiprob_recs.

    There was no SCHEDULED writer — the only one, `_hiprob_persist` (dashboard.py), fires as a
    side-effect of rendering the Streamlit HiProb page, so rows existed only on days a human
    opened it. That is why the table held exactly one date (2026-07-08, 261 rows). Corrected
    2026-07-22: an earlier note here claimed that code "no longer exists" — it does, and still
    runs on every dashboard visit. Deduped on (rec_date, ticker, strategy, legs) so re-runs in
    the same day are idempotent.
    """
    import re as _re
    try:
        conn = get_conn()
        _recs_ensure_src(conn)
        today = _et_now().date()
        rows = _hiprob_scan(tuple(_hiprob_default_tickers()[:40])) or []
        added = 0
        for it in rows:
            d = it[1] if isinstance(it, tuple) else it
            tk = str(d.get("tk") or "").upper()
            setup = str(d.get("setup") or "")
            strat = _REC_KIND.get(str(d.get("kind") or "").upper(), str(d.get("kind") or "?"))
            ks = [float(x) for x in _re.findall(r"\d+(?:\.\d+)?", setup)]
            k1 = ks[0] if ks else 0.0
            k2 = ks[1] if len(ks) > 1 else 0.0
            dte = int(d.get("dte") or 0)
            exp = (today + timedelta(days=dte)).isoformat()
            if conn.execute("SELECT 1 FROM hiprob_recs WHERE rec_date=? AND ticker=? AND "
                            "strategy=? AND legs=? LIMIT 1",
                            (today.isoformat(), tk, strat, setup)).fetchone():
                continue
            conn.execute(
                "INSERT INTO hiprob_recs (rec_date,ticker,strategy,legs,expiry,dte,pop,ror,"
                "k1,k2,net,spot0,capital,status,src) "
                "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?, 'OPEN','LIVE')",
                (today.isoformat(), tk, strat, setup, exp, dte,
                 float(d.get("pop") or 0) * 100, float(d.get("ret") or 0), k1, k2,
                 float(d.get("credit") or 0), float(_cur_price(tk, 0.0)[0] or 0),
                 float(d.get("risk") or 0)))
            added += 1
        _settle_recs(conn)              # close out anything that expired since last run
        conn.commit(); conn.close()
        log.info(f"record_hiprob_recs: +{added} new recs")
        return added
    except Exception as e:
        log.warning(f"record_hiprob_recs failed: {e}")
        return 0


def _rec_payoff(strategy, k1, k2, net, S):
    """Settlement P&L per contract (x100) for a hiprob_recs row at underlying price S.

    Stored convention (verified 2026-07-21): `net` is ALWAYS POSITIVE — a credit for
    sells, a debit for buys. k1 = primary/short strike, k2 = protection (0 for CSP).
    Cross-checked against the stored `capital`: UNH 460/470 call credit ->
    (470-460-1.90)*100 = 810 = capital.
    """
    s = (strategy or "").lower()
    if "call credit" in s:
        return (net - max(0.0, min(S, k2) - k1)) * 100
    if "put credit" in s:
        return (net - max(0.0, k1 - max(S, k2))) * 100
    if "cash-secured put" in s or "csp" in s:
        return (net - max(0.0, k1 - S)) * 100
    if "debit" in s:                      # long k1 / short k2
        return (max(0.0, min(S, k2) - k1) - net) * 100
    return 0.0


def _settle_recs(conn):
    """Settle any OPEN recommendation whose expiry has passed, against the real close.

    Was never implemented: hiprob_recs shipped with status/settle_px/pnl columns but
    nothing ever wrote them, so every rec sat 'OPEN' forever and the track record was
    unmeasurable (user 2026-07-21: "I asked you created an indicator to show performance
    of recommendations, is it not done").
    """
    today = _et_now().date().isoformat()
    n = 0
    try:
        rows = conn.execute(
            "SELECT rec_id, ticker, strategy, k1, k2, net, expiry FROM hiprob_recs "
            "WHERE (status IS NULL OR status='OPEN') AND expiry <= ?", (today,)).fetchall()
        for rid, tk, strat, k1, k2, net, exp in rows:
            px = conn.execute(
                "SELECT close FROM stock_history WHERE ticker=? AND trade_date<=? "
                "ORDER BY trade_date DESC LIMIT 1", (tk, exp)).fetchone()
            if not px or not px[0]:
                continue                       # no settle price yet — leave OPEN, retry later
            S = float(px[0])
            pnl = _rec_payoff(strat, float(k1 or 0), float(k2 or 0), float(net or 0), S)
            conn.execute("UPDATE hiprob_recs SET status='SETTLED', settle_px=?, pnl=? "
                         "WHERE rec_id=?", (S, pnl, rid))
            n += 1
        conn.commit()
    except Exception as e:
        log.warning(f"_settle_recs failed: {e}")
    return n


def _recs_performance(conn, limit_open=1000):
    """Track record: SETTLED results + mark-to-market on still-open recs.

    MTM matters because nothing has expired yet — settlement alone would report nothing.
    Open positions are marked with real OpenBB quotes (cost-to-close), not a model.
    """
    _recs_ensure_src(conn)
    _settle_recs(conn)
    out = {"settled": [], "open": [], "bf_settled": [], "bf_open": [],
           "asof": _et_now().strftime("%Y-%m-%d %H:%M ET")}
    for rid, tk, strat, k1, k2, net, exp, st, spx, pnl, src in conn.execute(
            "SELECT rec_id,ticker,strategy,k1,k2,net,expiry,status,settle_px,pnl,"
            "COALESCE(src,'LIVE') FROM hiprob_recs ORDER BY rec_id DESC LIMIT ?", (limit_open,)):
        k1 = float(k1 or 0); k2 = float(k2 or 0); net = float(net or 0)
        # reconstructed recs were never actually issued — kept in their own buckets so the
        # headline track record stays a record of real calls, not of hindsight
        bf = (src == "BACKFILL")
        if st == "SETTLED" and pnl is not None:
            out["bf_settled" if bf else "settled"].append(
                {"tk": tk, "strat": strat, "pnl": float(pnl)})
            continue
        try:                                   # mark-to-market from real BB quotes
            is_put = "put" in (strat or "").lower()
            typ = "put" if is_put else "call"
            q1 = _bb_quote(conn, tk, k1, str(exp)[:10], typ) if k1 else None
            q2 = _bb_quote(conn, tk, k2, str(exp)[:10], typ) if k2 else None
            m1 = float((q1 or {}).get("mid") or 0)
            m2 = float((q2 or {}).get("mid") or 0)
            if not m1:
                continue
            cost_to_close = m1 - m2            # spread; m2=0 for a naked CSP
            mtm = ((net - cost_to_close) if "debit" not in (strat or "").lower()
                   else (cost_to_close - net)) * 100
            out["bf_open" if bf else "open"].append(
                {"tk": tk, "strat": strat, "mtm": mtm, "exp": str(exp)[:10]})
        except Exception:
            log.debug("rec MTM failed", exc_info=True)
    return out


def _recs_perf_report(conn):
    d = _recs_performance(conn)
    se, op = d["settled"], d["open"]
    bse, bop = d.get("bf_settled") or [], d.get("bf_open") or []
    if not se and not op and not bse and not bop:
        return "No recommendations recorded yet."
    parts = [hdr("📊 RECOMMENDATION TRACK RECORD")]
    rows = []
    if se:
        w = sum(1 for r in se if r["pnl"] > 0)
        rows.append(("✅", "Settled", str(len(se)), f"{w/len(se)*100:.0f}%"))
        rows.append(("💵", "Net P&L", f"${sum(r['pnl'] for r in se):,.0f}", ""))
    if op:
        w = sum(1 for r in op if r["mtm"] > 0)
        rows.append(("⏳", "Open (MTM)", str(len(op)), f"{w/len(op)*100:.0f}%"))
        rows.append(("📈", "Unrealised", f"${sum(r['mtm'] for r in op):,.0f}", ""))
    parts.append(_pipe_table(("", "Metric", "Value", "Win%"), rows, right_cols={2, 3}))
    # per-strategy breakdown on the marked book
    if op:
        agg = {}
        for r in op:
            a = agg.setdefault(r["strat"][:22], [0, 0.0])
            a[0] += 1; a[1] += r["mtm"]
        srows = [("🟢" if v[1] > 0 else "🔴", k[:18], str(v[0]), f"{v[1]:+,.0f}")
                 for k, v in sorted(agg.items(), key=lambda x: -x[1][1])]
        parts.append("\n<b>By strategy (open, marked to market)</b>")
        parts.append(_pipe_table(("", "Strategy", "#", "P&L$"), srows, right_cols={2, 3}))
    if bse or bop:                             # reconstructed — NOT part of the track record
        brows = []
        if bse:
            w = sum(1 for r in bse if r["pnl"] > 0)
            brows.append(("✅", "Settled", str(len(bse)), f"{w/len(bse)*100:.0f}%"))
        if bop:
            w = sum(1 for r in bop if r["mtm"] > 0)
            brows.append(("⏳", "Open (MTM)", str(len(bop)), f"{w/len(bop)*100:.0f}%"))
            brows.append(("📈", "Unrealised", f"${sum(r['mtm'] for r in bop):,.0f}", ""))
        parts.append("\n<b>Reconstructed history (hindsight — not a track record)</b>")
        parts.append(_pipe_table(("", "Metric", "Value", "Win%"), brows, right_cols={2, 3}))
    parts.append(f"<i>As of {d['asof']}. Open legs marked with real OpenBB quotes "
                 f"(cost-to-close), settled rows against the actual close at expiry. "
                 f"Educational, not advice.</i>")
    return "\n".join(parts)


async def recperf_cmd(update, ctx):
    conn = get_conn()
    try:
        msg = _recs_perf_report(conn)
    except Exception as e:
        log.warning(f"recperf: {e}"); msg = "⚠️ Track-record error — try again."
    finally:
        conn.close()
    await _safe_reply(update.message, msg)


def _freq_kb(cur):
    """Inline keyboard for /freq — position-alert cadence picker."""
    opts = [("Auto", 0), ("5 min", 5), ("10 min", 10), ("15 min", 15),
            ("30 min", 30), ("60 min", 60)]
    row, rows = [], []
    for lbl, v in opts:
        mark = "✅ " if v == cur else ""
        row.append(InlineKeyboardButton(f"{mark}{lbl}", callback_data=f"freq|{v}"))
        if len(row) == 3:
            rows.append(row); row = []
    if row:
        rows.append(row)
    return InlineKeyboardMarkup(rows)


async def freq_cmd(update, ctx):
    """/freq [MIN] — how often the position monitor pushes to Telegram.

    Auto = the built-in default (10 min in RTH, 15 min after hours). A number pins one
    interval for both sessions. The job ticks every 5 min, so 5 is the finest resolution.
    """
    conn = get_conn()
    try:
        args = list(getattr(ctx, "args", []) or [])
        if args:
            try:
                v = max(0, int(args[0]))
                _set_app_setting(conn, "pos_alert_freq_min", v)
                _lbl = "Auto (10m RTH / 15m AH)" if v == 0 else f"every {v} min"
                await _safe_reply(update.message, f"⏱ Position alerts: <b>{_lbl}</b>.")
                return
            except ValueError:
                pass
        cur = int(float(_app_setting(conn, "pos_alert_freq_min", "0") or 0))
        _lbl = "Auto (10m RTH / 15m AH)" if cur == 0 else f"every {cur} min"
        await _safe_reply(update.message,
                          f"⏱ <b>Position-alert frequency</b>\nCurrently: <b>{_lbl}</b>\n"
                          "<i>Pick how often the monitor pushes your positions:</i>",
                          reply_markup=_freq_kb(cur))
    finally:
        conn.close()


def _reopen_trade(conn, trade_id):
    """Undo a close: put the row back to OPEN and clear every exit field.

    Mirrors the dashboard's Re-open button so an accidental close is reversible from
    wherever it happened (user 2026-07-22 closed AMD 640/680C by mistake). Leaves an audit
    note on the row rather than pretending the close never occurred.
    """
    row = conn.execute("SELECT ticker, option_type, strike, expiry, status FROM trades "
                       "WHERE trade_id=?", (trade_id,)).fetchone()
    if not row:
        return None, f"No trade with id {trade_id}."
    tk, ot, k, exp, st = row
    label = (f"{tk} {str(ot).upper()} ${float(k or 0):g} exp {str(exp)[:10]}"
             if str(ot).upper() != "STOCK" else f"{tk} STOCK")
    if str(st).upper() == "OPEN":
        return None, f"{label} (id {trade_id}) is already OPEN."
    conn.execute(
        "UPDATE trades SET status='OPEN', exit_date=NULL, exit_time=NULL, exit_price=NULL, "
        "exit_reason=NULL, pnl=NULL, pnl_pct=NULL, days_held=NULL, updated_at=?, "
        "notes=COALESCE(notes,'')||? WHERE trade_id=?",
        (datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
         f" | reopened {datetime.now().strftime('%Y-%m-%d')}", trade_id))
    conn.commit()
    return label, f"↩️ Reopened <b>{label}</b> (id {trade_id})."


async def reopen_cmd(update, ctx):
    """/reopen [trade_id] — undo an accidental close. No id lists what can be reopened."""
    args = list(getattr(ctx, "args", []) or [])
    conn = get_conn()
    try:
        if not args:
            rows = conn.execute(
                "SELECT trade_id, ticker, option_type, strike, expiry, exit_date, pnl "
                "FROM trades WHERE status='CLOSED' ORDER BY COALESCE(exit_date,'') DESC, "
                "trade_id DESC LIMIT 12").fetchall()
            if not rows:
                await _safe_reply(update.message, "No closed positions to reopen.")
                return
            trs = [(str(t), f"{tk} {str(ot).upper()[:1]}{float(k or 0):g}"
                    if str(ot).upper() != "STOCK" else f"{tk} STK",
                    str(xd or "")[5:10], f"{(p or 0):+,.0f}") for t, tk, ot, k, _e, xd, p in rows]
            await _safe_reply(update.message, _report(
                "↩️ REOPEN — recently closed", ("Id", "Leg", "Exit", "P&L"), trs,
                right_cols={3}, legend="Send /reopen <Id> to restore one",
                notes="Reopening clears the exit price and P&L for that leg."))
            return
        try:
            tid = int(str(args[0]).strip())
        except ValueError:
            await _safe_reply(update.message, "Usage: <code>/reopen 76</code>")
            return
        label, msg = _reopen_trade(conn, tid)
        await _safe_reply(update.message, msg)
    except Exception as e:
        log.warning(f"reopen_cmd failed: {e}", exc_info=True)
        await _safe_reply(update.message, "⚠️ Reopen failed — check the id with /reopen.")
    finally:
        conn.close()


def _spread_summary(rows):
    """Group paired legs into spreads and report COMBINED economics + exit timing.

    The per-leg card advises each leg in ISOLATION, which is dangerous on a vertical:
    "CUT LOSS" on the long leg of a credit spread leaves a NAKED SHORT with unbounded
    risk. This pairs opposite-sign legs on the same (ticker, expiry, right) and reports
    net debit/credit, combined P&L, max profit/loss, and how much of max is captured —
    which is what actually drives "sell early vs hold to expiry".
    """
    from collections import defaultdict
    grp = defaultdict(list)
    for r in rows:
        otype, strike, qty = str(r[2]).upper(), r[3], int(r[12] or 0)
        if otype.startswith("STOCK") or not strike or not qty:
            continue
        grp[(r[1], r[13], otype[:1])].append(r)

    blocks, tbl = [], []
    for (tk, exp, ot), legs in grp.items():
        longs = [l for l in legs if int(l[12] or 0) > 0]
        shorts = [l for l in legs if int(l[12] or 0) < 0]
        if not (longs and shorts):
            continue                                   # not a spread — leave to per-leg advice
        L, S = longs[0], shorts[0]
        n = min(abs(int(L[12])), abs(int(S[12])))
        KL, KS = float(L[3]), float(S[3])
        width = abs(KL - KS)
        net_entry = float(L[4]) - float(S[4])          # +debit / -credit, per share
        pnl = sum(float(l[7] or 0) for l in legs)
        if net_entry > 0:
            kind, maxp, maxl = "DEBIT", (width - net_entry) * n * 100, net_entry * n * 100
        else:
            cr = -net_entry
            kind, maxp, maxl = "CREDIT", cr * n * 100, (width - cr) * n * 100
        pct = (pnl / maxp * 100) if maxp > 0 else 0.0
        name = ({("P", True): "Bear Put", ("P", False): "Bull Put",
                 ("C", True): "Bear Call", ("C", False): "Bull Call"}
                .get((ot, KL > KS), "Vertical"))
        st = "🟢" if pct >= 50 else ("🟡" if pnl >= 0 else "🔴")
        # exit guidance: credit spreads are conventionally managed at 50-75% of max
        if pct >= 50:
            act = "TAKE PROFIT"
        elif pnl < 0 and maxl > 0 and abs(pnl) >= 0.5 * maxl:
            act = "REVIEW"
        else:
            act = "HOLD"
        # Net-debit/credit COMBO limit + work-down ladder (PLAN.md A4, 2026-07-24): the old
        # advice only said TAKE PROFIT/HOLD in prose with no actual order to place. Combo
        # current value = long leg's price minus short leg's price (closing a debit spread
        # means SELLING the combo, closing a credit spread means BUYING it back) — priced
        # like a single order 1/3 into the spread from the favorable side, then two more
        # rungs stepping toward the marketable price if unfilled, same edge-over-marketable
        # logic as _smart_close_limit (dashboard.py A3) applied to the whole combo at once.
        # close_value uses the SAME sign convention as net_entry (long leg price minus short
        # leg price): positive = you'd receive money selling the combo, negative = you'd need
        # to pay to close it. A debit spread's close_value is normally >=0 (sell for proceeds);
        # a credit spread's is normally <=0, so the actual cash needed to buy it back is
        # -close_value (caught in testing: using close_value directly for credit spreads gave
        # a nonsensical near-zero/negative price after clamping).
        close_value = float(L[5]) - float(S[5])
        _edge = max(0.05, round(width * 0.10, 2))
        if net_entry > 0:      # DEBIT spread: closing SELLS the combo — ask for MORE than mid first
            _rungs = [max(close_value + _edge, 0.01), max(close_value + _edge / 2, 0.01), max(close_value, 0.01)]
            _combo_line = (f"Close: SELL combo, work ${_rungs[0]:.2f} → ${_rungs[1]:.2f} → "
                           f"${_rungs[2]:.2f} (marketable) · collect ${_rungs[0]*n*100:,.0f}"
                           f"→${_rungs[2]*n*100:,.0f}")
        else:                  # CREDIT spread: closing BUYS the combo back — offer LESS than mid first
            _buy_cost = -close_value
            _rungs = [max(_buy_cost - _edge, 0.01), max(_buy_cost - _edge / 2, 0.01), max(_buy_cost, 0.01)]
            _combo_line = (f"Close: BUY combo, work ${_rungs[0]:.2f} → ${_rungs[1]:.2f} → "
                           f"${_rungs[2]:.2f} (marketable) · pay ${_rungs[0]*n*100:,.0f}"
                           f"→${_rungs[2]*n*100:,.0f}")
        # ONE row per spread: everything that drove the old 5-line block (user 2026-07-23 —
        # "make it a table"). Net/MaxP/MaxL/%Max/action all inline; the paired-leg warning is
        # identical for every spread so it is printed ONCE under the table, not per row.
        tbl.append((st, f"{tk[:4]}{int(min(KL,KS))}/{int(max(KL,KS))}{ot}",
                    f"{pnl:+,.0f}", f"{pct:+.0f}%"))
        # Net/max/action as ONE compact line per spread — keeping them as table columns
        # pushed the grid to ~48 chars and it WRAPPED on mobile (user screenshot 2026-07-23);
        # CLAUDE.md caps Telegram <pre> at ~28 chars.
        blocks.append(f"<b>{tk[:4]}{int(min(KL,KS))}/{int(max(KL,KS))}{ot}</b> {act} · "
                      f"net ${abs(net_entry)*n*100:,.0f} · max +${maxp:,.0f}/-${maxl:,.0f}\n"
                      f"  {_combo_line}")
    if not blocks:
        return ""
    head = _pipe_table(("ST", "Spread", "P&L", "%Max"), tbl, right_cols={2, 3},
                       title="🔗 PAIRED / HEDGED POSITIONS")
    return (head + "\n" + "\n".join(blocks)
            + "\n⚠️ <i>All PAIRED — close both legs together; one leg alone leaves a naked "
              "short (credit) or unhedged long (debit).</i>")


def _atm_iv_term(conn, tk, spot):
    """{expiry_iso: ATM IV} for `tk` from the latest OpenBB capture — the IV term structure.

    Used to size event premium empirically instead of guessing a haircut: an expiry that
    straddles earnings prices the event's whole move into a short window, so its ATM IV sits
    above expiries far enough out that the same event is a small share of total variance.
    """
    out = {}
    if not spot or spot <= 0:
        return out
    try:
        rows = conn.execute(
            "SELECT expiry_date, strike, iv_Call, iv_Put FROM options_openbb "
            "WHERE ticker=? AND trade_date=(SELECT MAX(trade_date) FROM options_openbb "
            "WHERE ticker=?)", (tk, tk)).fetchall()
    except Exception:
        log.debug("atm_iv_term query failed", exc_info=True)
        return out
    best = {}
    for exp, k, ivc, ivp in rows:
        try:
            k = float(k or 0)
            if k <= 0:
                continue
            ivs = [float(x) for x in (ivc, ivp) if x and float(x) > 0]
            if not ivs:
                continue
            d = abs(k - spot)
            e = _exp_iso(exp)
            if e not in best or d < best[e][0]:
                best[e] = (d, sum(ivs) / len(ivs))
        except (TypeError, ValueError):
            continue
    return {e: v[1] for e, v in best.items()}


_SI_CACHE = {}                 # ticker -> (fetched_ts, dict) — .info is slow, SI moves 2x/month


TRANSCRIPT_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "transcripts")


def _tx_ensure(conn=None):
    """Transcripts live on DISK, not in SQLite (user 2026-07-23).

    AlphaVantage's EARNINGS_CALL_TRANSCRIPT works on the key we ALREADY hold (verified:
    TSLA 2026Q1 = 61 segments / 38k chars), and the free tier is rate-limited (~25/day),
    so each call is fetched once and kept forever. But a 38 KB text blob per call belongs
    in a file, not a row: it would bloat the 2.35 GB DB, slow VACUUM/backups, and is never
    queried relationally. Layout per call:
        transcripts/TICKER_QUARTER.txt   full text
        transcripts/TICKER_QUARTER.json  metadata + extracted highlights (small, fast)
    `conn` is accepted and ignored so existing call sites keep working.
    """
    try:
        os.makedirs(TRANSCRIPT_DIR, exist_ok=True)
    except Exception:
        log.debug("transcript dir create failed", exc_info=True)


def _tx_paths(tk, quarter):
    base = os.path.join(TRANSCRIPT_DIR, f"{str(tk).upper()}_{quarter}")
    return base + ".txt", base + ".json"


_TX_GUIDE_KW = ("guidance", "outlook", "we expect", "we anticipate", "next quarter",
                "full year", "full-year", "margin", "capex", "capital expenditure",
                "demand", "headwind", "tailwind", "we forecast", "target")


def _tx_highlights(segments, limit=6):
    """Pull the sentences that actually move a stock: forward-looking statements from
    management. A 40k-char transcript cannot go in a Telegram card, and the market does not
    trade the pleasantries — it trades guidance. Operator/analyst chatter is skipped."""
    out = []
    for seg in segments or []:
        who = str(seg.get("speaker") or "")
        title = str(seg.get("title") or "").lower()
        # Skip the operator and Investor-Relations hosts: they read the disclaimer and relay
        # analyst questions, so they match the keywords without ever saying anything the
        # market trades on ("The next question is: what milestones are you targeting...").
        if who.lower().startswith("operator") or "investor relations" in title:
            continue
        body = str(seg.get("content") or "")
        for sent in re.split(r"(?<=[.!?])\s+", body):
            s = sent.strip()
            if not (40 <= len(s) <= 240):
                continue
            if s.endswith("?") or s.lower().startswith(("the next question",
                                                        "and what", "what are", "how ")):
                continue                    # a question is not guidance
            if "forward-looking statement" in s.lower():
                continue                    # boilerplate disclaimer
            if any(k in s.lower() for k in _TX_GUIDE_KW):
                out.append(f"{who.split()[0] if who else '?'}: {s}")
                break                       # one per segment keeps speakers varied
        if len(out) >= limit:
            break
    return out


def _tx_fetch(symbol, quarter):
    """(segments, raw) for one ticker-quarter from AlphaVantage; ([], None) if unavailable."""
    import urllib.request, json as _json
    key = os.environ.get("ALPHAVANTAGE_KEY") or os.environ.get("ALPHA_VANTAGE_KEY")
    if not key:
        return [], None
    try:
        u = ("https://www.alphavantage.co/query?function=EARNINGS_CALL_TRANSCRIPT"
             f"&symbol={symbol}&quarter={quarter}&apikey={key}")
        with urllib.request.urlopen(u, timeout=30) as r:
            d = _json.loads(r.read().decode())
        # AlphaVantage answers a throttle with 200 + a Note/Information body and NO
        # transcript key. Without this the caller cannot tell "rate limited" from "no such
        # call" and silently stores nothing (observed 2026-07-23: a 9-call burst returned
        # zero transcripts while the same call in isolation returned 61 segments).
        if isinstance(d, dict) and not d.get("transcript"):
            msg = d.get("Note") or d.get("Information") or d.get("Error Message")
            if msg:
                log.warning(f"AlphaVantage throttled/err on {symbol} {quarter}: {str(msg)[:120]}")
                return [], {"_throttled": True}
        return (d.get("transcript") or []), d
    except Exception:
        log.warning(f"transcript fetch {symbol} {quarter} failed", exc_info=True)
        return [], None


def _tx_capture(conn, tickers, quarters=None, budget=6):
    """Store any missing ticker-quarter transcripts, POSITION TICKERS FIRST.

    AlphaVantage free tier is ~25 requests/day and ~5/min, so this runs in tranches
    (user 2026-07-23): `tickers` is consumed in order — callers pass open-position names
    first — and `budget` caps fetches per run so one sweep can never burn the day's quota.
    Quarters already stored are skipped, so each daily run naturally advances to new ground.
    """
    _tx_ensure(conn)
    if not quarters:
        # MOST RECENTLY REPORTED quarter only — go forward, do not backfill history
        # (user 2026-07-23). Backfilling every prior quarter would burn the ~25/day
        # AlphaVantage quota for calls that have already been priced in.
        #
        # BUG FOUND 2026-07-24 (user: "earning call is not latest"): this used to compute
        # the CALENDAR quarter still in progress (e.g. "2026Q3" in July 2026) instead of the
        # quarter that just FINISHED and reported (Q2, reported ~July). A quarter's earnings
        # call doesn't happen until weeks after that quarter ends, so the in-progress quarter
        # never has a transcript to fetch -- this was silently failing every single day,
        # forever, never catching up to the real latest transcript. Fixed: target the PRIOR
        # completed quarter, with year wraparound for Q1 (previous quarter = prior year Q4).
        _n = _et_now()
        _prev_q = (_n.month - 1) // 3
        quarters = [f"{_n.year - 1}Q4"] if _prev_q == 0 else [f"{_n.year}Q{_prev_q}"]
    import json as _json
    n = fetched = 0
    for tk in dict.fromkeys(str(t).upper() for t in tickers if t):
        for q in quarters:
            if fetched >= budget:
                log.info(f"_tx_capture: budget {budget} reached — resuming next run")
                return n
            _txtp, _jsonp = _tx_paths(tk, q)
            if os.path.exists(_jsonp):
                continue                    # already on disk — never spend quota twice
            fetched += 1
            segs, _raw = _tx_fetch(tk, q)
            if not segs:
                if isinstance(_raw, dict) and _raw.get("_throttled"):
                    time.sleep(15)          # free tier is ~5 req/min — back off, keep the quota
                continue
            time.sleep(13)                  # pace under the 5-req/min free-tier ceiling
            txt = " ".join(str(s.get("content") or "") for s in segs)
            hl = _tx_highlights(segs)
            try:
                with io.open(_txtp, "w", encoding="utf-8") as f:
                    f.write(txt)
                with io.open(_jsonp, "w", encoding="utf-8") as f:
                    _json.dump({"ticker": tk, "quarter": q, "n_segments": len(segs),
                                "n_chars": len(txt), "highlights": hl,
                                "captured_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S")},
                               f, indent=1)
                n += 1
            except Exception:
                log.warning(f"transcript write failed {tk} {q}", exc_info=True)
    return n


def _tx_latest(conn, tk):
    """(quarter, highlights_text) for the newest transcript ON DISK, or None.
    Reads the small .json sidecar — never the 38 KB full text."""
    import json as _json, glob as _glob
    _tx_ensure()
    try:
        files = sorted(_glob.glob(os.path.join(TRANSCRIPT_DIR, f"{str(tk).upper()}_*.json")))
        if not files:
            return None
        with io.open(files[-1], encoding="utf-8") as f:      # quarters sort lexically
            d = _json.load(f)
        hl = d.get("highlights") or []
        return (d.get("quarter"), "\n".join(hl)) if hl else None
    except Exception:
        log.debug(f"transcript read {tk} failed", exc_info=True)
        return None


async def record_transcripts(context=None):
    """Daily transcript capture for the open book (quota-friendly: skips stored quarters)."""
    try:
        conn = get_conn()
        # tranche order: open positions first, index proxies after — if the budget runs out
        # it runs out on names we do not hold.
        _pos = [r[0] for r in conn.execute(
            "SELECT DISTINCT UPPER(ticker) FROM trades WHERE status='OPEN' "
            "AND UPPER(option_type)<>'STOCK'").fetchall()]
        n = _tx_capture(conn, _pos + [t for t in _hiprob_default_tickers() if t not in _pos])
        conn.close()
        log.info(f"record_transcripts: stored {n} new transcripts")
        return n
    except Exception as e:
        log.warning(f"record_transcripts failed: {e}", exc_info=True)
        return 0


def _earn_ensure(conn):
    """Earnings expectations vs actuals. yfinance carries the consensus EPS estimate, the
    reported EPS and the surprise % per quarter — the single most explanatory number for a
    post-earnings move (TSLA 2026-07-22: $0.33 vs $0.54 est = -38% miss -> -5.8% AH). It is
    NOT retained indefinitely upstream, so capture it; a stored history also lets us backtest
    'does a beat/miss predict the drift' later."""
    conn.execute("""CREATE TABLE IF NOT EXISTS earnings_history(
        ticker TEXT, earn_date TEXT, eps_est REAL, eps_actual REAL, surprise_pct REAL,
        captured_at TEXT, PRIMARY KEY (ticker, earn_date))""")
    conn.commit()


def _earn_capture(conn, tickers, limit=12):
    """Store estimate/actual/surprise per quarter. Idempotent on (ticker, earn_date):
    a future quarter lands estimate-only and is filled in once it reports."""
    _earn_ensure(conn)
    n = 0
    for tk in dict.fromkeys(str(t).upper() for t in tickers if t):
        try:
            d = _yf_ticker(tk).get_earnings_dates(limit=limit)
        except Exception:
            log.debug(f"earnings dates {tk} failed", exc_info=True)
            continue
        if d is None or not len(d):
            continue
        for ts, row in d.iterrows():
            try:
                ed = pd.Timestamp(ts).date().isoformat()
                _g = lambda k: (None if pd.isna(row.get(k)) else float(row.get(k)))
                conn.execute(
                    "INSERT OR REPLACE INTO earnings_history "
                    "(ticker,earn_date,eps_est,eps_actual,surprise_pct,captured_at) "
                    "VALUES (?,?,?,?,?,?)",
                    (tk, ed, _g("EPS Estimate"), _g("Reported EPS"), _g("Surprise(%)"),
                     datetime.now().strftime("%Y-%m-%d %H:%M:%S")))
                n += 1
            except Exception:
                continue
    conn.commit()
    return n


def _earn_context(conn, tk):
    """(last_reported, next_expected) for the card. last = most recent quarter WITH an
    actual; next = nearest future date carrying only an estimate."""
    _earn_ensure(conn)
    today = _et_now().date().isoformat()
    last = conn.execute(
        "SELECT earn_date,eps_est,eps_actual,surprise_pct FROM earnings_history "
        "WHERE ticker=? AND eps_actual IS NOT NULL ORDER BY earn_date DESC LIMIT 1",
        (tk,)).fetchone()
    nxt = conn.execute(
        "SELECT earn_date,eps_est FROM earnings_history WHERE ticker=? AND earn_date>? "
        "AND eps_actual IS NULL ORDER BY earn_date LIMIT 1", (tk, today)).fetchone()
    return last, nxt


async def record_earnings_history(context=None):
    """Daily capture of earnings estimates/actuals for the open book + index proxies."""
    try:
        conn = get_conn()
        n = _earn_capture(conn, _hiprob_default_tickers())
        conn.close()
        log.info(f"record_earnings_history: stored {n} rows")
        return n
    except Exception as e:
        log.warning(f"record_earnings_history failed: {e}", exc_info=True)
        return 0


def _si_ensure(conn):
    """short_interest history table. Exchanges publish SI TWICE MONTHLY with a ~2 week lag,
    and yfinance exposes only `current` + `prior month`. Daily capture (record_short_interest)
    keeps this current going forward; the full ~1yr backfill (_si_fetch_history/_si_backfill,
    2026-07-30, docs/PLAN.md A18) came from Nasdaq's free public API instead of waiting months
    for live accrual -- see _si_read for the resulting (null) backtest finding."""
    conn.execute("""CREATE TABLE IF NOT EXISTS short_interest(
        ticker TEXT, asof_date TEXT, captured_at TEXT,
        shares_short REAL, shares_short_prior REAL, short_ratio REAL,
        pct_float REAL, float_shares REAL, avg_volume REAL,
        PRIMARY KEY (ticker, asof_date))""")
    conn.commit()


def _si_fetch(ticker, max_age=21600):
    """Raw short-interest fields for one ticker (yfinance .info, cached 6h)."""
    tk = str(ticker).upper()
    hit = _SI_CACHE.get(tk)
    now = time.time()
    if hit and (now - hit[0]) < max_age:
        return hit[1]
    try:
        info = _yf_ticker(tk).info or {}
    except Exception:
        log.warning(f"_si_fetch({tk}) failed", exc_info=True)
        return None
    ss, sp = info.get("sharesShort"), info.get("sharesShortPriorMonth")
    if not ss:
        _SI_CACHE[tk] = (now, None)
        return None
    asof = info.get("dateShortInterest")
    try:
        asof = (datetime.utcfromtimestamp(int(asof)).date().isoformat() if asof else "")
    except Exception:
        asof = ""
    d = {"ticker": tk, "asof": asof, "shares_short": float(ss),
         "shares_short_prior": float(sp) if sp else None,
         "short_ratio": info.get("shortRatio"),
         "pct_float": info.get("shortPercentOfFloat"),
         "float_shares": info.get("floatShares"),
         "avg_volume": info.get("averageVolume")}
    if not d["pct_float"] and d["float_shares"]:
        d["pct_float"] = d["shares_short"] / float(d["float_shares"])
    if not d["short_ratio"] and d["avg_volume"]:
        d["short_ratio"] = d["shares_short"] / float(d["avg_volume"])
    _SI_CACHE[tk] = (now, d)
    return d


def _si_read(d):
    """Rule-based short-interest read. Returns dict or None.

    Thresholds are the published conventions, not invented ones:
      days-to-cover  <2 low · 2-5 moderate · 5-7 high · >7 extreme
      % of float     <5 low · 5-10 elevated · 10-20 high · >20 extreme
    Direction is month-over-month share count: >+10% BUILDING, <-10% COVERING.

    BACKTESTED 2026-07-30 (docs/PLAN.md A18): the "no history yet" blocker was real for
    live daily accrual, but a full ~1yr settlement-date series was backfilled for free via
    Nasdaq's public short-interest API (_si_fetch_history) instead of waiting months.
    Result: N=1462 (64 tickers x 23 dates), SI %-change vs fwd 10-trading-day return,
    rank-IC +0.017 (t=+0.65, p=0.52) -- NO meaningful edge. BUILDING (SI up >5%, N=476)
    averaged +1.36% fwd vs COVERING (SI down >5%, N=349) +1.13% -- both close to the
    unconditional baseline (+1.55%), no real separation. Same "no directional edge" verdict
    as /building and /uoa (see below) -- keep this a DESCRIPTIVE read (crowding/squeeze-risk
    context), never a directional signal.
    """
    if not d or not d.get("shares_short"):
        return None
    ss, sp = d["shares_short"], d.get("shares_short_prior")
    chg = ((ss - sp) / sp) if (sp and sp > 0) else None
    dtc = float(d["short_ratio"] or 0)
    pf = float(d["pct_float"] or 0) * 100.0
    if chg is None:
        state = "—"
    elif chg > 0.10:
        state = "BUILDING"
    elif chg < -0.10:
        state = "COVERING"
    else:
        state = "STABLE"
    crowd = ("extreme" if pf > 20 else "high" if pf > 10 else
             "elevated" if pf > 5 else "low")
    cover = ("extreme" if dtc > 7 else "high" if dtc > 5 else
             "moderate" if dtc > 2 else "low")
    # 0-100 squeeze-fuel score: how much short stock exists (crowding) x how hard it is to
    # buy back (days-to-cover), nudged by whether shorts are still adding.
    score = 0.45 * min(pf / 20.0, 1.0) * 100 + 0.40 * min(dtc / 7.0, 1.0) * 100
    if chg is not None:
        score += 0.15 * max(min(chg / 0.20, 1.0), -1.0) * 100
    return {"state": state, "chg": chg, "dtc": dtc, "pct_float": pf,
            "crowd": crowd, "cover": cover, "score": max(0.0, min(100.0, score)),
            "asof": d.get("asof", "")}


def _si_capture(conn, tickers):
    """Persist today's short-interest snapshot for `tickers` (idempotent per asof_date)."""
    _si_ensure(conn)
    n = 0
    for tk in dict.fromkeys(str(t).upper() for t in tickers if t):
        d = _si_fetch(tk)
        if not d or not d.get("asof"):
            continue
        conn.execute(
            "INSERT OR REPLACE INTO short_interest (ticker,asof_date,captured_at,shares_short,"
            "shares_short_prior,short_ratio,pct_float,float_shares,avg_volume) "
            "VALUES (?,?,?,?,?,?,?,?,?)",
            (d["ticker"], d["asof"], datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
             d["shares_short"], d["shares_short_prior"], d["short_ratio"],
             d["pct_float"], d["float_shares"], d["avg_volume"]))
        n += 1
    conn.commit()
    return n


def _si_fetch_history(ticker, max_rows=40):
    """Full historical settlement-date short-interest series for one ticker, via Nasdaq's
    public keyless API (docs/PLAN.md A18: yfinance only exposes current+prior month, which
    is why the backtest was blocked on live accrual -- this endpoint gives ~1yr of real
    bi-monthly settlement history in one call, unblocking it immediately instead of waiting
    months). Returns [(asof_iso, shares_short, days_to_cover)] oldest-first, or [] on failure.
    """
    import urllib.request, json as _json
    tk = str(ticker).upper()
    try:
        req = urllib.request.Request(
            f"https://api.nasdaq.com/api/quote/{tk}/short-interest?assetclass=stocks",
            headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=12) as r:
            d = _json.loads(r.read().decode())
        rows = ((d.get("data") or {}).get("shortInterestTable") or {}).get("rows") or []
        out = []
        for row in rows[:max_rows]:
            try:
                m, day, y = row["settlementDate"].split("/")
                asof = f"{y}-{m}-{day}"
                shares = float(str(row["interest"]).replace(",", ""))
                dtc = float(row["daysToCover"])
                out.append((asof, shares, dtc))
            except Exception:
                continue
        return list(reversed(out))   # oldest-first
    except Exception:
        log.debug(f"_si_fetch_history({tk}) failed", exc_info=True)
        return []


def _si_backfill(conn, tickers):
    """One-time historical backfill of `short_interest` from _si_fetch_history -- turns the
    2-3-months-of-live-accrual blocker (A18) into an immediately-testable ~1yr history.
    Idempotent (INSERT OR REPLACE on the (ticker, asof_date) PK), safe to re-run."""
    _si_ensure(conn)
    n = 0
    for tk in dict.fromkeys(str(t).upper() for t in tickers if t):
        hist = _si_fetch_history(tk)
        prior = None
        for asof, shares, dtc in hist:
            conn.execute(
                "INSERT OR REPLACE INTO short_interest (ticker,asof_date,captured_at,shares_short,"
                "shares_short_prior,short_ratio,pct_float,float_shares,avg_volume) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                (tk, asof, datetime.now().strftime("%Y-%m-%d %H:%M:%S"), shares, prior,
                 dtc, None, None, None))
            prior = shares
            n += 1
    conn.commit()
    return n


async def record_short_interest(context=None):
    """Daily short-interest snapshot for the open book + index proxies.

    SI only changes twice a month, but capturing daily is cheap (cached 6h) and means the
    `asof_date` transition is caught the day it publishes. Universe is kept small on purpose:
    .info is a per-ticker network call, so this is the open positions plus SPY/QQQ/IWM, not
    all 734 names.
    """
    try:
        conn = get_conn()
        tks = _hiprob_default_tickers()          # open-position tickers + SPY/QQQ/IWM
        n = _si_capture(conn, tks)
        conn.close()
        log.info(f"record_short_interest: stored {n} snapshots")
        return n
    except Exception as e:
        log.warning(f"record_short_interest failed: {e}", exc_info=True)
        return 0


_LIVE_CHAIN_CACHE = {}         # (tk, expiry) -> (epoch, {(strike, typ): mid})


def _live_opt_mid(tk, strike, typ, expiry_s, max_age=90):
    """REAL market mid for one contract during RTH — no model.

    A model is only needed when options are not trading. During regular hours a live quote
    exists and is strictly better: the card was BS-repricing off a captured (stale) IV and
    printing GOOG 300P at 6.99 while the market said 6.10 (user 2026-07-23: "during live
    hours show real price, why to calculate").

    ONE chain download per (ticker, expiry), cached 90s and shared across every leg on that
    expiry — which is why the old per-leg download was too slow to leave on.
    Returns None outside RTH or when the contract is not quoted, so callers fall back to the
    BS reprice (correct after hours, when the option market is shut).
    """
    try:
        _n = _et_now()
        _t = _n.hour * 60 + _n.minute
        if _n.weekday() >= 5 or not (9 * 60 + 30 <= _t < 16 * 60):
            return None                                   # not RTH — BS reprice is right
        key = (str(tk).upper(), str(expiry_s)[:10])
        hit = _LIVE_CHAIN_CACHE.get(key)
        if not hit or (time.time() - hit[0]) > max_age:
            ch = _yf_ticker(key[0]).option_chain(key[1])
            book = {}
            for _df, _ty in ((ch.calls, "call"), (ch.puts, "put")):
                for _r in _df.itertuples():
                    b, a = float(_r.bid or 0), float(_r.ask or 0)
                    mid = ((b + a) / 2 if (b > 0 and a > 0) else float(_r.lastPrice or 0))
                    if mid > 0:
                        book[(round(float(_r.strike), 2), _ty)] = mid
            _LIVE_CHAIN_CACHE[key] = (time.time(), book)
            hit = _LIVE_CHAIN_CACHE[key]
        return hit[1].get((round(float(strike), 2), str(typ).lower()))
    except Exception:
        log.debug(f"live chain {tk} {expiry_s} failed", exc_info=True)
        return None


def _post_event_leg(conn, tk, strike, typ, expiry_s, spot, iv_now, dte, ev):
    """Re-price ONE leg for the day after its next event — the IV-crush projection.

    User ask 2026-07-22: "some stock like google and AMD have more premium, so i want what
    be price after event". This isolates the VOL component only: spot fixed AND time fixed,
    with just the event premium removed from IV. Deliberately NOT the calendar price on the
    day after the event -- on a 9-DTE leg that number is dominated by seven days of theta and
    tells you nothing about event risk (first cut did exactly that and printed a -100% leg).

    Crush size comes from the ATM IV term structure as a RATIO, not a level: front-expiry ATM
    IV vs the median ATM IV of expiries >=30d past the event. Applying the ratio to the leg's
    own IV preserves skew -- comparing an OTM leg's IV directly against ATM IV is apples to
    oranges (AMD 640C at spot 555 carries 86% from skew, not from earnings). Falls back to the
    documented crush bands (EARNINGS 20-40%, FOMC 10-20% -> 0.70x/0.85x, matching the premarket
    model) only when the term structure is unusable.

    Returns None when there is no event before expiry, or the move is too small to be worth a
    line (<1% and <$0.05) -- printing "IV 38%->38% +0%" is noise.
    """
    if not (ev and ev.get("has_event")) or not iv_now or iv_now <= 0:
        return None
    if not spot or spot <= 0 or not strike or strike <= 0 or dte is None or dte <= 0:
        return None
    ev_days = ev.get("event_days")
    if ev_days is None or ev_days > dte:        # event lands after expiry -> no crush to model
        return None

    etype = ev.get("event_type") or "EVENT"
    term = _atm_iv_term(conn, tk, spot)
    ratio, src = None, "band"
    try:
        front_atm = term.get(_exp_iso(expiry_s[:10]))
        base = [iv for e, iv in term.items()
                if (datetime.strptime(e, "%Y-%m-%d").date() - _et_now().date()).days
                >= (ev_days + 30)]
        if front_atm and front_atm > 0 and base:
            base_atm = sorted(base)[len(base) // 2]
            # ratio >= 1 means THIS expiry carries no event premium (GOOG Aug-28 sits at the
            # floor of an 83%->37% earnings curve). That is a real answer: no crush. Falling
            # back to a band here would invent a 30% haircut the market is not pricing.
            ratio, src = min(base_atm / front_atm, 1.0), "term"
    except Exception:
        log.debug("term-structure baseline failed", exc_info=True)
    if ratio is None:                            # term structure genuinely unavailable
        ratio = 0.70 if etype == "EARNINGS" else 0.85
    iv_post = max(iv_now * ratio, 0.01)

    T_now = dte / 365.0                          # time HELD FIXED -- vol effect only
    try:
        px_now  = bs_price(spot, strike, T_now, R, iv_now,  opt=typ)
        px_post = bs_price(spot, strike, T_now, R, iv_post, opt=typ)
    except Exception:
        log.warning(f"post-event reprice FAILED {tk} {strike}{typ[:1]}", exc_info=True)
        return None
    if px_now is None or px_post is None or px_now <= 0:
        return None
    d = px_post - px_now
    if abs(d) < 0.05 and abs(d / px_now) < 0.01:
        return None                              # immaterial -- do not clutter the card
    return {"px": float(px_post), "px_now": float(px_now), "iv_now": float(iv_now),
            "iv_post": float(iv_post), "etype": etype,
            "edate": ev.get("event_date_str") or "", "edays": int(ev_days), "src": src}


def _book_risk_flags(rows, spot_of):
    """Book-level risk lines for the positions card: directional concentration + assignment.

    rows = the per-leg tuples the card builds; spot_of(tk) -> current spot (AH-aware).
    Two risks the per-leg view structurally cannot show:
      1. CONCENTRATION — if every leg leans the same way, one market gap the wrong way hits
         them all at once. A bearish book that just won on an earnings drop is exactly when
         this gets ignored.
      2. ASSIGNMENT — a SHORT option that is ITM near expiry can be exercised early.
    Directional sign per leg: long call / short put = bullish (+); short call / long put =
    bearish (-). qty carries the long/short sign.
    """
    # Direction is per POSITION, not per leg. A bear-put spread has one long + one short leg
    # whose per-leg signs cancel, so leg-counting wrongly reads "balanced". Group into
    # verticals by (ticker, put/call) and classify each by its long-vs-short strike; count
    # unpaired legs on their own. bull/bear are counts of POSITIONS, the unit that carries risk.
    lines, assign = [], []
    groups = {}
    for r in rows:
        try:
            _, tk, otype, strike, entry, cur_px, pnl_pct, pnl, dte_s, prob_s, oi_s, action, qty, exp = r
        except Exception:
            continue
        q = int(qty or 0)
        if q == 0 or float(strike or 0) <= 0:
            continue
        is_call = str(otype).upper().startswith("C")
        groups.setdefault((tk, is_call, str(exp)[:10]), []).append((float(strike), q))
        sp = float(spot_of(tk) or 0)
        if q < 0 and sp > 0:                     # short leg — assignment check
            itm = (sp > float(strike)) if is_call else (sp < float(strike))
            dte_n = int(dte_s[1:]) if str(dte_s).startswith("D") and dte_s[1:].isdigit() else None
            if itm and (dte_n is None or dte_n <= 7):
                depth = (sp - float(strike)) if is_call else (float(strike) - sp)
                assign.append(f"{tk} {int(float(strike))}{'C' if is_call else 'P'} "
                              f"short ITM ${depth:+.2f}" + (f", {dte_n}d" if dte_n is not None else ""))

    bull = bear = 0
    for (tk, is_call, _e), legs in groups.items():
        longs = [k for k, q in legs if q > 0]
        shorts = [k for k, q in legs if q < 0]
        if longs and shorts:                     # vertical — classify by long vs short strike
            lo_long = min(longs) if is_call else max(longs)
            # bullish if: long call BELOW short call (bull call) / long put BELOW short put (bull put)
            bullish = (lo_long < min(shorts)) if is_call else (max(longs) < max(shorts))
        else:                                    # single leg
            q = legs[0][1]
            bullish = (is_call and q > 0) or ((not is_call) and q < 0)
        if bullish:
            bull += 1
        else:
            bear += 1

    tot = bull + bear
    if tot >= 2 and (bull == 0 or bear == 0):
        side = "bullish" if bear == 0 else "bearish"
        lines.append(f"⚠️ <b>Book is 100% {side}</b> ({tot} positions) — a market gap the "
                     f"other way hits every one at once.")
    elif tot >= 3 and (max(bull, bear) / tot) >= 0.75:
        side = "bullish" if bull > bear else "bearish"
        lines.append(f"⚠️ <b>Book leans {side}</b> ({max(bull,bear)}/{tot} positions) — "
                     f"concentrated one-way risk.")
    for a in assign[:4]:
        lines.append(f"🔔 {a} — early-assignment risk.")
    return lines


def _expiry_outcome(rows, spot_of, dte_max=3):
    """Plain-English settlement walk-through for verticals near expiry.

    Near expiry the only questions that matter are: does this get assigned, do the legs
    offset, and is there a price band that leaves me holding stock I never wanted. A
    per-leg P&L table answers none of them. For each vertical inside `dte_max`:
      * both legs ITM  -> they OFFSET at settlement, net = max profit, NO share position
      * both OTM       -> both expire worthless
      * spot BETWEEN the strikes -> PIN RISK: one leg auto-exercises and the other does
        not, so you wake up holding (or short) 100 shares per contract
    OCC auto-exercises anything >= $0.01 ITM, which is why the middle band is the danger.
    """
    from collections import defaultdict
    grp = defaultdict(list)
    for r in rows:
        otype, strike, qty = str(r[2]).upper(), r[3], int(r[12] or 0)
        if otype.startswith("STOCK") or not strike or not qty:
            continue
        dte_n = int(r[8][1:]) if str(r[8]).startswith("D") and str(r[8])[1:].isdigit() else None
        grp[(r[1], r[13], otype[:1], dte_n)].append(r)

    out = []
    for (tk, exp, ot, dte_n), legs in grp.items():
        if dte_n is None or dte_n > dte_max:
            continue
        longs = [l for l in legs if int(l[12] or 0) > 0]
        shorts = [l for l in legs if int(l[12] or 0) < 0]
        if not (longs and shorts):
            continue
        S = float(spot_of(tk) or 0)
        if S <= 0:
            continue
        KL, KS = float(longs[0][3]), float(shorts[0][3])
        n = min(abs(int(longs[0][12])), abs(int(shorts[0][12])))
        is_put = (ot == "P")
        itm = (lambda K: S < K) if is_put else (lambda K: S > K)
        lo, hi = min(KL, KS), max(KL, KS)
        width = hi - lo
        net_entry = float(longs[0][4]) - float(shorts[0][4])
        maxp = (width - net_entry) * n * 100 if net_entry > 0 else -net_entry * n * 100
        when = "TODAY" if dte_n == 0 else ("tomorrow" if dte_n == 1 else f"in {dte_n}d")
        head = f"<b>{tk} {lo:.0f}/{hi:.0f}{ot} — expires {when}</b> (spot ${S:.2f})"
        if itm(KL) and itm(KS):
            out.append(
                f"{head}\n   ✅ BOTH legs ITM → they OFFSET at settlement: assigned on the "
                f"short, exercised on the long. Net <b>${maxp:,.0f}</b> (max profit), "
                f"<b>no share position</b>.\n"
                f"   ⚠️ PIN RISK if {tk} moves back between <b>${lo:.0f}–${hi:.0f}</b> by expiry — "
                f"then only one leg exercises and you end up holding {100*n} shares.\n"
                f"   → Closing the spread now locks the same ${maxp:,.0f} and removes "
                f"assignment + pin risk entirely.")
        elif not itm(KL) and not itm(KS):
            out.append(f"{head}\n   Both legs OTM — expire worthless, max loss already realised.")
        else:
            out.append(
                f"{head}\n   🚨 <b>IN THE PIN BAND</b> (${lo:.0f}–${hi:.0f}): only one leg "
                f"auto-exercises (OCC exercises ≥$0.01 ITM), leaving you {100*n} shares "
                f"long/short after expiry.\n   → Close BOTH legs before the bell to avoid it.")
    return out


def _closed_today_block(conn, today, spot_of):
    """Positions closed TODAY: entry → exit → what it would be worth NOW.

    The 'Now' column is the point: it scores the exit. If a leg you sold is worth more now
    you left money on the table; less, and you timed it well. Closed rows vanish from the
    open book entirely, so without this the day's realised P&L is invisible on the card.
    """
    try:
        rows = conn.execute(
            "SELECT ticker, option_type, strike, quantity, entry_price, exit_price, pnl, expiry "
            "FROM trades WHERE status='CLOSED' AND exit_date=? ORDER BY trade_id",
            (today.isoformat(),)).fetchall()
    except Exception:
        log.debug("closed-today query failed", exc_info=True)
        return "", 0.0
    if not rows:
        return "", 0.0
    out, tot = [], 0.0
    for tk, otype, K, qty, entry, exitp, pnl, exp in rows:
        try:
            typ = "stock" if str(otype).upper() == "STOCK" else str(otype).lower()
            K = float(K or 0); q = int(qty or 0)
            lbl = (f"{'+' if q > 0 else '-'}{str(tk)[:4]}"
                   + (f"{int(K)}{str(otype)[:1].upper()}" if K > 0 else " sh"))
            now_px = None
            # A ticker closed out today has NO open legs, so it is absent from the card's
            # AH price cache and spot_of() returns 0 — fetch it directly in that case.
            S = float(spot_of(tk) or 0)
            if S <= 0:
                _d = _get_spot_with_ah(tk) or {}
                S = float(_d.get("spot_ext") or _d.get("spot_reg") or 0)
            if K > 0 and S > 0 and exp:
                dte = (datetime.strptime(str(exp)[:10], "%Y-%m-%d").date() - today).days
                q2 = _bb_quote(conn, tk, K, str(exp)[:10], typ)
                iv = (q2 or {}).get("iv")
                if iv and dte >= 0:
                    g = bs_greeks(S, K, max(dte, 0) / 365.0 or 1 / 365.0, R, iv, typ)
                    now_px = g.get("price")
                if now_px is None:
                    now_px = max(K - S, 0.0) if typ == "put" else max(S - K, 0.0)
            tot += float(pnl or 0)
            _pk = (f"{float(pnl or 0)/1000:+.1f}K" if abs(float(pnl or 0)) >= 1000
                   else f"{float(pnl or 0):+.0f}")
            out.append((lbl, f"{float(entry or 0):.2f}", f"{float(exitp or 0):.2f}",
                        f"{now_px:.2f}" if now_px is not None else "—"))
        except Exception:
            log.debug(f"closed row {tk} failed", exc_info=True)
    if not out:
        return "", 0.0
    _tk = f"{tot/1000:+.1f}K" if abs(tot) >= 1000 else f"{tot:+.0f}"
    # 4 cols: the per-leg P&L column pushed this past the mobile wrap point (~40 chars),
    # and buy/sell/now were the explicitly requested values. Realised total goes in the
    # legend, where it is recoverable without costing table width.
    return _pipe_table(("Leg", "Buy", "Sell", "Now"), out, right_cols={1, 2, 3},
                       title="📕 CLOSED TODAY",
                       legend=f"Now = worth if still held (scores the exit) · realised {_tk}"), tot


def _open_positions(conn, options_only=True, include_paper=True):
    """Open positions across BOTH books, each row tagged `_book` = 'REAL' or 'DEMO' (ID 270).

    The real `trades` book is currently empty -- 81 closed, zero open -- while 13 live
    holdings sit in `paper_trades`. Every position lane queried `trades` alone, so
    position_monitor returned early, position_alerts returned early, and the card rendered
    blank: the ID 217 material-change re-send was correct but firing on nothing. Same shape
    as ID 250, where /indianews read trades+watchlist and missed the India book.

    SCOPE IS DELIBERATELY NARROW. CLAUDE.md draws the paper/real boundary on purpose, so this
    union is ONLY for monitoring and alerting. The tax clock, Exit Planner, realised P&L and
    capital effect still read `trades` directly and are untouched -- a DEMO row must never
    reach them. Callers render `_book` so a paper alert cannot be mistaken for real money
    (the user's explicit condition when approving this).
    """
    frames = []
    try:
        q = "SELECT * FROM trades WHERE status='OPEN'"
        if options_only:
            q += " AND UPPER(option_type)<>'STOCK'"
        real = pd.read_sql(q + " ORDER BY trade_id", conn)
        if not real.empty:
            real["_book"] = "REAL"
            frames.append(real)
    except Exception:
        log.debug("open_positions: real book read failed", exc_info=True)
    if include_paper:
        try:
            _pt_setup(conn)
            q = "SELECT * FROM paper_trades WHERE status='OPEN'"
            if options_only:
                q += " AND UPPER(option_type)<>'STOCK'"
            demo = pd.read_sql(q + " ORDER BY trade_id", conn)
            if not demo.empty:
                demo["_book"] = "DEMO"
                frames.append(demo)
        except Exception:
            log.debug("open_positions: paper book read failed", exc_info=True)
    if not frames:
        return pd.DataFrame()
    # trade_id is only unique WITHIN a book, so a bare id would collide across them --
    # alert dedup keys and card labels both need the book to disambiguate.
    out = pd.concat(frames, ignore_index=True, sort=False)
    out["_uid"] = out["_book"].str[0] + out["trade_id"].astype(str)
    return out


def _book_tag(row):
    """Marker for a position row: empty for real money, an explicit flag for paper."""
    try:
        return "" if str(row.get("_book", "REAL")).upper() == "REAL" else "🧪"
    except Exception:
        return ""


def _positions_card_parts(trades, now_s, today):
    """Build the POSITIONS health card (table + advice + urgent + HP engine) —
    SHARED by the 10-min position_monitor push and the menu positions_view
    (user 2026-07-18: one card format everywhere). Returns dict with 'full',
    'head' (header+cards for splitting), 'tail' (urgent+hp+footer), 'first_tk'."""
    # ── Prefetch OI signals for all tickers ──────────────────────
    oi_sigs = {}
    try:
        _oi_conn = get_conn()
        _lr = pd.read_sql("""
            SELECT DISTINCT trade_date_now FROM options_change
            ORDER BY trade_date_now DESC LIMIT 1
        """, _oi_conn)
        if not _lr.empty:
            _ltd = _lr["trade_date_now"].iloc[0]
            for _sym in trades["ticker"].str.upper().unique():
                _oi = pd.read_sql("""
                    SELECT SUM(change_OI_Call) as cc, SUM(change_OI_Put) as pc
                    FROM options_change WHERE ticker=? AND trade_date_now=?
                """, _oi_conn, params=(_sym, _ltd))
                if not _oi.empty:
                    _cc = float(_oi["cc"].iloc[0] or 0)
                    _pc = float(_oi["pc"].iloc[0] or 0)
                    oi_sigs[_sym] = "BUL" if _cc > abs(_pc)*1.2 else ("BEA" if _pc > abs(_cc)*1.2 else "NEU")
        _oi_conn.close()
    except Exception:
        log.debug("suppressed exception", exc_info=True)

    # ── Per-position data collection ─────────────────────────────
    rows       = []
    _eod_list  = []                  # EOD mark per leg, parallel to rows (2nd loop builds table)
    _book_list = []                  # book tag per leg, parallel to rows -- MUST be parallel:
                                     # the 2nd loop unpacks `rows` and never rebinds `tr`, so
                                     # reading tr there gave every leg the LAST row's book and
                                     # marked real money as paper (ID 270).
    total_pnl  = 0.0
    total_cost = 0.0                 # basis, so the card can report P&L as a % (ID 217)
    urgent_lines = []
    # Stable identifiers for the ACTION REQUIRED lines below. The recurring status card is
    # EDITED in place and Telegram does not notify on an edit, so a newly-fired EXIT/CUT
    # would scroll past silently. `position_monitor` diffs these keys against the last
    # notified set to decide when to send a FRESH (notifying) message instead. (ID 217)
    urgent_keys = []
    _pc_conn   = get_conn()          # shared conn for fast BB leg marks
    _ah_cache  = {}                  # per-ticker after-hours spot (avoid repeat fast_info)
    _ah_any    = False               # did any leg use an extended-hours mark?
    _live_mark_any = False           # did any leg use a REAL live market mid?
    _ev_cache  = {}                  # per-ticker event risk (yfinance calendar — cache it)
    _post_ev   = {}                  # (tk,otype,strike,expiry) -> post-event reprice dict

    # Which legs belong to a DEFINED-RISK vertical (same ticker+type+expiry with both a long
    # and a short leg). Their risk is the spread, not the leg -- so the per-leg action logic
    # must NOT emit a solo "EXIT NOW / cut loss" that contradicts the spread roll-up. Grouped
    # here, up front, so the guard is available inside the leg loop below.
    _spread_keys = set()
    try:
        _grp = {}
        for _, _t in trades.iterrows():
            _ot = str(_t.get("option_type", "")).upper()
            if _ot == "STOCK":
                continue
            _k = (str(_t.get("ticker", "")).upper(), _ot.startswith("C"),
                  str(_t.get("expiry", ""))[:10])
            _grp.setdefault(_k, []).append(int(_t.get("quantity", 0) or 0))
        for _k, _qs in _grp.items():
            if any(q > 0 for q in _qs) and any(q < 0 for q in _qs):
                _spread_keys.add(_k)
    except Exception:
        log.debug("spread-key precompute failed", exc_info=True)

    for _, tr in trades.iterrows():
        tid      = int(tr.get("trade_id", 0))
        tk       = str(tr.get("ticker", "?")).upper()
        otype    = str(tr.get("option_type", "call")).upper()
        strike   = _safe_float(tr.get("strike", 0), 0)
        entry    = _safe_float(tr.get("entry_price", 0), 0)
        qty      = _safe_int(tr.get("quantity", 1), 1)
        expiry_s = str(tr.get("expiry", ""))

        # DTE
        dte = None
        try:
            dte = (datetime.strptime(expiry_s[:10], "%Y-%m-%d").date() - today).days
        except Exception:
            try:
                dte = (datetime.strptime(expiry_s[:10], "%Y-%m-%d").date() - today).days
            except Exception:
                log.debug("suppressed exception", exc_info=True)

        # Option mark WITHOUT a per-leg yfinance option-chain download (was the
        # '⏳ Fetching live marks' 5-15s stall, 2026-07-19). BB DB gives IV/delta/mid
        # (indexed, ~instant); the leg is BS-re-priced off the CURRENT stock — which is
        # the extended-hours price when the market is closed, so 'Now' tracks the stock
        # after 4pm even though the option itself is frozen (user ask: "take stock values
        # if option values are frozen").
        cur_px = entry
        prob   = None
        stock_px = None
        iv_leg = None                # MUST pre-exist: _bb_quote can raise before it is bound
        try:
            typ = "call" if otype == "CALL" else "put"
            if tk not in _ah_cache:
                try:
                    _ah_cache[tk] = _get_spot_with_ah(tk)
                except Exception:
                    _ah_cache[tk] = {}
            _ah = _ah_cache[tk] or {}
            if _ah.get("is_extended"):
                _ah_any = True
            stock_px = float(_ah.get("spot_ext") or _ah.get("spot_reg") or 0) or (_last_price(tk) or None)
            bbq = _bb_quote(_pc_conn, tk, strike, expiry_s[:10], typ) if strike > 0 else None
            iv_leg = None
            if bbq:
                iv_leg = bbq.get("iv")
                if bbq.get("delta"):
                    prob = abs(float(bbq["delta"])) * 100
                if bbq.get("mid", 0) > 0:
                    cur_px = bbq["mid"]
                elif bbq.get("last", 0) > 0:
                    cur_px = bbq["last"]
            # BS re-price off the (extended-hours) stock, holding the frozen IV — keeps
            # 'Now' current in every session without a chain download.
            if strike > 0 and stock_px and dte is not None and dte >= 0 and iv_leg:
                _T = max(dte, 0) / 365.0
                if _T > 0:
                    _g = bs_greeks(stock_px, strike, _T, R, iv_leg, typ)
                    if _g.get("price", 0) > 0:
                        cur_px = _g["price"]
                    if prob is None and _g.get("delta") is not None:
                        prob = abs(float(_g["delta"])) * 100
        except Exception:
            # WARNING, not debug: this block is what keeps "Now" tracking the live stock.
            # It silently swallowed a NameError on `R` for its entire life, leaving every
            # position mark frozen at the EOD capture. A failure here corrupts displayed
            # P&L, so it must be loud.
            log.warning(f"positions leg re-price FAILED for {tk} {strike}{otype[:1]} "
                        f"— mark falls back to stale capture", exc_info=True)

        # EOD mark = the SAME leg repriced off the regular-session close, so the card can show
        # buy -> EOD -> AH side by side (user 2026-07-22). cur_px above is the AH mark; here we
        # BS-reprice with spot_reg holding the same IV. When there's no AH move eod_px == cur_px.
        eod_px = cur_px
        try:
            _reg = float((_ah_cache.get(tk) or {}).get("spot_reg") or 0)
            if strike > 0 and _reg > 0 and dte is not None and dte >= 0 and iv_leg:
                _Te = max(dte, 0) / 365.0
                if _Te > 0:
                    _ge = bs_greeks(_reg, strike, _Te, R, iv_leg, typ)
                    if _ge.get("price", 0) > 0:
                        eod_px = _ge["price"]
        except Exception:
            log.debug("EOD leg reprice failed", exc_info=True)

        # DURING RTH prefer the REAL market mid over any model (user 2026-07-23). The BS
        # reprice above uses a CAPTURED IV, which goes stale after an event and printed GOOG
        # 300P at 6.99 against a 6.10 market. One cached chain download per (ticker, expiry)
        # serves every leg on it. Outside RTH this returns None and the model stands, which
        # is correct — the option market is shut then.
        try:
            if strike > 0 and expiry_s:
                _lm = _live_opt_mid(tk, strike, typ, expiry_s)
                if _lm and _lm > 0:
                    cur_px = _lm
                    _live_mark_any = True
        except Exception:
            log.debug("live mid failed", exc_info=True)

        # Post-event (IV-crush) reprice — what the leg is worth once the event premium is gone,
        # spot held fixed. Priced off the SAME iv_leg the mark above uses, so the two numbers
        # are directly comparable.
        try:
            if tk not in _ev_cache:
                _ev_cache[tk] = _get_event_risk(tk)
            _pe = _post_event_leg(_pc_conn, tk, strike,
                                  "call" if otype == "CALL" else "put",
                                  expiry_s, stock_px, iv_leg, dte, _ev_cache[tk])
            if _pe:
                _post_ev[(tk, otype, strike, expiry_s)] = _pe
        except Exception:
            log.warning(f"post-event calc failed for {tk} {strike}{otype[:1]}", exc_info=True)

        # Rough moneyness-based probability if delta unavailable
        if prob is None and stock_px and strike:
            mono_pct = (stock_px - strike) / strike * 100
            if otype == "CALL":
                prob = max(5, min(95, 50 + mono_pct * 2.5))
            else:
                prob = max(5, min(95, 50 - mono_pct * 2.5))

        # |delta| ~ P(expire ITM) = the BUYER's win chance. A SHORT leg wins when
        # the option expires WORTHLESS — flip it (user bug report 2026-07-18:
        # short AMD 400P deep OTM showed 'win 5%'; seller's true win ~95%).
        if prob is not None and qty < 0:
            prob = 100 - prob

        pnl     = (cur_px - entry) * qty * 100
        # Guard the DENOMINATOR, not just `entry`. `_safe_int` truncates a fractional-share
        # quantity to 0 (a real 0.044-share SOXX lot exists in the book), so entry>0 was not
        # enough and this raised ZeroDivisionError -- inside a scheduled job, where a throw
        # is silent. Same failure class as ID 217.
        _cost = abs(entry * qty * 100)
        pnl_pct = (pnl / _cost * 100) if _cost > 0 else 0.0
        total_pnl += pnl
        total_cost += abs(entry * qty * 100)

        oi_s = oi_sigs.get(tk, "?")
        oi_align = not ((otype == "CALL" and oi_s == "BEA") or (otype == "PUT" and oi_s == "BUL"))

        # ── Action logic ──────────────────────────────────────────
        # A leg inside a defined-risk vertical is governed by the SPREAD roll-up, not by its
        # own DTE/P&L. Emitting a solo "EXIT NOW" or "cut loss" here contradicts it (TSLA
        # bear-put at +43% of max was screaming exit on both legs). For spread legs, defer.
        _in_spread = (tk, str(otype).upper().startswith("C"), str(expiry_s)[:10]) in _spread_keys
        if _in_spread:
            if dte is not None and dte <= 2:
                action = "SPREAD ⚠"
                em     = "🟡"
            elif pnl_pct <= -40:
                action = "SPREAD"
                em     = "🟡"
            elif pnl_pct >= 50:
                action = "SPREAD"
                em     = "🟢"
            elif dte is not None and dte <= 10:
                action = "SPREAD"
                em     = "🟡"
            else:
                action = "SPREAD"
                em     = "🟢" if pnl_pct >= 0 else "🟡"
        elif dte is not None and dte <= 2:
            action = "EXIT NOW"
            em     = "🚨"
            urgent_lines.append(f"🚨 #{tid} {tk} {otype[:1]} ${strike:.0f} — {dte}d left, exit immediately")
            urgent_keys.append(f"{tid}:exit")
        elif pnl_pct <= -50:
            action = "CUT LOSS"
            em     = "🔴"
            urgent_lines.append(f"🔴 #{tid} {tk} {otype[:1]} ${strike:.0f} — down {pnl_pct:.0f}%, cut loss")
            urgent_keys.append(f"{tid}:cut")
        elif pnl_pct <= -40:
            action = "CUT LOSS"
            em     = "🔴"
        elif pnl_pct >= 70:
            action = "TAKE PROFIT"
            em     = "🟢"
            urgent_lines.append(f"🟢 #{tid} {tk} {otype[:1]} ${strike:.0f} — up {pnl_pct:.0f}%, take profit")
            # Deliberately NOT added to urgent_keys: the user scoped the re-send to EXIT/CUT
            # (2026-08-14). A take-profit still shows in ACTION REQUIRED on the card, and a
            # move big enough to reach +70% will normally trip the 20-point P&L rule anyway --
            # so it is surfaced, just not as its own interrupt. Losses interrupt; gains wait.
        elif pnl_pct >= 50:
            action = "TAKE PROFIT"
            em     = "🟢"
        elif dte is not None and dte <= 5:
            action = "ROLL/EXIT" if pnl_pct >= 0 else "CUT"
            em     = "⚠️"
        elif dte is not None and dte <= 10:
            action = "ROLL SOON" if pnl_pct >= 0 else "REVIEW"
            em     = "🟡"
        elif not oi_align:
            action = "REVIEW"
            em     = "🟡"
        elif pnl_pct > 15:
            action = "HOLD"
            em     = "🟢"
        elif pnl_pct < -15:
            action = "HOLD"
            em     = "🔴"
        else:
            action = "HOLD"
            em     = "🟡"

        dte_s  = f"D{dte}"  if dte  is not None else "D?"
        prob_s = f"{prob:.0f}%" if prob is not None else "?"
        # qty + expiry carried through so the card can show LONG/SHORT and the expiry date
        # (user 2026-07-21: "which is long and which is short not showing also expiry" —
        # on a spread the side IS the risk, so a leg list without it is unreadable).
        _book_list.append(_book_tag(tr))
        rows.append((em, tk, otype[:4], strike, entry, cur_px, pnl_pct, pnl, dte_s, prob_s, oi_s,
                     action, qty, expiry_s[:10]))
        _eod_list.append(eod_px)     # parallel to rows; consumed by the table loop below

    try:
        _pc_conn.close()
    except Exception:
        pass

    # ── Action emoji map (replaces single-char badge + legend) ──────
    _action_em = {
        "EXIT NOW":    "🚨",
        "CUT LOSS":    "✂️",
        "TAKE PROFIT": "💰",
        "ROLL/EXIT":   "🔄",
        "ROLL SOON":   "🔄",
        "REVIEW":      "👁",
        "HOLD":        "✅",
        "SPREAD":      "🔗",
        "SPREAD ⚠":    "🔗",
    }
    # Plain-English action advice (no jargon)
    _action_advice = {
        "SPREAD":      "Part of a defined-risk spread — act on the spread roll-up above, not this leg alone.",
        "SPREAD ⚠":    "Spread near expiry — decide on the WHOLE spread above; never leg out of it.",
        "EXIT NOW":    "Exit immediately — this position is at critical risk.",
        "CUT LOSS":    "Close this trade. The loss is large enough to cut now rather than risk more.",
        "TAKE PROFIT": "Lock in your profit — sell to close and bank the gain.",
        "ROLL/EXIT":   "Expiry is very close. Either close it now or move to a later date.",
        "ROLL SOON":   "Expiry approaching in ~1 week. Plan to roll or close before it decays further.",
        "REVIEW":      "OI flow is not supporting this trade. Review and decide whether to hold or exit.",
        "HOLD":        "Within normal range — no action trigger hit; keep holding and monitor.",
    }

    # ── /earnvol standard: ONE narrow table (ST emoji col 0, ≤28 chars)
    #    + per-leg detail lines below (entry→now, DTE, win, OI, advice) ──
    _tbl_rows  = []
    html_cards = []
    _leg_ah_rows = []                # (dot, leg, buy, eod, ah, pnl$) for the buy->EOD->AH table
    _leg_tot_eodpnl = _leg_tot_ahpnl = _leg_cap = 0.0

    for _ri, (em, tk, otype, strike, entry, cur_px, pnl_pct, pnl, dte_s, prob_s, oi_s, action,
              qty, expiry_s) in enumerate(rows):
        eod_px = _eod_list[_ri] if _ri < len(_eod_list) else cur_px   # per-leg EOD mark
        _is_long = int(qty or 0) >= 0
        _side_w  = "LONG" if _is_long else "SHORT"
        a_em   = _action_em.get(action, "✅")
        advice = _action_advice.get(action, "Monitor position.")
        dte_num  = int(dte_s[1:]) if dte_s.startswith("D") and dte_s[1:].isdigit() else None
        dte_disp = f"{dte_num}d" if dte_num is not None else "?"
        urg_flag = "⚠" if dte_num is not None and dte_num <= 3 else ""
        oi_disp  = oi_s if oi_s and oi_s != "?" else "-"

        # +/- prefix = long/short. One char, and it is the single most important fact on a
        # spread (which leg you are short determines the whole risk profile).
        # 🧪 marks a PAPER leg (ID 270). The user allowed position alerts to cover the demo
        # book only on condition that a demo row can never be mistaken for real money, and
        # the card is the surface they actually read -- labelling the alert headline alone
        # was not enough.
        _leg = (f"{(_book_list[_ri] if _ri < len(_book_list) else '')}{_ticker_flag(tk)}"
                f"{'+' if _is_long else '-'}{tk[:4]}{int(strike)}{otype[:1]}")
        _pnl_s = f"{pnl:+,.0f}" if abs(pnl) < 1000 else f"{'+' if pnl >= 0 else '-'}{abs(pnl)/1000:.1f}K"
        # 3-state colored circle (user wants real green/yellow/red 2026-07-17;
        # this is the only way to get genuine color in Telegram — solid emoji
        # circles, alone in their own ST column, no text glued on). Now that
        # the arrow-width bug and emoji+text-in-cell bug are fixed at the
        # root, this should align correctly; any residual size is the emoji
        # glyph itself, which every Telegram client renders larger than a
        # text character — that's a font fact, not fixable in the table code.
        _st_dot = {"🚨": "🔴", "🔴": "🔴", "🟢": "🟢", "⚠️": "🟡", "🟡": "🟡"}.get(em, "🟡")
        # Buy -> EOD -> AH -> P&L (user 2026-07-22). eod_px is the EOD-close reprice; cur_px
        # the AH mark; pnl the current (AH) P&L. _leg_ah_rows also feeds the TOTAL row below.
        _eod_pnl = (eod_px - entry) * (qty or 0) * 100
        _act_short = {"SPREAD": "sprd", "SPREAD ⚠": "sprd⚠", "EXIT NOW": "EXIT",
                      "CUT LOSS": "CUT", "TAKE PROFIT": "TAKE", "ROLL/EXIT": "roll",
                      "ROLL SOON": "roll", "REVIEW": "rev", "HOLD": "hold"}.get(action, "hold")
        _pnl_k = (f"{pnl/1000:+.1f}K" if abs(pnl) >= 1000 else f"{pnl:+.0f}")
        _leg_ah_rows.append((_st_dot, _leg, f"{entry:.2f}", f"{cur_px:.2f}", _pnl_k))
        _leg_tot_eodpnl += _eod_pnl
        _leg_tot_ahpnl  += pnl
        _leg_cap        += abs(entry * (qty or 0) * 100)
        _tbl_rows.append((_st_dot, _leg, f"{cur_px:.2f}", f"{pnl_pct:+.0f}%"))

        # Card carries the FULL per-leg detail: bought price, current mark, P&L $ and %,
        # win prob, OI (user 2026-07-19: table 'only shows P&L, not bought/last price').
        # Post-event line: only when an event actually sits before expiry. Shows the IV
        # collapse and what it does to THIS leg — a short leg gains what a long leg loses.
        _pe = _post_ev.get((tk, otype, strike, expiry_s))
        _crush_line = ""
        if _pe:
            # Apply the MODELLED vol delta to the real mark, so the projection stays anchored
            # to the price actually quoted rather than drifting to a pure model number.
            _d_px  = _pe["px"] - _pe["px_now"]
            _proj  = max(cur_px + _d_px, 0.0)
            _d_pnl = _d_px * (qty or 0) * 100
            _pct   = (_d_px / cur_px * 100) if cur_px > 0 else 0
            _em_c  = "🟢" if _d_pnl >= 0 else "🔴"
            _appr  = "~" if _pe["src"] == "band" else ""
            _crush_line = (
                f"\n   {_em_c} If {'Earnings' if _pe['etype'] == 'EARNINGS' else _pe['etype']} "
                f"premium gone ({_pe['edate']}, "
                f"{_pe['edays']}d): IV {_pe['iv_now']*100:.0f}%→{_appr}{_pe['iv_post']*100:.0f}%"
                f" · leg <b>${_proj:.2f}</b> ({_pct:+.0f}%) · P&L <b>{_d_pnl:+,.0f}</b>"
            )

        # Everything that used to be a 4-line card per leg now lives in the table above
        # (buy/EOD/AH/P&L/action). Only genuinely per-leg extras survive as one short line:
        # the event IV-crush projection, and non-routine actions worth a sentence.
        if _crush_line:
            html_cards.append(f"<b>{_leg}</b>{_crush_line}")
        elif action not in ("HOLD", "SPREAD"):
            html_cards.append(f"<b>{_leg}</b> — {advice}")

    # Per-leg table: Buy -> EOD -> AH -> P&L, with a TOTAL row. P&L columns sum (EOD vs AH);
    # price columns don't (different strikes). Capital respects the 100x multiplier.
    if _leg_ah_rows:
        _rr = list(_leg_ah_rows)
        _tp = (_leg_tot_ahpnl / _leg_cap * 100) if _leg_cap > 0 else 0.0
        _tk_pnl = (f"{_leg_tot_ahpnl/1000:+.1f}K" if abs(_leg_tot_ahpnl) >= 1000
                   else f"{_leg_tot_ahpnl:+.0f}")
        _rr.append(("", "TOTAL", "", "", _tk_pnl))
        # 5 columns max — EOD and the action code moved to the legend/line below so the
        # grid stays inside Telegram's mobile width instead of wrapping.
        table1 = _pipe_table(("", "Leg", "Buy", "Now", "P&L"), _rr,
                             right_cols={2, 3, 4},
                             legend=f"Buy→EOD→AH marks · P&L=live(AH) · TOTAL EOD {_leg_tot_eodpnl:+,.0f} "
                                    f"→ AH {_leg_tot_ahpnl:+,.0f} ({_tp:+.0f}% on ${_leg_cap:,.0f})")
    else:
        table1 = ""

    advice_section = "\n\n".join(html_cards)
    # Spread roll-up goes FIRST: on a vertical the combined position is the real trade,
    # and per-leg advice below must be read in that context (never act on one leg alone).
    _spreads = _spread_summary(rows)
    # Book-level risk (concentration + assignment) — pull spot from the AH cache we already
    # populated per ticker so this adds no new network calls.
    try:
        _risk = _book_risk_flags(rows, lambda t: float((_ah_cache.get(t) or {}).get("spot_ext")
                                 or (_ah_cache.get(t) or {}).get("spot_reg") or 0.0))
    except Exception:
        _risk = []
        log.debug("book risk flags failed", exc_info=True)
    _risk_section = ("<b>⚡ BOOK RISK</b>\n" + "\n".join(_risk) + "\n\n") if _risk else ""
    # Settlement walk-through for anything expiring within ~3 days — assignment, whether the
    # legs offset, and the pin band. None of that is answerable from a per-leg P&L table.
    try:
        _xo = _expiry_outcome(rows, lambda t: float((_ah_cache.get(t) or {}).get("spot_ext")
                              or (_ah_cache.get(t) or {}).get("spot_reg") or 0.0))
    except Exception:
        _xo = []
        log.debug("expiry outcome failed", exc_info=True)
    if _xo:
        _risk_section += "<b>🏁 EXPIRY / ASSIGNMENT</b>\n" + "\n".join(_xo) + "\n\n"

    # Events header — built from the per-ticker _ev_cache the card already populated, so no
    # new network calls on a message pushed every 10-15 min. Flags earnings/FOMC that land
    # before a leg's expiry, with the AH move for names that reported today.
    _ev_bits = []
    for _etk in sorted(_ev_cache):
        _ev = _ev_cache.get(_etk) or {}
        if not _ev.get("has_event"):
            continue
        _ed = _ev.get("event_days")
        _lbl = "Earnings" if _ev.get("event_type") == "EARNINGS" else str(_ev.get("event_type") or "Event")
        _ah = _ah_cache.get(_etk) or {}
        _mv = (f" {_ah.get('ext_chg_pct'):+.1f}%"
               if _ah.get("is_extended") and _ed == 0 else "")
        _when = "today" if _ed == 0 else (f"{_ed}d" if _ed is not None else "")
        _ev_bits.append(f"{_etk} {_lbl} {_when}{_mv}".strip())
    _events_section = ("📅 <b>EVENTS</b>: " + " · ".join(_ev_bits) + "\n") if _ev_bits else ""

    # 📊 EARNINGS — the estimate-vs-actual that EXPLAINS the move the marks are showing
    # (TSLA $0.33 vs $0.54 est = -38% miss -> -5.8% AH). Stored in earnings_history.
    try:
        _ec = get_conn()
        _erows = []
        for _etk2 in (_ah_cache.keys() or []):
            _last, _next = _earn_context(_ec, _etk2)
            # REPORTED: signed `In` (−d = already passed) + Est/Act merged into one cell.
            # Only rendered when the actual is HELD — a scheduled time that has passed with
            # no data never reads as released.
            # ONE ROW PER TICKER (user 2026-07-23: two rows read as "different dates for the
            # same stock"). Last reported and next scheduled belong side by side — they are
            # two facts about one name, not two events to scan.
            if not ((_last and _last[2] is not None) or (_next and _next[1] is not None)):
                continue
            _em2, _lastd, _res = "🟡", "—", "—"
            if _last and _last[2] is not None:
                _sp = _last[3]
                _em2 = "🟢" if (_sp or 0) > 0 else ("🔴" if (_sp or 0) < 0 else "⚪")
                _lastd = str(_last[0])[5:]
                _res = (f"{_last[1]:.2f}/{_last[2]:.2f}" if _last[1] is not None
                        else f"{_last[2]:.2f}")
            _nextd, _nin = "—", "—"
            if _next and _next[1] is not None:
                _nextd = str(_next[0])[5:]
                try:
                    _dd2 = (datetime.strptime(str(_next[0])[:10], "%Y-%m-%d").date() - today).days
                    _nin = f"+{_dd2}d"
                except Exception:
                    pass
            _erows.append((f"{_em2}{_etk2[:4]}", _lastd, _res, _nextd, _nin))
        _ec.close()
        if _erows:
            # Header order follows the tuple appended above — it did not, so the table read
            # "Date 2.91/9.11" and "Est/Act +79d" (user 2026-08-12). The row is
            # (ticker, last report date, est/actual, next report date, days until next).
            # `In` is always the countdown to the NEXT report, so it is always +d; the old
            # legend also advertised a "−d passed" case that this table never produces.
            _events_section += ("\n" + _pipe_table(
                ("Tkr", "Rept", "Est/Act", "Next", "In"), _erows, right_cols={2, 4},
                title="📅 EARNINGS", legend="Rept = last report · Est/Act = EPS est/actual · "
                "Next = next report, In = days away · 🟢 beat 🔴 miss 🟡 upcoming") + "\n")
        # Call highlights for EVERY position, not just whichever ticker you drilled into
        # (user 2026-07-23). One line per name keeps it readable on a multi-position book.
        #
        # STALE-LABEL FIX (2026-07-27, user: "why Q1 is coming it should be Q2"): _tx_capture's
        # quarter math was already correct (commit be21f08) -- the real cause is AlphaVantage's
        # transcript endpoint lagging the earnings PRINT by days/weeks (GOOG reported 07-22,
        # transcript still empty on AlphaVantage as of 07-27; verified via a live _tx_fetch
        # call). The bot was silently showing the last transcript ON DISK with no hint it was
        # a stale quarter, which reads as a bug even though there's genuinely nothing newer to
        # show. Flag it: if the ticker's last-REPORTED quarter (from earnings_history, which
        # updates same-day) is newer than the stored transcript's quarter, say so explicitly.
        _hl_lines = []
        _ec3 = get_conn()
        try:
            for _htk in (_ah_cache.keys() or []):
                _t = _tx_latest(None, _htk)
                if _t:
                    _first = [h for h in str(_t[1]).split("\n") if h.strip()][:1]
                    if _first:
                        _stale = ""
                        try:
                            _hlast, _ = _earn_context(_ec3, _htk)
                            if _hlast and _hlast[0]:
                                _rd = datetime.strptime(str(_hlast[0])[:10], "%Y-%m-%d").date()
                                _rq = (_rd.month - 1) // 3
                                _rq_label = f"{_rd.year - 1}Q4" if _rq == 0 else f"{_rd.year}Q{_rq}"
                                if _rq_label != _t[0]:
                                    _stale = f" <i>(reported {_hlast[0]}, {_rq_label} call not yet transcribed)</i>"
                        except Exception:
                            log.debug("call-highlight staleness check failed", exc_info=True)
                        _hl_lines.append(f"<b>{_htk}</b> ({_t[0]}){_stale} {_first[0][:150]}")
        finally:
            _ec3.close()
        if _hl_lines:
            _events_section += "\n🎙 <b>CALL HIGHLIGHTS</b>\n" + "\n".join(_hl_lines) + "\n"
        _events_section += "\n"
    except Exception:
        log.debug("earnings context block failed", exc_info=True)
        _events_section += "\n"

    # 📰 NEWS — what is actually being said about each name we hold (user ask: news-based
    # analysis, not just event dates). Earnings-related headlines are sorted first because
    # the day after a print they explain the move the marks are showing. Cached 30 min.
    _news_section = ""
    try:
        _pn = _position_news(list(_ah_cache.keys()) or
                             trades["ticker"].astype(str).str.upper().unique().tolist())
        if _pn:
            _nl = []
            for _ntk, _hs in _pn.items():
                _mv = _ah_cache.get(_ntk) or {}
                _tag = (f" <i>({_mv.get('ext_chg_pct'):+.1f}% AH)</i>"
                        if _mv.get("is_extended") else "")
                # Hyperlink to the full article (user 2026-07-24: "I asked for hyperlinks
                # to read full news") -- falls back to plain text when no URL was found.
                _hl = " · ".join(f'<a href="{u}">{h[:95]}</a>' if u else h[:95]
                                 for h, u in _hs)
                _nl.append(f"<b>{_ntk}</b>{_tag} " + _hl)
            _news_section = "📰 <b>NEWS</b>\n" + "\n".join(_nl) + "\n\n"
    except Exception:
        log.debug("positions news block failed", exc_info=True)

    # Order (user 2026-07-23): positions and risk FIRST — that is what you act on. The
    # earnings / call-highlights / news context explains the moves but is reference, so it
    # is appended at the END via _context_section rather than pushing the book off-screen.
    colour_section = (_risk_section
                      + (f"{_spreads}\n\n" if _spreads else "")
                      + f"{table1}\n\n{advice_section}")
    # Realised P&L for today — closed rows leave the open book, so without this the day's
    # result is invisible on the card.
    _closed_tbl, _closed_pnl = "", 0.0
    try:
        _cc = get_conn()
        _closed_tbl, _closed_pnl = _closed_today_block(
            _cc, today, lambda t: float((_ah_cache.get(t) or {}).get("spot_ext")
                                        or (_ah_cache.get(t) or {}).get("spot_reg") or 0.0))
        _cc.close()
    except Exception:
        log.debug("closed-today block failed", exc_info=True)
    _context_section = ((("\n\n" + _closed_tbl) if _closed_tbl else "")
                        + "\n\n" + _events_section + _news_section).rstrip()

    urgent_section = ""
    if urgent_lines:
        urgent_section = "\n\n<b>⚡ ACTION REQUIRED</b>\n" + "\n".join(urgent_lines)

    net_em  = "🟢" if total_pnl >= 0 else "🔴"
    n_pos   = len(_leg_ah_rows)   # legs, not advice lines (html_cards is no longer 1-per-leg)
    footer  = f"\n{net_em} <b>Portfolio total: ${total_pnl:+,.0f}</b>  ({n_pos} open position{'s' if n_pos != 1 else ''})"

    # ── High-Prob Engine — compact ST table + per-ticker detail lines ──
    hp_section = ""
    _SIG_ICON = {"BULL":"🟢","BEAR":"🔴","SELL_PREMIUM":"💰","NEUTRAL":"⚪"}
    try:
        conn_hp_pm = get_conn()
        _hp_rows = []; _hp_details = []
        for _htk_pm in trades["ticker"].str.upper().unique().tolist()[:5]:
            try:
                _sp_pm = _get_spot_with_ah(_htk_pm).get("spot_ext", 0.0)
                _hr_pm = high_prob_signals_engine(_htk_pm, conn_hp_pm, _spy_day_ret(conn_hp_pm))
                _ic_pm = _SIG_ICON.get(_hr_pm["signal"], "⚪")
                _cf_pm = _hr_pm.get("confidence","")
                _pb_pm = _hr_pm["prob"]
                _bv   = _hr_pm["bull_v"]; _rv = _hr_pm["bear_v"]
                _sv   = _hr_pm.get("sell_v", 0)
                _vb = _hr_pm.get("vrvp_box", {})
                _pocv = float(_vb.get("poc") or 0)
                # POC alone is unreadable without spot — show the PULL: how far the volume
                # magnet sits from spot, and which way. Magnet above spot = upward pull.
                if _pocv > 0 and _sp_pm > 0:
                    _pl = (_pocv - _sp_pm) / _sp_pm * 100
                    _pull = f"{_pl:+.0f}%{'↑' if _pl > 0 else '↓'}"
                else:
                    _pull = "—"
                # One ROW per ticker — bias, conviction votes, expected range and OI walls all
                # inline (user 2026-07-23: this belongs in the table, not prose underneath).
                _rng = (f"{_vb['lo']:.0f}-{_vb['hi']:.0f}" if _vb.get("lo") else "—")
                _wl = _hr_pm.get("models", {}).get("put_call_wall", {})
                _wls = (f"{_wl['put_wall']:.0f}/{_wl['call_wall']:.0f}"
                        if (_wl.get("call_wall") and _wl.get("prob", 0) >= 65) else "—")
                # 5 cols max — votes/range/walls move to the detail line below, else this
                # grid runs ~59 chars and WRAPS on mobile (CLAUDE.md caps <pre> at ~28).
                _hp_rows.append((_ic_pm, _htk_pm[:5], f"${_sp_pm:.0f}",
                                 f"{_pb_pm:.0f}%", _pull))
                _hp_details.append(f"<b>{_htk_pm}</b> votes 🟢{_bv}/🔴{_rv}/💰{_sv} · "
                                   f"range {_rng} · walls {_wls}")
            except Exception as _e_pm:
                log.debug(f"pos_mon hp {_htk_pm}: {_e_pm}")
        if _hp_rows:
            _hp_tbl = _pipe_table(("ST", "Tkr", "Spot", "Prob", "Pull"),
                                  _hp_rows, right_cols={2, 3, 4},
                                  legend="Pull = POC vs spot (volume magnet)")
            hp_section = ("\n\n<b>🧠 HP Engine</b>\n" + _hp_tbl + "\n"
                          + "\n".join(_hp_details))
            # RAG grounding (user 2026-07-27): WHY context for the single highest-conviction
            # verdict only -- one query per card, not per ticker, to keep this cheap and the
            # card from ballooning. Uses the icon already computed above (BULL/BEAR/etc), not
            # a re-derived label, so the grounding query always matches what's actually shown.
            try:
                _lead_i = max(range(len(_hp_rows)), key=lambda i: abs(float(_hp_rows[i][3][:-1]) - 50))
                _lead_tk = _hp_rows[_lead_i][1]
                _lead_sig = {v: k for k, v in _SIG_ICON.items()}.get(_hp_rows[_lead_i][0])
                _ground = _verdict_grounding(_lead_tk, _lead_sig, top_k=3)
                if _ground:
                    _gl = "; ".join(f"{g['title'][:70]}" for g in _ground[:3])
                    hp_section += f"\n<i>🔎 Why ({_lead_tk}): {_gl}</i>"
            except Exception:
                log.debug("hp verdict grounding failed", exc_info=True)
        conn_hp_pm.close()
    except Exception as _e_hp_pm:
        log.debug(f"pos_mon hp block: {_e_hp_pm}")

    _ah_banner = ""
    if _live_mark_any:
        _ah_banner += "<i>🟢 Live market mids (real bid/ask), not model prices.</i>\n\n"
    if _ah_any:
        _ah_banner = ("<i>⏳ After-hours: 'Now' re-priced from the extended-hours stock via "
                      "Black-Scholes (IV held); the options themselves are frozen at the 4pm close.</i>\n\n")
    full_msg = (
        f"{hdr(f'💼 POSITIONS · {now_s}')}\n\n"
        + _ah_banner
        + colour_section
        + urgent_section
        + hp_section
        + footer
        + _context_section          # earnings / call highlights / news — reference, at the end
    )

    return {"full": full_msg,
            "head": f"{hdr(f'💼 POSITIONS · {now_s}')}\n\n{_ah_banner}{colour_section}",
            "tail": urgent_section + hp_section + footer + _context_section,
            "first_tk": str(trades["ticker"].iloc[0]).upper() if not trades.empty else "SPY",
            # Materiality inputs for the re-send rule (ID 217) -- surfaced from figures the
            # card already computed rather than re-priced, so the check costs nothing.
            "total_pnl": total_pnl,
            "pnl_pct": (total_pnl / total_cost * 100) if total_cost > 0 else 0.0,
            "urgent_keys": urgent_keys}


def _ensure_alert_dedup_table(conn):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS alert_dedup (
            alert_date TEXT NOT NULL,
            grp_key    TEXT NOT NULL,
            atype      TEXT NOT NULL,
            PRIMARY KEY (alert_date, grp_key, atype)
        )
    """)
    conn.commit()


def _alert_already_sent(conn, today_str, grp_key, atype):
    """Return True if alert was already sent today; insert the key if not."""
    try:
        conn.execute(
            "INSERT INTO alert_dedup (alert_date, grp_key, atype) VALUES (?, ?, ?)",
            (today_str, grp_key, atype)
        )
        conn.commit()
        return False
    except sqlite3.IntegrityError:
        return True


# ── Data-health watchdog (user ask 2026-07-17): detect missing/stale/thin EOD
#    data, alert Telegram + Streamlit banner DAILY until user acknowledges. ──
def _ensure_data_health_table(conn):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS data_health_alerts (
            alert_id   INTEGER PRIMARY KEY AUTOINCREMENT,
            kind       TEXT NOT NULL,
            detail     TEXT,
            first_seen TEXT,
            last_seen  TEXT,
            status     TEXT DEFAULT 'OPEN',   -- OPEN / ACK / RESOLVED
            ack_at     TEXT
        )
    """)
    conn.commit()


def _last_expected_eod():
    """Most recent trading day whose EOD capture should already exist (ISO).
    Before the EOD lane has had time to land (18:00 ET) we only expect the
    PREVIOUS weekday.

    The cutoff is NY-clock, not UTC (user 2026-08-14). It used to be a hardcoded
    22:30 UTC, which is 18:30 ET in EDT but **17:30 ET in EST** — earlier than the
    ~17:32 ET lane finish. Every winter that let the dashboard's _live_audit_refresh()
    audit a still-capturing day and write a FAILED row for TODAY, which then won
    MAX(audit_date) and flashed a red banner over data that was merely unfinished.
    An ET cutoff is the same moment in both halves of the year, so it cannot drift.

    The scheduler now audits the captured day directly at lane completion, so this
    is the backstop path (bot job + dashboard live refresh), not the primary one.
    """
    ny = _et_now()
    d = ny.date()
    if ny.hour < 18:
        d -= timedelta(days=1)
    while d.weekday() >= 5:
        d -= timedelta(days=1)
    return d.isoformat()


# ── Invariants for the scoped nightly derive (user 2026-08-12; PROMOTED 2026-09-02) ──
# NYSE_OpenBB.py used to re-derive EVERY capture date every night; it now does the
# captured day plus anything genuinely missing (_derive_scope). That is a large win
# (~50 min/night, and it no longer grows with history) but it removes an accidental
# safety net: the full rebuild used to paper over any day that came out wrong.
#
# This began as a 2-week watch that expired on 2026-08-26 (tracker ID 234). At the
# decision point it had found nothing across all five downstream tables — and the
# temptation was to read a clean fortnight as "proven, delete it". Kept instead,
# because these are not probes of a change under trial, they are INVARIANTS: a derive
# that silently skips a captured day is the one fault that cannot be repaired later.
# CBOE serves current open interest only, so a day noticed weeks afterwards is gone
# for good. A check that costs three queries a night against a permanently
# unrecoverable loss is not a close call.
#
# What DID change at promotion: the gap scan is bounded to a recent window. Over all
# history one genuinely unfixable old gap would raise an alert that can never be
# resolved and would nag forever, which is how a useful check trains you to ignore it.
# Checks 2 and 3 already look only at the newest day.
_DERIVE_WATCH_DAYS = 30


def _derive_scope_watch(conn):
    """Return (kind, detail) issues specific to the scoped derive. Runs permanently."""
    issues = []

    def _dates(tbl, col):
        try:
            return [r[0] for r in conn.execute(f"SELECT DISTINCT {col} FROM {tbl} ORDER BY {col}")]
        except Exception:
            return []

    cap = _dates("options_openbb", "trade_date")
    if not cap:
        return []
    latest = cap[-1]

    # 1. GAPS — the self-heal in _derive_scope is meant to make these impossible. The newest
    #    capture date is excluded on purpose: while the EOD job is still running it is legitimately
    #    absent, and capture_stale/derive_stale already cover it.
    for tbl, col, label in (("options_daily", "trade_date", "options_daily"),
                            ("options_change", "trade_date_now", "options_change"),
                            ("stock_daily", "trade_date", "stock_daily"),
                            ("daily_ticker_summary", "trade_date", "serving layer"),
                            ("skew_snapshot", "trade_date", "skew_snapshot")):
        # Recent window only -- see the note above on why an unbounded scan self-defeats.
        missing = sorted(set(cap[-(_DERIVE_WATCH_DAYS + 1):-1]) - set(_dates(tbl, col)))
        if missing:
            issues.append((f"derive_gap_{tbl}",
                           f"{label} missing {len(missing)} captured day(s): "
                           f"{', '.join(missing[-5:])} - scoped derive skipped them and the "
                           f"self-heal did not pick them up"))

    # 2. SKEW COLUMNS — the regression the skew-before-serving-layer reorder fixes. Before it,
    #    a day's atm_iv/skew25/pcvol landed NULL and waited for the next full rebuild.
    try:
        n, ok = conn.execute(
            "SELECT COUNT(*), SUM(atm_iv IS NOT NULL) FROM daily_ticker_summary "
            "WHERE trade_date=(SELECT MAX(trade_date) FROM daily_ticker_summary)").fetchone()
        d = conn.execute("SELECT MAX(trade_date) FROM daily_ticker_summary").fetchone()[0]
        if n and (ok or 0) < n * 0.5:
            issues.append(("derive_skew_nulls",
                           f"daily_ticker_summary {d}: only {ok or 0}/{n} rows have atm_iv - "
                           f"skew_snapshot is not landing before the serving layer"))
    except Exception:
        pass

    # 3. THIN DAY — a partial derive now survives to morning instead of being redone. Compare the
    #    newest derived day against the median of the ten before it rather than a fixed floor,
    #    because row counts drift with the universe.
    for tbl, col in (("options_change", "trade_date_now"), ("options_daily", "trade_date")):
        try:
            rows = conn.execute(
                f"SELECT {col}, COUNT(*) FROM {tbl} WHERE {col} IN "
                f"(SELECT DISTINCT {col} FROM {tbl} ORDER BY {col} DESC LIMIT 11) "
                f"GROUP BY {col} ORDER BY {col}").fetchall()
            if len(rows) >= 6:
                hist = sorted(c for _, c in rows[:-1])
                med = hist[len(hist) // 2]
                day, cnt = rows[-1]
                if med and cnt < med * 0.70:
                    issues.append((f"derive_thin_{tbl}",
                                   f"{tbl} {day}: {cnt:,} rows vs {med:,} median of prior 10 "
                                   f"({cnt / med:.0%}) - derive may have run on a partial capture"))
        except Exception:
            pass
    return issues


def _data_health_scan(conn):
    """Return list of (kind, detail) issues. Checks capture vs derive vs stock lanes."""
    exp = _last_expected_eod()
    issues = []

    def _latest(tbl, col):
        try:
            r = conn.execute(f"SELECT MAX({col}) FROM {tbl}").fetchone()
            return r[0] or ""
        except Exception:
            return ""

    def _count(tbl, col, day):
        try:
            r = conn.execute(
                f"SELECT COUNT(DISTINCT ticker) FROM {tbl} WHERE {col}=?", (day,)).fetchone()
            return int(r[0] or 0)
        except Exception:
            return 0

    cap = _latest("options_openbb", "trade_date")
    der = _latest("options_change", "trade_date_now")
    stk = _latest("stock_daily", "trade_date")
    if cap < exp:
        issues.append(("capture_stale", f"options_openbb latest {cap or 'NONE'} < expected {exp} — BB EOD capture missed"))
    elif _count("options_openbb", "trade_date", cap) < 300:
        issues.append(("capture_thin", f"options_openbb {cap}: only {_count('options_openbb','trade_date',cap)} tickers (<300)"))
    if der < exp:
        issues.append(("derive_stale", f"options_change latest {der or 'NONE'} < expected {exp} — derive step missed (bot reads stale OI)"))
    if stk < exp:
        issues.append(("stock_stale", f"stock_daily latest {stk or 'NONE'} < expected {exp}"))
    issues += _derive_scope_watch(conn)
    return issues


def _data_health_upsert(conn):
    """Scan + reconcile alert rows. Returns DataFrame of OPEN (un-acked) alerts."""
    _ensure_data_health_table(conn)
    issues = _data_health_scan(conn)
    now_s = datetime.now(timezone.utc).replace(tzinfo=None).strftime("%Y-%m-%d %H:%M")
    live_kinds = set()
    for kind, detail in issues:
        live_kinds.add(kind)
        row = conn.execute(
            "SELECT alert_id FROM data_health_alerts WHERE kind=? AND status IN ('OPEN','ACK') "
            "ORDER BY alert_id DESC LIMIT 1", (kind,)).fetchone()
        if row:
            conn.execute("UPDATE data_health_alerts SET detail=?, last_seen=? WHERE alert_id=?",
                         (detail, now_s, row[0]))
        else:
            conn.execute(
                "INSERT INTO data_health_alerts (kind, detail, first_seen, last_seen) VALUES (?,?,?,?)",
                (kind, detail, now_s, now_s))
    conn.execute(
        "UPDATE data_health_alerts SET status='RESOLVED' WHERE status IN ('OPEN','ACK') "
        "AND kind NOT IN ({})".format(",".join("?" * len(live_kinds)) or "''"),
        tuple(live_kinds))
    conn.commit()
    return pd.read_sql("SELECT * FROM data_health_alerts WHERE status='OPEN' ORDER BY alert_id", conn)


# ── Stringent daily data AUDIT (user 2026-07-17): after the EOD run, grade the
#    day's data VALIDATED / PARTIAL / FAILED across every lane; dashboard shows
#    the verdict banner every day; Telegram posts it post-EOD. ──
def _ensure_data_audit_table(conn):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS data_audit (
            audit_date TEXT PRIMARY KEY,   -- trading day audited (ISO)
            status     TEXT,               -- VALIDATED / PARTIAL / FAILED
            summary    TEXT,               -- one line per check
            run_at     TEXT
        )
    """)
    conn.commit()


def _data_audit(conn, day=None):
    """Stringent per-day audit. Returns (status, checks, day);
    checks = [(name, ok_bool, detail_str)]. Persists to data_audit."""
    day = day or _last_expected_eod()
    # Fill stock_history BEFORE judging it. The sync is a free fold-forward from stock_daily,
    # but it only runs when _daily_history is called WITHOUT a connection -- so whether it had
    # happened by audit time was luck. That is why `history` was the check that kept failing:
    # 2026-08-24 was recorded as 15 tickers against stock_daily's 730, and later held all 730
    # once something happened to trigger the sync. Auditing a table the audit itself can bring
    # up to date was reporting a scheduling accident as a data fault.
    try:
        _sync_history_from_daily(conn)
    except Exception:
        log.debug("pre-audit history sync failed", exc_info=True)
    checks = []

    def _nt(tbl, col):
        try:
            return int(conn.execute(
                f"SELECT COUNT(DISTINCT ticker) FROM {tbl} WHERE {col}=?", (day,)).fetchone()[0] or 0)
        except Exception:
            return 0

    cap = _nt("options_openbb", "trade_date")
    der = _nt("options_change", "trade_date_now")
    stk = _nt("stock_daily", "trade_date")
    skw = _nt("skew_snapshot", "trade_date")
    checks.append(("capture", cap >= 300, f"options_openbb: {cap} tickers"))
    checks.append(("derive", der >= 300, f"options_change: {der} tickers"))
    checks.append(("derive=capture", cap > 0 and der >= cap * 0.9, f"derive covers {der}/{cap}"))
    checks.append(("stock", stk >= 300, f"stock_daily: {stk} tickers"))
    checks.append(("skew", skw >= 300, f"skew_snapshot: {skw} tickers"))
    # stock_history was NOT audited, and that is why it drifted 2 sessions behind in silence
    # while this same audit reported 7/7 green (ID 274). It is the multi-year series every
    # row-counted window is built on, so a gap there shifts trend numbers without any error
    # anywhere. Compared against stock_daily for the SAME day: the sync is a pure-SQL fold of
    # one into the other, so anything less than near-parity means the fold did not run.
    hst = _nt("stock_history", "trade_date")
    checks.append(("history", stk == 0 or hst >= stk * 0.9,
                   f"stock_history: {hst} tickers vs stock_daily {stk}"))
    try:
        tot, nul = conn.execute(
            "SELECT COUNT(*), SUM(CASE WHEN openInt_Call_now IS NULL THEN 1 ELSE 0 END) "
            "FROM options_change WHERE trade_date_now=?", (day,)).fetchone()
        _nr = (float(nul or 0) / tot * 100) if tot else 100.0
        checks.append(("null-rate", _nr < 5.0, f"{_nr:.1f}% NULL call-OI rows"))
    except Exception:
        checks.append(("null-rate", False, "null check failed"))
    _pq = os.path.join(os.path.dirname(DB_PATH), "openbb_chains", f"chains_{day}.parquet")
    checks.append(("parquet", os.path.exists(_pq), f"chains_{day}.parquet "
                   + ("present" if os.path.exists(_pq) else "MISSING (offsite-backup source)")))

    if all(ok for _, ok, _ in checks):
        status = "VALIDATED"
    elif cap >= 300 and der >= 300:
        status = "PARTIAL"
    else:
        status = "FAILED"
    _ensure_data_audit_table(conn)
    _summary = " · ".join(("✅" if ok else "❌") + f" {n}: {d}" for n, ok, d in checks)
    conn.execute("INSERT OR REPLACE INTO data_audit (audit_date, status, summary, run_at) "
                 "VALUES (?,?,?,?)",
                 (day, status, _summary,
                  datetime.now(timezone.utc).replace(tzinfo=None).strftime("%Y-%m-%d %H:%M")))
    conn.commit()
    _reaudit_stale(conn, day)
    return status, checks, day


def _reaudit_stale(conn, today_str, lookback=20):
    """Re-check past PARTIAL/FAILED days and upgrade any whose data has since healed.

    The verdict was a point-in-time snapshot nothing ever revisited, so a day audited while
    the EOD lane was still running kept its amber mark permanently. The dashboard strip then
    showed failures that no longer existed, and the same phantom cost three separate
    investigations (IDs 215, 274, 353).

    UPGRADE ONLY. A day that genuinely still fails keeps its mark, so this cannot paper over
    a real gap -- it can only retract a stale accusation.
    """
    try:
        stale = [r[0] for r in conn.execute(
            "SELECT audit_date FROM data_audit WHERE status <> 'VALIDATED' "
            "AND audit_date < ? ORDER BY audit_date DESC LIMIT ?", (today_str, lookback))]
    except Exception:
        return
    for d in stale:
        try:
            cap = conn.execute("SELECT COUNT(DISTINCT ticker) FROM options_openbb "
                               "WHERE trade_date=?", (d,)).fetchone()[0]
            der = conn.execute("SELECT COUNT(DISTINCT ticker) FROM options_change "
                               "WHERE trade_date_now=?", (d,)).fetchone()[0]
            stk = conn.execute("SELECT COUNT(DISTINCT ticker) FROM stock_daily "
                               "WHERE trade_date=?", (d,)).fetchone()[0]
            hst = conn.execute("SELECT COUNT(DISTINCT ticker) FROM stock_history "
                               "WHERE trade_date=?", (d,)).fetchone()[0]
            skw = conn.execute("SELECT COUNT(DISTINCT ticker) FROM skew_snapshot "
                               "WHERE trade_date=?", (d,)).fetchone()[0]
            _pq = os.path.join(os.path.dirname(DB_PATH), "openbb_chains", f"chains_{d}.parquet")
            if (cap >= 300 and der >= cap * 0.98 and stk >= 300
                    and hst >= stk * 0.95 and skw >= 300 and os.path.exists(_pq)):
                conn.execute(
                    "UPDATE data_audit SET status='VALIDATED', summary=?, run_at=? "
                    "WHERE audit_date=?",
                    (f"✅ re-audited and healed · capture {cap} · derive {der} · stock {stk}"
                     f" · history {hst} · skew {skw}",
                     datetime.now(timezone.utc).replace(tzinfo=None).strftime("%Y-%m-%d %H:%M"),
                     d))
                conn.commit()
                log.info("data_audit: %s upgraded to VALIDATED on re-audit (history now %d)",
                         d, hst)
        except Exception:
            log.debug("re-audit failed for %s", d, exc_info=True)


def _fmt_signal_accuracy(conn):
    """Telegram body for the measured-signal state, or None when nothing is graded yet."""
    res, crit = _signal_base_rates(conn)
    if not res:
        return None, set()
    passed = [o for o in res if o["t"] >= crit]
    nominal = [o for o in res if 2.0 < o["t"] < crit]
    days = max(o["days"] for o in res)
    keys = {f"{o['model']}/{o['call']}" for o in passed}

    # ⚪ not ▪ (user 2026-09-02, ID 390). U+25AA measures as ONE cell in _disp_w but Telegram
    # renders it with emoji presentation at TWO, so every below-the-bar row sat a space wider
    # than the 🟢 rows and the column visibly stepped. ⚪ is a real emoji codepoint, so the
    # width counter and the renderer agree, and it is already this repo's neutral marker
    # (⚪ HOLD / ⚪ N/A in the Exit Planner) rather than a fourth vocabulary.
    rows = [(("🟢" if o["t"] >= crit else ("🟡" if o["t"] > 2 else "⚪")),
             o["model"][:13], f"{o['hit'] * 100:.0f}%",
             f"{(o['hit'] - o['base']) * 100:+.0f}", f"{o['t']:.2f}")
            for o in res[:8]]
    body = _report(
        "🎯 SIGNAL ACCURACY",
        ("", "Model", "Hit", "vs base", "t"), rows, right_cols={2, 3, 4},
        # Every marker used must be NAMED here. The third one was printed and never
        # explained, which is worse than omitting it: the reader sees a distinction being
        # drawn and has to guess which way it cuts (ID 392).
        legend=f"🟢 clears the multiplicity bar (t≥{crit:.2f}) — measured · "
               f"🟡 nominal only, not corrected for testing many models · "
               f"⚪ no evidence (t≤2) · {len(res)} models tested on {days} days",
        notes="A model only counts as MEASURED if it clears the Bonferroni column. "
              "Testing ~20 models at once produces about half a nominal hit from noise alone.")
    if passed:
        body += ("\n\n<b>✅ Measured edge:</b> "
                 + " · ".join(f"{o['model']}/{o['call']} "
                              f"({o['hit'] * 100:.0f}% vs {o['base'] * 100:.0f}%, t={o['t']:.2f})"
                              for o in passed))
    else:
        body += ("\n\n<b>Nothing clears the bar yet.</b> That is a real answer, not a "
                 "failure — it is what stops a self-improving loop from optimising noise.")
    if nominal:
        body += (f"\n<i>Nominal only, do NOT act on: "
                 f"{', '.join(o['model'] + '/' + o['call'] for o in nominal)}</i>")
    return body, keys


async def signal_accuracy_alert(ctx: ContextTypes.DEFAULT_TYPE):
    """Daily measured-signal state (ID 336). Speaks up when the VERDICT changes.

    The measurement existed only as a tool someone had to remember to run, so a model
    crossing the multiplicity bar — the single event this whole apparatus exists to detect —
    could pass unnoticed for weeks. A model entering or leaving the measured set is pushed
    loudly; an unchanged verdict is logged and sent quietly, so the daily message cannot
    become wallpaper.
    """
    conn = get_conn()
    try:
        body, keys = _fmt_signal_accuracy(conn)
        if not body:
            return
        prev = set(filter(None, (_app_setting(conn, "sigacc_measured") or "").split(",")))
        gained, lost = keys - prev, prev - keys
        _set_app_setting(conn, "sigacc_measured", ",".join(sorted(keys)))
    finally:
        conn.close()
    head = ""
    if gained:
        head = (f"🔔 <b>NEW measured edge: {', '.join(sorted(gained))}</b>\n"
                f"<i>First time this cleared the multiplicity bar. Re-run as the sample "
                f"grows before acting — a threshold crossed once on a thin sample is "
                f"exactly when a false positive looks most convincing.</i>\n\n")
    elif lost:
        head = (f"⚠️ <b>No longer measured: {', '.join(sorted(lost))}</b>\n"
                f"<i>It fell back below the bar as more data arrived. That is the sample "
                f"correcting itself, and the reason nothing is acted on early.</i>\n\n")
    _, chat_id = load_creds()
    try:
        await ctx.bot.send_message(chat_id=int(chat_id), text=(head + body)[:4000],
                                   parse_mode=H, disable_notification=not (gained or lost))
    except Exception as e:
        log.warning(f"signal_accuracy_alert send failed: {e}")


async def data_audit_alert(ctx: ContextTypes.DEFAULT_TYPE):
    """Post-EOD job: run the stringent audit and post the verdict (once/day)."""
    conn = get_conn()
    try:
        status, checks, day = _data_audit(conn)
        today_s = datetime.now(timezone.utc).replace(tzinfo=None).strftime("%Y-%m-%d")
        _ensure_alert_dedup_table(conn)
        if _alert_already_sent(conn, today_s, f"{day}|{status}", "data_audit"):
            return
    finally:
        conn.close()
    _em = {"VALIDATED": "🟢", "PARTIAL": "🟡", "FAILED": "🔴"}[status]
    rows = [(("✅" if ok else "❌"), n, d.split(":")[-1].strip()[:14]) for n, ok, d in checks]
    msg = _report(
        f"{_em} DATA AUDIT {day} — {status}",
        ("ST", "Check", "Detail"), rows,
        legend="✅ pass · ❌ fail",
        notes=("All lanes verified — data is trustworthy today." if status == "VALIDATED" else
               "Core lanes OK but some checks failed — see dashboard banner." if status == "PARTIAL" else
               "Data NOT usable — capture/derive missing. Check scheduler + logs."))
    _, chat_id = load_creds()
    try:
        await ctx.bot.send_message(chat_id=chat_id, text=msg, parse_mode=H)
    except Exception as e:
        log.warning(f"data_audit_alert send failed: {e}")


async def data_status_cmd(update, ctx):
    """/data (alias /status) — on-demand EOD data-download status. Runs the stringent
    audit LIVE against the current DB (VALIDATED / PARTIAL / FAILED) so you can check
    whether today's capture + derive finished — watch the ticker count climb mid-run."""
    conn = get_conn()
    try:
        status, checks, day = _data_audit(conn)
        exp = _last_expected_eod()
        cap_date = conn.execute("SELECT MAX(trade_date) FROM options_openbb").fetchone()[0] or "NONE"
    finally:
        conn.close()
    _em = {"VALIDATED": "🟢", "PARTIAL": "🟡", "FAILED": "🔴"}[status]
    rows = [(("✅" if ok else "❌"), n, d.split(":")[-1].strip()[:16]) for n, ok, d in checks]
    _note = ("All lanes verified — data is ready to use." if status == "VALIDATED" else
             "Core data present; some checks still pending — capture may be mid-run." if status == "PARTIAL" else
             "Data incomplete — capture/derive missing. Scheduler retries on login / 17:00 ET.")
    msg = _report(
        f"{_em} DATA {status} — {day}",
        ("ST", "Check", "Detail"), rows,
        legend="✅ pass · ❌ fail",
        notes=f"Latest capture {cap_date} · expected {exp}. {_note}")
    await update.message.reply_text(msg, parse_mode=H)


