    try:
        df = pd.read_sql(
            """
            SELECT filer_name, ticker, value_usd, report_date
            FROM institutional_holdings
            ORDER BY value_usd DESC
            LIMIT 10
            """,
            conn,
        )
    except Exception:
        df = pd.DataFrame()
