_EXECUTOR = ThreadPoolExecutor(max_workers=6)


async def _bg(fn, *args, **kwargs):
    loop = asyncio.get_event_loop()
    return await loop.run_in_executor(_EXECUTOR, functools.partial(fn, *args, **kwargs))


async def _send_result(loading_msg, text, parse_mode="HTML", reply_markup=None):
    """Edit loading placeholder. Auto-splits if over 4000 chars."""
    chunks = _split_msg(str(text))
    try:
        await loading_msg.edit_text(chunks[0], parse_mode=parse_mode,
                                    reply_markup=reply_markup if len(chunks) == 1 else None,
                                    disable_web_page_preview=True)
    except Exception:
        try:
            await loading_msg.reply_text(chunks[0], parse_mode=parse_mode,
                                         reply_markup=reply_markup if len(chunks) == 1 else None,
                                         disable_web_page_preview=True)
        except Exception:
            log.debug("suppressed exception", exc_info=True)
        try:
            await loading_msg.delete()
        except Exception:
            log.debug("suppressed exception", exc_info=True)
    for chunk in chunks[1:]:
        try:
            await loading_msg.reply_text(chunk, parse_mode=parse_mode,
                                         reply_markup=reply_markup if chunk == chunks[-1] else None,
                                         disable_web_page_preview=True)
        except Exception:
            log.debug("suppressed exception", exc_info=True)

# ─── Config ───


def _tg_spot_label(ticker: str) -> tuple:
    """Returns (best_price, display_label, source_key) using live/AH/EOD.
    source_key: 'ah' | 'pm' | 'live' | 'eod' | 'wkd'
    Use best_price for all calculations; display_label for Telegram output.
    """
    from datetime import datetime as _dt
    try:
        import pytz as _tz
        _now = _dt.now(_tz.timezone("US/Eastern"))
        _wday = _now.weekday()  # 0=Mon 6=Sun
        _hour = _now.hour + _now.minute / 60
    except Exception:
        _wday, _hour = 0, 12.0

    ah = _get_spot_with_ah(ticker)
    reg = ah["spot_reg"]
    ext = ah["spot_ext"]
    src = ah["ext_src"]
    is_ext = ah["is_extended"]
    chg = ah["ext_chg_pct"]

    if _wday >= 5:  # Weekend
        lbl = f"📅 WKD ${reg:.2f}" if reg > 0 else "📅 N/A"
        return reg, lbl, "wkd"
    if is_ext and ext > 0 and abs(ext - reg) > 0.01:
        if "Post" in src or "post" in src:
            return ext, f"🌙 AH ${ext:.2f} ({chg:+.1f}% vs EOD ${reg:.2f})", "ah"
        else:
            return ext, f"🌅 PM ${ext:.2f} ({chg:+.1f}% vs EOD ${reg:.2f})", "pm"
    if 9.5 <= _hour <= 16.0 and _wday < 5:
        return reg, f"📈 Live ${reg:.2f}", "live"
    return reg, f"☀️ EOD ${reg:.2f}", "eod"


# ─── Black-Scholes ───


async def _exit_batch_analysis(open_trades):
    """Return compact text summary for a set of open trades."""
    today = datetime.now().date()
    lines = []
    total_pnl = 0.0
    for _, r in open_trades.iterrows():
        try:
            tk  = str(r['ticker']).upper()
            ot  = str(r['option_type']).lower()
            st  = float(r['strike'])
            ep  = float(r['entry_price'])
            qty = abs(int(r.get('quantity', 1) or 1))
            ex  = str(r['expiry'])
            try:
                exp_dt = datetime.strptime(ex, '%Y-%m-%d').date()
                dte = (exp_dt - today).days
            except Exception:
                dte = None
            mid = None
            try:
                tk_obj = _yf_ticker(tk)
                avail = tk_obj.options
                exp_str = ex
                if avail and ex not in avail:
                    try:
                        req_dt = datetime.strptime(ex, '%Y-%m-%d').date()
                        avail_dts = [datetime.strptime(e, '%Y-%m-%d').date() for e in avail]
                        exp_str = min(avail_dts, key=lambda d: abs((d - req_dt).days)).strftime('%Y-%m-%d')
                    except Exception:
                        log.debug("suppressed exception", exc_info=True)
                chain  = tk_obj.option_chain(exp_str)
                df_c   = chain.puts if ot == 'put' else chain.calls
                row_c  = df_c.iloc[(df_c['strike'] - st).abs().argsort()[:1]]
                if not row_c.empty:
                    bid = float(row_c['bid'].iloc[0])
                    ask = float(row_c['ask'].iloc[0])
                    mid = (bid + ask) / 2 if bid >= 0 and ask >= 0 else None
            except Exception:
                log.debug("suppressed exception", exc_info=True)
            if mid is not None:
                pnl = (mid - ep) * qty * 100
                pnl_pct = (mid - ep) / ep * 100 if ep > 0 else 0
                total_pnl += pnl
                if pnl_pct >= 50:
                    sig = 'PROFIT'
                elif pnl_pct <= -30:
                    sig = 'CUT'
                elif dte is not None and dte <= 5:
                    sig = 'EXPIRY'
                else:
                    sig = 'HOLD'
                dte_s = f'{dte}d' if dte is not None else '?'
                lines.append(
                    f'{sig} {tk} {ot[0].upper()} ${st:.0f} DTE:{dte_s}\n'
                    f'  Entry:${ep:.2f} Now:${mid:.2f} P&L:{pnl_pct:+.0f}%')
            else:
                lines.append(f'{tk} {ot[0].upper()} ${st:.0f} no data')
        except Exception:
            continue
    summary = '\n'.join(lines) if lines else 'No data available.'
    if lines:
        n_with_data = sum(1 for l in lines if 'no data' not in l)
        winners = sum(1 for l in lines if 'P&L:+' in l or ('P&L:' in l and 'P&L:-' not in l and 'P&L:0' not in l))
        losers = n_with_data - winners
        em = '🟢' if total_pnl >= 0 else '🔴'
        summary += f'\n\n{em} <b>Total P&L: ${total_pnl:+,.0f}</b>  ({winners}W/{losers}L of {n_with_data} legs)'
    return summary


def _oi_signal_verdict(ticker, today_date, prev_date):
    """OI SIGNAL / Verdict text for EOD vs EOD (same format as live vs EOD)."""
    try:
        conn = get_conn()
        df_t = pd.read_sql("""
            SELECT strike, SUM(openInt_Call_now) AS c_oi, SUM(openInt_Put_now) AS p_oi
            FROM options_change WHERE ticker=? AND trade_date_now=?
            GROUP BY strike""", conn, params=(ticker.upper(), today_date))
        df_p = pd.read_sql("""
            SELECT strike, SUM(openInt_Call_now) AS c_oi, SUM(openInt_Put_now) AS p_oi
            FROM options_change WHERE ticker=? AND trade_date_now=?
            GROUP BY strike""", conn, params=(ticker.upper(), prev_date))
        sd = pd.read_sql("""SELECT close FROM stock_daily WHERE ticker=?
            ORDER BY trade_date DESC LIMIT 1""",
            conn, params=(ticker.upper(),))
        kl = _oi_key_levels(ticker.upper(), conn)
        conn.close()
    except Exception:
        return ""

    if df_t.empty or df_p.empty:
        return ""

    c_now = float(df_t["c_oi"].sum()); p_now = float(df_t["p_oi"].sum())
    c_prv = float(df_p["c_oi"].sum()); p_prv = float(df_p["p_oi"].sum())
    call_chg = c_now - c_prv; put_chg = p_now - p_prv
    call_pct = call_chg / max(c_prv, 1) * 100
    put_pct  = put_chg  / max(p_prv, 1) * 100
    pcr_eod  = p_prv / max(c_prv, 1)
    pcr_now  = p_now / max(c_now, 1)
    spot     = float(sd["close"].iloc[0]) if not sd.empty else 0.0

    if put_chg > 0 and abs(put_chg) > abs(call_chg) * 1.2:
        sig = "BEARISH";  sig_em = "\U0001f4c9"
    elif call_chg > 0 and call_chg > abs(put_chg) * 1.2:
        sig = "BULLISH";  sig_em = "\U0001f4c8"
    elif call_chg > 0 and put_chg > 0:
        sig = "STRADDLE"; sig_em = "⚡"
    elif call_chg < 0 and put_chg < 0:
        sig = "UNWIND";   sig_em = "\U0001f504"
    elif pcr_now > 1.3:
        sig = "BEARISH";  sig_em = "\U0001f4c9"
    elif pcr_now < 0.7:
        sig = "BULLISH";  sig_em = "\U0001f4c8"
    else:
        sig = "NEUTRAL";  sig_em = "⚪"

    reasons = []
    if put_chg > 0 and abs(put_chg) > abs(call_chg):
        reasons.append(f"• Put OI grew {put_chg:+,.0f} ({put_pct:+.1f}%) — traders adding downside bets")
    if call_chg > 0 and call_chg > abs(put_chg):
        reasons.append(f"• Call OI grew {call_chg:+,.0f} ({call_pct:+.1f}%) — bullish positioning increasing")
    if call_chg < 0:
        reasons.append(f"• Call OI fell {call_chg:+,.0f} ({call_pct:+.1f}%) — bulls reducing exposure")
    if pcr_now > pcr_eod * 1.05:
        reasons.append(f"• PCR rose {pcr_eod:.2f} → {pcr_now:.2f} (more puts vs calls = bearish lean)")
    elif pcr_now < pcr_eod * 0.95:
        reasons.append(f"• PCR fell {pcr_eod:.2f} → {pcr_now:.2f} (fewer puts vs calls = bullish lean)")
    if not reasons:
        reasons.append(f"• Net change: calls {call_chg:+,.0f}  puts {put_chg:+,.0f}")

    strike_lines = []
    if kl:
        cw = kl.get("call_wall", 0); pw = kl.get("put_wall", 0)
        mp = kl.get("max_pain", 0)
        cw_oi = kl.get("call_wall_oi", 0); pw_oi = kl.get("put_wall_oi", 0)
        if cw and spot:
            strike_lines.append(f"  Call Wall: ${cw:.0f} ({(cw-spot)/spot*100:+.1f}% from spot) OI:{cw_oi/1000:.0f}K — CEILING")
        if pw and spot:
            strike_lines.append(f"  Put Wall:  ${pw:.0f} ({(pw-spot)/spot*100:+.1f}% from spot) OI:{pw_oi/1000:.0f}K — FLOOR")
        if mp and spot:
            _dir = "above" if mp > spot else "below"
            strike_lines.append(f"  Max Pain:  ${mp:.0f} ({(mp-spot)/spot*100:+.1f}%) {_dir} spot — expiry magnet")

    simple_ans = ""
    if spot and kl:
        cw = kl.get("call_wall", 0); pw = kl.get("put_wall", 0); mp = kl.get("max_pain", 0)
        bull_tgt = cw if cw and cw > spot else spot * 1.03
        bear_tgt = pw if pw and pw < spot else spot * 0.97
        simple_ans = (
            chr(10) + "\U0001f3af <b>Simple Answer</b>" + chr(10)
            + ("⚠️" if sig in ("BEARISH", "STRADDLE") else "✅")
            + f" Bullish scenario → ${bull_tgt:.0f} target"
            + (" (call wall)" if cw and cw > spot else " (+3% est)") + chr(10)
            + ("❌" if sig in ("BEARISH", "STRADDLE") else "⚠️")
            + f" Bearish scenario → ${bear_tgt:.0f} target"
            + (" (put wall)" if pw and pw < spot else " (-3% est)")
            + (chr(10) + f"\U0001f9f2 Max Pain ${mp:.0f} — price may drift here by expiry" if mp else "")
        )

    return (
        f"{sig_em} <b>{ticker} OI SIGNAL — {today_date}</b>" + chr(10)
        + f"<b>Verdict: {sig}</b>" + chr(10) + chr(10)
        + f"<b>Why {sig.title()}?</b>" + chr(10)
        + chr(10).join(reasons)
        + (chr(10) + chr(10) + "<b>Key Strike Levels</b>" + chr(10) + chr(10).join(strike_lines) if strike_lines else "")
        + simple_ans
        + chr(10) + chr(10) + f"<i>Net call chg: {call_chg:+,.0f}  Net put chg: {put_chg:+,.0f}</i>"
    )


def _oi_volume_chart(ticker: str, conn, spot: float, latest_date: str):
    """Option Volume Profile — calls top, puts bottom, OI as dashed outline.
    Returns BytesIO PNG or None.
    """
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        import numpy as np

        BG = "#0D1117"; PANEL = "#161B22"; TXT = "#E6EDF3"; GRID = "#30363D"

        df = pd.read_sql("""
            SELECT strike,
                   SUM(vol_Call_now)    AS c_vol,
                   SUM(vol_Put_now)     AS p_vol,
                   SUM(openInt_Call_now) AS c_oi,
                   SUM(openInt_Put_now)  AS p_oi
            FROM options_change
            WHERE ticker=? AND trade_date_now=?
              AND strike BETWEEN ? AND ?
            GROUP BY strike ORDER BY strike
        """, conn, params=(ticker, latest_date, spot * 0.80, spot * 1.20))

        if df.empty:
            return None

        for col in ["c_vol", "p_vol", "c_oi", "p_oi"]:
            df[col] = pd.to_numeric(df[col], errors="coerce").fillna(0)

        df["total_vol"] = df["c_vol"] + df["p_vol"]
        df = df[df["total_vol"] > 0].nlargest(20, "total_vol").sort_values("strike")
        if df.empty:
            return None

        strikes = df["strike"].tolist()
        c_vol = df["c_vol"].tolist()
        p_vol = [-v for v in df["p_vol"].tolist()]
        c_oi  = df["c_oi"].tolist()
        p_oi  = [-v for v in df["p_oi"].tolist()]
        x = np.arange(len(strikes))
        w = 0.38

        fig, ax = plt.subplots(figsize=(10, 5), facecolor=BG)
        ax.set_facecolor(PANEL)

        ax.bar(x - w/2, c_vol, width=w, color="#2D8B2D", label="Call Vol", alpha=0.85)
        ax.bar(x + w/2, p_vol, width=w, color="#8B0000", label="Put Vol",  alpha=0.85)
        ax.bar(x - w/2, c_oi,  width=w, fill=False, edgecolor="#00CC66", linewidth=0.8, linestyle="--", label="Call OI")
        ax.bar(x + w/2, p_oi,  width=w, fill=False, edgecolor="#FF6666", linewidth=0.8, linestyle="--", label="Put OI")

        atm_idx = min(range(len(strikes)), key=lambda i: abs(strikes[i] - spot))
        ax.axvline(atm_idx, color="#FFD700", linewidth=1.5, linestyle="--", alpha=0.9, label="ATM")

        try:
            kl = _oi_key_levels(ticker, conn)
            if kl:
                for wall_k, wall_lbl, wall_col in [
                    ("call_wall", "CWall", "#00CC66"),
                    ("put_wall",  "PWall", "#FF4444"),
                ]:
                    wv = kl.get(wall_k, 0)
                    if wv and wv in strikes:
                        wi = strikes.index(wv)
                        y_top = max(max(c_vol), 1)
                        ax.axvline(wi, color=wall_col, linewidth=1.2, linestyle=":", alpha=0.8)
                        ax.text(wi + 0.15, y_top * 0.85, wall_lbl,
                                fontsize=7, color=wall_col, rotation=90, va="top")
        except Exception:
            log.debug("suppressed exception", exc_info=True)

        ax.set_xticks(x)
        ax.set_xticklabels([f"${s:.0f}" for s in strikes], fontsize=7, color=TXT, rotation=45, ha="right")
        ax.tick_params(colors=TXT, length=0)
        ax.axhline(0, color=TXT, linewidth=0.6)
        ax.legend(fontsize=7, facecolor=PANEL, edgecolor=GRID, labelcolor=TXT, loc="upper right")
        ax.set_title(f"{ticker}  Option Volume Profile  ·  Spot ${spot:.0f}  ·  {latest_date}",
                     color=TXT, fontsize=10, fontweight="bold")
        ax.set_ylabel("Volume (calls +, puts −)", fontsize=8, color=TXT)
        for spine in ax.spines.values():
            spine.set_edgecolor(GRID)
        ax.yaxis.label.set_color(TXT)
        ax.tick_params(axis="y", colors=TXT)
        fig.text(0.5, 0.01,
                 "Solid bars=today volume  Dashed outline=open interest  Gold dashed=ATM",
                 ha="center", fontsize=7, color="#8B949E")
        plt.tight_layout(rect=[0, 0.04, 1, 1])

        buf = BytesIO()
        plt.savefig(buf, format="png", dpi=105, bbox_inches="tight", facecolor=BG)
        plt.close(fig)
        buf.seek(0)
        return buf
    except Exception as _e:
        log.warning(f"_oi_volume_chart failed: {_e}")
        return None


def _oi_multiday_conviction_text(ticker, n_days=7):
    """Multi-day OI conviction summary — Telegram mobile format (pre blocks ≤28 chars)."""
    conn = get_conn()
    try:
        dates_df = pd.read_sql(
            "SELECT DISTINCT trade_date_now FROM options_change WHERE ticker=? "
            "ORDER BY trade_date_now DESC",
            conn, params=[ticker.upper()])
        all_dates = dates_df["trade_date_now"].tolist()
    except Exception:
        conn.close()
        return ""
    dates_use = all_dates[:n_days]
    if not dates_use:
        conn.close()
        return ""
    frames = []
    for td in dates_use:
        try:
            df = pd.read_sql(
                "SELECT strike, change_OI_Call, change_OI_Put "
                "FROM options_change WHERE ticker=? AND trade_date_now=?",
                conn, params=[ticker.upper(), td])
            if not df.empty:
                df["trade_date"] = td
                frames.append(df)
        except Exception:
            continue
    conn.close()
    if not frames:
        return ""
    multi_df = pd.concat(frames, ignore_index=True)
    day_agg = multi_df.groupby(["strike", "trade_date"]).agg(
        call_chg=("change_OI_Call", "sum"),
        put_chg=("change_OI_Put", "sum"),
    ).reset_index()
    day_agg["net_chg"] = day_agg["call_chg"] - day_agg["put_chg"]
    strike_agg = day_agg.groupby("strike").agg(
        cum_call=("call_chg", "sum"),
        cum_put=("put_chg", "sum"),
        cum_net=("net_chg", "sum"),
        n_days=("trade_date", "count"),
        bull_days=("net_chg", lambda x: (x > 0).sum()),
        bear_days=("net_chg", lambda x: (x < 0).sum()),
    ).reset_index()
    date_rank = {d: i for i, d in enumerate(dates_use)}
    streaks = []
    for strike in strike_agg["strike"].unique():
        sk = day_agg[day_agg["strike"] == strike].copy()
        sk["rank"] = sk["trade_date"].map(date_rank)
        sk = sk.sort_values("rank")
        streak, streak_dir = 0, "FLT"
        for _, row in sk.iterrows():
            cur = "BUL" if row["net_chg"] > 0 else ("BEA" if row["net_chg"] < 0 else "FLT")
            if streak == 0:
                streak_dir = cur
                streak = 1 if cur != "FLT" else 0
            elif cur == streak_dir and cur != "FLT":
                streak += 1
            else:
                break
        streaks.append({"strike": strike, "streak": streak, "streak_dir": streak_dir})
    streak_df = pd.DataFrame(streaks)
    strike_agg = strike_agg.merge(streak_df, on="strike", how="left")
    strike_agg["consistency"] = strike_agg.apply(
        lambda r: r["bull_days"] / r["n_days"] if r["cum_net"] >= 0
                  else r["bear_days"] / r["n_days"], axis=1)
    max_cum = strike_agg["cum_net"].abs().max()
    strike_agg["mag"] = (strike_agg["cum_net"].abs() / max_cum * 4).clip(0, 4) if max_cum > 0 else 0.0
    strike_agg["cons_s"] = (strike_agg["consistency"] * 3).clip(0, 3)
    strike_agg["streak_s"] = strike_agg["streak"].clip(0, 2).astype(float)
    strike_agg["conviction"] = (strike_agg["mag"] + strike_agg["cons_s"] + strike_agg["streak_s"]).clip(0, 9).round(1)
    strike_agg["direction"] = strike_agg["cum_net"].apply(lambda x: "BUL" if x > 0 else ("BEA" if x < 0 else "FLT"))
    strike_agg = strike_agg.sort_values("conviction", ascending=False)

    def _fk(n):
        return f"{n/1000:.0f}K" if abs(n) >= 1000 else f"{n:.0f}"

    lines_out = [f"<b>📈 {ticker} {n_days}d OI BUILD</b>", ""]
    lines_out.append("<pre>")
    lines_out.append("Stk  Dir Scr Str")
    lines_out.append("-" * 17)
    for _, r in strike_agg.head(6).iterrows():
        sk = int(r["strike"])
        d = str(r["direction"])
        sc = f"{r['conviction']:.1f}"
        st_days = f"{int(r['streak'])}d"
        arrow = "^" if d == "BUL" else ("v" if d == "BEA" else "-")
        lines_out.append(f"{sk:<5}{d} {sc:<4}{st_days}{arrow}")
    lines_out.append("</pre>")
    lines_out.append("")
    hc = strike_agg[strike_agg["conviction"] >= 5.5].head(2)
    if not hc.empty:
        lines_out.append("🚀 <b>Trade Ideas</b>")
        for _, r in hc.iterrows():
            sk = int(r["strike"])
            d = str(r["direction"])
            stk = int(r["streak"])
            net = _fk(r["cum_net"])
            pct = f"{r['consistency']:.0%}"
            icon = "🟢" if d == "BUL" else "🔴"
            setup = f"Long  Call" if d == "BUL" else f"Long  Put"
            reason = f"Build {stk}d · Net {'+' if r['cum_net']>0 else ''}{net} · {pct}"
            lines_out.append(f"{icon} <b>{setup}</b>")
            lines_out.append(f"  {reason}")
        lines_out.append("")
    bull_hi = len(strike_agg[(strike_agg["direction"] == "BUL") & (strike_agg["conviction"] >= 6)])
    bear_hi = len(strike_agg[(strike_agg["direction"] == "BEA") & (strike_agg["conviction"] >= 6)])
    bias = "🟢 BULLISH" if bull_hi > bear_hi else ("🔴 BEARISH" if bear_hi > bull_hi else "⚪ NEUTRAL")
    lines_out.append(f"Bias: <b>{bias}</b> ({bull_hi}B/{bear_hi}Be)")
    lines_out.append(f"<i>({len(dates_use)} trade days)</i>")
    return "\n".join(lines_out)


def _fk_amt(n):
    """+39K / -1.2M compact signed money/contract formatter (shared by write-up)."""
    n = float(n or 0); s = "+" if n >= 0 else "-"; a = abs(n)
    if a >= 1_000_000: return f"{s}{a/1_000_000:.1f}M"
    if a >= 1_000:     return f"{s}{a/1_000:.0f}K"
    return f"{s}{a:.0f}"


def _ticker_chart_png(tk, levels=None):
    """One visual to grasp a ticker fast (user ask 2026-07-19):
      • TOP  — today's intraday move (1-min line) + volume.
      • BOTTOM — ~2yr daily close with a VOLUME-BY-PRICE histogram (where the most
        volume traded = 'Point of Control') and the OI call-wall / put-wall / max-pain
        drawn as horizontal support/resistance lines.
    Design mirrors how traders read charts (TradingView VPVR 'point of control' +
    options max-pain as S/R). Returns PNG bytes, or None if no data."""
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        from matplotlib.gridspec import GridSpec
        import numpy as _np, os as _os, sqlite3 as _sql
        from io import BytesIO as _BytesIO
        tk = str(tk).upper()
        BG="#0d1117"; GRID="#21262d"; LINE="#58a6ff"; TEXT="#c9d1d9"
        UP="#26a641"; DN="#da3633"; CW="#f85149"; PW="#3fb950"; MP="#d29922"; VP="#6e7681"

        conn = get_conn()
        if levels is None:
            levels = _oi_key_levels(tk, conn) or {}
        daily = pd.read_sql("SELECT trade_date, close, volume FROM stock_history WHERE ticker=? "
                            "ORDER BY trade_date DESC LIMIT 504", conn, params=(tk,))
        conn.close()
        if daily.empty:
            return None
        daily = daily.iloc[::-1].reset_index(drop=True)
        d_close = pd.to_numeric(daily["close"],  errors="coerce").to_numpy()
        d_vol   = pd.to_numeric(daily["volume"], errors="coerce").fillna(0).to_numpy()
        spot = float(d_close[-1])

        # latest intraday session
        intra = pd.DataFrame(); idate = None
        try:
            ic = _sql.connect(_os.path.join(DATA_DIR, "US_intraday.db"))
            intra = pd.read_sql("SELECT ts, close, volume FROM intraday_bars WHERE ticker=? AND "
                                "trade_date=(SELECT MAX(trade_date) FROM intraday_bars WHERE ticker=?) "
                                "ORDER BY ts", ic, params=(tk, tk))
            _r = ic.execute("SELECT MAX(trade_date) FROM intraday_bars WHERE ticker=?", (tk,)).fetchone()
            idate = _r[0] if _r else None
            ic.close()
        except Exception:
            pass

        fig = plt.figure(figsize=(7.2, 8.2), dpi=130, facecolor=BG)
        gs  = GridSpec(2, 2, width_ratios=[4, 1], height_ratios=[1, 1.5],
                       hspace=0.30, wspace=0.03, figure=fig)
        ax_i = fig.add_subplot(gs[0, :])
        ax_p = fig.add_subplot(gs[1, 0])
        ax_v = fig.add_subplot(gs[1, 1], sharey=ax_p)
        for a in (ax_i, ax_p, ax_v):
            a.set_facecolor(BG); a.grid(True, color=GRID, lw=0.5, ls="--")
            a.spines[:].set_visible(False); a.tick_params(colors=TEXT, labelsize=7)

        # ── Panel A: today's intraday ──
        if not intra.empty and len(intra) > 2:
            icl = pd.to_numeric(intra["close"], errors="coerce").to_numpy()
            xs  = list(range(len(icl)))
            net = (icl[-1] - icl[0]) / icl[0] * 100 if icl[0] else 0
            col = UP if net >= 0 else DN
            ax_i.plot(xs, icl, color=col, lw=1.3)
            ax_i.fill_between(xs, icl, _np.nanmin(icl), color=col, alpha=0.08)
            axiv = ax_i.twinx()
            axiv.bar(xs, pd.to_numeric(intra["volume"], errors="coerce").fillna(0).to_numpy() / 1e3,
                     color=VP, alpha=0.30, width=1.0)
            axiv.set_yticks([]); axiv.spines[:].set_visible(False)
            ax_i.set_title(f"{tk}  today ({idate})   {icl[-1]:,.2f}   {net:+.2f}%",
                           loc="left", color=TEXT, fontsize=10, fontweight="bold", pad=6)
            ax_i.yaxis.tick_right(); ax_i.tick_params(axis="x", bottom=False, labelbottom=False)
        else:
            ax_i.text(0.5, 0.5, "No intraday bars for latest session",
                      ha="center", va="center", color=TEXT, fontsize=9)
            ax_i.set_xticks([]); ax_i.set_yticks([])

        # ── Panel B: ~2yr daily close + option walls ──
        xs2 = list(range(len(d_close)))
        ax_p.plot(xs2, d_close, color=LINE, lw=1.1)
        cw = float(levels.get("call_wall") or 0); pw = float(levels.get("put_wall") or 0)
        mp = float(levels.get("max_pain")  or 0)
        def _hl(val, color, label):
            if val and 0.5 * spot < val < 2.0 * spot:
                ax_p.axhline(val, color=color, lw=1.0, ls="--", alpha=0.9)
                ax_p.text(len(d_close) * 0.995, val, f" {label} {val:,.0f}",
                          color=color, fontsize=7, va="center", ha="right")
        _hl(cw, CW, "Call wall"); _hl(pw, PW, "Put wall"); _hl(mp, MP, "Max pain")
        ax_p.axhline(spot, color=TEXT, lw=0.8, ls=":", alpha=0.7)
        lo, hi = float(_np.nanmin(d_close)), float(_np.nanmax(d_close))
        walls_on = [v for v in (cw, pw, mp) if v and 0.5 * spot < v < 2.0 * spot]
        ymin = min([lo] + walls_on); ymax = max([hi] + walls_on)
        pad = (ymax - ymin) * 0.04 or 1.0
        ax_p.set_ylim(ymin - pad, ymax + pad)
        ax_p.set_title(f"{tk}  ~{len(d_close)/252:.1f}yr daily  ·  spot {spot:,.0f}",
                       loc="left", color=TEXT, fontsize=9, fontweight="bold", pad=4)
        ax_p.yaxis.tick_left(); ax_p.tick_params(axis="x", bottom=False, labelbottom=False)

        # ── Panel C: volume-by-price (where volume traded) ──
        if hi > lo:
            nb = 40
            histv, edges = _np.histogram(d_close, bins=nb, range=(lo, hi), weights=d_vol)
            centers = (edges[:-1] + edges[1:]) / 2
            if histv.max() > 0:
                poc = int(_np.argmax(histv))
                cols = [MP if i == poc else VP for i in range(nb)]
                ax_v.barh(centers, histv / histv.max(), height=(hi - lo) / nb * 0.9,
                          color=cols, alpha=0.75)
                ax_v.text(0.02, centers[poc], f" POC {centers[poc]:,.0f}",
                          color=MP, fontsize=6.5, va="center", ha="left")
        # price ledger on the far-right y-axis (user 2026-07-20): ax_v shares the price
        # axis, so its right ticks label the stock-value scale down the right edge.
        ax_v.set_xticks([])
        ax_v.yaxis.tick_right(); ax_v.yaxis.set_label_position("right")
        ax_v.tick_params(axis="y", labelright=True, labelleft=False, colors=TEXT, labelsize=7)
        try:
            from matplotlib.ticker import FuncFormatter as _FF
            ax_v.yaxis.set_major_formatter(_FF(lambda v, _p: f"${v:,.0f}"))
        except Exception:
            pass
        ax_v.set_title("Vol@price", color=TEXT, fontsize=7, pad=4)

        buf = _BytesIO(); fig.savefig(buf, format="png", facecolor=BG, bbox_inches="tight")
        plt.close(fig); buf.seek(0)
        return buf.read()
    except Exception as _e:
        log.debug(f"_ticker_chart_png {tk} failed: {_e}", exc_info=True)
        try:
            import matplotlib.pyplot as _plt; _plt.close("all")
        except Exception:
            pass
        return None


def _ticker_writeup(tk, conn, spot=0.0, call_chg=0.0, put_chg=0.0, pcr=1.0,
                    sig_lbl="", levels=None, latest_date=None):
    """Plain-English 'what's happening -> what it means -> your trade & risk' synthesis
    for a ticker's OI picture. Reusable across the OI-detail / OI-rolls / mirofish views
    (user ask 2026-07-19: 'explain in simple language what happened, leading to what,
    and the trade & risk'). Returns an HTML block (or '' on failure)."""
    try:
        tk = str(tk).upper()
        # self-compute flow + signal when the caller didn't pass them (one-call reuse)
        if not latest_date:
            _r = pd.read_sql("SELECT DISTINCT trade_date_now FROM options_change WHERE ticker=? "
                             "ORDER BY trade_date_now DESC LIMIT 1", conn, params=(tk,))
            latest_date = _r["trade_date_now"].iloc[0] if not _r.empty else None
        if (not sig_lbl) and latest_date:
            _a = pd.read_sql("SELECT SUM(change_OI_Call) cc, SUM(change_OI_Put) pp, "
                             "SUM(openInt_Call_now) co, SUM(openInt_Put_now) po "
                             "FROM options_change WHERE ticker=? AND trade_date_now=?",
                             conn, params=(tk, latest_date))
            if not _a.empty:
                call_chg = float(_a["cc"].iloc[0] or 0); put_chg = float(_a["pp"].iloc[0] or 0)
                _co = float(_a["co"].iloc[0] or 0);      _po = float(_a["po"].iloc[0] or 0)
                pcr = _po / _co if _co > 0 else 1.0
                sig_lbl, _ = _oi_signal_light(call_chg, put_chg, pcr)
        if levels is None:
            levels = _oi_key_levels(tk, conn, latest_date, spot=spot) or {}
        cw = float(levels.get("call_wall") or 0)
        pw = float(levels.get("put_wall")  or 0)
        mp = float(levels.get("max_pain")  or 0)
        spot = float(spot or 0)
        if spot <= 0:
            try:
                _sd = pd.read_sql("SELECT close FROM stock_daily WHERE ticker=? "
                                  "ORDER BY trade_date DESC LIMIT 1", conn, params=(tk,))
                _dbc = float(_sd["close"].iloc[0]) if not _sd.empty else 0.0
                # LIVE-first: every caller omits `spot`, so this fallback decides the price the
                # whole write-up is built on — narrative, wall distances, BS prices and trade
                # ideas. Taking the EOD close here meant that during RTH the header showed a
                # live quote while the body priced off YESTERDAY's close (e.g. QQQ header
                # $704.16 vs body $696, which made a $680 call print BELOW intrinsic).
                # _cur_price() serves intraday when the market is open and falls back to this
                # same close off-hours, so this is strictly better in both states.
                spot = float((_cur_price(tk, _dbc) or (0,))[0] or _dbc)
            except Exception:
                pass

        # ── read of the flow ──
        if "BULL" in sig_lbl and "HEDGE" not in sig_lbl:   bias, bem = "bullish — call buyers in control", "🟢"
        elif "BEAR" in sig_lbl:                            bias, bem = "bearish — put buyers in control", "🔴"
        elif "HEDGE" in sig_lbl:                           bias, bem = "defensive — puts look like protection, not a crash bet", "🔵"
        elif "STRADDLE" in sig_lbl:                        bias, bem = "two-sided — the market is pricing a big MOVE, not a direction (event/vol play)", "🟡"
        elif "UNWIND" in sig_lbl:                          bias, bem = "unwinding — both sides closing, conviction fading", "⚪"
        else:                                              bias, bem = "mixed — no clear edge yet", "⚪"

        lines = ["\n<b>📖 What's happening (plain English)</b>"]
        lines.append(f"{bem} <b>Read:</b> {bias}.")
        lines.append(f"Today's option flow: calls {_fk_amt(call_chg)} vs puts {_fk_amt(put_chg)} in new OI "
                     f"(PCR {pcr:.2f} — {'puts&gt;calls' if pcr>1.1 else ('calls&gt;puts' if pcr<0.9 else 'balanced')}).")

        # ── walls vs price ──
        if spot > 0 and cw > 0 and pw > 0:
            up = (cw - spot) / spot * 100      # signed vs spot; POSITIVE only if wall is above
            dn = (pw - spot) / spot * 100
            # Price does NOT always sit between the walls. Saying "sits between" and calling
            # $330 a "ceiling" while price is $357 is simply false, and it printed a negative
            # % next to the word ceiling (reported 2026-08-03). Branch on where spot actually
            # is — and when a wall has been breached, say what it becomes.
            if pw <= spot <= cw:
                lines.append(f"Price <b>${spot:,.0f}</b> sits between the put-wall floor "
                             f"<b>${pw:,.0f}</b> ({dn:+.1f}%) and the call-wall ceiling "
                             f"<b>${cw:,.0f}</b> ({up:+.1f}%).")
            elif spot > cw:
                lines.append(f"Price <b>${spot:,.0f}</b> has <b>cleared both walls</b> — the call wall "
                             f"<b>${cw:,.0f}</b> ({up:+.1f}%) and put wall <b>${pw:,.0f}</b> ({dn:+.1f}%) "
                             f"now sit BELOW price. That call wall is no longer resistance; it is the "
                             f"first support shelf on a pullback.")
            else:
                lines.append(f"Price <b>${spot:,.0f}</b> is <b>below both walls</b> — the put wall "
                             f"<b>${pw:,.0f}</b> ({dn:+.1f}%) and call wall <b>${cw:,.0f}</b> ({up:+.1f}%) "
                             f"are overhead. The put-wall support has already broken; it becomes "
                             f"resistance on the way back up.")
            if mp > 0:
                dmp = (mp - spot) / spot * 100
                _dir = "DOWN" if dmp < -0.2 else ("UP" if dmp > 0.2 else "sideways to")
                lines.append(f"Max-pain <b>${mp:,.0f}</b> ({dmp:+.1f}%) is where most options expire "
                             f"worthless — the pin, if it happens, pulls price <b>{_dir}</b> "
                             f"{abs(dmp):.1f}% into Friday's expiry.")
            # "AT" the wall means NEAR it, not miles past it. This fired whenever spot was
            # anywhere above cw*0.99, so a price that had cleared the wall by 11% still got
            # "right at the call wall" printed directly under a sentence saying it had
            # cleared both walls (user 2026-08-03).
            if cw * 0.99 <= spot <= cw * 1.02:
                lines.append("⚠️ Right at the <b>call wall</b>: heavy call OI = resistance. Needs a volume break to go higher; dealers sell strength.")
            elif pw * 0.98 <= spot <= pw * 1.01:
                lines.append("🛟 Right at the <b>put wall</b>: heavy put OI = support shelf. Bounces are common unless it breaks down on volume.")

        # ── your open position + risk ──
        try:
            pos = pd.read_sql(
                "SELECT strike, option_type, quantity, expiry, entry_price FROM trades "
                "WHERE ticker=? AND status='OPEN' AND UPPER(option_type)<>'STOCK'",
                conn, params=(tk,))
        except Exception:
            pos = pd.DataFrame()
        if not pos.empty:
            prows = []
            net_dir = 0
            for _, p in pos.iterrows():
                typ = str(p["option_type"]).upper()[:1]
                K   = float(p["strike"] or 0)
                q   = int(float(p["quantity"] or 0))
                if typ == "C": money = "ITM" if spot > K else "OTM"
                else:          money = "ITM" if (spot and spot < K) else "OTM"
                net_dir += (1 if typ == "C" else -1) * (1 if q >= 0 else -1)
                prows.append((f"{'+' if q>=0 else ''}{q}", f"${K:.0f}{typ}", str(p["expiry"])[5:] or "-", money))
            lines.append("\n<b>📌 Your position & risk</b>\n"
                         + _pipe_table(("Qty", "Leg", "Exp", "Now"), prows, right_cols={0}))
            # aggregate risk note (net_dir signs bullish>0 / bearish<0, leg-agnostic)
            if net_dir > 0:
                lines.append("<i>Net <b>bullish</b> lean: you want price UP toward the call wall "
                             + (f"${cw:,.0f}. " if cw>0 else "the ceiling. ")
                             + "Risk = time decay + a stall there, and max-pain pulling it back into expiry.</i>")
            elif net_dir < 0:
                lines.append("<i>Net <b>bearish</b> lean: you want price DOWN toward the put wall "
                             + (f"${pw:,.0f}. " if pw>0 else "support. ")
                             + "Risk = a bounce off support and time decay if it stalls.</i>")
            else:
                lines.append("<i>Mixed legs (spread/hedge): you profit from the MOVE/range, not raw direction — watch IV and the walls as your box.</i>")
        else:
            lines.append("\n<i>📌 No open position in this name — this is a watch, not a trade.</i>")

        # ── one actionable suggestion ──
        if "STRADDLE" in sig_lbl:
            sug = "Both sides are loading up — favors OWNING premium (long straddle/strangle) or waiting for the break, NOT selling premium into an event."
        elif "BULL" in sig_lbl and "HEDGE" not in sig_lbl and cw > 0:
            sug = f"Momentum up: a break above ${cw:,.0f} on volume opens the next leg; keep a stop below the put wall ${pw:,.0f}."
        elif "BEAR" in sig_lbl and pw > 0:
            sug = f"Pressure down: a break below ${pw:,.0f} accelerates; watch for a bounce first if it's already stretched."
        elif "HEDGE" in sig_lbl:
            sug = "Puts are protection here — don't read it as an outright short signal; the underlying trend still rules."
        else:
            sug = "No clear edge — wait for calls or puts to clearly dominate before committing premium."
        lines.append(f"💡 <b>Suggestion:</b> {sug}")
        lines.append("<i>Educational, not financial advice.</i>")
        return "\n".join(lines)
    except Exception as _e:
        log.debug(f"_ticker_writeup {tk} failed: {_e}", exc_info=True)
        return ""


async def signal_ticker_detail(query, ticker):
    """Per-ticker OI signal detail with this-week/next-week expiry split, OI walls, volume analysis."""
    tk = str(ticker).upper()
    _loading = await query.message.reply_text(f"⏳ Loading {tk} signals...", parse_mode=H)
    conn = get_conn()
    try:
        lr = pd.read_sql("""SELECT DISTINCT trade_date_now FROM options_change WHERE ticker=?
            ORDER BY trade_date_now DESC
            LIMIT 1""", conn, params=(tk,))
        if lr.empty:
            await query.message.reply_text(f"No OI data for {tk}.", reply_markup=InlineKeyboardMarkup([[BACK_BTN]]))
            conn.close(); return
        latest_date = lr["trade_date_now"].iloc[0]
        agg = pd.read_sql("""SELECT SUM(change_OI_Call) as cc, SUM(change_OI_Put) as pp,
               SUM(openInt_Call_now) as co, SUM(openInt_Put_now) as po
            FROM options_change WHERE ticker=? AND trade_date_now=?""", conn, params=(tk, latest_date))
        call_chg = float(agg["cc"].iloc[0] or 0) if not agg.empty else 0
        put_chg  = float(agg["pp"].iloc[0] or 0) if not agg.empty else 0
        call_oi  = float(agg["co"].iloc[0] or 0) if not agg.empty else 0
        put_oi   = float(agg["po"].iloc[0] or 0) if not agg.empty else 0
        pcr = put_oi / call_oi if call_oi > 0 else 1.0
    except Exception as _e:
        log.warning(f"signal_ticker_detail {tk}: {_e}")
        conn.close(); return

    sig_lbl, _sig_hex = _oi_signal_light(call_chg, put_chg, pcr)   # 2nd return is a hex COLOR, not text
    _SIG_DESC = {
        "BULLISH":    "Call OI dominating — bullish flow",
        "BEARISH":    "Put OI dominating — bearish flow",
        "HEDGE":      "Puts building on high PCR — likely protection",
        "BULL+HEDGE": "Calls lead, puts hedging — net bullish",
        "STRADDLE":   "Both sides building — event / vol play",
        "UNWIND":     "Both sides unwinding — positions closing",
        "NEUTRAL":    "No clear OI edge",
    }
    sig_txt = _SIG_DESC.get(sig_lbl, "")
    sig_em = "🟢" if "BULL" in sig_lbl else ("🔴" if "BEAR" in sig_lbl else ("🔵" if "HEDGE" in sig_lbl else "🟡"))

    def _fk(n):
        n = float(n or 0); s = "+" if n >= 0 else "-"
        a = abs(n)
        if a >= 1_000_000: return f"{s}{a/1_000_000:.1f}M"
        if a >= 1_000:     return f"{s}{a/1_000:.0f}K"
        return f"{s}{abs(n):.0f}"

    # Live price line (OI itself is EOD; the PRICE should be live during market hours)
    _px_line = ""
    _pxv = 0.0            # must exist even if the price lookup below fails
    try:
        _dbc = pd.read_sql("SELECT close FROM stock_daily WHERE ticker=? ORDER BY trade_date DESC LIMIT 1",
                           conn, params=(tk,))
        _dbclose = float(_dbc["close"].iloc[0]) if not _dbc.empty else 0.0
        _pxv, _islive, _asof = _cur_price(tk, db_close=_dbclose)
        if _pxv > 0:
            _dl = (f" ({(_pxv/_dbclose-1)*100:+.2f}%)" if (_islive and _dbclose) else "")
            _px_line = (f"{'🟢' if _islive else '⏺'} <b>${_pxv:,.2f}</b>{_dl}  "
                        f"<i>{_asof}{'' if _islive else ' · OI as of '+str(latest_date)}</i>")
    except Exception:
        log.debug("oi-detail price line failed", exc_info=True)

    parts = [
        hdr(f"📊 {tk} · {latest_date}"),
    ]
    if _px_line:
        parts.append(_px_line)
    parts += [
        f"{sig_em} <b>{sig_lbl}</b>" + (f"\n<i>{sig_txt}</i>" if sig_txt else ""),
        _pipe_table(("Metric", "Value"),
                    [("Call dOI", _fk(call_chg)), ("Put dOI", _fk(put_chg)),
                     ("PCR", f"{pcr:.2f}")], right_cols={1})
    ]

    # OI walls
    try:
        _kl = _oi_key_levels(tk, conn, latest_date, spot=_pxv)
        if _kl:
            _cws = _kl.get("call_wall",0); _pws = _kl.get("put_wall",0); _mps = _kl.get("max_pain",0)
            _gws = " / ".join(f"${g:.0f}" for g in _kl.get("gamma_walls",[])[:3]) or "—"
            _wrows = [("Call Wall", f"${_cws:.0f}"), ("Put Wall", f"${_pws:.0f}"),
                      ("Max Pain", f"${_mps:.0f}")]
            _wtxt = (f"\n<b>🧱 OI Walls ({str(_kl.get('expiry',''))[5:]})</b>\n"
                     + _pipe_table(("Level", "Strike"), _wrows, right_cols={1}))
            if _gws and _gws != "—":
                _wtxt += f"\n<i>Γ walls: {_gws}</i>"
            parts.append(_wtxt)
    except Exception: pass

    # Plain-English write-up + your-position advice (leads before the dense tables)
    try:
        _wu = _ticker_writeup(tk, conn, call_chg=call_chg, put_chg=put_chg,
                              pcr=pcr, sig_lbl=sig_lbl, latest_date=latest_date)
        if _wu:
            parts.append(_wu)
    except Exception:
        log.debug("signal_ticker_detail writeup failed", exc_info=True)

    # Per-expiry: This Week / Next Week / Later
    try:
        exp_df = pd.read_sql("""
            SELECT expiry_date,
                   SUM(change_OI_Call) as cc, SUM(change_OI_Put) as pp,
                   SUM(openInt_Call_now) as co, SUM(openInt_Put_now) as po
            FROM options_change WHERE ticker=? AND trade_date_now=?
            GROUP BY expiry_date
            ORDER BY expiry_date
        """, conn, params=(tk, latest_date))
        if not exp_df.empty:
            _today = datetime.now().date()
            _dtf = (4 - _today.weekday()) % 7
            _this_fri = _today + timedelta(days=_dtf)
            _next_fri = _this_fri + timedelta(days=7)
            _bk_tw = chr(0x26a1) + " THIS WEEK"
            _bk_nw = chr(0x1f4c5) + " NEXT WEEK"
            _bk_lt = chr(0x1f52d) + " LATER"
            _bk = {_bk_tw: [], _bk_nw: [], _bk_lt: []}
            for _, er in exp_df.iterrows():
                try:
                    _edt = datetime.strptime(str(er["expiry_date"]), "%Y-%m-%d").date()
                    if _edt <= _this_fri:   _bk[_bk_tw].append(er)
                    elif _edt <= _next_fri: _bk[_bk_nw].append(er)
                    else:                   _bk[_bk_lt].append(er)
                except Exception:
                    _bk[_bk_lt].append(er)
            # ONE expiry table with a When column (merged 2026-07-23). Was three separate
            # tables — THIS WEEK / NEXT WEEK / LATER — over identical columns, which tripled
            # the headers and separators for no extra information.
            _wlbl = {_bk_tw: "wk1", _bk_nw: "wk2", _bk_lt: "later"}

            def _opex_kind(d):
                """W weekly · M monthly OPEX (3rd Friday) · Q quarterly triple-witching.

                Monthly OPEX carries most of the open interest and is where pinning toward
                max-pain actually bites; quarterly (Mar/Jun/Sep/Dec 3rd Friday) adds index
                futures+options expiry on top. A weekly and a monthly sitting in the same
                list look identical without this, which understates the big one.
                """
                try:
                    # `date` is not imported at module level here — build via datetime
                    _f = [x for x in range(1, 29)
                          if datetime(d.year, d.month, x).weekday() == 4]  # Fridays
                    third_fri = (datetime(d.year, d.month, _f[2]).date()
                                 if len(_f) >= 3 else None)
                    if third_fri and d == third_fri:
                        return "Q" if d.month in (3, 6, 9, 12) else "M"
                except Exception:
                    pass
                return "W" if d.weekday() == 4 else "d"

            def _ebias(c, p):
                """Same call/put-build read the old separate 'By Expiry' table carried —
                folded in here so that duplicate table could be deleted without losing it."""
                if c > 300 and p > 300:      return "🟡"   # straddle
                if c > abs(p) * 1.5 and c > 0: return "🟢" # call build
                if p > abs(c) * 1.5 and p > 0: return "🔴" # put build
                if c < -200 and p < -200:    return "⚪"   # unwind
                return "⚪"

            _erows = []
            for _lbl, _rows in _bk.items():
                for er in _rows:
                    cc2 = float(er["cc"] or 0); pp2 = float(er["pp"] or 0)
                    ep2 = float(er["po"] or 0) / max(float(er["co"] or 0), 1)
                    try:
                        _ed2 = datetime.strptime(str(er["expiry_date"])[:10], "%Y-%m-%d").date()
                        _kind = _opex_kind(_ed2)
                    except Exception:
                        _kind = ""
                    _erows.append((_ebias(cc2, pp2), _wlbl.get(_lbl, ""),
                                   str(er["expiry_date"])[5:], _kind,
                                   _fk(cc2), _fk(pp2), f"{min(ep2, 9.9):.1f}"))
            if _erows:
                # "PCR(OI)" not "PCR": this column is put/call OPEN INTEREST, not the ratio of
                # the CdOI/PdOI (change) columns beside it — verified 07-21. The bare label
                # made the table look self-contradictory.
                parts.append("\n<b>📅 Expiry Breakdown</b>\n"
                             + _pipe_table(("ST", "When", "Expiry", "Typ", "CdOI", "PdOI", "PCR(OI)"),
                                           _erows, right_cols={4, 5, 6},
                                           legend="Typ: M=monthly OPEX (3rd Fri) · Q=quarterly triple-witch · "
                                                  "W=weekly · d=daily — M/Q hold the most OI and pin hardest · "
                                                  "🟢 call-build 🔴 put-build 🟡 straddle ⚪ flat"))
    except Exception as _ex_e:
        log.warning(f"signal_ticker_detail expiry {tk}: {_ex_e}")

    # Calendar spreads
    try:
        _cal = [r for r in analyze_oi_rolls(tk, conn) if r["type"] == "CALENDAR_ROLL"]
        if _cal:
            cal_lines = ["\n<b>🗓 Calendar Spreads:</b>"]
            for cr in _cal[:3]:
                cal_lines.append(
                    f"📆 {cr['option']} <b>${cr['strike']:.0f}</b>  "
                    f"{str(cr['near_expiry'])[:8]}→{str(cr['far_expiry'])[:8]}  ~{cr['qty']:,}c\n"
                    f"   <i>Duration extended — same direction, more time.</i>"
                )
            parts.append("\n".join(cal_lines))
    except Exception: pass

    # Spot + strike breakdown
    spot = 0.0
    try:
        _sd = pd.read_sql("""SELECT close FROM stock_daily WHERE ticker=?
            ORDER BY trade_date DESC LIMIT 1""",
            conn, params=(tk,))
        if not _sd.empty: spot = float(_sd["close"].iloc[0])
    except Exception: pass

    # ── Earnings (est vs actual) + call highlights + filtered news for THIS ticker ──
    # Same context the positions card carries: the print explains the move, the guidance
    # explains the print, and the news explains how the street read it.
    try:
        _l, _nx = _earn_context(conn, tk)
        _ebits = []
        if _l and _l[2] is not None:
            _v = "BEAT" if (_l[3] or 0) > 0 else ("MISS" if (_l[3] or 0) < 0 else "INLINE")
            _ebits.append(f"{str(_l[0])[5:]} EPS <b>{_l[2]:.2f}</b> vs {_l[1]:.2f} est "
                          f"(<b>{_l[3]:+.0f}% {_v}</b>)" if _l[1] is not None
                          else f"{str(_l[0])[5:]} EPS {_l[2]:.2f}")
        if _nx and _nx[1] is not None:
            _ebits.append(f"next {str(_nx[0])[5:]} est {_nx[1]:.2f}")
        if _ebits:
            parts.append("\n<b>📊 Earnings:</b> " + " · ".join(_ebits))
        _tx = _tx_latest(conn, tk)
        if _tx:
            _hl = [h for h in str(_tx[1]).split("\n") if h.strip()][:3]
            if _hl:
                parts.append(f"\n<b>🎙 Call highlights ({_tx[0]}):</b>\n"
                             + "\n".join(f"• <i>{h[:150]}</i>" for h in _hl))
    except Exception:
        log.debug("ticker earnings/transcript block failed", exc_info=True)
    try:
        _nw = _position_news([tk], per_tk=3)
        if _nw.get(tk):
            parts.append("\n<b>📰 News:</b>\n"
                         + "\n".join((f'• <a href="{u}">{h[:120]}</a>' if u else f"• {h[:120]}")
                                     for h, u in _nw[tk]))
    except Exception:
        log.debug("ticker news block failed", exc_info=True)

    bd = _oi_strike_breakdown(tk, conn, spot, latest_date)
    if bd: parts.append(f"\n<b>🔍 Strike Activity:</b>\n{bd}")

    trend = _oi_trend_summary(tk, conn, latest_date)
    if trend: parts.append(f"\n<b>📅 OI Trend (1W/1M):</b>\n{trend}")

    # Volume analysis
    try:
        _vm = _classify_stock_move(tk, call_chg, put_chg)
        if _vm and _vm.get("signal") not in ("NEUTRAL", "MIXED"):
            _vi = {"REAL_BUY":"🟢","DELTA_HEDGE":"🔵","SHORT_COVER":"🟡",
                    "SPEC_CALL":"⚡","REAL_SELL":"🔴","EVENT_STRADDLE":"⚡"}.get(_vm["signal"],"⚪")
            parts.append(
                f"\n<b>📊 Move Classification</b>\n"
                f"{_vi} <b>{_vm['signal'].replace('_',' ')}</b>  [{_vm['confidence']}]\n"
                + mono(f"Vol {_vm['vol_ratio']:.2f}x  Price {_vm['price_chg']:+.2f}%")
                + f"\n<i>{_vm['explanation'][:100]}</i>"
            )
    except Exception: pass

    conn.close()
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("📊 OI Rolls",     callback_data=f"oi_roll_{tk}"),
         InlineKeyboardButton("📡 Inst Signals", callback_data=f"inst_sig_{tk}")],
        [InlineKeyboardButton("📈 Mean Rev",     callback_data=f"mean_rev_{tk}"),
         InlineKeyboardButton("📅 OI Build",     callback_data=f"oi_build_{tk}")],
        [InlineKeyboardButton("🔄 Refresh",      callback_data=f"sigtk_{tk}"),
         InlineKeyboardButton("🔥 Signals",      callback_data="menu_signals")],
        [BACK_BTN],
    ])
    try: await _loading.delete()
    except Exception: pass
    await _safe_reply(query.message, "\n".join(parts), reply_markup=kb)

    # Visual: today intraday + ~2yr line w/ volume-by-price (POC) + OI walls
    try:
        _png = _ticker_chart_png(tk)
        if _png:
            await query.message.reply_photo(
                _png, caption=f"📈 {tk} — today + ~2yr · volume-by-price (POC) + OI walls")
    except Exception:
        log.debug("ticker chart send failed", exc_info=True)

    # Charts for the OI tables above (user 2026-07-23: "summarize in graphs, simple to
    # grasp"). Both renderers already existed and were never called from anywhere —
    # _oi_money_flow_chart turns the per-strike premium columns into a bar chart, and
    # _oi_week_heatmap turns the OI-timeline grid into a heatmap. Same numbers, read at a
    # glance instead of scanned row by row.
    try:
        _c2 = get_conn()
        _lt = _c2.execute("SELECT MAX(trade_date_now) FROM options_change WHERE ticker=?",
                          (tk,)).fetchone()
        _lt = _lt[0] if _lt else None
        if _lt and spot > 0:
            # A small delay between sends (user 2026-07-24: "only getting one chart" for
            # GOOGL, verified BOTH chart functions succeed standalone -- the actual bug was
            # sending 2 photos back-to-back with zero gap, right after the 2yr ticker chart
            # a few lines above this loop already sent a THIRD photo in the same burst.
            # Telegram's per-chat flood control can silently drop a rapid-fire send; the
            # exception was also only logged at debug level, invisible without verbose logs.
            for _fn, _cap in ((_oi_money_flow_chart,
                               f"💰 {tk} — $ flow per strike (calls vs puts)"),
                              (_oi_week_heatmap,
                               f"🔥 {tk} — OI build/unwind heatmap by strike & day")):
                try:
                    await asyncio.sleep(0.6)
                    _p = _fn(tk, _c2, spot, _lt)
                    if _p:
                        await query.message.reply_photo(_p, caption=_cap)
                except Exception as _chart_e:
                    log.warning(f"{_fn.__name__} send failed for {tk}: {_chart_e}", exc_info=True)
        _c2.close()
    except Exception:
        log.debug("OI chart block failed", exc_info=True)

#  7) INSIDER / CONGRESS — table format


async def oi_build_detail(query, ticker):
    """Multi-day OI accumulation view: sparkline, persistence, conviction, hedge ratio."""
    tk = str(ticker).upper()
    _loading = await query.message.reply_text(f"⏳ Analysing {tk} OI buildup…", parse_mode=H)
    conn = get_conn()
    try:
        res = _oi_build_analysis(tk, conn, n_days=20)
    except Exception as _e:
        res = {}
        log.warning(f"oi_build_detail {tk}: {_e}")
    conn.close()

    if not res:
        await query.message.reply_text(
            f"No multi-day OI data for {tk}.",
            reply_markup=InlineKeyboardMarkup([[BACK_BTN]]))
        try: await _loading.delete()
        except Exception: pass
        return

    def _fk(n):
        n = float(n or 0); s = "+" if n >= 0 else "-"
        a = abs(n)
        if a >= 1_000_000: return f"{s}{a/1_000_000:.1f}M"
        if a >= 1_000:     return f"{s}{a/1_000:.0f}K"
        return f"{s}{abs(n):.0f}"

    bias_em   = "🟢" if res["bias_5d"] == "BULL" else "🔴"
    conv_lbl  = "HIGH" if res["conviction"] > 15 else ("MED" if res["conviction"] > 5 else "LOW")
    pcr_em    = "📈" if res["pcr_trend"] == "FALLING" else ("📉" if res["pcr_trend"] == "RISING" else "➡️")

    parts = [
        hdr(f"📈 {tk} OI BUILD ({res['n_days']}d)"),
        f"{bias_em} <b>{res['bias_5d']} Bias</b>  [{conv_lbl} conviction {res['conviction']:.1f}%]",
        "\n<b>10-Day Net OI Flow</b>  <i>(oldest \u2192 newest \u00b7 net = calls minus puts)</i>",
        _oi_flow_ledger(res),
        mono(
            f"{'5d Call\u0394':<12} {_fk(res['cum5_call']):>9}\n"
            f"{'5d Put\u0394':<12} {_fk(res['cum5_put']):>9}\n"
            f"{'PCR 5d':<12} {res['pcr_5d']:>9.3f}\n"
            f"{'PCR 20d':<12} {res['pcr_20d']:>9.3f}\n"
            f"{'PCR Trend':<12} {res['pcr_trend']:>9}"
        ),
    ]

    if res["conviction"] > 15:
        parts.append(f"\n💪 <b>HIGH conviction</b> \u2014 {res['bias_5d']} bias, {res['conviction']:.1f}% of base OI moved in 5 days.")
    elif res["conviction"] > 5:
        parts.append(f"\n📊 Moderate conviction \u2014 {res['bias_5d']} lean, watch for follow-through.")
    else:
        parts.append("\n\u26a0\ufe0f Low conviction \u2014 OI changes are noise-level, no clear institutional direction.")

    if res["hot_calls"]:
        _hc = "  ".join(f"${sk:.0f}({d}d/{n})" for sk,d,n in res["hot_calls"][:4])
        parts.append(f"\n<b>🟢 Hot Call Strikes</b>:\n<code>{_hc}</code>")
    if res["hot_puts"]:
        _hp = "  ".join(f"${sk:.0f}({d}d/{n})" for sk,d,n in res["hot_puts"][:4])
        parts.append(f"\n<b>🔴 Hot Put Strikes</b>:\n<code>{_hp}</code>")
    if not res["hot_calls"] and not res["hot_puts"]:
        parts.append("\n<i>No persistent strike build \u2014 flow is rotating, not accumulating at fixed strikes.</i>")

    h_lbl = "HIGH \u26a0\ufe0f" if res["hedge_ratio"] > 40 else ("ELEVATED" if res["hedge_ratio"] > 25 else "NORMAL \u2705")
    _hedge_note = ("Institutions adding protection \u2014 shows strong long base." if res["hedge_ratio"] > 30
                   else "Normal hedge levels \u2014 no panic hedging detected.")
    parts.append(
        f"\n<b>🛡 Hedge Ratio</b>: {res['hedge_ratio']:.1f}% OTM puts  [{h_lbl}]\n"
        f"<i>{_hedge_note}</i>"
    )

    if res["daily"]:
        _drows = [(str(d['date'])[5:], _fk(d['call_chg']), _fk(d['put_chg']), f"{d['pcr']:.2f}")
                  for d in res["daily"][:5]]
        parts.append("\n<b>Daily OI Flow:</b>\n"
                     + _pipe_table(("Date", "dCall", "dPut", "PCR"), _drows, right_cols={1, 2, 3}))

    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("📊 OI Detail",    callback_data=f"oi_detail_{tk}"),
         InlineKeyboardButton("📡 Inst Signals", callback_data=f"inst_sig_{tk}")],
        [InlineKeyboardButton("🔄 Refresh",      callback_data=f"oi_build_{tk}"),
         InlineKeyboardButton("📈 Mean Rev",     callback_data=f"mean_rev_{tk}")],
        [BACK_BTN],
    ])
    try: await _loading.delete()
    except Exception: pass
    await _safe_reply(query.message, "\n".join(parts), reply_markup=kb)

