def _oi_flow_ledger(res: dict) -> str:
    """10-day net-OI ledger: one COLORED bar per day scaled to the 10-day max, with the
    date and value beside it. Replaces the tiny unicode sparkline (user 2026-07-20:
    'i want bigger with color and ledger to understand'). net = call dOI - put dOI."""
    def _fk(n):
        n = float(n or 0); s = "+" if n >= 0 else "-"
        a = abs(n)
        if a >= 1_000_000: return f"{s}{a/1_000_000:.1f}M"
        if a >= 1_000:     return f"{s}{a/1_000:.0f}K"
        return f"{s}{abs(n):.0f}"
    d10 = list(reversed((res.get("daily") or [])[:10]))        # oldest -> newest
    if not d10:
        return ""
    mx = max((abs(float(d.get("net", 0) or 0)) for d in d10), default=0.0) or 1.0
    out = []
    for d in d10:
        n = float(d.get("net", 0) or 0)
        bar = ("🟩" if n >= 0 else "🟥") * max(1, int(round(abs(n) / mx * 6)))
        out.append(f"{'🟢' if n >= 0 else '🔴'} <code>{str(d.get('date',''))[5:]}</code> "
                   f"<b>{_fk(n):>7}</b>  {bar}")
    out.append("<i>🟩 call-heavy (bullish OI build) · 🟥 put-heavy (bearish/hedge) · "
               f"bar = size vs 10-day max {_fk(mx)}</i>")
    return "\n".join(out)


def _oi_build_analysis(ticker: str, conn, n_days: int = 20) -> dict:
    """Multi-day OI accumulation analysis.
    Returns: sparkline, conviction score, hot strikes (persistent build),
             hedge ratio, PCR trend, daily flow table.
    """
    tk = str(ticker).upper()
    try:
        dates_df = pd.read_sql("""SELECT DISTINCT trade_date_now FROM options_change WHERE ticker=?
            ORDER BY trade_date_now DESC
            LIMIT ?""", conn, params=(tk, n_days))
        if len(dates_df) < 3:
            return {}
        dates = dates_df["trade_date_now"].tolist()

        # Daily aggregates
        daily = []
        for dt in dates:
            r = pd.read_sql("""SELECT SUM(change_OI_Call) as cc, SUM(change_OI_Put) as pp,
                SUM(openInt_Call_now) as co, SUM(openInt_Put_now) as po
                FROM options_change WHERE ticker=? AND trade_date_now=?""", conn, params=(tk, dt))
            cc = float(r["cc"].iloc[0] or 0); pp = float(r["pp"].iloc[0] or 0)
            co = float(r["co"].iloc[0] or 0); po = float(r["po"].iloc[0] or 0)
            daily.append({"date": dt, "call_chg": cc, "put_chg": pp,
                          "call_oi": co, "put_oi": po,
                          "net": cc - pp, "pcr": po / max(co, 1)})

        # Sparkline: 10-day net OI (calls-puts) as Unicode bar chart
        nets = [d["net"] for d in daily]
        mn, mx = min(nets), max(nets)
        rng = max(mx - mn, 1)
        _blocks = " ▁▂▃▄▅▆▇█"
        spark = "".join(_blocks[max(0, min(8, int((v - mn) / rng * 8)))] for v in reversed(nets[:10]))

        # 5-day conviction
        base_oi   = daily[0]["call_oi"] + daily[0]["put_oi"]
        cum5_call = sum(d["call_chg"] for d in daily[:5])
        cum5_put  = sum(d["put_chg"]  for d in daily[:5])
        conviction = abs(cum5_call - cum5_put) / max(base_oi, 1) * 100
        bias_5d = "BULL" if cum5_call > cum5_put else "BEAR"

        # Strike persistence — how many of last 10 days each strike built OI
        qmarks = ",".join("?" * len(dates[:10]))
        strike_df = pd.read_sql(f"""
            SELECT trade_date_now, strike,
                   SUM(change_OI_Call) as cc, SUM(change_OI_Put) as pp
            FROM options_change WHERE ticker=? AND trade_date_now IN ({qmarks})
            GROUP BY trade_date_now, strike""",
            conn, params=[tk] + dates[:10])
        strike_df["strike"] = pd.to_numeric(strike_df["strike"], errors="coerce")
        strike_df["cc"] = pd.to_numeric(strike_df["cc"], errors="coerce").fillna(0)
        strike_df["pp"] = pd.to_numeric(strike_df["pp"], errors="coerce").fillna(0)

        hot_calls, hot_puts = [], []
        for sk, grp in strike_df.groupby("strike"):
            n = len(grp)
            if n < 3: continue
            pos_c = int((grp["cc"] > 0).sum())
            pos_p = int((grp["pp"] > 0).sum())
            if pos_c >= max(3, int(n * 0.6)): hot_calls.append((float(sk), pos_c, n))
            if pos_p >= max(3, int(n * 0.6)): hot_puts.append((float(sk), pos_p, n))
        hot_calls.sort(key=lambda x: -x[1])
        hot_puts.sort(key=lambda x: -x[1])

        # Hedge ratio: OTM put OI (>5% below spot) / total put OI
        hedge_ratio = 0.0
        try:
            sp_df = pd.read_sql("""SELECT close FROM stock_daily WHERE ticker=?
                ORDER BY trade_date DESC LIMIT 1""",
                conn, params=(tk,))
            spot = float(sp_df["close"].iloc[0]) if not sp_df.empty else 0
            if spot > 0:
                latest = dates[0]
                otm_df = pd.read_sql("""SELECT SUM(openInt_Put_now) as otm,
                    (SELECT SUM(openInt_Put_now) FROM options_change WHERE ticker=? AND trade_date_now=?) as tot
                    FROM options_change WHERE ticker=? AND trade_date_now=? AND CAST(strike AS REAL) < ?""",
                    conn, params=[tk, latest, tk, latest, spot * 0.95])
                tot = float(otm_df["tot"].iloc[0] or 0)
                if tot > 0:
                    hedge_ratio = float(otm_df["otm"].iloc[0] or 0) / tot * 100
        except Exception:
            log.debug("suppressed exception", exc_info=True)

        # PCR 5d vs 20d
        pcr_5d  = sum(d["pcr"] for d in daily[:5])  / min(5,  len(daily))
        pcr_20d = sum(d["pcr"] for d in daily[:20]) / min(20, len(daily))
        pcr_trend = "RISING" if pcr_5d > pcr_20d * 1.10 else ("FALLING" if pcr_5d < pcr_20d * 0.90 else "STABLE")

        return {
            "daily": daily, "spark": spark,
            "conviction": round(conviction, 1), "bias_5d": bias_5d,
            "cum5_call": cum5_call, "cum5_put": cum5_put,
            "hot_calls": hot_calls[:5], "hot_puts": hot_puts[:5],
            "hedge_ratio": round(hedge_ratio, 1),
            "pcr_5d": round(pcr_5d, 3), "pcr_20d": round(pcr_20d, 3),
            "pcr_trend": pcr_trend, "n_days": len(dates),
        }
    except Exception as e:
        log.debug(f"_oi_build_analysis {tk}: {e}")
        return {}


def _oi_key_levels(ticker: str, conn, trade_date: str = None, spot: float = 0.0) -> dict:
    """OI walls: call_wall, put_wall, max_pain, gamma_walls from options_change.

    `spot` is optional — when supplied, gamma walls are ranked by OI size discounted by
    distance from spot, so the returned walls are the ones that actually matter near price.
    """
    tk = str(ticker).upper()
    try:
        # Get latest trade date if not provided
        if not trade_date:
            r = pd.read_sql("""SELECT DISTINCT trade_date_now FROM options_change WHERE ticker=?
                ORDER BY trade_date_now DESC
                LIMIT 1""", conn, params=(tk,))
            if r.empty: return {}
            trade_date = r["trade_date_now"].iloc[0]
        # Aggregate by strike across nearest future expiry
        df = pd.read_sql("""
            SELECT strike, expiry_date,
                   SUM(openInt_Call_now) as call_oi, SUM(openInt_Put_now) as put_oi
            FROM options_change WHERE ticker=? AND trade_date_now=?
            GROUP BY strike, expiry_date
        """, conn, params=(tk, trade_date))
        if df.empty: return {}
        df["strike"] = pd.to_numeric(df["strike"], errors="coerce")
        df["call_oi"] = pd.to_numeric(df["call_oi"], errors="coerce").fillna(0)
        df["put_oi"]  = pd.to_numeric(df["put_oi"],  errors="coerce").fillna(0)
        # Use nearest future expiry
        today_s = datetime.now().strftime("%Y%m%d")
        def _exp_sort(e):
            s = str(e)
            return s[6:10]+s[0:2]+s[3:5] if len(s)>=10 else s
        df["_es"] = df["expiry_date"].apply(_exp_sort)
        future = df[df["_es"] >= today_s]
        if future.empty: future = df
        near_exp = future["_es"].min()
        near_df = future[future["_es"] == near_exp].copy()
        near_agg = near_df.groupby("strike").agg({"call_oi":"sum","put_oi":"sum"}).reset_index()
        # Call wall = strike with max call OI
        call_wall_row = near_agg.loc[near_agg["call_oi"].idxmax()]
        put_wall_row  = near_agg.loc[near_agg["put_oi"].idxmax()]
        call_wall = float(call_wall_row["strike"])
        put_wall  = float(put_wall_row["strike"])
        # Max pain = strike minimizing sum of ITM losses.
        # Vectorized (2026-07-19): the old O(n^3) triple loop (a full DataFrame .loc
        # mask per strike-pair) took ~5s on wide chains like GOOG. numpy broadcast
        # makes it O(n^2) in microseconds.
        _ka = near_agg.sort_values("strike")
        strikes_arr = _ka["strike"].to_numpy(dtype=float)
        call_arr    = _ka["call_oi"].to_numpy(dtype=float)
        put_arr     = _ka["put_oi"].to_numpy(dtype=float)
        _tests = strikes_arr[:, None]                 # (n,1) candidate settle prices
        _ks    = strikes_arr[None, :]                 # (1,n) strikes held
        _pain  = (np.maximum(0.0, _tests - _ks) * call_arr[None, :]).sum(axis=1) \
               + (np.maximum(0.0, _ks - _tests) * put_arr[None, :]).sum(axis=1)
        max_pain_strike = float(strikes_arr[int(np.argmin(_pain))])
        strikes = strikes_arr.tolist()
        # Gamma walls = strikes where call+put OI >= 2x mean.
        # Rank by SIGNIFICANCE, not by strike value. The old code did
        # sorted(qualifying_strikes) and the caller took [:3], which returned the three
        # NUMERICALLY LOWEST strikes — i.e. the deepest OTM puts — so QQQ at $704 advertised
        # "Γ walls: $525 / $530 / $555". Rank by OI size, discounted by distance from spot
        # when spot is known, then sort ascending for display.
        near_agg["total"] = near_agg["call_oi"] + near_agg["put_oi"]
        mean_oi = near_agg["total"].mean()
        _gw = near_agg[near_agg["total"] >= 2 * mean_oi].copy()
        if not _gw.empty:
            _sp = float(spot or 0)
            if _sp > 0:
                _gw["_rank"] = _gw["total"] / (1.0 + (_gw["strike"] - _sp).abs() / _sp)
            else:
                _gw["_rank"] = _gw["total"]
            gamma_walls = sorted(_gw.nlargest(6, "_rank")["strike"].tolist())
        else:
            gamma_walls = []
        near_exp_str = near_df["expiry_date"].iloc[0] if not near_df.empty else ""
        return {"call_wall": call_wall, "put_wall": put_wall, "max_pain": max_pain_strike,
                "gamma_walls": gamma_walls, "expiry": near_exp_str}
    except Exception as e:
        return {}


def _classify_stock_move(ticker: str, net_call_chg: float, net_put_chg: float) -> dict:
    """Classify if price move is real stock buying vs MM delta hedging vs short cover."""
    tk = str(ticker).upper()
    try:
        # DB-first (2026-07-19): read close/volume from stock_daily instead of a live
        # yfinance call (~2.3s network round-trip). Same data, ~1000x faster; yfinance
        # only as a fallback when the DB is thin.
        h = None
        try:
            _c = get_conn()
            _sd = pd.read_sql("SELECT close, volume FROM stock_daily WHERE ticker=? "
                              "ORDER BY trade_date DESC LIMIT 30", _c, params=(tk,))
            _c.close()
            if len(_sd) >= 5 and _sd["volume"].notna().sum() >= 5 and _sd["close"].notna().sum() >= 2:
                _sd = _sd.iloc[::-1].reset_index(drop=True)   # chronological
                h = _sd.rename(columns={"close": "Close", "volume": "Volume"})
        except Exception:
            h = None
        if h is None:
            h = _yf_ticker(tk).history(period="30d")
        if len(h) < 5: return {}
        today_vol  = float(h["Volume"].iloc[-1])
        avg_vol    = float(h["Volume"].iloc[-21:-1].mean()) if len(h) >= 21 else float(h["Volume"].mean())
        vol_ratio  = today_vol / avg_vol if avg_vol > 0 else 1.0
        price_now  = float(h["Close"].iloc[-1])
        price_prev = float(h["Close"].iloc[-2])
        price_chg  = (price_now - price_prev) / price_prev * 100 if price_prev > 0 else 0.0
        # Classification
        signal = "NEUTRAL"
        confidence = "LOW"
        explanation = ""
        net_call = float(net_call_chg or 0)
        net_put  = float(net_put_chg or 0)
        if price_chg > 1.0 and vol_ratio > 1.4 and net_call > 0:
            signal = "REAL_BUY"; confidence = "HIGH"
            explanation = "Price up + high volume + call OI building = real institutional buying confirmed by options flow."
        elif price_chg > 0.5 and vol_ratio < 0.8 and net_call > 0:
            signal = "DELTA_HEDGE"; confidence = "MEDIUM"
            explanation = "Price up on low volume + call OI rising = MMs delta-hedging sold calls; not genuine buying pressure."
        elif price_chg > 1.0 and vol_ratio > 1.4 and net_call < 0:
            signal = "SHORT_COVER"; confidence = "HIGH"
            explanation = "Price up + high volume + calls closing = short squeeze / short covering. Caution - may not sustain."
        elif abs(price_chg) < 0.5 and net_call > abs(net_put) * 1.5 and vol_ratio < 1.2:
            signal = "SPEC_CALL"; confidence = "MEDIUM"
            explanation = "Price flat + call OI up without stock volume = speculative option bet. Watch for confirmation."
        elif price_chg < -1.0 and vol_ratio > 1.4 and net_put > 0:
            signal = "REAL_SELL"; confidence = "HIGH"
            explanation = "Price down + high volume + put OI building = real selling / institutional exit confirmed."
        elif price_chg < -0.5 and vol_ratio < 0.8 and net_put > 0:
            signal = "DELTA_HEDGE"; confidence = "MEDIUM"
            explanation = "Price down on low volume + put OI rising = MMs hedging; not outright selling."
        elif net_call > 0 and net_put > 0 and min(net_call, net_put) > abs(net_call - net_put) * 0.4:
            signal = "EVENT_STRADDLE"; confidence = "MEDIUM"
            explanation = "Both call + put OI rising together = market pricing an event/volatility expansion."
        else:
            signal = "MIXED"; confidence = "LOW"
            explanation = "Mixed signals - volume and OI diverge. Await stronger confirmation."
        _vol_lbl = "HIGH" if vol_ratio > 1.4 else ("LOW" if vol_ratio < 0.7 else "AVG")
        return {"signal": signal, "confidence": confidence, "explanation": explanation,
                "vol_ratio": round(vol_ratio, 2), "vol_label": _vol_lbl,
                "price_chg": round(price_chg, 2), "today_vol": int(today_vol), "avg_vol": int(avg_vol)}
    except Exception:
        return {}


