def _score_ticker_full(ticker: str, conn, vix_val: float = 20.0, fast: bool = False) -> dict:
    """Score ticker 0-100: tech(30) + OI(30) + fundamental(20) + short_interest(20) − VIX."""
    tk = str(ticker).upper()
    try:
        h = _yf_ticker(tk).history(period="60d")
        if len(h) < 20:
            return {}
        closes = h["Close"]
        px = float(closes.iloc[-1])

        # ── RSI(14) ──────────────────────────────────────────
        delta = closes.diff()
        gain  = delta.clip(lower=0).rolling(14).mean()
        loss  = (-delta.clip(upper=0)).rolling(14).mean()
        rs    = gain / loss.replace(0, 1e-9)
        rsi   = float(100 - 100 / (1 + rs.iloc[-1]))

        # ── MACD(12,26,9) ────────────────────────────────────
        ema12      = closes.ewm(span=12).mean()
        ema26      = closes.ewm(span=26).mean()
        macd_line  = ema12 - ema26
        macd_sig   = macd_line.ewm(span=9).mean()
        macd_bull  = bool(macd_line.iloc[-1] > macd_sig.iloc[-1])
        macd_cross = bool(macd_line.iloc[-1] > macd_sig.iloc[-1] and
                         macd_line.iloc[-2] <= macd_sig.iloc[-2])

        # ── Bollinger Bands (20,2) ────────────────────────────
        sma20  = closes.rolling(20).mean()
        std20  = closes.rolling(20).std()
        bb_up  = float(sma20.iloc[-1] + 2 * std20.iloc[-1])
        bb_lo  = float(sma20.iloc[-1] - 2 * std20.iloc[-1])
        bb_pct = (px - bb_lo) / (bb_up - bb_lo) if bb_up != bb_lo else 0.5
        bb_bot = bb_pct < 0.2
        bb_top = bb_pct > 0.8

        # ── SMA200 ────────────────────────────────────────────
        sma200   = float(closes.rolling(200, min_periods=50).mean().iloc[-1]) if len(closes) >= 50 else px
        above200 = px > sma200

        # ── Technical score (0-30) ────────────────────────────
        tech = 0
        if rsi < 30:    tech += 10
        elif rsi < 40:  tech += 7
        elif rsi < 50:  tech += 4
        elif rsi > 70:  tech -= 8
        elif rsi > 60:  tech -= 4

        if macd_cross:  tech += 10
        elif macd_bull: tech += 5
        else:           tech -= 3

        if bb_bot:      tech += 10
        elif bb_top:    tech -= 8

        if above200:    tech += 5
        else:           tech -= 5
        tech = max(0, min(30, tech))

        # ── OI / Mean Reversion score (0-30) ─────────────────
        oi_score = 15
        pcr_z = 0.0
        oi_bull = False
        oi_bear = False
        try:
            mr      = analyze_mean_reversion(tk, conn)
            pcr_z   = float(mr.get("pcr_z",    {}).get("z", 0) or 0)
            comp    = float(mr.get("composite", {}).get("score", 0) or 0)
            if pcr_z > 2:    oi_score += 8
            elif pcr_z > 1:  oi_score += 4
            elif pcr_z < -2: oi_score -= 7
            elif pcr_z < -1: oi_score -= 3
            if comp > 3:     oi_score += 10;  oi_bull = True
            elif comp > 1:   oi_score += 5
            elif comp < -3:  oi_score -= 8;   oi_bear = True
            elif comp < -1:  oi_score -= 4
            oi_score = max(0, min(30, oi_score))
        except Exception:
            log.debug("suppressed exception", exc_info=True)

        # ── Fundamental score — use fast_info to avoid slow yf.info call ──
        fund = 10
        try:
            fi = _yf_ticker(tk).fast_info
            mktcap = fi.get("market_cap") or fi.get("marketCap") or 0
            if mktcap > 500e9:    fund += 4   # mega-cap premium
            elif mktcap > 50e9:   fund += 2
            elif mktcap < 1e9:    fund -= 2   # micro-cap risk
            fund = max(0, min(20, fund))
        except Exception:
            log.debug("suppressed exception", exc_info=True)

        # ── Short interest score (0-20) ─────────────────────
        si_sc      = 5
        short_pct  = 0.0
        squeeze_sc = 0
        dtc        = 0.0
        if not fast:
            try:
                sd         = _get_short_data(tk)
                short_pct  = float(sd.get("short_pct_float") or 0)
                squeeze_sc = int(sd.get("squeeze_score") or 0)
                dtc        = float(sd.get("short_ratio") or 0)
                if short_pct >= 20 and macd_bull and rsi < 55:
                    si_sc = 18
                elif short_pct >= 10 and macd_bull:
                    si_sc = 12
                elif short_pct < 3:
                    si_sc = 8
                else:
                    si_sc = 5
            except Exception:
                log.debug("suppressed exception", exc_info=True)
        # ── VIX environment adjustment ────────────────────────
        vix_adj = (5 if vix_val < 15 else
                   -10 if vix_val > 30 else
                   -5  if vix_val > 25 else 0)

        total = int(max(0, min(100, tech + oi_score + fund + si_sc + vix_adj)))

        # ── Insight headline ──────────────────────────────────
        ins = []
        if macd_cross and rsi < 45:
            ins.append(f"MACD bull cross + RSI {rsi:.0f} — momentum reversal signal")
        elif rsi < 30 and bb_bot:
            ins.append(f"RSI {rsi:.0f} oversold at BB lower band — high-prob bounce zone")
        elif rsi < 35:
            ins.append(f"RSI {rsi:.0f} oversold — watch for bounce catalyst")
        if squeeze_sc >= 7:
            ins.append(f"HIGH squeeze risk ({short_pct:.0f}% SI) — catalyst = explosive move")
        elif squeeze_sc >= 5:
            ins.append(f"Moderate squeeze ({short_pct:.0f}% SI) — watch momentum shift")
        if pcr_z > 2:
            ins.append(f"PCR Z-score {pcr_z:.1f} — put-heavy OI = oversold positioning")
        if above200 and macd_cross:
            ins.append("Above 200d + MACD cross — institutional momentum continuation")
        insight = ins[0] if ins else f"Tech:{tech} OI:{oi_score} Fund:{fund} SI:{si_sc}"

        return {
            "ticker":        tk,
            "total":         total,
            "tech_score":    tech,
            "oi_score":      oi_score,
            "fund_score":    fund,
            "si_score":      si_sc,
            "rsi":           rsi,
            "macd_bull":     macd_bull,
            "macd_cross":    macd_cross,
            "bb_bot":        bb_bot,
            "bb_top":        bb_top,
            "above200":      above200,
            "pcr_z":         pcr_z,
            "oi_bull":       oi_bull,
            "oi_bear":       oi_bear,
            "short_pct":     short_pct,
            "squeeze_score": squeeze_sc,
            "dtc":           dtc,
            "insight":       insight,
        }
    except Exception as e:
        log.debug(f"_score_ticker_full {tk}: {e}")
        return {}


async def recommend_engine(query):
    """🎯 Recommendation engine: technical + OI + fundamental + short interest + macro cascade."""
    _loading = await query.message.reply_text(
        "🎯 Scoring universe — please wait (~30s)…", parse_mode=H)
    conn = get_conn()
    tickers = _ticker_universe()

    # ── Macro context ─────────────────────────────────────────
    vix_val    = 20.0
    macro_chg  = {}
    try:
        vix_h = _yf_ticker("^VIX").history(period="3d")
        if len(vix_h):
            vix_val = float(vix_h["Close"].iloc[-1])
    except Exception:
        log.debug("suppressed exception", exc_info=True)
    for sym, key in [("CL=F", "oil"), ("GC=F", "gold"), ("^TNX", "tnx"), ("BTC-USD", "btc")]:
        try:
            h = _yf_ticker(sym).history(period="5d")
            if len(h) >= 2:
                macro_chg[key] = ((float(h["Close"].iloc[-1]) - float(h["Close"].iloc[-2]))
                                  / float(h["Close"].iloc[-2]) * 100)
        except Exception:
            log.debug("suppressed exception", exc_info=True)

    # ── Score each ticker (limit 10 for speed) ──────────────
    scored = []
    _yf_warm(tickers[:10], period="60d")   # parallel prefetch the per-ticker history
    for tk in tickers[:10]:
        try:
            s = _score_ticker_full(tk, conn, vix_val, fast=True)
            if s:
                scored.append(s)
        except Exception as _sk_e:
            log.debug(f"score_ticker {tk}: {_sk_e}")
    conn.close()

    if not scored:
        await query.message.reply_text(
            f"{hdr('🎯 RECOMMENDATION ENGINE')}\n"
            f"⚠️ Could not score any tickers. VIX: {vix_val:.1f}\n"
            f"<i>Try again in a moment — data feeds may be slow.</i>",
            parse_mode=H, reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("🔄 Retry", callback_data="menu_recommend"), BACK_BTN]]))
        try: await _loading.delete()
        except Exception: pass
        return
    scored.sort(key=lambda x: x["total"], reverse=True)

    vix_em = "🔴" if vix_val > 25 else ("🟡" if vix_val > 18 else "🟢")
    regime  = ("Risk-OFF — hedge first" if vix_val > 25
               else ("Caution zone" if vix_val > 18 else "Risk-ON"))
    _vxn = _get_vol_indices().get("vxn", 0) or 0          # Nasdaq-100 fear gauge (tech names)
    _vxn_s = f"  ·  🟣 VXN <b>{_vxn:.1f}</b> (tech)" if _vxn > 0 else ""

    parts = [
        hdr("🎯 RECOMMENDATION ENGINE"),
        f"{vix_em} VIX <b>{vix_val:.1f}</b>  {regime}{_vxn_s}",
    ]

    # ── Scored universe summary table ────────────────────────
    if scored:
        tbl = []
        for s in scored[:10]:
            sig = "BUY"   if s["total"] >= 65 else ("WATCH" if s["total"] >= 45 else "AVOID")
            em  = "🟢"    if s["total"] >= 65 else ("🟡"    if s["total"] >= 45 else "🔴")
            tbl.append((f"{em}{s['ticker']}", str(s["total"]), sig))
        parts.append("\n<b>UNIVERSE SCORES</b>")
        parts.append(_pipe_table(("Ticker", "Score", "Signal"), tbl))

    # ── Top 3 detailed picks ─────────────────────────────────
    parts.append("\n<b>TOP PICKS (Detailed)</b>")
    for s in scored[:3]:
        em  = "🟢" if s["total"] >= 65 else "🟡"
        lbl = "STRONG BUY" if s["total"] >= 65 else "WATCH"
        rsi_v  = s.get("rsi", 0)
        macd_s = "🟢" if s.get("macd_bull") else "🔴"
        bb_s   = "BOT" if s.get("bb_bot") else ("TOP" if s.get("bb_top") else "MID")
        ema_s  = "🟢" if s.get("above200") else "🔴"
        spf    = s.get("short_pct", 0)
        sc     = s.get("squeeze_score", 0)
        sq_em  = "🔴" if sc >= 7 else ("🟡" if sc >= 4 else "🟢")
        oi_s   = "🟢 Bull" if s.get("oi_bull") else ("🔴 Bear" if s.get("oi_bear") else "Neut")
        parts.append(
            f"\n{em} <b>{s['ticker']}</b>  {s['total']}/100  [{lbl}]\n"
            f"  Tech:  RSI:{rsi_v:.0f} MACD:{macd_s} BB:{bb_s} EMA200:{ema_s}\n"
            f"  OI:    PCR_z:{s.get('pcr_z', 0):.1f}  {oi_s}\n"
            f"  Short: SI:{spf:.1f}%  Sq:{sc}/10{sq_em}\n"
            f"  💡 {s.get('insight', '—')}"
        )

    # ── Quick opportunities: squeeze + oversold ──────────────
    quick = [s for s in scored if s.get("squeeze_score", 0) >= 6 and s.get("rsi", 50) < 58]
    quick += [s for s in scored if s.get("rsi", 50) < 32 and s not in quick]
    if quick:
        parts.append("\n<b>⚡ QUICK OPPORTUNITIES (24h)</b>")
        for s in quick[:4]:
            reasons = []
            if s.get("squeeze_score", 0) >= 6:
                reasons.append(f"Sq:{s['squeeze_score']}/10🔴 SI:{s.get('short_pct', 0):.0f}%")
            if s.get("rsi", 50) < 32:
                reasons.append(f"RSI:{s.get('rsi', 0):.0f} oversold")
            if s.get("macd_cross"):
                reasons.append("MACD cross")
            if reasons:
                parts.append(f"⚡ <b>{s['ticker']}</b>: {' | '.join(reasons)}")

    # ── Macro cascade ────────────────────────────────────────
    mc = ["\n<b>🌐 MACRO CASCADE</b>"]
    oil = macro_chg.get("oil", 0)
    gld = macro_chg.get("gold", 0)
    tnx = macro_chg.get("tnx", 0)
    btc = macro_chg.get("btc", 0)
    if abs(oil) > 1.0:
        mc.append(f"Oil{'↑' if oil>0 else '↓'}{oil:+.1f}% → "
                  f"{'DAL/UAL  XLE/XOM' if oil > 0 else 'DAL/UAL  XLE'}")
    if abs(gld) > 0.5:
        mc.append(f"Gold{'↑' if gld>0 else '↓'}{gld:+.1f}% → "
                  f"{'GDX/NEM  DXY→EEM' if gld > 0 else 'DXY  GDX/NEM'}")
    if abs(tnx) > 0.3:
        mc.append(f"10Y{'↑' if tnx>0 else '↓'}{tnx:+.1f}% → "
                  f"{'Banks  REITs/Tech' if tnx > 0 else 'Growth/REITs  Banks'}")
    if abs(btc) > 3.0:
        mc.append(f"BTC{'↑' if btc>0 else '↓'}{btc:+.1f}% → "
                  f"{'Risk-ON: MSTR/COIN/RIOT' if btc > 0 else 'Risk-OFF: spec positions'}")
    if vix_val > 25:
        mc.append(f"VIX {vix_val:.1f} ELEVATED → sell premium, hedge longs")
    elif vix_val < 15:
        mc.append(f"VIX {vix_val:.1f} LOW → condors / covered calls attractive")
    if len(mc) > 1:
        parts.append("\n".join(mc))

    # ── Stock relation map (tracked tickers in downstream map) ─
    rel_lines = ["\n<b>📡 STOCK RELATIONS</b>"]
    for tk_map, v in _DOWNSTREAM_MAP.items():
        tracked_down = [d for d in v.get("down", []) if d in tickers]
        if tk_map in tickers or tracked_down:
            dn_str = " / ".join(v.get("down", [])[:3])
            rel_lines.append(
                f"<b>{tk_map}</b> → {dn_str}\n"
                f"  <i>{v['theme'][:60]}</i>"
            )
    if len(rel_lines) > 1:
        parts.append("\n".join(rel_lines[:6]))

    parts.append(
        f"\n<i>Scored {len(scored)} tickers | VIX {vix_val:.1f} | "
        f"{datetime.now().strftime('%H:%M')} ET</i>"
    )

    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("🔄 Refresh",       callback_data="menu_recommend"),
         InlineKeyboardButton("🌍 Global Market", callback_data="menu_global_market")],
        [InlineKeyboardButton("📡 Market",        callback_data="menu_analytics"),
         InlineKeyboardButton("📊 OI Signals",    callback_data="menu_signals")],
        [BACK_BTN],
    ])
    try:
        await _loading.delete()
    except Exception:
        log.debug("suppressed exception", exc_info=True)
    try:
        await _safe_reply(query.message, "\n".join(parts), reply_markup=kb)
    except Exception as _send_e:
        log.warning(f"recommend_engine send error: {_send_e}")
        # Send truncated version
        short_parts = parts[:8]
        short_parts.append(f"\n<i>⚠️ Full output truncated — scored {len(scored)} tickers</i>")
        try:
            await query.message.reply_text("\n".join(short_parts), parse_mode=H, reply_markup=kb)
        except Exception:
            await query.message.reply_text(
                f"🎯 Recommend Engine: Scored {len(scored)} tickers.\n"
                f"Top: {', '.join(s['ticker'] for s in scored[:5])}",
                reply_markup=kb)

# ═══════════════════════════════════════════════════════════
#  SMART MONEY HUB — single unified report (plain-English, beginner-friendly)
# ═══════════════════════════════════════════════════════════


async def smart_money_hub_report(query):
    # ── single unified report body starts here ──
    conn = get_conn()
    _loading = await query.message.reply_text("⏳ Building Smart Money report…")
    try:
        today = datetime.now(timezone.utc).replace(tzinfo=None)
        parts = []
        score = 0; max_score = 13

        # ── header ──
        parts.append(f"<b>🧠 SMART MONEY REPORT</b>")
        parts.append(f"<i>What big funds &amp; insiders are doing right now — explained simply</i>")
        parts.append("─" * 26)

        # ─── SECTION 1: UNUSUAL OPTIONS (UOA) ───
        # Big investors quietly buy huge amounts of options before a big move.
        # We compare today's volume to the 10-day average.
        try:
            td = today.strftime("%Y-%m-%d")
            q1 = """
                SELECT ticker,
                       SUM(openInt_Call_now + openInt_Put_now) AS oi_today,
                       COUNT(*) AS strikes
                FROM options_change WHERE trade_date_now=?
                GROUP BY ticker HAVING oi_today > 0
                ORDER BY oi_today DESC LIMIT 100
            """
            df_uoa = pd.read_sql(q1, conn, params=[td])
            # compare to 10-day avg OI per ticker
            q1b = """
                SELECT ticker, AVG(total_oi) AS avg_oi FROM (
                  SELECT ticker, trade_date_now,
                         SUM(openInt_Call_now+openInt_Put_now) AS total_oi
                  FROM options_change GROUP BY ticker, trade_date_now
                ) GROUP BY ticker
            """
            df_avg = pd.read_sql(q1b, conn)
            df_uoa = df_uoa.merge(df_avg, on="ticker", how="left")
            df_uoa["surge"] = df_uoa["oi_today"] / df_uoa["avg_oi"].replace(0, np.nan)
            hot = df_uoa[df_uoa["surge"] >= 1.5].sort_values("surge", ascending=False).head(5)
            parts.append("\n<b>📊 1. UNUSUAL OPTIONS ACTIVITY</b>")
            parts.append("<i>💡 Big funds buy options quietly before a move.</i>")
            parts.append("<i>   Surge ≥1.5× = someone knows something.</i>")
            if hot.empty:
                parts.append(mono("🟡 No big bets today — market\n   is quiet"))
            else:
                score += min(2, len(hot))
                parts.append(_pipe_table(
                    ("ST", "Tkr", "Surge", "Stks"),
                    [("🔥", str(r['ticker'])[:6], f"{r['surge']:.1f}x", str(int(r['strikes'])))
                     for _, r in hot.iterrows()],
                    right_cols={2, 3}))
                parts.append(f"🔴 <b>Alert: {len(hot)} tickers show unusual bets</b>")
        except Exception as e:
            parts.append(mono(f"UOA: data unavailable"))

        # ─── SECTION 2: DARK POOL / BLOCK OI ───
        # Institutions hide massive trades in "dark pools".
        # A single strike with 3× the normal OI = hidden block trade.
        try:
            q2 = """
                SELECT ticker, strike, expiry_date,
                       (openInt_Call_now + openInt_Put_now) AS oi,
                       (openInt_Call_now*1.0 / NULLIF(openInt_Call_now+openInt_Put_now,0)) AS call_pct
                FROM options_change WHERE trade_date_now=?
                ORDER BY oi DESC LIMIT 200
            """
            df_dp = pd.read_sql(q2, conn, params=[td])
            if not df_dp.empty:
                avg_oi = df_dp["oi"].mean()
                blocks = df_dp[df_dp["oi"] >= avg_oi * 3].head(5)
            else:
                blocks = pd.DataFrame()
            parts.append("\n<b>🏦 2. DARK POOL / BLOCK TRADES</b>")
            parts.append("<i>💡 A strike with 3× normal OI = institution</i>")
            parts.append("<i>   quietly built a huge position there.</i>")
            if blocks.empty:
                parts.append(mono("🟡 No block concentrations found"))
            else:
                score += min(1, len(blocks))
                _blk = []
                for _, r in blocks.iterrows():
                    _bem = "🟢" if r["call_pct"] > 0.6 else ("🔴" if r["call_pct"] < 0.4 else "🟡")
                    _blk.append((_bem, str(r['ticker'])[:5], f"{r['strike']:.0f}",
                                 str(r["expiry_date"])[5:10] if r["expiry_date"] else "?"))
                parts.append(_pipe_table(("ST", "Tkr", "Stk", "Exp"), _blk,
                                         right_cols={2},
                                         legend="🟢 call-bias · 🔴 put-bias · 🟡 mixed"))
                parts.append(f"🔵 <b>{len(blocks)} block positions detected</b>")
        except Exception as e:
            parts.append(mono(f"DarkPool: data unavailable"))

        # ─── SECTION 3: MARKET MOOD (PCR Z-Score = COT Proxy) ───
        # Put/Call Ratio tells us if investors are buying fear (puts) or greed (calls).
        # When it's extreme, the market often reverses — like a rubber band.
        try:
            q3 = "SELECT ticker, pcr_oi FROM stock_daily WHERE trade_date=? AND pcr_oi IS NOT NULL"
            df_pcr = pd.read_sql(q3, conn, params=[td])
            q3b = "SELECT ticker, AVG(pcr_oi) AS mean_pcr, " \
                  "AVG(pcr_oi*pcr_oi) - AVG(pcr_oi)*AVG(pcr_oi) AS var_pcr " \
                  "FROM stock_daily WHERE ticker!='SPY' GROUP BY ticker"
            df_base = pd.read_sql(q3b, conn)
            df_pcr = df_pcr[df_pcr["ticker"] != "SPY"].merge(df_base, on="ticker", how="inner")
            df_pcr["std_pcr"] = np.sqrt(df_pcr["var_pcr"].clip(0))
            df_pcr["z"] = (df_pcr["pcr_oi"] - df_pcr["mean_pcr"]) / df_pcr["std_pcr"].replace(0, np.nan)
            fear = df_pcr[df_pcr["z"] >= 1.5]
            greed = df_pcr[df_pcr["z"] <= -1.5]
            parts.append("\n<b>😨 3. MARKET MOOD (Fear vs Greed)</b>")
            parts.append("<i>💡 PCR = Put/Call Ratio. High PCR = fear.</i>")
            parts.append("<i>   Extreme fear often means a bounce coming.</i>")
            mood_lines = []
            if not fear.empty:
                score += 1
                top_fear = fear.nlargest(3, "z")["ticker"].tolist()
                mood_lines.append(f"😨 FEAR tickers: {', '.join(top_fear)}")
                mood_lines.append("   (Investors panic-buying puts = possible bounce)")
            if not greed.empty:
                score += 1
                top_greed = greed.nsmallest(3, "z")["ticker"].tolist()
                mood_lines.append(f"😎 GREED tickers: {', '.join(top_greed)}")
                mood_lines.append("   (Too much call buying = possible pullback)")
            if not mood_lines:
                mood_lines.append("🟡 Mood is NEUTRAL — no extremes today")
            parts.append(mono("\n".join(mood_lines)))
        except Exception:
            parts.append(mono("Mood: data unavailable"))

        # ─── SECTION 4: DEALER GEX (Market Stabilizer?) ───
        # Market makers must hedge. When they hold more calls than puts
        # they BUY dips (stabilizes market). When more puts, they SELL rallies (amplifies).
        try:
            q4 = """SELECT ticker, strike, expiry_date,
                        openInt_Call_now, openInt_Put_now
                    FROM options_change WHERE trade_date_now=? LIMIT 2000"""
            df_gex = pd.read_sql(q4, conn, params=[td])
            q4s = "SELECT ticker, close AS spot FROM stock_daily WHERE trade_date=?"
            df_spots = pd.read_sql(q4s, conn, params=[td])
            df_gex = df_gex.merge(df_spots, on="ticker", how="left")
            df_gex = df_gex.dropna(subset=["spot"])
            df_gex["w"] = np.exp(-0.5 * ((df_gex["strike"] - df_gex["spot"]) / (df_gex["spot"] * 0.05)) ** 2)
            df_gex["gex"] = df_gex["w"] * (df_gex["openInt_Call_now"] - df_gex["openInt_Put_now"])
            gex_sum = df_gex.groupby("ticker")["gex"].sum()
            pos_gex = (gex_sum > 0).sum(); neg_gex = (gex_sum < 0).sum()
            total_t = len(gex_sum)
            parts.append("\n<b>⚖️ 4. DEALER GEX (Market Stabilizer)</b>")
            parts.append("<i>💡 When dealers hold more calls, they BUY</i>")
            parts.append("<i>   dips — market stays calm. More puts =</i>")
            parts.append("<i>   they SELL rallies — bigger swings ahead.</i>")
            if total_t > 0:
                pct_pos = pos_gex / total_t * 100
                if pct_pos >= 60:
                    score += 2
                    parts.append(mono(f"🟢 STABILIZING ({pct_pos:.0f}% tickers)\nMarket dips likely to be bought"))
                elif pct_pos <= 40:
                    parts.append(mono(f"🔴 AMPLIFYING ({100-pct_pos:.0f}% tickers)\nExpect bigger swings both ways"))
                else:
                    score += 1
                    parts.append(mono(f"🟡 MIXED GEX ({pct_pos:.0f}% positive)\nNo clear stabilizer regime"))
            else:
                parts.append(mono("GEX: insufficient data"))
        except Exception:
            parts.append(mono("GEX: data unavailable"))

        # ─── SECTION 5: OIL CRASH SIGNAL ───
        # Every major crash since 1987 was preceded by oil rising 100%+ in 12 months.
        # Iran War 2026 is a recent example. We track oil 12-month change.
        try:
            import yfinance as yf
            oil = _yf_ticker("CL=F").history(period="14mo")["Close"].dropna()
            if len(oil) >= 250:
                roc_12m = (oil.iloc[-1] / oil.iloc[-252] - 1) * 100
            elif len(oil) >= 2:
                roc_12m = (oil.iloc[-1] / oil.iloc[0] - 1) * 100
            else:
                roc_12m = 0
            parts.append("\n<b>🛢️ 5. OIL CRASH SIGNAL</b>")
            parts.append("<i>💡 Oil rising 100%+ in a year has preceded</i>")
            parts.append("<i>   EVERY crash since 1987 (1990, 2000, 2008,</i>")
            parts.append("<i>   2022, 2026). Below 100% = safer zone.</i>")
            oil_now = oil.iloc[-1] if len(oil) else 0
            if roc_12m >= 100:
                score += 2
                parts.append(mono(f"🚨 DANGER: Oil 12m ROC={roc_12m:.0f}%\nPrice: ${oil_now:.1f}\nHISTORIC crash warning active!"))
            elif roc_12m >= 60:
                score += 1
                parts.append(mono(f"⚠️ WATCH: Oil 12m ROC={roc_12m:.0f}%\nPrice: ${oil_now:.1f}\nApproaching danger zone"))
            else:
                parts.append(mono(f"🟢 SAFE: Oil 12m ROC={roc_12m:.0f}%\nPrice: ${oil_now:.1f}\nNo crash signal from oil"))
        except Exception:
            parts.append(mono("Oil signal: unavailable"))

        # ─── SECTION 6: CREDIT WARNING (Bond Market Leads Stocks) ───
        # Bond investors are smarter money. When bonds fall while stocks rise,
        # stocks usually follow bonds down within 2–5 days.
        try:
            spyh = _yf_ticker("SPY").history(period="15d")["Close"].dropna()
            hygh = _yf_ticker("HYG").history(period="15d")["Close"].dropna()
            if len(spyh) >= 6 and len(hygh) >= 6:
                spy5 = (spyh.iloc[-1] / spyh.iloc[-6] - 1) * 100
                hyg5 = (hygh.iloc[-1] / hygh.iloc[-6] - 1) * 100
                div = spy5 - hyg5
            else:
                spy5 = hyg5 = div = 0
            # VIX ratio
            try:
                vix = _yf_ticker("^VIX").history(period="5d")["Close"].dropna()
                vix3m = _yf_ticker("^VIX3M").history(period="5d")["Close"].dropna()
                vix_ratio = vix.iloc[-1] / vix3m.iloc[-1] if len(vix) and len(vix3m) else 1.0
            except Exception:
                vix_ratio = 1.0
            parts.append("\n<b>📉 6. CREDIT WARNING SIGNAL</b>")
            parts.append("<i>💡 Bonds warn 2–5 days before stocks drop.</i>")
            parts.append("<i>   HYG = junk bonds. If HYG falls while SPY</i>")
            parts.append("<i>   rises → stocks will likely follow bonds down.</i>")
            warn = False
            if div >= 2.0:
                score += 2; warn = True
                parts.append(mono(f"🚨 DIVERGENCE: SPY +{spy5:.1f}% but\n   HYG {hyg5:+.1f}% (5d)\nStocks may correct soon!"))
            elif div >= 1.0:
                score += 1; warn = True
                parts.append(mono(f"⚠️ Mild gap: SPY {spy5:+.1f}%\n   HYG {hyg5:+.1f}% (5d)\nWatch for pullback"))
            else:
                parts.append(mono(f"🟢 No divergence\nSPY {spy5:+.1f}%  HYG {hyg5:+.1f}% (5d)"))
            vix_str = "DANGER (vol spike likely)" if vix_ratio > 1.05 else ("Calm" if vix_ratio < 0.95 else "Normal")
            vix_icon = "🚨" if vix_ratio > 1.05 else ("🟢" if vix_ratio < 0.95 else "🟡")
            parts.append(mono(f"VIX/VIX3M: {vix_ratio:.2f} {vix_icon}\n{vix_str}"))
            if vix_ratio > 1.05:
                score += 1
        except Exception:
            parts.append(mono("Credit: data unavailable"))

        # ─── SECTION 7: MARKET REGIME ───
        # Is the market in BULL (rising), BEAR (falling), or CHOPPY mode?
        # This tells you which strategies work right now.
        try:
            # Regime read used us_analytics_daily, now dropped (ID 281). An empty frame
            # falls through to the existing "no regime data" branch instead of scoring the
            # market off February.
            df_reg = pd.DataFrame(columns=["bull_score", "bear_score"])
            parts.append("\n<b>🌡️ 7. MARKET REGIME (What mode are we in?)</b>")
            parts.append("<i>💡 BULL = buy dips. BEAR = sell rallies.</i>")
            parts.append("<i>   CHOPPY = stay small, wait for clarity.</i>")
            if df_reg.empty:
                parts.append(mono("Regime: data unavailable"))
            else:
                avg_bull = df_reg["bull_score"].mean()
                avg_bear = df_reg["bear_score"].mean()
                if avg_bull > avg_bear * 1.3:
                    regime = "🟢 BULL"
                    advice = "Buy dips. Favor call options."
                    score += 0
                elif avg_bear > avg_bull * 1.3:
                    regime = "🔴 BEAR"
                    advice = "Sell rallies. Favor put options."
                    score += 2
                else:
                    regime = "🟡 CHOPPY"
                    advice = "Stay small. Wait for breakout."
                    score += 1
                parts.append(mono(f"Regime: {regime}\nBull score: {avg_bull:.1f}\nBear score: {avg_bear:.1f}\n→ {advice}"))
        except Exception:
            parts.append(mono("Regime: data unavailable"))

        # ─── FINAL VERDICT ───
        parts.append("\n" + "═" * 26)
        pct = score / max_score * 100
        if score >= 8:
            verdict = "🚨 HIGH RISK — Strong warning signals"
            advice_final = "Multiple systems are flashing red. Consider reducing exposure or hedging."
        elif score >= 5:
            verdict = "⚠️ CAUTION — Mixed signals"
            advice_final = "Some warning signs present. Keep positions smaller, watch closely."
        else:
            verdict = "🟢 CALM — No major warnings"
            advice_final = "Market looks relatively stable. Normal risk-taking is fine."
        parts.append(f"<b>VERDICT: {verdict}</b>")
        parts.append(mono(f"Risk Score: {score}/{max_score} ({pct:.0f}%)"))
        parts.append(f"\n<i>{advice_final}</i>")
        parts.append("\n<i>⚠️ Not financial advice. For learning only.</i>")

        kb = InlineKeyboardMarkup([[BACK_BTN]])
        await _safe_reply(query.message, "\n".join(parts), reply_markup=kb)
    except Exception as e:
        await query.message.reply_text(f"❌ Smart Money error: {e}", reply_markup=InlineKeyboardMarkup([[BACK_BTN]]))
    finally:
        conn.close()
    try:
        await _loading.delete()
    except Exception:
        log.debug("suppressed exception", exc_info=True)


