# ── MORNING EVENT BRIEFING  (optimistic / pessimistic / balanced)
# ═══════════════════════════════════════════════════════════════════
# Ordered list of the events surfaced in the daily brief. Edit to taste.
_BRIEFING_EVENTS = ["iran", "war", "oil_spike", "fed_cut", "china_stimulus"]

def morning_briefing(conn, event_keys=None):
    """Assemble the daily brief: OpEx/gamma regime + a 3-view read on each major
    macro event (optimistic / pessimistic / balanced) with the lead defined-risk
    trade and hedge. Pure composition over opex_radar + MACRO_EVENT_MAP."""
    keys = event_keys or _BRIEFING_EVENTS
    rad = {}
    try:
        rad = opex_radar(conn)
    except Exception:
        rad = {}
    evs = [(k, MACRO_EVENT_MAP[k]) for k in keys if k in MACRO_EVENT_MAP]
    news = {}
    try:
        news = _event_news_google(keys)
    except Exception:
        news = {}
    regime = {}
    try:
        regime = _risk_regime()
    except Exception:
        regime = {}
    mom = {}
    try:
        _mdf, _masof = load_momentum_ranks(conn)
        if _mdf is not None and not _mdf.empty:
            mom = {"asof": _masof,
                   "top": _mdf.head(3)[["ticker", "ret_12_1"]].values.tolist(),
                   "bottom": _mdf.tail(3).iloc[::-1][["ticker", "ret_12_1"]].values.tolist()}
    except Exception:
        mom = {}
    return {"opex": rad, "events": evs, "news": news, "regime": regime, "momentum": mom}

_POS_NEWS_CACHE = {}           # tk -> (epoch, [headline, ...]) — .news is a network call


def _position_news(tickers, per_tk=2, max_age=1800, days=3):
    """Recent per-ticker headlines for the positions card, earnings-first.

    The card pushes every 10-15 min, so this is cached 30 min per ticker — the underlying
    feeds update far slower than that and an uncached fetch per push would hammer them.

    Sources: Finnhub company-news when the key is present (it carries a `summary`, which is
    the closest thing we get to an earnings-call takeaway), falling back to keyless yfinance
    per-ticker news. NOTE: neither source gives actual earnings-CALL transcripts — what you
    get is reporting ABOUT the print, so it is labelled as headlines, not "management said".
    """
    import urllib.request, json as _json, datetime as _dt
    key = os.environ.get("FINNHUB_API_KEY") or os.environ.get("FINNHUB_KEY")
    now = time.time()
    _KW = ("earning", "results", "quarter", "guidance", "beat", "miss", "outlook",
           "revenue", "forecast", "eps", "price target", "upgrade", "downgrade")
    # Sources that actually move a stock. Everything else (aggregator spam, listicles,
    # "3 stocks to watch" content) is dropped — user 2026-07-23: "strong news, not timepass".
    _GOOD_SRC = ("reuters", "bloomberg", "wall street journal", "wsj", "cnbc", "barron",
                 "financial times", "benzinga", "marketwatch", "associated press", "ap ",
                 "investor's business daily", "seeking alpha", "yahoo finance", "forbes",
                 "the information", "axios", "business insider")
    # Company aliases so a headline is only attached to a ticker it actually names.
    _ALIAS = {"GOOG": ("alphabet", "google"), "GOOGL": ("alphabet", "google"),
              "TSLA": ("tesla", "musk"), "AMD": ("amd", "advanced micro"),
              "NVDA": ("nvidia",), "AAPL": ("apple",), "MSFT": ("microsoft",),
              "AMZN": ("amazon",), "META": ("meta", "facebook"), "NFLX": ("netflix",),
              "AVGO": ("broadcom",), "MU": ("micron",), "INTC": ("intel",)}

    def _relevant(tk_, headline):
        """Headline must actually NAME this company. Without this, unrelated sector news
        ('STMicro Plunges...') was being filed under TSLA."""
        h = headline.lower()
        if tk_.lower() in h.split() or f"({tk_.lower()})" in h or f"${tk_.lower()}" in h:
            return True
        return any(a in h for a in _ALIAS.get(tk_, (tk_.lower(),)))
    out = {}
    _used = set()                  # headlines already shown for ANOTHER ticker
    for tk in dict.fromkeys(str(t).upper() for t in tickers if t):
        hit = _POS_NEWS_CACHE.get(tk)
        if hit and (now - hit[0]) < max_age:
            _fresh = [(h, u) for h, u in hit[1] if h.lower()[:40] not in _used]
            if _fresh:
                out[tk] = _fresh
                _used.update(h.lower()[:40] for h, u in _fresh)
            continue
        items = []
        if key:
            try:
                _to = _et_now().date(); _fr = _to - _dt.timedelta(days=days)
                u = (f"https://finnhub.io/api/v1/company-news?symbol={tk}"
                     f"&from={_fr}&to={_to}&token={key}")
                with urllib.request.urlopen(u, timeout=12) as r:
                    for d in _json.loads(r.read().decode())[:40]:
                        h = str(d.get("headline") or "").strip()
                        src = str(d.get("source") or "").lower()
                        if h and _relevant(tk, h) and (not src or
                                                       any(g in src for g in _GOOD_SRC)):
                            items.append((h, str(d.get("summary") or "").strip(),
                                         str(d.get("url") or "").strip()))
            except Exception:
                log.debug(f"finnhub news {tk} failed", exc_info=True)
        if not items:                                   # keyless fallback
            try:
                for it in (_yf_ticker(tk).news or [])[:20]:
                    c = it.get("content", it) or {}
                    h = str(c.get("title") or "").strip()
                    if h and _relevant(tk, h):
                        _u = ((c.get("canonicalUrl") or {}).get("url")
                              or (c.get("clickThroughUrl") or {}).get("url") or "")
                        items.append((h, str(c.get("summary") or "").strip(), _u))
            except Exception:
                log.debug(f"yf news {tk} failed", exc_info=True)
        # earnings-related first — that is what moves a position the day after a print
        items.sort(key=lambda x: 0 if any(k in x[0].lower() for k in _KW) else 1)
        # dedupe within the ticker AND across tickers — a market-wide headline ("Nasdaq
        # futures fall as Tesla, Alphabet earnings...") otherwise repeats on every position.
        # Carries the article URL through now (user 2026-07-24: "I asked for hyperlinks to
        # read full news") -- each item is (headline, url) instead of a bare headline string.
        picked, seen = [], set()
        for h, _s, _u in items:
            k = h.lower()[:40]
            if k in seen or k in _used:
                continue
            seen.add(k)
            picked.append((h, _u))
            if len(picked) >= per_tk:
                break
        _POS_NEWS_CACHE[tk] = (now, picked)
        if picked:
            out[tk] = picked
            _used.update(h.lower()[:40] for h, _u in picked)
    return out



# ── World / geopolitical news lane (user 2026-08-07) ─────────────────────────────────
# ROOT CAUSE of "why no Japan/yen or Ukraine/Russia": _world_news_block wires
# market_news_enhanced.get_aggregated_news, which pulls FOUR US-EQUITY feeds only --
# Yahoo Finance, Google Finance, MarketWatch, Benzinga -- capped at 2-3 items each. A BoJ
# yen intervention or a strike on Ukrainian infrastructure is simply not in that feed. It
# was never a filtering bug; the stories were never fetched.
#
# These are keyless RSS. Reuters was tested and is dead from here (DNS fails), so it is not
# in the list rather than sitting there failing silently every morning.
_GEO_FEEDS = [
    ("BBC World",    "http://feeds.bbci.co.uk/news/world/rss.xml"),
    ("BBC Business", "http://feeds.bbci.co.uk/news/business/rss.xml"),
    ("Al Jazeera",   "https://www.aljazeera.com/xml/rss/all.xml"),
    # Google News topic searches: keyless, and the only reliable way to force coverage of a
    # theme the general feeds may bury on a given day.
    ("Japan/BoJ",  "https://news.google.com/rss/search?q=yen+OR+%22bank+of+japan%22+when:2d&hl=en-US&gl=US&ceid=US:en"),
    ("Ukraine",    "https://news.google.com/rss/search?q=ukraine+russia+when:2d&hl=en-US&gl=US&ceid=US:en"),
    ("Trade/China","https://news.google.com/rss/search?q=tariffs+OR+sanctions+OR+china+trade+when:2d&hl=en-US&gl=US&ceid=US:en"),
    ("Energy",     "https://news.google.com/rss/search?q=opec+OR+%22oil+prices%22+when:2d&hl=en-US&gl=US&ceid=US:en"),
]

# what makes a world story MARKET news rather than general news
_GEO_KEYWORDS = {
    "🇯🇵 Japan / yen": ("yen", "bank of japan", "boj", "nikkei", "japanese"),
    "⚔️ Russia / Ukraine": ("ukraine", "russia", "russian", "kyiv", "moscow", "drone strike"),
    # "china" alone let in "First school for robots opens in China" — a country name is not
    # a market story. Requires an economic/trade word (2026-08-07).
    "🇨🇳 China / trade": ("tariff", "sanction", "trade war", "export control", "chip curb",
                          "yuan", "china trade", "beijing stimulus"),
    "🛢️ Energy / OPEC": ("opec", "oil price", "crude", "refinery", "pipeline", "lng"),
    "🏦 Central banks": ("federal reserve", "ecb", "rate cut", "rate hike", "inflation",
                         "central bank", "boe"),
    "⚠️ Conflict / risk": ("missile", "attack", "strike", "war", "ceasefire", "invasion",
                           "military"),
}


def _geo_news(limit_per_theme=2, timeout=10):
    """Market-relevant WORLD headlines, grouped by theme. [] on failure — never blocks the brief."""
    import urllib.request as _u, re as _re, html as _html
    items = []
    for src, url in _GEO_FEEDS:
        try:
            req = _u.Request(url, headers={"User-Agent": "Mozilla/5.0"})
            xml = _u.urlopen(req, timeout=timeout).read().decode("utf-8", "ignore")
        except Exception:
            log.debug("geo feed failed: %s", src)
            continue
        # parse <item> blocks — grabbing every <title> also picks up the CHANNEL title
        for blk in _re.findall(r"<item[^>]*>(.*?)</item>", xml, _re.S)[:12]:
            m = _re.search(r"<title>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?</title>", blk, _re.S)
            l = _re.search(r"<link>(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?</link>", blk, _re.S)
            if not m:
                continue
            t = _html.unescape(_re.sub(r"<[^>]+>", "", m.group(1))).strip()
            if len(t) < 20:
                continue
            items.append((t, (l.group(1).strip() if l else ""), src))
    if not items:
        return {}
    out, seen = {}, set()
    for title, url, src in items:
        low = title.lower()
        for theme, kws in _GEO_KEYWORDS.items():
            if not any(k in low for k in kws):
                continue
            key = title[:55].lower()
            if key in seen:
                break
            bucket = out.setdefault(theme, [])
            if len(bucket) >= limit_per_theme:
                break
            seen.add(key)
            bucket.append((title[:130], url, src))
            break
    return out


def _fmt_geo_news(themes=None, max_themes=4):
    """The WORLD section for the morning brief. None when nothing market-relevant landed."""
    themes = themes if themes is not None else _geo_news()
    if not themes:
        return None
    order = ["⚔️ Russia / Ukraine", "🇯🇵 Japan / yen", "🇨🇳 China / trade",
             "🛢️ Energy / OPEC", "🏦 Central banks", "⚠️ Conflict / risk"]
    out = ["<b>🌏 WORLD — what moved overnight</b>"]
    n = 0
    for th in order:
        if th not in themes or n >= max_themes:
            continue
        n += 1
        out.append(f"<b>{th}</b>")
        for title, url, src in themes[th]:
            out.append(f"  • " + (f'<a href="{url}">{title}</a>' if url else title)
                       + f" <i>({src})</i>")
    if n == 0:
        return None
    out.append("<i>World feeds are BBC/Al Jazeera plus themed Google News searches — "
               "kept separate from the US equity wires, which do not carry these stories.</i>")
    return "\n".join(out)


def _world_news_block(limit=6):
    """Top world/market headlines for the morning brief — wires the previously-orphaned
    `_lib/market_news_enhanced.get_aggregated_news` (Google/Yahoo/MarketWatch/Benzinga RSS,
    keyless). Filters the blank rows the raw feed returns (verified 2026-07-22: the first
    Yahoo item comes back with an empty headline), dedupes, and formats compactly. Returns
    [] on any failure so the brief still renders without news.
    """
    try:
        import sys as _sys
        _lp = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_lib")
        if _lp not in _sys.path:
            _sys.path.insert(0, _lp)
        import market_news_enhanced as _mne
        raw = _mne.get_aggregated_news(limit=limit * 3) or []
    except Exception as e:
        log.debug(f"world news fetch failed: {e}", exc_info=True)
        return []
    out, seen = [], set()
    for it in raw:
        if not isinstance(it, dict):
            continue
        head = str(it.get("headline") or it.get("title") or "").strip()
        if len(head) < 12:                     # drops the empty/junk rows
            continue
        key = head[:60].lower()
        if key in seen:
            continue
        seen.add(key)
        src = str(it.get("source") or "").strip()
        # url WAS already in the raw feed (market_news_enhanced's own docstring: "with
        # links") but was being silently dropped here (user 2026-07-24: "no hyperlinks to
        # read full news"). Carried through now as a 3rd tuple element.
        url = str(it.get("url") or it.get("link") or "").strip()
        out.append((head, src, url))
        if len(out) >= limit:
            break
    return out


# ─────────────────── RAG grounding (moved from mcp_server.py 2026-07-27) ───────────────────
# Owns the notes corpus + FTS5 index HERE (the canonical engine file) so both dashboard.py
# and this bot can call it directly. mcp_server.py's search_notes MCP tool now delegates to
# search_notes_core() below instead of keeping its own copy -- one ingestion path, not two.
_RAG_DB = os.path.join(os.path.dirname(os.path.abspath(__file__)), "rag_index.db")
_RAG_TTL = 600  # rebuild the index if it is older than this many seconds


def _rag_chunk_md(text: str, max_chars: int = 1200) -> list:
    """Split a markdown doc into heading/dated-entry chunks for retrieval."""
    parts = re.split(r"\n(?=#{1,3}\s|\d{4}-\d\d-\d\d)", text)
    out = []
    for p in parts:
        p = p.strip("\n")
        if len(p) <= max_chars:
            out.append(p)
        else:
            out.extend(p[i:i + max_chars] for i in range(0, len(p), max_chars))
    return out


def _rag_docs() -> list:
    """Collect (source, ref, date, title, body) docs from DB tables + docs/*.md."""
    docs = []
    conn = get_conn()

    def _q(sql):
        try:
            return list(conn.execute(sql))
        except Exception:
            return []

    try:
        for r in _q("SELECT id, event_id, phase, writeup_text, generated_at FROM event_writeups "
                    "WHERE writeup_text IS NOT NULL AND writeup_text != ''"):
            docs.append(("event_writeup", f"ew{r[0]}/evt{r[1]}/{r[2]}", str(r[4] or ""),
                         f"Event {r[1]} · {r[2]}", r[3]))
        for r in _q("SELECT news_id, ticker, headline, summary, source, published_date, sentiment "
                    "FROM news_feed"):
            body = f"[{r[4] or ''} · {r[6] or ''}] {(r[2] or '')} — {(r[3] or '')}".strip()
            docs.append(("news", f"news{r[0]}/{r[1] or ''}", str(r[5] or ""),
                         f"{r[1] or ''}: {r[2] or ''}", body))
        for r in _q("SELECT event_id, name, category, event_date, impact, related_tickers, "
                    "estimate, actual, prior, unit FROM event_catalog"):
            body = (f"{r[1]} ({r[2]}, impact {r[4]}). tickers={r[5]}. "
                    f"est={r[6]} actual={r[7]} prior={r[8]} {r[9] or ''}")
            docs.append(("event_catalog", f"cat{r[0]}", str(r[3] or ""), r[1] or "", body))
        for r in _q("SELECT id, ticker, direction, note, entry_date, status FROM event_journal "
                    "WHERE note IS NOT NULL AND note != ''"):
            docs.append(("journal", f"jrn{r[0]}/{r[1] or ''}", str(r[4] or ""),
                         f"{r[1] or ''} {r[2] or ''} {r[5] or ''}", r[3]))
        for r in _q("SELECT id, kind, label, content, created FROM bookmarks "
                    "WHERE content IS NOT NULL AND content != ''"):
            docs.append(("bookmark", f"bm{r[0]}/{r[1] or ''}", str(r[4] or ""), r[2] or "", r[3]))
        for r in _q("SELECT ticker, trade_date, source, label, score, fwd_ret FROM sentiment_log"):
            body = f"{r[0]} sentiment ({r[2]}): {r[3]}, score={r[4]}, fwd_ret={r[5]}"
            docs.append(("sentiment", f"sent/{r[0]}/{r[1]}", str(r[1] or ""), f"{r[0]} sentiment", body))
        for r in _q("SELECT fund, quarter, cusip, issuer, shares, value, put_call FROM edgar_13f"):
            shares = int(r[4]) if r[4] is not None else 0
            value = float(r[5]) if r[5] is not None else 0.0
            body = (f"{r[0]} ({r[1]}): {r[3] or r[2]} — {shares:,} shares, ${value:,.0f}"
                    f"{(' ' + r[6]) if r[6] else ''}")
            docs.append(("13f", f"13f/{r[0]}/{r[1]}/{r[2]}", "", f"{r[0]} 13F {r[1]}", body))
    finally:
        conn.close()

    _here = os.path.dirname(os.path.abspath(__file__))
    for fn in ("LOG.md", "NEXT.md", "PLAN.md"):
        p = os.path.join(_here, "docs", fn)
        if not os.path.exists(p):
            continue
        try:
            text = open(p, encoding="utf-8").read()
        except Exception:
            continue
        for i, chunk in enumerate(_rag_chunk_md(text)):
            if chunk.strip():
                docs.append((f"doc:{fn}", f"{fn}#{i}", "", fn, chunk))
    return docs


def _rag_index(force: bool = False):
    """Open rag_index.db, (re)building the FTS5 table if missing or stale. Returns the conn."""
    rc = sqlite3.connect(_RAG_DB)
    rc.execute("CREATE TABLE IF NOT EXISTS rag_meta(k TEXT PRIMARY KEY, v TEXT)")
    fresh = False
    if not force:
        built = rc.execute("SELECT v FROM rag_meta WHERE k='built_at'").fetchone()
        has = rc.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='notes'").fetchone()
        fresh = bool(built and has and (time.time() - float(built[0])) < _RAG_TTL)
    if not fresh:
        rc.execute("DROP TABLE IF EXISTS notes")
        rc.execute("CREATE VIRTUAL TABLE notes USING fts5("
                   "source, ref, date, title, body, tokenize='porter unicode61')")
        docs = _rag_docs()
        rc.executemany("INSERT INTO notes(source, ref, date, title, body) VALUES (?,?,?,?,?)",
                       [(d[0], d[1], d[2], d[3], d[4] or "") for d in docs])
        rc.execute("INSERT OR REPLACE INTO rag_meta(k,v) VALUES('built_at',?)", (str(time.time()),))
        rc.execute("INSERT OR REPLACE INTO rag_meta(k,v) VALUES('n_docs',?)", (str(len(docs)),))
        rc.commit()
    return rc


def _rag_fts_query(q: str) -> str:
    """Turn free text into a safe FTS5 MATCH expression (strip syntax-breaking punctuation)."""
    q2 = re.sub(r'[^\w\s"*]', ' ', q)
    return re.sub(r'\s+', ' ', q2).strip()


def search_notes_core(query: str, top_k: int = 6, source: str = None) -> dict:
    """Full-text search across the engine's notes corpus (RAG retrieval) -- the single
    implementation both mcp_server.py's search_notes tool and _verdict_grounding() call.
    See docs/PLAN.md 13F/sentiment RAG note (2026-07-27) for why this lives here, not in
    mcp_server.py: mcp_server imports this module, so the reverse import would be circular."""
    q = (query or "").strip()
    if not q:
        return {"query": query, "results": [], "error": "empty query"}
    rc = _rag_index()
    try:
        def run(expr):
            sql = ("SELECT source, ref, date, title, "
                   "snippet(notes, 4, '<<', '>>', ' … ', 12) AS snip, bm25(notes) AS rank "
                   "FROM notes WHERE notes MATCH ? ")
            params = [expr]
            if source:
                sql += "AND source = ? "
                params.append(source)
            sql += "ORDER BY rank LIMIT ?"
            params.append(int(top_k))
            return rc.execute(sql, params).fetchall()

        expr = _rag_fts_query(q)
        rows = []
        if expr:
            try:
                rows = run(expr)
                if not rows and " " in expr:
                    rows = run(" OR ".join(expr.split()))
            except Exception as e:
                return {"query": q, "results": [], "error": f"fts: {str(e)[:150]}"}
        meta = rc.execute("SELECT v FROM rag_meta WHERE k='n_docs'").fetchone()
    finally:
        rc.close()
    results = [{"source": r[0], "ref": r[1], "date": r[2], "title": r[3], "snippet": r[4]}
               for r in rows]
    return {"query": q, "matched_query": expr,
            "corpus_docs": int(meta[0]) if meta else None, "results": results}


_VERDICT_HINTS = {
    "BULL": "bullish call buying upside", "BULLISH": "bullish call buying upside",
    "BEAR": "bearish put selling downside", "BEARISH": "bearish put selling downside",
    "SELL_PREMIUM": "premium selling income theta", "NEUTRAL": "range bound mixed",
}


def _verdict_grounding(ticker, verdict, top_k=5):
    """Verdict-driven RAG grounding for a signal card: news/sentiment/13F context that
    actually matches WHY a verdict fired, not just "last N days for this ticker."

    Builds the query from the ticker plus the verdict's own direction keywords (see
    _VERDICT_HINTS) so retrieval favors passages that explain the same lean the model
    took, rather than unrelated same-day noise. Returns [] on any failure -- this is a
    display-layer enrichment, never allowed to block a verdict card from rendering.
    """
    tk = str(ticker or "").strip().upper()
    if not tk:
        return []
    hint = _VERDICT_HINTS.get(str(verdict or "").strip().upper(), "")
    q = f"{tk} {hint}".strip()
    try:
        res = search_notes_core(q, top_k=top_k)
        return res.get("results") or []
    except Exception:
        log.debug(f"verdict grounding failed for {tk}/{verdict}", exc_info=True)
        return []


def _fmt_briefing(b):
    from datetime import datetime as _dt
    news = b.get("news") or {}
    lines = ["☀️ <b>MORNING BRIEF</b> — " + _dt.now().strftime("%a %d %b %Y"), ""]
    _rg = b.get("regime") or {}
    if _rg:
        lines.append(f"{_rg.get('emoji','')} <b>Regime: {_rg.get('label','?')}</b> (score {_rg.get('score',0):+d})")
    try:
        _fc = _fomc_context()
    except Exception:
        _fc = None
    if _fc and _fc.get("pre_drift"):
        lines.append(f"📅 Pre-FOMC drift (FOMC {_fc['next']}) — historically bullish.")
    if _rg or (_fc and _fc.get("pre_drift")):
        lines.append("")

    rad = b.get("opex") or {}
    mj = rad.get("major") or {}
    gex = rad.get("gex") or {}
    if mj:
        q = "QUAD-WITCHING" if mj.get("is_quarterly") else "monthly OpEx"
        lines.append(f"\U0001F5D3 Next major OpEx: <b>{mj.get('date','?')}</b> ({mj.get('dte','?')}d, {q})")
    if gex:
        flip = gex.get("zero_gamma")
        lines.append("\U0001F4C8 SPY gamma: <b>" + str(gex.get("gex_signal", "?")) + "</b>"
                     + (f" | flip ${flip:.0f}" if flip else ""))
        if gex.get("gex_signal") == "TRENDING":
            lines.append("<i>Negative gamma -> dealers amplify moves; expect bigger swings.</i>")
        elif gex.get("gex_signal") == "PINNING":
            lines.append("<i>Positive gamma -> dealers dampen moves; range/mean-revert bias.</i>")
    _mm = b.get("momentum") or {}
    if _mm.get("top"):
        _tp = " · ".join(f"{t} {r:+.0f}%" for t, r in _mm["top"])
        _bt = " · ".join(f"{t} {r:+.0f}%" for t, r in _mm["bottom"])
        lines.append("🚀 <b>Momentum leaders:</b> " + _tp)
        lines.append("🐌 <b>Laggards:</b> " + _bt)
    lines.append("")
    lines.append("<b>\U0001F30D Events to watch</b>  (optimistic / pessimistic / balanced)")

    for key, ev in b.get("events", []):
        lead = ev["chain"][0] if ev.get("chain") else None
        lead_trade = (f"{lead[3]} ({lead[2]})" if lead else "")
        lines.append("")
        lines.append(f"<b>{ev['title']}</b>  <code>/event {key}</code>")
        if key in news:
            lines.append(f"🔥 <i>{news[key][0][:90]}</i>")
        lines.append(f"\U0001F7E2 <b>Bull:</b> {ev['thesis']}")
        lines.append(f"\U0001F534 <b>Bear:</b> {ev['caveat']}")
        if lead:
            lines.append(f"⚖️ <b>Play:</b> {lead_trade} — <i>{lead[4]}</i>")
        lines.append(f"\U0001F6E1 <b>Hedge:</b> {ev['hedge']}")

    # ── OVERNIGHT INTERNATIONAL (user raised repeatedly; ID 92 was closed against the WRONG
    # function). A US morning brief without Asia/Europe is missing the only thing that
    # actually happened while you slept, so this leads rather than trails.
    try:
        # reuse the proven fetcher rather than a second one: _plan_markets_rows already
        # handles every symbol, drops failures, and carries region + flag.
        _mr = [r for r in (_plan_markets_rows() or [])
               if r["region"] in ("Asia", "Europe") and r.get("last")]
        if _mr:
            # name[:7] and NO thousands separator: with 9-char names and commas the table
            # measured 30 display cells against Telegram's 28-cell <pre> limit.
            _irows = [("🟢" if (r["pct"] or 0) > 0 else "🔴" if (r["pct"] or 0) < 0 else "🟡",
                       r["name"][:7], f"{r['last']:.0f}",
                       f"{r['pct']:+.2f}" if r["pct"] is not None else "—") for r in _mr]
            _up = sum(1 for r in _mr if (r["pct"] or 0) > 0)
            lines += ["", _pipe_table(("ST", "Market", "Level", "Chg%"), _irows,
                                      right_cols={2, 3},
                                      title=f"🌏 OVERNIGHT — ASIA & EUROPE ({_up}/{len(_mr)} up)")]
    except Exception:
        log.debug("brief intl block failed", exc_info=True)

    # ── GEO NEWS. _world_news_block() calls a generic aggregator that has been returning
    # EMPTY, which is why Japan kept vanishing from this brief while _geo_news() (Japan/yen,
    # Russia/Ukraine, China/trade, Energy/OPEC) worked perfectly and was simply never wired
    # in here. Use _geo_news FIRST and keep the old aggregator only as a fallback.
    _geo_ok = False
    try:
        _g = _geo_news() or {}
        if _g:
            lines += ["", "🌍 <b>WORLD — what moved overnight</b>"]
            for _theme, _items in _g.items():
                if not _items:
                    continue
                lines.append(f"<b>{_theme}</b>")
                for _it in _items[:2]:
                    _h, _u = (_it if isinstance(_it, (list, tuple)) else (str(_it), ""))[:2]
                    lines.append(f"  • " + (f'<a href="{_u}">{_h[:105]}</a>' if _u else _h[:105]))
            _geo_ok = True
    except Exception:
        log.debug("brief geo block failed", exc_info=True)

    if not _geo_ok:
        _wn = _world_news_block()
        if _wn:
            lines += ["", "📰 <b>WORLD & MARKETS</b>"]
            for _h, _s, _u in _wn:
                _htxt = f'<a href="{_u}">{_h[:110]}</a>' if _u else _h[:110]
                lines.append(f"• {_htxt}" + (f" <i>({_s})</i>" if _s else ""))

    lines += ["",
        "<i>Tap /event NAME for the full 1st/2nd/3rd-order chain, or /opex for the expiration radar.</i>",
        "<i>Educational - not advice. Size for being wrong; let options price the odds.</i>"]
    return "\n".join(lines)

