# ── Market heatmap (user 2026-08-07) ─────────────────────────────────────────────────
# Tiles sized by market cap, coloured by % move, grouped by sector — the TradingView-style
# read. Built entirely from the DB: daily_fundamentals carries market_cap + sector for 453
# tickers and stock_daily carries the moves, so no new data source and no API key.
#
# LIVE vs EOD: when the market is open the move is measured against the last close using
# live quotes for the largest names; off-hours it is the completed session. Which one you
# are looking at is stated on the chart, because a heatmap with no as-of is misleading.

def _heatmap_frame(conn, live=False, max_names=180):
    """DataFrame: ticker, sector, mcap, pct — for the treemap. Empty frame on failure."""
    try:
        f = pd.read_sql(
            "SELECT UPPER(ticker) AS ticker, market_cap, sector FROM daily_fundamentals "
            "WHERE market_cap > 0 AND sector IS NOT NULL AND sector <> ''", conn)
        d = pd.read_sql(
            "SELECT UPPER(ticker) AS ticker, trade_date, close FROM stock_daily "
            "WHERE trade_date >= (SELECT MAX(trade_date) FROM stock_daily) "
            "   OR trade_date >= (SELECT MAX(trade_date) FROM stock_daily WHERE trade_date "
            "                     < (SELECT MAX(trade_date) FROM stock_daily))", conn)
    except Exception:
        return pd.DataFrame()
    if f.empty or d.empty:
        return pd.DataFrame()
    d = d.sort_values("trade_date")
    last = d.groupby("ticker").tail(1).set_index("ticker")["close"]
    prev = d.groupby("ticker").head(1).set_index("ticker")["close"]
    m = f.set_index("ticker").join(last.rename("px")).join(prev.rename("prev")).dropna()
    m = m[(m.px > 0) & (m.prev > 0)]
    if m.empty:
        return pd.DataFrame()
    m["pct"] = (m.px / m.prev - 1) * 100
    m = m.sort_values("market_cap", ascending=False).head(max_names).reset_index()
    if live:
        # refresh only the biggest names — a live quote per ticker is far too slow for 180
        for tk in m.head(40)["ticker"]:
            try:
                lp = _last_price(tk)
                if lp and lp > 0:
                    _pv = float(m.loc[m.ticker == tk, "prev"].iloc[0])
                    m.loc[m.ticker == tk, "pct"] = (lp / _pv - 1) * 100
            except Exception:
                pass
    return m


def _heatmap_png(conn, live=False, title=None):
    """Sector treemap -> PNG BytesIO for Telegram. None when unavailable."""
    m = _heatmap_frame(conn, live=live)
    if m.empty or len(m) < 10:
        return None
    try:
        import plotly.graph_objects as _go
        _lab = [f"{r.ticker}<br>{r.pct:+.1f}%" for r in m.itertuples()]
        fig = _go.Figure(_go.Treemap(
            labels=_lab,
            parents=list(m["sector"]),
            values=list(m["market_cap"]),
            marker=dict(colors=list(m["pct"]), colorscale=[[0, "#8b1a1a"], [0.5, "#3a3a3a"],
                                                           [1, "#0f7b2f"]],
                        cmid=0, cmin=-4, cmax=4, line=dict(width=1, color="#111")),
            textposition="middle center", textfont=dict(size=11, color="white"),
            hovertemplate="%{label}<extra></extra>",
            # NOT branchvalues="total": that requires each parent's value to EQUAL the sum
            # of its children, and appending sector rows with value 0 made every parent
            # smaller than its children, so Plotly silently dropped the whole tree and
            # rendered a blank chart (caught by looking at the PNG, 2026-08-07). The default
            # sums children into the parent, which is what a market-cap treemap wants.
        ))
        # sector rows must exist as parents, or the children have nothing to attach to
        _secs = sorted(set(m["sector"]))
        fig.data[0].labels = tuple(list(fig.data[0].labels) + _secs)
        fig.data[0].parents = tuple(list(fig.data[0].parents) + [""] * len(_secs))
        fig.data[0].values = tuple(list(fig.data[0].values) + [0] * len(_secs))
        fig.data[0].marker.colors = tuple(list(fig.data[0].marker.colors) + [0] * len(_secs))
        _asof = ("LIVE " + _et_now().strftime("%H:%M ET")) if live else "last completed session"
        fig.update_layout(
            title=dict(text=title or f"Market heatmap — {_asof} · tile size = market cap",
                       font=dict(size=15, color="white")),
            margin=dict(l=4, r=4, t=44, b=4), height=620, width=1000,
            paper_bgcolor="#0d0d0d", plot_bgcolor="#0d0d0d",
        )
        buf = BytesIO(fig.to_image(format="png", scale=2))
        buf.seek(0)
        return buf
    except Exception:
        log.debug("heatmap render failed", exc_info=True)
        return None


def _fmt_heatmap_text(conn, live=False, top=6):
    """The numbers behind the picture — a chart alone cannot be read back or quoted."""
    m = _heatmap_frame(conn, live=live)
    if m.empty:
        return None
    _sec = (m.assign(w=m.market_cap)
              .groupby("sector")
              .apply(lambda g: pd.Series({
                  "pct": float((g.pct * g.w).sum() / g.w.sum()),
                  "n": len(g)}), include_groups=False)
              .sort_values("pct", ascending=False))
    rows = [(("🟢" if r.pct > 0.3 else "🔴" if r.pct < -0.3 else "🟡"),
             str(i)[:14], f"{r.pct:+.2f}%", str(int(r.n))) for i, r in _sec.iterrows()]
    out = [_pipe_table(("ST", "Sector", "Cap-wtd", "N"), rows, right_cols={2, 3},
                       title="🗺️ SECTOR HEATMAP")]
    _up = m.nlargest(top, "pct"); _dn = m.nsmallest(top, "pct")
    out.append(_pipe_table(("Tkr", "Move"),
                           [(r.ticker[:6], f"{r.pct:+.1f}%") for r in _up.itertuples()],
                           right_cols={1}, title="🏆 Biggest gainers"))
    out.append(_pipe_table(("Tkr", "Move"),
                           [(r.ticker[:6], f"{r.pct:+.1f}%") for r in _dn.itertuples()],
                           right_cols={1}, title="⬇️ Biggest losers"))
    out.append("<i>Sector move is MARKET-CAP WEIGHTED, so it reflects index impact rather "
               "than an average of tickers — a mega-cap moving 1% outweighs ten small caps "
               "moving 3%.</i>")
    return "\n".join(out)


async def heatmap_command(update, ctx):
    """/heatmap — sector treemap: tile size = market cap, colour = today's move."""
    _live = _market_is_open() if callable(globals().get("_market_is_open")) else False
    msg = await update.message.reply_text("🗺️ Building the heatmap…", parse_mode=H)
    conn = get_conn()
    try:
        png = _heatmap_png(conn, live=_live)
        txt = _fmt_heatmap_text(conn, live=_live)
    finally:
        conn.close()
    try:
        await msg.delete()
    except Exception:
        pass
    if png:
        await update.message.reply_photo(png, caption="🗺️ Market heatmap — size = market cap, "
                                                      "colour = move")
    if txt:
        for _p in _chunk_on_sections(txt):
            await update.message.reply_text(_p, parse_mode=H)
    if not png and not txt:
        await update.message.reply_text("Heatmap unavailable — no market-cap/sector data.",
                                        parse_mode=H)



# ── Company money-flow (Sankey) ──────────────────────────────────────────────────────
# Lives HERE, in the engine, not in a helper module: house rule is that this file and
# dashboard.py are the canonical ones, and the dashboard reaches the engine through
# _TB_ENGINE rather than importing side modules.
#
# Colour is convention, not decoration: money kept is green, money spent is red, and links
# take their destination's hue at low alpha so a flow reads as "where this went". Revenue is
# GREY on purpose -- it is not yet profit or cost, and colouring it green would prejudge the
# statement. `_money` is already taken twice in this file, hence the _sk_ prefix throughout.
_SK_GREEN, _SK_GREEN_L = "#16a34a", "rgba(22,163,74,0.38)"
_SK_RED, _SK_RED_L = "#dc2626", "rgba(220,38,38,0.30)"
_SK_GREY, _SK_GREY_L = "#6b7280", "rgba(156,163,175,0.32)"

_SK_YF_ROWS = {
    "revenue": ("Total Revenue", "TotalRevenue", "Operating Revenue"),
    "gross":   ("Gross Profit", "GrossProfit"),
    "opinc":   ("Operating Income", "OperatingIncome", "Total Operating Income As Reported"),
    "net":     ("Net Income", "NetIncome", "Net Income Common Stockholders"),
    "tax":     ("Tax Provision", "TaxProvision", "Income Tax Expense"),
    "rnd":     ("Research And Development", "ResearchAndDevelopment"),
    "sga":     ("Selling General And Administration", "SellingGeneralAndAdministration"),
    "opex":    ("Operating Expense", "OperatingExpense", "Total Operating Expenses"),
    "pretax":  ("Pretax Income", "PretaxIncome", "Income Before Tax"),
    "cogs_only": ("Cost Of Revenue", "CostOfRevenue", "Reconciled Cost Of Revenue"),
}


def _sk_unit(max_millions):
    """(divisor, suffix) for a statement whose largest line is `max_millions` millions.

    Chosen from the LARGEST value in the statement, not per node, for two reasons: a diagram
    mixing "109,417M" against "$2.4B" is unreadable, and scaling each node independently
    would print a $15M tax line as "0.0B" beside a "$109.4B" revenue. One unit per diagram
    keeps the flows visually comparable, which is the whole point of a Sankey.
    """
    m = abs(float(max_millions or 0))
    if m >= 1_000_000:
        return 1_000_000.0, "T"
    if m >= 1_000:
        return 1_000.0, "B"
    if m < 1:
        return 0.001, "K"
    return 1.0, "M"


def _sk_money(v, unit="M", cur="$", div=1.0):
    """Money at the statement's chosen unit. Sub-unit values keep one decimal so a small line
    does not collapse to $0B next to a large one."""
    x = float(v) / (div or 1.0)
    if unit in ("B", "T"):
        # A tax line of 15M against 1.9B of revenue rounds to "$0.0B", which reads as zero
        # and is worse than useless on a diagram about where the money went. Small values
        # keep enough precision to stay a number.
        if abs(x) < 0.1:
            return f"{cur}{x:,.2f}{unit}"
        if abs(x) < 100:
            return f"{cur}{x:,.1f}{unit}"
    return f"{cur}{x:,.0f}{unit}"


def _sk_label(name, value, yoy, unit="M", cur="$", div=1.0):
    """Node label: name, amount, and the year-over-year move beneath it. The level says how
    big the business is; the change says what is happening to it."""
    out = f"<b>{name}</b><br>{_sk_money(value, unit, cur, div)}"
    if yoy is not None:
        out += (f"<br><span style='font-size:11px'>"
                f"{'▲' if yoy >= 0 else '▼'} {yoy:+.0f}% Y/Y</span>")
    return out


# Exchange suffixes that legitimately follow a dot. Anything else after a dot is a SHARE
# CLASS, which Yahoo writes with a hyphen -- BRK.B is BRK-B there, and asking for the dotted
# form returns no statement at all. RELIANCE.NS and BP.L must NOT be touched, which is why
# this is a known-suffix list rather than a blanket dot-to-hyphen swap.
_YF_EXCH_SUFFIX = {
    "NS", "BO", "L", "T", "TO", "V", "AX", "DE", "F", "PA", "AS", "BR", "MI", "MC",
    "LS", "VI", "ST", "OL", "CO", "HE", "IC", "SW", "HK", "SS", "SZ", "KS", "KQ",
    "TW", "TWO", "SI", "JK", "BK", "NZ", "SA", "MX", "BA", "IL", "TA", "IS", "WA",
    "PR", "AT", "CR", "JO", "QA", "SR", "AE", "KL",
}


def _yf_symbol(ticker):
    """Yahoo's spelling of a symbol. BRK.B -> BRK-B, RELIANCE.NS -> unchanged."""
    tk = str(ticker or "").upper().strip()
    if "." in tk:
        head, _, tail = tk.rpartition(".")
        if head and tail not in _YF_EXCH_SUFFIX:
            return f"{head}-{tail}"
    return tk


_SEC_UA = {"User-Agent": "srinivas.analystsas@gmail.com options-research"}
_SEC_CIK_CACHE = {}


def _sec_cik(ticker):
    """SEC CIK for a ticker, or None. The map is ~10k entries, fetched once per process."""
    global _SEC_CIK_CACHE
    tk = str(ticker or "").upper().strip().replace(".", "-")
    if not _SEC_CIK_CACHE:
        try:
            import urllib.request as _u, json as _j
            d = _j.loads(_u.urlopen(_u.Request(
                "https://www.sec.gov/files/company_tickers.json",
                headers=_SEC_UA), timeout=25).read())
            _SEC_CIK_CACHE = {v["ticker"].upper(): str(v["cik_str"]).zfill(10)
                              for v in d.values()}
        except Exception:
            log.debug("SEC ticker map fetch failed", exc_info=True)
            _SEC_CIK_CACHE = {"__failed__": ""}
    return _SEC_CIK_CACHE.get(tk)


def _revenue_segments(ticker, quarterly=True, unit_div=1e6, total=None,
                      basis="geography", attempt=0):
    """{segment: revenue} from the company's own filing, or {} — NEVER raises.

    SEC renders every filing's segment tables as plain HTML (the "R" reports listed in
    FilingSummary.xml), so this needs no PDF parsing and no raw XBRL: the disaggregation
    table SEC has already built is read directly. Verified against PLTR's 2026-08-04 10-Q,
    which yields United States 1,573,047 and Rest of world 362,417 against a 1,935,464 total.

    RETURNS {} ON ANY FAILURE, BY DESIGN. The caller falls back to a single revenue node —
    exactly the behaviour before this existed — so a missing filing, a renamed report or a
    non-US issuer costs nothing. EDGAR is US-only, so Indian and other foreign listings will
    always land here.
    """
    try:
        import urllib.request as _u, json as _j, re as _re
        cik = _sec_cik(ticker)
        if not cik:
            return {}
        subs = _j.loads(_u.urlopen(_u.Request(
            f"https://data.sec.gov/submissions/CIK{cik}.json",
            headers=_SEC_UA), timeout=25).read())
        rec = subs.get("filings", {}).get("recent", {})
        forms = rec.get("form", [])
        # PREFERENCE, NOT MEMBERSHIP. This read `f in want`, which is a SET test: the tuple
        # order meant nothing and the newest filing of EITHER form won. So a company that had
        # just filed its 10-K handed back ANNUAL segments while the caller reconciled them
        # against a QUARTERLY revenue total -- MSFT's geography split sums to its full-year
        # 331,839 against a ~76,000 quarter, so the check correctly rejected a correctly-read
        # table, every quarter, forever. Walk the preferences IN ORDER and take the newest
        # filing OF THAT FORM (ID 361).
        want = ("10-Q", "10-K") if quarterly else ("10-K", "10-Q")
        idx = None
        for _wf in want:
            idx = next((i for i, f in enumerate(forms) if f == _wf), None)
            if idx is not None:
                break
        if idx is None:
            return {}
        acc = rec["accessionNumber"][idx].replace("-", "")
        base = f"https://www.sec.gov/Archives/edgar/data/{int(cik)}/{acc}"
        fs = _u.urlopen(_u.Request(f"{base}/FilingSummary.xml",
                                   headers=_SEC_UA), timeout=25).read().decode("utf-8", "ignore")
        # Prefer a geography/disaggregation report; segment tables carry profit lines too and
        # are messier to read as a pure revenue split.
        best, cands, fallback = None, [], []
        for rep in _re.findall(r"<Report[^>]*>.*?</Report>", fs, _re.S):
            nm = _re.search(r"<ShortName>(.*?)</ShortName>", rep, _re.S)
            fn = _re.search(r"<HtmlFileName>(.*?)</HtmlFileName>", rep, _re.S)
            if not nm or not fn:
                continue
            name = nm.group(1)
            # Names vary a lot by filer: PLTR "Summary of Revenue by Geography", AAPL
            # "Revenue - Disaggregated Net Sales", XOM "Schedule of Geographic Sales".
            # Prefer a details table; the "(Tables)" variants are empty templates.
            if _re.search(r"\(tables\)", name, _re.I):
                continue
            # Two DIFFERENT disaggregations live in the same filing and answer different
            # questions: geography (where customers are) and operating segment (who they
            # are -- government vs commercial). The caller picks.
            # Matching stays PER BASIS -- the two axes are told apart by name and nothing
            # else, so a single heuristic across both collapses them (tried, reverted: it
            # made geography and customer-type return identical rows). What changes is that
            # matches are COLLECTED rather than taken first-and-break, so the caller can ask
            # for the next candidate within the same axis when the first lacks sub-lines.
            # SELECT BY CONTENT, NOT BY TITLE. Every filer names this table differently, so
            # each title pattern was a guess -- and matching only 30% of a 20-name sample is
            # what that guessing actually bought. The net is now cast WIDE by title (a cheap
            # filter) and the decision is made by RECONCILIATION downstream: the right table
            # is the one whose members sum to total revenue, which is a property of the data
            # rather than of the wording. Candidates stay ordered best-guess-first so the
            # usual case still resolves on the first try.
            if not _re.search(r"\(detail", name, _re.I):
                continue                                   # narrative blocks carry no data
            if basis == "segment":
                if _re.search(r"financial information for each reportable segment|"
                              r"segment.*(revenue|financial info)|revenue by segment",
                              name, _re.I):
                    cands.append(fn.group(1))
                elif _re.search(r"segment|business unit|reportable", name, _re.I):
                    fallback.append(fn.group(1))
            else:
                # A TRUE geography match always beats the segment-shaped fallback, whatever
                # order they appear in the filing. Collecting both into one list lost that
                # precedence and handed Alphabet's geography slot to its segment table,
                # because "Revenue by Segment" happens to be filed first.
                if _re.search(r"disaggregat|revenue by geograph|geographic (sales|revenue)",
                              name, _re.I):
                    cands.append(fn.group(1))
                elif _re.search(r"segment.*(revenue|sales)|(revenue|sales).*segment|"
                                r"geograph|by (product|region|market)|revenue.*(product|line)",
                                name, _re.I):
                    fallback.append(fn.group(1))
        # The Nth match within THIS basis. attempt=0 reproduces the old
        # first-match behaviour; the caller raises it only when the chosen
        # table turned out to carry no sub-lines.
        cands = cands or fallback          # geography wins; segment-shaped is last resort
        best = cands[attempt] if attempt < len(cands) else None
        if not best:
            return {}
        html = _u.urlopen(_u.Request(f"{base}/{best}", headers=_SEC_UA), timeout=25).read()
        tbl = pd.read_html(io.BytesIO(html))[0]
        header = " ".join(str(c) for c in tbl.columns)
        tbl.columns = [str(i) for i in range(tbl.shape[1])]

        # THE TABLE STATES ITS OWN SCALE and filers disagree: PLTR reports "$ in Thousands",
        # AAPL "$ in Millions". Reading it is not optional -- assuming one would put every
        # Apple segment out by a factor of a thousand.
        scale = 1.0
        if _re.search(r"in\s+thousands", header, _re.I):
            scale = 1e3
        elif _re.search(r"in\s+millions", header, _re.I):
            scale = 1e6
        elif _re.search(r"in\s+billions", header, _re.I):
            scale = 1e9

        # Two row shapes in the wild, sharing one rule: a LABEL row carrying no value names
        # the segment, and the next revenue row holds its money.
        #   PLTR: "United States | Geographic Concentration Risk"  then  "Revenue  $1,573,047"
        #   AAPL: "iPhone"                                          then  "Net sales  54,252"
        # Boilerplate line-item headers and percentage "Benchmark" rows are not segments.
        _BOILER = _re.compile(r"line items|\[|benchmark|abstract|^total$|^revenues?$|"
                              r"^net sales$|percentage|portion of|flag$", _re.I)
        # Axis labels are the DIMENSION, never the member: they name how the business is cut,
        # not a piece of it.
        _AXIS = _re.compile(r"^(operating|reportable)? ?segments?$|concentration risk|"
                            r"revenue benchmark|axis$|\[member\]", _re.I)
        # The VALUE row is labelled differently by every filer: "Revenue" (PLTR),
        # "Net revenue" (V), "Revenue from contract with customers" (GOOGL). Matching only
        # the first three meant Alphabet extracted nothing at all while its table sat there
        # fully populated.
        _MONEY = _re.compile(
            r"^(net |total |operating )*(revenues?|sales)"
            r"( from contract(s)? with customers)?$", _re.I)
        # THE MONEY IS NOT ALWAYS IN COLUMN 1. Filers interleave a footnote-marker column:
        # Microsoft's geography table is 5 columns wide and column 1 holds "[1]" or nothing,
        # with the figures starting at column 2. Reading a FIXED column returned nothing at
        # all for every such filer while the table sat there fully populated -- MSFT, XOM,
        # JNJ, CVX and PFE all file the split and all came back empty (ID 361).
        # Scanning also has to REJECT the footnote marker rather than parse it: "[1]" contains
        # a digit, so the old bare \d test reads it as money and yields a revenue of 1.
        _NUM = _re.compile(r"^\(?-?[\d,]+(\.\d+)?\)?$")

        def _money_cells(row):
            """Every real number in the row, left to right. First = current period."""
            vals = []
            for _ci in range(1, tbl.shape[1]):
                _cv = str(row[str(_ci)]).strip()
                if not _cv or _cv.lower() == "nan":
                    continue
                _cv = _cv.replace("$", "").replace(" ", "").replace(" ", "")
                if not _NUM.match(_cv):
                    continue                      # footnote marker, date, or stray text
                try:
                    _v = float(_re.sub(r"[^\d.]", "", _cv))
                except ValueError:
                    continue
                vals.append(-_v if _cv.startswith("(") else _v)
            return vals

        out, cur, cur_parent = {}, None, None
        for _, r in tbl.iterrows():
            lab = str(r["0"]).strip()
            cells = _money_cells(r)
            has_val = bool(cells)
            if not lab or lab.lower() == "nan":
                continue
            if _MONEY.match(lab) and has_val:
                if cur:                                   # belongs to the segment above it
                    now = cells[0] * scale / unit_div
                    # The PRIOR-PERIOD column sits right beside it, so per-segment growth
                    # costs no extra request -- and "which part is growing" is the whole
                    # question a single consolidated number cannot answer.
                    prior = (cells[1] * scale / unit_div) if len(cells) > 1 else None
                    out[cur] = {"now": now, "prior": prior, "parent": cur_parent}
                    cur = cur_parent = None
                continue                                  # a bare total, no segment -> skip
            if not has_val and not _BOILER.search(lab):
                # The name sits on EITHER side of the pipe depending on the report:
                #   "United States | Geographic Concentration Risk"  -> name first
                #   "Operating Segments | Government"                -> name LAST
                # Taking [0] blindly collapsed Government and Commercial into one bucket
                # called "Operating Segments". Drop the axis parts and keep what remains.
                parts = [q.strip() for q in lab.split("|") if q.strip()]
                keep = [q for q in parts if not _AXIS.search(q)]
                # NESTING. Two surviving parts mean "child | parent": Alphabet files
                # "Google Search & other | Google Services" as a CHILD of the segment
                # "Google Services". Taking keep[0] alone flattened the tree and made the
                # child a sibling of its own parent, which is why a second level never
                # appeared. Order is child-first in every filing seen.
                cur = keep[0] if keep else None
                cur_parent = keep[1] if len(keep) > 1 else None
        # A TOTAL ROW OFTEN LOOKS LIKE A SEGMENT. PLTR's axis label "Geographic
        # Concentration Risk" and XOM's "Sales and other operating revenue" both carry the
        # consolidated figure, so taking them at face value double-counted the business:
        # PLTR summed to 3,871M against a real 1,935M. Drop any entry that equals the sum of
        # the others -- that is arithmetically a total, whatever it is called.
        # Match against the KNOWN revenue, not against "the sum of the others". That earlier
        # test dropped iPhone from Apple's split, because iPhone is coincidentally about half
        # of total revenue and so looked like a total. A real total equals the revenue line;
        # a large segment merely resembles the rest of the business.
        if total:
            for k in [k for k, v in out.items()
                      if v["now"] > 0 and abs(v["now"] - total) / total < 0.02]:
                out.pop(k)
        # Reconcile against the statement's own revenue when the caller supplied it: a split
        # that does not add up is worse than no split, because it looks authoritative.
        # ONE AXIS ONLY. A single table often stacks several disaggregations: Visa lists
        # geography (U.S. + International), THEN product (Service, Data processing, ...),
        # THEN the contra-revenue line Client incentives. Each axis reconciles to revenue on
        # its own, but taking every row together double-counts -- Visa summed to 32,626
        # against real revenue of 11,633, so the check below threw away a perfectly good
        # geography split. Walk the rows IN ORDER and keep the first contiguous run that
        # reconciles; that is the first complete axis in the table.
        # Children never take part in the top-level reconciliation: they are already counted
        # inside their parent, so leaving them in doubles the sum and the axis check throws
        # away a perfectly good split (the same trap Visa's stacked axes sprang).
        kids = {k: v for k, v in out.items() if v.get("parent")}
        out = {k: v for k, v in out.items() if not v.get("parent")}
        if total and len(out) > 2:
            # Pick the run that lands CLOSEST to the total, not the first one merely within
            # tolerance. Alphabet files Google Services 94,540 + Google Cloud 24,768 =
            # 119,308, which is 0.41% off 119,796 and passed -- so the search stopped there
            # and discarded Other Bets at 382, even though including it gives 119,690 and
            # 0.09%. A first-match rule silently drops the smallest segment of ANY company
            # whose largest two already sum near the total; it was never Alphabet-specific.
            items = list(out.items())
            best_run, best_gap = None, None
            for start in range(len(items)):
                run = 0.0
                for end in range(start, len(items)):
                    run += items[end][1]["now"]
                    if end == start:
                        continue
                    gap = abs(run - total) / total
                    if gap < 0.02 and (best_gap is None or gap < best_gap):
                        best_run, best_gap = (start, end), gap
            if best_run:
                out = dict(items[best_run[0]:best_run[1] + 1])
        if total and out:
            gap = abs(sum(v["now"] for v in out.values()) - total) / total
            if gap > 0.05:
                log.debug("segments for %s miss the total by %.1f%% — discarding",
                          ticker, gap * 100)
                return {}
        # Attach each child to its parent, dropping SUBTOTAL rows. Alphabet files
        # "Google advertising" as a child of Google Services worth exactly
        # Search + YouTube + Network, so rendering it beside its own components would
        # double the level and read as a data error. A child whose value equals the sum
        # of its siblings is therefore a subtotal, not a peer.
        for _pname, _pv in out.items():
            _mine = {k: v for k, v in kids.items() if v.get("parent") == _pname}
            if not _mine:
                continue
            # The flat "child | parent" labels collapse what is really THREE levels:
            # Alphabet reports Google advertising 81,629 AND its own components (Search
            # 63,271, YouTube 11,055, Network 7,303) as siblings under Google Services.
            # Two different subsets each reconcile to the parent -- {advertising,
            # subscriptions} and {Search, YouTube, Network, subscriptions} -- so pick the
            # one with the MOST members, which is the finest real breakdown, and treat
            # everything outside it as a subtotal already counted.
            _kept = _mine
            if len(_mine) <= 10 and _pv["now"] > 0:
                import itertools as _it
                _ks = list(_mine)
                _best = None
                for _n in range(len(_ks), 1, -1):
                    for _combo in _it.combinations(_ks, _n):
                        _sum = sum(_mine[k]["now"] for k in _combo)
                        if abs(_sum - _pv["now"]) / _pv["now"] < 0.01:
                            _best = _combo
                            break
                    if _best:
                        break                      # largest cardinality wins
                if _best:
                    _kept = {k: _mine[k] for k in _best}
            if _kept:
                _pv["children"] = _kept
        return out if len(out) >= 2 else {}
    except Exception:
        log.debug("revenue segment lookup failed for %s", ticker, exc_info=True)
        return {}


_FLOW_INDEXY = {"SPY", "QQQ", "IWM", "DIA", "VIX", "SPX", "NDX", "RUT", "VXX", "UVXY",
                "TLT", "HYG", "EEM", "EFA", "GLD", "SLV", "XLF", "XLE", "XLK", "SMH"}


def _options_activity(conn, ma=5):
    """5-day average call / put contract volume and the call-to-put ratio (ID 383).

    SCOPE, because it decides what this number can be compared against. This sums OUR
    captured universe -- about 730 optionable US names -- not the whole listed market. The
    LEVEL is therefore ours and will not match a published figure built from OCC totals
    across every symbol. The RATIO is scale-invariant and does travel: measured 1.26 on
    2026-09-01 against a published 1.25 for the same week, which is the agreement you would
    expect from two different samples of the same market.

    NO PERCENTILE. The obvious next line is "higher than X% of history", and the honest
    answer is that we cannot say: capture starts 2026-07-02, so the entire series is a few
    dozen sessions. A percentile computed over that and printed without its window reads
    exactly like a multi-year one, which is how a short sample gets laundered into
    authority. Direction over a month is what this length of history supports.

    Returns {} when there is not enough history to average.
    """
    try:
        df = pd.read_sql(
            "SELECT trade_date d, SUM(vol_Call) c, SUM(vol_Put) p, "
            "COUNT(DISTINCT ticker) n FROM options_openbb "
            "GROUP BY trade_date ORDER BY trade_date", conn)
    except Exception:
        return {}
    if df is None or len(df) < ma:
        return {}
    df = df.dropna(subset=["c", "p"])
    if len(df) < ma:
        return {}
    cur_c = float(df["c"].tail(ma).mean())
    cur_p = float(df["p"].tail(ma).mean())
    if cur_p <= 0:
        return {}
    out = {"date": str(df["d"].iloc[-1]), "days": len(df), "tickers": int(df["n"].iloc[-1]),
           "call": cur_c, "put": cur_p,
           # Ratio of the AVERAGES, not the average of daily ratios: the latter lets a thin
           # session count as much as a heavy one.
           "ratio": float(df["c"].tail(ma).sum() / df["p"].tail(ma).sum()),
           "start": str(df["d"].iloc[0])}
    # Change against the same average a month of sessions back, when we have that much.
    back = 21
    if len(df) >= ma + back:
        prev_c = float(df["c"].iloc[-(ma + back):-back].mean())
        prev_p = float(df["p"].iloc[-(ma + back):-back].mean())
        if prev_c > 0 and prev_p > 0:
            out["call_chg"] = (cur_c / prev_c - 1) * 100
            out["put_chg"] = (cur_p / prev_p - 1) * 100
            out["ratio_prev"] = float(df["c"].iloc[-(ma + back):-back].sum()
                                      / df["p"].iloc[-(ma + back):-back].sum())
    return out


def _fmt_activity(conn, ma=5):
    """One block on market-wide option activity, or '' when history is too short."""
    a = _options_activity(conn, ma=ma)
    if not a:
        return ""
    lines = [f"📊 <b>Option activity</b> — {ma}-day average to {a['date']}",
             f"Calls <b>{a['call'] / 1e6:.1f}M</b> · Puts <b>{a['put'] / 1e6:.1f}M</b> · "
             f"call/put <b>{a['ratio']:.2f}</b>"]
    if "call_chg" in a:
        lines.append(f"vs a month ago: calls {a['call_chg']:+.0f}%, puts {a['put_chg']:+.0f}%, "
                     f"ratio {a['ratio_prev']:.2f} → {a['ratio']:.2f}")
    lines.append(f"<i>Contracts across our {a['tickers']} captured names, not the whole listed "
                 f"market — the LEVEL is ours and will not match an OCC-based figure. The "
                 f"RATIO is scale-free and does compare. No percentile: capture starts "
                 f"{a['start']} ({a['days']} sessions), too short to rank against.</i>")
    return "\n".join(lines)


def _flow_board(conn, trade_date=None, top=10, min_premium=1e6):
    """Premium leaderboards by ticker: where the option money actually went.

    WHAT THIS IS NOT. Services like Cheddar Flow rank by ORDER COUNT and split bullish from
    bearish by whether a trade hit the ask or the bid. Both need time-and-sales with the
    aggressor side. We capture chain SNAPSHOTS, so we have contracts traded and a price --
    never an order count and never who initiated. Printing an "orders" column would be
    invention, so this reports premium and contracts, which are real.

    RANKED ON NET, NOT GROSS, and that matters more than it sounds. On 2026-08-28 SPY put
    premium was $1,005M against $396M of calls -- that is structural index hedging, not
    bearish conviction, and a gross put board is topped by the same hedges every single day.
    Netting the two sides cancels the standing hedge and leaves the day's tilt. Index and
    sector ETFs are still flagged, because even their NET is mostly someone buying insurance.

    Premium uses the mid where a two-sided quote exists, falling back to last traded.
    """
    day = trade_date or conn.execute(
        "SELECT MAX(trade_date) FROM options_openbb").fetchone()[0]
    if not day:
        return {"date": None, "bullish": [], "bearish": []}
    rows = conn.execute("""
        SELECT ticker,
               SUM(vol_Call * COALESCE(NULLIF((bid_Call+ask_Call)/2.0,0), lastPrice_Call) * 100),
               SUM(vol_Put  * COALESCE(NULLIF((bid_Put +ask_Put )/2.0,0), lastPrice_Put ) * 100),
               SUM(COALESCE(vol_Call,0)), SUM(COALESCE(vol_Put,0))
        FROM options_openbb WHERE trade_date=?
        GROUP BY ticker""", (day,)).fetchall()
    out = []
    for tk, cprem, pprem, cvol, pvol in rows:
        cprem, pprem = float(cprem or 0), float(pprem or 0)
        if cprem + pprem < min_premium:
            continue
        out.append({"ticker": tk, "call_prem": cprem, "put_prem": pprem,
                    "net": cprem - pprem, "call_vol": float(cvol or 0),
                    "put_vol": float(pvol or 0), "total": cprem + pprem,
                    "index": tk in _FLOW_INDEXY,
                    "skew": (cprem / pprem) if pprem > 0 else None})
    bull = sorted([r for r in out if r["net"] > 0], key=lambda r: -r["net"])[:top]
    bear = sorted([r for r in out if r["net"] < 0], key=lambda r: r["net"])[:top]
    return {"date": day, "bullish": bull, "bearish": bear}


def _fmt_flow_board(conn, top=8):
    """Telegram body for the flow boards. Two tables, framed for what they are."""
    b = _flow_board(conn, top=top)
    if not b["bullish"] and not b["bearish"]:
        return None

    def _tbl(rows, title, net_key):
        body = []
        for r in rows:
            mark = "🏛" if r["index"] else ("🟢" if net_key > 0 else "🔴")
            # No sign: the table title already states the direction, and "+659M" on a
            # PUT-leading board reads as bullish at a glance.
            body.append((mark, r["ticker"][:6],
                         _compact_money(abs(r["net"])).lstrip("+"),
                         _compact_money(r["total"]).lstrip("+")))
        return _pipe_table(("", "Ticker", "Net", "Total"), body, right_cols={2, 3},
                           title=title)

    parts = [hdr(f"💸 OPTION FLOW · {b['date']}")]
    if b["bullish"]:
        parts.append(_tbl(b["bullish"], "📈 Call premium leading", 1))
    if b["bearish"]:
        parts.append(_tbl(b["bearish"], "📉 Put premium leading", -1))
    det = []
    for r in (b["bullish"][:3] + b["bearish"][:3]):
        det.append(f"<b>{r['ticker']}</b> calls {_compact_money(r['call_prem'])} vs puts "
                   f"{_compact_money(r['put_prem'])} · {r['call_vol']+r['put_vol']:,.0f} contracts"
                   + (" · 🏛 index/sector — its put demand is largely hedging, not a view"
                      if r["index"] else ""))
    parts.append("\n".join(det))
    # When the put board is mostly index and sector names, the day is a HEDGING day, not a
    # bearish one -- saying so is the difference between a flow board and a misleading one.
    _idx = sum(1 for r in b["bearish"] if r["index"])
    if b["bearish"] and _idx >= max(2, len(b["bearish"]) // 2):
        parts.append(f"<i>⚠️ {_idx} of {len(b['bearish'])} names on the put board are "
                     f"index or sector ETFs. That is portfolio insurance being bought, not "
                     f"a directional view — read it as a hedging day, not a bearish one.</i>")
    parts.append("<i>Premium = contracts × mid × 100, netted call-minus-put so a standing "
                 "hedge does not top the board every day. NOT order counts and NOT "
                 "ask-vs-bid — a chain snapshot cannot see who initiated a trade. "
                 "Descriptive only: the UOA family scored 47% over 204 fires, a coin flip.</i>")
    return "\n\n".join(parts)


def _valuation_inputs(ticker):
    """Everything a DCF needs, pulled once. Returns a dict, or raises with a plain reason.

    Kept separate from the model so the ASSUMPTIONS and the FACTS never get muddled: this
    function reports only what the company filed and what the market currently pays, and the
    caller supplies every forward-looking judgement.
    """
    import yfinance as _yf
    t = _yf.Ticker(ticker)
    info = t.info or {}
    cf = t.cashflow
    if cf is None or cf.empty:
        raise ValueError(f"{ticker}: no cash-flow statement filed")

    def _row(name):
        try:
            s = cf.loc[name].dropna()
            return [float(x) for x in s.values], [str(c)[:10] for c in s.index]
        except Exception:
            return [], []

    fcf, yrs = _row("Free Cash Flow")
    if not fcf:
        ocf, yrs = _row("Operating Cash Flow")
        capex, _ = _row("Capital Expenditure")
        if ocf and capex:
            # capex is filed NEGATIVE, so this adds a negative -- do not subtract twice.
            fcf = [o + c for o, c in zip(ocf, capex)]
    if not fcf:
        raise ValueError(f"{ticker}: cannot derive free cash flow")

    shares = info.get("sharesOutstanding") or 0
    if not shares:
        raise ValueError(f"{ticker}: share count unavailable")
    price = info.get("currentPrice") or info.get("regularMarketPrice") or 0
    if not price:
        try:
            price = float(t.fast_info.get("lastPrice") or 0)
        except Exception:
            price = 0.0
    return {
        "ticker": ticker.upper(),
        "name": info.get("longName") or info.get("shortName") or ticker.upper(),
        "fcf": fcf, "fcf_years": yrs,
        "fcf_latest": fcf[0],
        # A single year can be distorted by one large working-capital swing or a legal
        # settlement, so the model offers a 3-year mean as the alternative base.
        "fcf_avg3": sum(fcf[:3]) / len(fcf[:3]),
        "shares": float(shares),
        "price": float(price),
        "market_cap": float(info.get("marketCap") or price * shares),
        "debt": float(info.get("totalDebt") or 0),
        "cash": float(info.get("totalCash") or 0),
        "beta": float(info.get("beta") or 1.0),
        "trailing_pe": info.get("trailingPE"),
        "forward_pe": info.get("forwardPE"),
        "eps_fwd": info.get("forwardEps"),
        "ebitda": float(info.get("ebitda") or 0),
        "ev": float(info.get("enterpriseValue") or 0),
        "sector": info.get("sector") or "—",
        # WHEN this valuation was last able to change, and when it next will. A DCF does not
        # drift day to day -- it steps when a new cash-flow statement lands, so a fair value
        # with no filing date attached hides how stale it might be (user asked directly how
        # often these change: roughly quarterly, on the filing).
        "as_of": (yrs[0] if yrs else None),
        "next_earnings": _next_earnings_date(t),
    }


def _next_earnings_date(t):
    """Next scheduled results date, or None. That is when the fair value can next move."""
    try:
        cal = t.calendar
        d = cal.get("Earnings Date") if isinstance(cal, dict) else None
        if isinstance(d, (list, tuple)) and d:
            d = d[0]
        return str(d)[:10] if d else None
    except Exception:
        return None


def _wacc(inp, rf=0.042, erp=0.05, cost_debt=0.05, tax=0.21):
    """CAPM cost of equity, blended with after-tax debt at market weights.

    Defaults are deliberately conservative and stated rather than hidden: a 10-year around
    4.2% and a 5% equity risk premium. WACC is the single most violent input in a DCF -- a
    point either way moves fair value by tens of percent -- which is why the page shows a
    sensitivity grid instead of one number.
    """
    e = max(inp["market_cap"], 1.0)
    d = max(inp["debt"], 0.0)
    v = e + d
    re = rf + inp["beta"] * erp
    return (e / v) * re + (d / v) * cost_debt * (1 - tax)


def _dcf(inp, growth, years=5, fade_to=0.025, wacc=None, terminal_growth=0.025,
         exit_multiple=None, base="latest"):
    """Project free cash flow, discount it, and add a terminal value.

    `growth` is year-one growth; it FADES linearly to `fade_to` by the final year, because a
    company compounding at 15% for five straight years and then stopping abruptly is not a
    forecast anyone believes. Terminal value is Gordon growth unless `exit_multiple` is given.

    Returns the components, never just an answer -- the split between explicit-period value
    and terminal value is the honest health warning: when terminal is 80% of the total, the
    valuation is a statement about the far future, not about the next five years.
    """
    w = wacc if wacc is not None else _wacc(inp)
    f0 = inp["fcf_avg3"] if base == "avg3" else inp["fcf_latest"]
    if w <= terminal_growth:
        # Gordon growth explodes (or flips sign) when the discount rate does not exceed the
        # perpetual growth rate. Refuse rather than print a confident absurdity.
        raise ValueError(f"WACC {w:.1%} must exceed terminal growth {terminal_growth:.1%}")
    flows, pv_sum, f = [], 0.0, f0
    for i in range(1, years + 1):
        g = growth + (fade_to - growth) * (i - 1) / max(years - 1, 1)
        f = f * (1 + g)
        pv = f / ((1 + w) ** i)
        pv_sum += pv
        flows.append({"year": i, "growth": g, "fcf": f, "pv": pv})
    if exit_multiple:
        tv = f * exit_multiple
    else:
        tv = f * (1 + terminal_growth) / (w - terminal_growth)
    pv_tv = tv / ((1 + w) ** years)
    ev = pv_sum + pv_tv
    equity = ev - inp["debt"] + inp["cash"]
    per_share = equity / inp["shares"]
    return {
        "wacc": w, "flows": flows, "pv_explicit": pv_sum, "terminal_value": tv,
        "pv_terminal": pv_tv, "terminal_pct": (pv_tv / ev * 100) if ev else 0,
        "enterprise_value": ev, "equity_value": equity, "per_share": per_share,
        "upside": ((per_share / inp["price"] - 1) * 100) if inp["price"] else None,
        "base_fcf": f0,
    }


def _reverse_dcf(inp, lo=-0.30, hi=1.50, tol=0.005, **kw):
    """The growth rate the CURRENT PRICE implies. Returns None if no rate explains it.

    This is the honest way round for a company the forward model calls wildly overvalued.
    Instead of asserting Apple is worth $105 against a $320 price -- which mostly says the
    assumptions were mine -- it asks what the market must believe, and lets the reader judge
    THAT. It is the standard practitioner answer (a "reverse" or "inverse" DCF) precisely
    because it needs no forecast: the price supplies it.

    Bisection on year-one growth. Monotonic in growth, so bisection is safe and exact enough.
    """
    px = inp.get("price") or 0
    if px <= 0:
        return None
    def _v(g):
        try:
            return _dcf(inp, g, **kw)["per_share"]
        except Exception:
            return None
    v_lo, v_hi = _v(lo), _v(hi)
    if v_lo is None or v_hi is None or not (v_lo <= px <= v_hi):
        return None                       # the price is outside anything this model can reach
    for _ in range(60):
        mid = (lo + hi) / 2
        v = _v(mid)
        if v is None:
            return None
        if abs(v - px) / px < tol:
            return mid
        if v < px:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2


_FV_CACHE = {}                      # ticker -> (expires_at, value or None)
_FV_TTL = 6 * 3600


def _fair_value(ticker, growth=0.06):
    """Base-case DCF value per share, or None. Six-hour in-process cache.

    THE ENGINE OWNS THIS. The dashboard had its own copy of these refusal rules behind an
    st.cache_data wrapper; two copies of a rule about when a valuation is meaningless is
    exactly the arrangement that lets the two surfaces disagree about whether a number
    should be shown at all. The dashboard now calls this and keeps only its cache.

    The cache is what makes it usable from Telegram: a DCF is one to two seconds of yfinance
    per ticker, so a six-leg book would add ten seconds to every /paper without it. Fair
    value moves with the last FILING and barely changes between them, so six hours is
    generous rather than stale.

    Returns None rather than a number whenever the model does not describe the business:
      * non-positive free cash flow -- a DCF fed negative cash produces a figure with no
        meaning and full authority, which is worse than a blank (Bloom Energy came back at
        +28,580%, Amazon at MINUS $2.47)
      * a gap beyond roughly 10x either way, which says the model is wrong about this
        company rather than that the market is wrong by 28,000%
    """
    tk = str(ticker or "").upper()
    if not tk:
        return None
    hit = _FV_CACHE.get(tk)
    if hit and hit[0] > time.time():
        return hit[1]
    val = None
    try:
        inp = _valuation_inputs(tk)
        if inp["fcf_latest"] > 0 and inp["fcf_avg3"] > 0:
            fv = float(_dcf(inp, growth)["per_share"])
            px = inp.get("price") or 0
            if fv > 0 and (not px or 0.1 <= px / fv <= 10):
                val = fv
    except Exception:
        val = None
    _FV_CACHE[tk] = (time.time() + _FV_TTL, val)
    return val


def _price_requires(inp, growth, tol=0.004, **kw):
    """What each assumption must become, ON ITS OWN, to justify today's price.

    The natural chart for "why does the market pay $325 when the cash says $105" is a
    waterfall splitting the gap into growth, discount rate and multiple. That chart would
    be a LIE, and it is worth saying why: those levers are SUBSTITUTES, not components.
    Raising growth and lowering WACC each close the whole gap by themselves, so any split
    between them sums to far more than the gap and the "contribution" of each depends
    entirely on the order you apply them. The residual bar would be doing the real work.

    So this answers the honest version instead: hold everything else at base and solve
    each lever separately for the value that reproduces the price. The output is a set of
    ALTERNATIVES -- believe any one of these and the price is fair -- never an addition.

    Every level is SOLVED by bisection, never assumed. Each lever is monotonic in value
    (value rises with growth and terminal growth, falls with WACC), which is what makes
    bisection exact enough here. Returns [] when there is no price to explain, and drops
    any lever the model cannot reach -- an unreachable level is a real answer ("no discount
    rate explains this price") and is better shown as absent than as a clipped bound.
    """
    px = inp.get("price") or 0
    if px <= 0:
        return []
    try:
        base = _dcf(inp, growth, **kw)
    except Exception:
        return []
    base_w = base["wacc"]
    base_tg = kw.get("terminal_growth", 0.025)

    def _solve(fn, lo, hi, rising):
        """Bisect fn(x)->per_share for fn(x)==px. `rising` = value increases with x."""
        try:
            v_lo, v_hi = fn(lo), fn(hi)
        except Exception:
            return None
        if v_lo is None or v_hi is None:
            return None
        span = (v_lo, v_hi) if rising else (v_hi, v_lo)
        if not (span[0] <= px <= span[1]):
            return None                      # price is outside anything this lever can reach
        for _ in range(60):
            mid = (lo + hi) / 2
            v = fn(mid)
            if v is None:
                return None
            if abs(v - px) / px < tol:
                return mid
            if (v < px) == rising:
                lo = mid
            else:
                hi = mid
        return (lo + hi) / 2

    def _ps(**over):
        kw2 = dict(kw); kw2.update(over)
        try:
            return _dcf(inp, growth, **kw2)["per_share"]
        except Exception:
            return None

    out = []
    # Year-one growth. Reuse the existing solver so the page and /value cannot disagree.
    g_req = _reverse_dcf(inp, **kw)
    if g_req is not None:
        out.append({"lever": "Year-1 growth", "base": growth, "required": g_req,
                    "unit": "pct", "move": (g_req - growth) * 100})
    # Discount rate. Terminal growth is the floor: Gordon explodes as WACC approaches it.
    w_req = _solve(lambda w: _ps(wacc=w), base_tg + 0.005, 0.30, rising=False)
    if w_req is not None:
        out.append({"lever": "Discount rate (WACC)", "base": base_w, "required": w_req,
                    "unit": "pct", "move": (w_req - base_w) * 100})
    # Perpetual growth, capped below WACC for the same reason.
    tg_req = _solve(lambda g: _ps(terminal_growth=g), -0.02, base_w - 0.005, rising=True)
    if tg_req is not None:
        out.append({"lever": "Terminal growth", "base": base_tg, "required": tg_req,
                    "unit": "pct", "move": (tg_req - base_tg) * 100})
    return out


def _dcf_sensitivity(inp, growth, waccs, terminals, **kw):
    """Fair value across a WACC x terminal-growth grid.

    This exists because a single DCF number invites more confidence than the method can
    carry. Seeing the answer swing from one corner of the grid to the other is the point.
    """
    grid = []
    for w in waccs:
        row = []
        for g in terminals:
            try:
                row.append(_dcf(inp, growth, wacc=w, terminal_growth=g, **kw)["per_share"])
            except Exception:
                row.append(None)
        grid.append(row)
    return grid


def _multiples_value(inp, pe=None, ev_ebitda=None):
    """Valuation by multiple, as a cross-check on the DCF rather than a rival to it.

    A DCF says what the cash is worth; a multiple says what the market currently pays for
    comparable cash. When they disagree sharply, that gap IS the finding.
    """
    out = {}
    if pe and inp.get("eps_fwd"):
        out["pe"] = {"multiple": pe, "metric": inp["eps_fwd"],
                     "per_share": pe * inp["eps_fwd"]}
    if ev_ebitda and inp.get("ebitda"):
        ev = ev_ebitda * inp["ebitda"]
        out["ev_ebitda"] = {"multiple": ev_ebitda, "metric": inp["ebitda"],
                            "per_share": (ev - inp["debt"] + inp["cash"]) / inp["shares"]}
    for v in out.values():
        v["upside"] = ((v["per_share"] / inp["price"] - 1) * 100) if inp["price"] else None
    return out


def _income_stmt(ticker, quarterly=True, unit_div=1e6):
    """A company's income statement, shaped for the flow diagram.

    REPORTED SUBTOTALS WIN; RESIDUALS ARE DERIVED. A filing's gross profit and operating
    income are authoritative, but rounded to millions they rarely reconcile to the cent
    against the other lines -- so cost of revenue is taken as revenue minus gross profit, and
    other income as net plus tax minus operating income. The diagram then always balances AND
    every headline figure is the one the company actually reported, instead of a recomputed
    number that disagrees with their own press release.
    """
    sym = _yf_symbol(ticker)                      # BRK.B -> BRK-B; NSE suffixes untouched
    t = _yf_ticker(sym)
    df = t.quarterly_income_stmt if quarterly else t.income_stmt
    if (df is None or df.empty) and quarterly:
        # Plenty of issuers file only annually, or Yahoo carries no quarterly frame for them.
        # Falling back beats telling the user the company publishes nothing.
        df = t.income_stmt
        quarterly = False
    if df is None or df.empty:
        raise ValueError(f"no income statement published for {ticker}")

    def pick(key, col=0):
        for name in _SK_YF_ROWS[key]:
            if name in df.index:
                try:
                    v = float(df.loc[name].iloc[col])
                    if v == v:
                        return v / unit_div
                except Exception:
                    continue
        return None

    rev, net, tax = pick("revenue"), pick("net"), pick("tax") or 0.0
    if rev is None or net is None:
        raise ValueError(f"{ticker}: the filed statement has no revenue or net income line")
    # BANKS AND INSURERS DO NOT REPORT GROSS PROFIT OR OPERATING INCOME. Berkshire's statement
    # carries Total Revenue, Pretax Income, Tax and Net Income and nothing in between, so
    # demanding the standard chain refused a company that obviously files. Degrade instead:
    #   gross  -> reported, else revenue minus cost of revenue, else revenue (no cost breakout)
    #   opinc  -> reported, else pretax income, else net + tax
    # The picture stays truthful; it just has fewer stages for a business that reports fewer.
    gross = pick("gross")
    if gross is None:
        _cost = pick("cogs_only")
        gross = (rev - _cost) if _cost is not None else rev
    opinc = pick("opinc")
    if opinc is None:
        opinc = pick("pretax")
    if opinc is None:
        opinc = net + tax
    rnd, sga = pick("rnd"), pick("sga")
    opex = {}
    if sga:
        opex["SG&A"] = sga
    if rnd:
        opex["R&D"] = rnd
    residual = (gross - opinc) - sum(opex.values())
    if residual > 0.5:
        opex["Other opex"] = residual
    if not opex:
        opex["Costs & expenses"] = max(gross - opinc, 0.0)

    # Year-over-year against the SAME quarter a year ago (4 columns back). Comparing Q2 with
    # Q1 would read seasonality as growth.
    yoy, back = {}, (4 if quarterly else 1)
    if df.shape[1] > back:
        for key, lbl in (("revenue", "Total revenue"), ("gross", "Gross profit"),
                         ("opinc", "Operating income"), ("net", "Net income"),
                         ("tax", "Taxes"), ("rnd", "R&D"), ("sga", "SG&A")):
            now, then = pick(key), pick(key, back)
            if now is not None and then not in (None, 0):
                yoy[lbl] = (now / then - 1) * 100

    name = str(ticker).upper()
    try:
        name = (t.info or {}).get("shortName") or name
    except Exception:
        pass
    period = str(df.columns[0])[:10]
    # Where the business actually comes from. Best-effort and never fatal: no filing, a
    # foreign issuer or an unparseable table simply leaves this empty and the diagram shows
    # one revenue node, exactly as before.
    try:
        # Try each candidate until one RECONCILES. _revenue_segments returns {} when the
        # members do not sum to revenue, so an empty result means "wrong table", not "no
        # data" -- and walking on is what turns a title guess into a content decision.
        segments = {}
        for _a in range(6):
            segments = _revenue_segments(ticker, quarterly=quarterly, unit_div=unit_div,
                                         total=rev, basis="geography", attempt=_a) or {}
            if segments:
                break
        seg_by = {}
        for _a in range(6):
            seg_by = _revenue_segments(ticker, quarterly=quarterly, unit_div=unit_div,
                                       total=rev, basis="segment", attempt=_a) or {}
            if seg_by:
                break
        # If the chosen segment table lists only the parents, try the NEXT candidate for the
        # same axis -- filers often publish both a summary and a fuller table, and only the
        # fuller one carries the sub-lines (Alphabet's Search / YouTube / Network sit under
        # Google Services). Only ever within this basis: the axes are told apart by name, so
        # searching across both collapses geography into segment.
        if seg_by and not any((v.get("children") or {}) for v in seg_by.values()):
            for _try in (1, 2):
                _alt = _revenue_segments(ticker, quarterly=quarterly, unit_div=unit_div,
                                         total=rev, basis="segment", attempt=_try)
                if _alt and any((v.get("children") or {}) for v in _alt.values()):
                    seg_by = _alt
                    break
    except Exception:
        segments, seg_by = {}, {}
    return {"company": name, "period": (f"quarter ending {period}" if quarterly
                                        else f"FY {period}"),
            "segments": segments, "segments_by": seg_by,
            "revenue": rev, "cogs": rev - gross, "gross": gross,
            "opex_parts": opex, "opex": gross - opinc, "opinc": opinc,
            "other": max(net + tax - opinc, 0.0), "tax": tax, "net": net, "yoy": yoy}


def _flow_insights(d):
    """Plain-language readings of an income statement, as a list of HTML strings.

    A Sankey shows the SHAPE of a quarter and nothing about the direction of travel: the
    same diagram is drawn by a business compounding and by one quietly shrinking. Every
    figure used here is already fetched -- year-over-year lines come back in `yoy`, and each
    segment carries its own `prior` -- so this costs no extra request (ID 330).

    Three readings, in the order they change a decision:
      OPERATING LEVERAGE  did profit grow faster than sales, i.e. did costs grow slower
      MIX SHIFT           which part of the business is taking over, in share not dollars
      DIVERGENCE          the fastest and slowest parts, which one blended number hides

    Mix shift matters more than it sounds. Two segments can both grow while the business
    changes character entirely, and a consolidated growth rate cannot show that -- Apple
    grew 22% on iPhone while iPad FELL 6% in the same quarter.
    """
    out, yoy = [], (d.get("yoy") or {})
    rev, opinc = d.get("revenue") or 0, d.get("opinc") or 0
    g_rev, g_oi = yoy.get("Total revenue"), yoy.get("Operating income")

    # 1. OPERATING LEVERAGE. Reconstruct the prior margin from the two growth rates rather
    #    than fetching the prior quarter again: margin_prior = (opinc/(1+g_oi)) / (rev/(1+g_rev)).
    if g_rev is not None and g_oi is not None and rev and opinc:
        try:
            m_now = opinc / rev * 100
            m_prev = (opinc / (1 + g_oi / 100)) / (rev / (1 + g_rev / 100)) * 100
            gap = g_oi - g_rev
            if gap > 1:
                out.append(f"⚙️ <b>Operating leverage is positive</b> — operating income grew "
                           f"{g_oi:+.1f}% on revenue up {g_rev:+.1f}%, so costs grew SLOWER than "
                           f"sales. Operating margin {m_prev:.1f}% → {m_now:.1f}% "
                           f"({m_now - m_prev:+.1f}pp).")
            elif gap < -1:
                out.append(f"⚙️ <b>Operating leverage is negative</b> — operating income grew "
                           f"{g_oi:+.1f}% while revenue grew {g_rev:+.1f}%, so costs grew FASTER "
                           f"than sales. Operating margin {m_prev:.1f}% → {m_now:.1f}% "
                           f"({m_now - m_prev:+.1f}pp). Growth is being bought, not earned.")
            else:
                out.append(f"⚙️ Operating income and revenue grew in step ({g_oi:+.1f}% vs "
                           f"{g_rev:+.1f}%) — margin held near {m_now:.1f}%.")
        except Exception:
            pass

    # 2/3. MIX SHIFT and DIVERGENCE, from whichever axis actually resolved.
    segs = d.get("segments") or d.get("segments_by") or {}
    pairs = [(k, v["now"], v["prior"]) for k, v in segs.items()
             if not v.get("parent") and v.get("prior") not in (None, 0) and v.get("now") is not None]
    if len(pairs) >= 2:
        tot_now = sum(p[1] for p in pairs)
        tot_prev = sum(p[2] for p in pairs)
        if tot_now and tot_prev:
            shifts = sorted(((n / tot_now - p / tot_prev) * 100, k, n, p)
                            for k, n, p in pairs)
            up, dn = shifts[-1], shifts[0]
            if abs(up[0]) >= 0.3 or abs(dn[0]) >= 0.3:
                out.append(f"🔀 <b>Mix shift</b> — {up[1]} took {up[0]:+.1f}pp of revenue share "
                           f"(now {up[2] / tot_now * 100:.1f}%), while {dn[1]} gave up "
                           f"{abs(dn[0]):.1f}pp (now {dn[2] / tot_now * 100:.1f}%). Share, not "
                           f"dollars: both can grow and the business still change character.")
        grow = sorted(((n / p - 1) * 100, k) for k, n, p in pairs)
        fast, slow = grow[-1], grow[0]
        if fast[0] - slow[0] > 5:
            # Only tie this back to the consolidated growth rate when it actually SITS
            # between the extremes. It does not always: segment growth comes from the
            # filing's own prior column while `yoy` comes from the statement four quarters
            # back, and for a filer whose fiscal year ends mid-calendar (PG in June) those
            # can be different periods -- PG reads +13.6% and +6.4% against a consolidated
            # +1.5%, which no weighting of the two produces. Asserting an average there
            # would be arithmetic that cannot be true, stated confidently.
            tie = ""
            if g_rev is not None and slow[0] <= g_rev <= fast[0]:
                tie = (f" The consolidated {g_rev:+.1f}% sits between them and describes "
                       f"neither.")
            out.append(f"↕️ <b>The parts disagree</b> — {fast[1]} {fast[0]:+.1f}% against "
                       f"{slow[1]} {slow[0]:+.1f}% year-over-year, on the company's own "
                       f"prior-period column.{tie}")
    return out


def _sankey_fig(s, width=1150, height=620):
    """Plotly figure for one income statement. Raises if the flows do not balance."""
    import plotly.graph_objects as _go
    bad = [k for k in ("revenue", "gross", "opinc", "net") if (s.get(k) or 0) <= 0]
    if bad:
        raise ValueError(f"cannot draw a flow: {', '.join(bad)} is zero or negative "
                         f"(a Sankey has no way to show a negative flow)")

    # ONE unit for the whole diagram, picked from the largest line (ID 325).
    _div, _unit = _sk_unit(max(s["revenue"], s["gross"], s["net"], s["opex"]))
    labels, colors, idx = [], [], {}

    def node(key, value, color):
        """Allocate each node's index ONCE. Every link is (source_index, target_index) and
        Plotly draws a confidently wrong diagram when one is off by one, so indices are never
        written by hand."""
        if key not in idx:
            idx[key] = len(labels)
            labels.append(_sk_label(key, value, s["yoy"].get(key), _unit, "$", _div))
            colors.append(color)
        return idx[key]

    src, tgt, val, lnk = [], [], [], []

    def link(a, b, v, color):
        if v and v > 0:
            src.append(a); tgt.append(b); val.append(v); lnk.append(color)

    total = node("Total revenue", s["revenue"], _SK_GREY)
    # Revenue SOURCES feed the total, largest first so the diagram reads top-down. Grey like
    # the total: revenue is not yet profit or cost, and colouring it green would prejudge it.
    for _nm, _v in sorted((s.get("segments") or {}).items(),
                          key=lambda kv: -kv[1]["now"]):
        _amt = _v["now"]
        if _amt > 0:
            # Per-segment growth on the label: the level says how big this source is, the
            # change says whether it is the part carrying the business or the part fading.
            if _v.get("prior"):
                s["yoy"][_nm] = (_amt / _v["prior"] - 1) * 100
            link(node(_nm, _amt, _SK_GREY), total, _amt, _SK_GREY_L)
    gross = node("Gross profit", s["gross"], _SK_GREEN)
    link(total, gross, s["gross"], _SK_GREEN_L)
    link(total, node("Cost of revenue", s["cogs"], _SK_RED), s["cogs"], _SK_RED_L)
    opinc = node("Operating income", s["opinc"], _SK_GREEN)
    link(gross, opinc, s["opinc"], _SK_GREEN_L)
    opex = node("Operating expenses", s["opex"], _SK_RED)
    link(gross, opex, s["opex"], _SK_RED_L)
    for nm, amt in s["opex_parts"].items():
        link(opex, node(nm, amt, _SK_RED), amt, _SK_RED_L)
    net = node("Net income", s["net"], _SK_GREEN)
    link(opinc, net, s["opinc"] - s["tax"], _SK_GREEN_L)
    link(opinc, node("Taxes", s["tax"], _SK_RED), s["tax"], _SK_RED_L)
    if s["other"] > 0:
        # Other income joins at the END: it never passed through gross profit, and routing it
        # earlier would overstate operating performance.
        link(node("Other income", s["other"], _SK_GREEN), net, s["other"], _SK_GREEN_L)

    margin = s["net"] / s["revenue"] * 100
    fig = _go.Figure(_go.Sankey(
        arrangement="snap",
        # textfont set explicitly: Plotly's default draws labels with a halo meant to lift
        # them off a light ground, and over the coloured node bars it reads as smudged
        # doubled text.
        textfont=dict(color="#111827", size=11.5,
                      family="IBM Plex Sans, Segoe UI, sans-serif"),
        node=dict(pad=34, thickness=15, line=dict(color="rgba(0,0,0,0)", width=0),
                  label=labels, color=colors,
                  hovertemplate="%{label}<br>%{value:,.0f}M<extra></extra>"),
        link=dict(source=src, target=tgt, value=val, color=lnk,
                  hovertemplate="%{source.label} → %{target.label}"
                                "<br><b>%{value:,.0f}M</b><extra></extra>")))
    fig.update_layout(
        title=dict(text=f"<b>{s['company']}</b> — how the money flows &nbsp;·&nbsp; "
                        f"<span style='font-size:14px;color:#6b7280'>{s['period']}"
                        f" &nbsp;·&nbsp; net margin {margin:.0f}%</span>",
                   x=0.02, xanchor="left", font=dict(size=20)),
        font=dict(family="IBM Plex Sans, Segoe UI, sans-serif", size=12.5, color="#171d24"),
        paper_bgcolor="white", width=width, height=height,
        margin=dict(l=14, r=14, t=72, b=22))
    return fig


def _fmt_valuation(ticker):
    """Telegram body for /value. Three scenarios, the assumption RANGE, and a cross-check.

    Deliberately never prints one fair value on its own. A DCF swings by multiples across
    assumptions nobody would call unreasonable, so a bare number would be the same false
    precision `_signal_writeup` exists to prevent -- the range IS the answer.
    """
    inp = _valuation_inputs(ticker)
    w = _wacc(inp)
    scen = (("Bear", 0.02, 0.015, w + 0.015),
            ("Base", 0.06, 0.025, w),
            ("Bull", 0.11, 0.030, max(w - 0.010, 0.03)))
    rows, base = [], None
    for nm, g, tg, sw in scen:
        try:
            r = _dcf(inp, g, wacc=sw, terminal_growth=tg)
        except Exception:
            continue
        if nm == "Base":
            base = r
        em = "🟢" if (r["upside"] or 0) > 0 else "🔴"
        rows.append((em, nm, f"{r['per_share']:,.0f}", f"{r['upside']:+.0f}%"))
    if not rows:
        return f"{hdr('🧮 VALUATION')}\n\n{ticker}: the model could not be solved."

    grid = _dcf_sensitivity(inp, 0.06, [w - 0.02, w - 0.01, w, w + 0.01, w + 0.02],
                            [0.015, 0.020, 0.025, 0.030, 0.035])
    flat = [v for r in grid for v in r if v]
    lo, hi = (min(flat), max(flat)) if flat else (0, 0)

    det = [f"<b>Price ${inp['price']:,.2f}</b> · {inp['sector']} · beta {inp['beta']:.2f} · "
           f"WACC {w:.1%}",
           f"Free cash flow <b>${inp['fcf_latest']/1e9:,.1f}B</b> latest, "
           f"${inp['fcf_avg3']/1e9:,.1f}B 3-yr average"]
    # WHEN this can next change. A fair value with no filing date attached hides how stale it
    # might be -- this steps on the filing, roughly quarterly, not on the tick.
    if inp.get("as_of"):
        _nx = (f" · next results <b>{inp['next_earnings']}</b>"
               if inp.get("next_earnings") else "")
        det.insert(1, f"Built from the statement to <b>{inp['as_of']}</b>{_nx} — "
                      f"it steps on the filing, not on the tick.")
    if base:
        det.append(f"Terminal value is <b>{base['terminal_pct']:.0f}%</b> of the base case — "
                   f"{'mostly a bet on the far future' if base['terminal_pct'] >= 70 else 'a reasonable share'}.")
    if flat:
        det.append(f"Across sensible WACC and terminal-growth choices the answer runs "
                   f"<b>${lo:,.0f}–${hi:,.0f}</b> ({hi/max(lo,0.01):.1f}× spread). "
                   f"That range is the output; a single number is not.")
    try:
        impl = _reverse_dcf(inp)
    except Exception:
        impl = None
    if impl is not None:
        det.append(f"<b>What the price already assumes:</b> roughly <b>{impl:.0%}</b> "
                   f"first-year cash-flow growth. This needs no forecast — the price "
                   f"supplies it; the question is whether you believe it.")
    mv = _multiples_value(inp, pe=inp.get("forward_pe"), ev_ebitda=15)
    for k, v in mv.items():
        det.append(f"{'Forward P/E' if k == 'pe' else 'EV/EBITDA'} {v['multiple']:.1f}x implies "
                   f"<b>${v['per_share']:,.0f}</b> ({v['upside']:+.0f}%)")
    if base and mv:
        gap = max(abs(v["per_share"] - base["per_share"]) / max(base["per_share"], 1)
                  for v in mv.values())
        if gap > 0.4:
            det.append("⚠️ The two methods disagree sharply — the market is paying for growth "
                       "this model does not assume, or the multiple has run ahead of the cash.")
    return _report(f"🧮 {inp['name'][:26]} — what the cash is worth",
                   ("", "Case", "Value", "vs px"), rows, right_cols={2, 3},
                   legend=f"$ per share · base free cash flow ${inp['fcf_latest']/1e9:,.1f}B",
                   details=det,
                   notes="A MODEL, not a measurement. Every forward number is an assumption. "
                         "Not advice.")


async def value_command(update, ctx):
    """/value TICKER — discounted cash flow with its own uncertainty attached."""
    tk = (ctx.args[0].upper() if ctx.args else "AAPL")
    await update.message.reply_text(f"🧮 Valuing {tk}…", parse_mode=H)
    try:
        body = await asyncio.to_thread(_fmt_valuation, tk)
    except Exception as e:
        body = (f"❌ Couldn't value <b>{tk}</b> — {_h.escape(str(e)[:160])}\n"
                f"<i>Needs a filed cash-flow statement and a share count; ETFs and funds "
                f"have neither.</i>")
    await update.message.reply_text(body[:4000], parse_mode=H)


async def sankey_command(update, ctx):
    """/sankey TICKER [annual] — how a company's money flows, revenue through to net income.

    The browser tools for this (SankeyMATIC, Sankey Open Studio) all make you TYPE the
    figures in. Pulling them from the filing is the only part worth automating -- and it is
    where the mistakes are, since a Sankey renders unbalanced numbers without complaint.
    `_income_stmt` takes the reported subtotals and derives the residuals, so
    the picture always balances and still matches the company's own headline numbers.
    """
    args = [a for a in (getattr(ctx, "args", []) or [])]
    if not args:
        await update.message.reply_text(
            f"{hdr('💧 /sankey — company money flow')}\n\n"
            "<code>/sankey PLTR</code> — latest quarter\n"
            "<code>/sankey AAPL annual</code> — full year\n\n"
            "<i>Revenue → gross profit → operating income → net income, with costs branching "
            "off. Figures come from the company's filed statement.</i>", parse_mode=H)
        return
    tk = str(args[0]).upper().strip()
    quarterly = not any(str(a).lower() in ("annual", "yearly", "fy", "year") for a in args[1:])
    wait = await update.message.reply_text(f"💧 Building {tk} money flow…", parse_mode=H)
    try:
        stmt = _income_stmt(tk, quarterly=quarterly)
        fig = _sankey_fig(stmt, width=1180, height=620)
        png = fig.to_image(format="png", scale=2)      # kaleido
    except Exception as e:
        try:
            await wait.delete()
        except Exception:
            pass
        await update.message.reply_text(
            f"⚠️ Couldn't build {tk}: {_llm_err_msg(e) or e}\n"
            f"<i>Needs a filed income statement — works for most listed companies, but not "
            f"for ETFs, indices or names with no published financials.</i>", parse_mode=H)
        return
    try:
        await wait.delete()
    except Exception:
        pass
    m = stmt["net"] / stmt["revenue"] * 100
    await update.message.reply_photo(
        png, caption=(f"💧 <b>{stmt.company}</b> — {stmt.period}\n"
                      f"Revenue ${stmt['revenue']:,.0f}M → net ${stmt['net']:,.0f}M "
                      f"({m:.0f}% margin)"), parse_mode=H)
    await update.message.reply_text(
        _report(f"💧 {tk} INCOME FLOW",
                ("Line", "Amount", "of rev"),
                [("Revenue", f"{stmt["revenue"]:,.0f}", "100%"),
                 ("Cost of rev", f"-{stmt["cogs"]:,.0f}",
                  f"{stmt["cogs"] / stmt["revenue"] * 100:.0f}%"),
                 ("Gross profit", f"{stmt["gross"]:,.0f}",
                  f"{stmt["gross"] / stmt["revenue"] * 100:.0f}%"),
                 ("Op expenses", f"-{stmt["opex"]:,.0f}",
                  f"{stmt["opex"] / stmt["revenue"] * 100:.0f}%"),
                 ("Op income", f"{stmt["opinc"]:,.0f}",
                  f"{stmt["opinc"] / stmt["revenue"] * 100:.0f}%"),
                 ("Taxes", f"-{stmt["tax"]:,.0f}",
                  f"{stmt["tax"] / stmt["revenue"] * 100:.0f}%"),
                 ("Net income", f"{stmt["net"]:,.0f}", f"{m:.0f}%")],
                right_cols={1, 2}, legend="$ millions · figures as filed",
                notes="Subtotals are the company's reported ones; residuals derived so the "
                      "flow balances."), parse_mode=H)
    # The diagram shows the SHAPE of a quarter and nothing about direction of travel -- the
    # same picture is drawn by a business compounding and one quietly shrinking (ID 330).
    _ins = _flow_insights(stmt)
    if _ins:
        await update.message.reply_text(
            f"📈 <b>What changed since a year ago</b>\n\n" + "\n\n".join(_ins),
            parse_mode=H)


# ── Fear & Greed history (user 2026-08-07) ───────────────────────────────────────────
# The composite is a deterministic function of VIX and 5-day momentum, and stock_history
# holds VIX back to 1990 and SPY to 2016 — so the whole series is RECONSTRUCTABLE rather
# than something we have to start accruing today. CNN's own API is unreachable from this
# machine (DNS fails on production.datastore.cnn.com), which is moot given the above.
#
# The formula is kept in ONE place and reused by the live reading and the history, so the
# "now" value on the chart always equals the number printed beside it.

def _fg_series(conn=None, days=1300):
    """Reconstructed Fear & Greed, 0-100 daily. pandas Series indexed by date; empty on fail."""
    own = conn is None
    if own:
        conn = get_conn()
    try:
        v = pd.read_sql("SELECT trade_date d, close vix FROM stock_history "
                        "WHERE ticker='VIX' ORDER BY d", conn)
        sp = pd.read_sql("SELECT trade_date d, close spy FROM stock_history "
                         "WHERE ticker='SPY' ORDER BY d", conn)
    except Exception:
        return pd.Series(dtype=float)
    finally:
        if own:
            conn.close()
    if v.empty or sp.empty:
        return pd.Series(dtype=float)
    m = v.merge(sp, on="d")
    m["d"] = pd.to_datetime(m["d"])
    m = m.set_index("d").astype(float)
    fg = 50 + (20 - m["vix"]).mul(2.5).clip(-25, 25)          # VIX term, as live
    mom = (m["spy"] / m["spy"].shift(5) - 1) * 100 * 4        # momentum proxy
    fg = (fg + mom.clip(-20, 20)).clip(0, 100).dropna()
    return fg.tail(days)


def _fg_label(v):
    if v >= 75:  return "EXTREME GREED 🤑"
    if v >= 55:  return "GREED 😀"
    if v >= 45:  return "NEUTRAL 😐"
    if v >= 25:  return "FEAR 😨"
    return "EXTREME FEAR 😱"


def _fmt_fg_history(conn=None):
    """Table of where fear/greed sat 1d/1w/1m/3m/1y/5y ago. None when unavailable."""
    fg = _fg_series(conn, days=1400)
    if fg.empty or len(fg) < 30:
        return None
    now = float(fg.iloc[-1])
    # The series ends where VIX history ends, which can lag today by days. Label the
    # as-of instead of calling a week-old number "now" (2026-08-07).
    _asof = fg.index[-1].strftime("%d %b")
    rows = [(f"{_asof}", f"{now:.0f}", _fg_label(now).split()[0][:9], "—")]
    for lbl, off in (("1d", 1), ("1w", 5), ("1m", 21), ("3m", 63), ("1y", 252), ("5y", 1260)):
        if len(fg) > off:
            was = float(fg.iloc[-1 - off])
            rows.append((lbl, f"{was:.0f}", _fg_label(was).split()[0][:9], f"{now - was:+.0f}"))
    return _pipe_table(("When", "Score", "Mood", "vs now"), rows, right_cols={1, 3},
                       title="😱 FEAR & GREED — HISTORY",
                       legend=f"0 = extreme fear · 100 = extreme greed · reconstructed from "
                              f"VIX + 5d momentum (same formula as the live reading) · "
                              f"latest point {fg.index[-1]:%d %b %Y}, which is where VIX "
                              f"history ends — not necessarily today")


def _fg_chart_png(conn=None, days=400):
    """Fear/greed line with the fear/greed bands shaded. None on failure."""
    fg = _fg_series(conn, days=days)
    if fg.empty or len(fg) < 30:
        return None
    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        fig, ax = plt.subplots(figsize=(9, 3.4), dpi=130)
        ax.axhspan(75, 100, color="#0f7b2f", alpha=.18)
        ax.axhspan(55, 75, color="#0f7b2f", alpha=.09)
        ax.axhspan(25, 45, color="#8b1a1a", alpha=.09)
        ax.axhspan(0, 25, color="#8b1a1a", alpha=.18)
        ax.plot(fg.index, fg.values, lw=1.4, color="#111")
        ax.axhline(50, color="#888", lw=.8, ls=":")
        ax.scatter([fg.index[-1]], [fg.iloc[-1]], s=32, zorder=5, color="#1565c0")
        ax.annotate(f"{fg.iloc[-1]:.0f}", (fg.index[-1], fg.iloc[-1]),
                    textcoords="offset points", xytext=(6, 4), fontsize=9, color="#1565c0")
        ax.set_ylim(0, 100); ax.set_ylabel("Fear ← → Greed", fontsize=8)
        ax.set_title(f"Fear & Greed — last {len(fg)} sessions", fontsize=10)
        ax.tick_params(labelsize=8); ax.grid(alpha=.18)
        fig.tight_layout()
        buf = BytesIO(); fig.savefig(buf, format="png"); plt.close(fig); buf.seek(0)
        return buf
    except Exception:
        log.debug("fg chart failed", exc_info=True)
        return None


async def feargreed_command(update, ctx):
    """/feargreed — current reading plus 1d/1w/1m/3m/1y/5y history and a chart."""
    conn = get_conn()
    try:
        txt = _fmt_fg_history(conn)
        png = _fg_chart_png(conn)
    finally:
        conn.close()
    if png:
        await update.message.reply_photo(png, caption="😱 Fear & Greed — reconstructed history")
    if txt:
        for _p in _chunk_on_sections(txt):
            await update.message.reply_text(_p, parse_mode=H)
    if not txt and not png:
        await update.message.reply_text("Fear & Greed history unavailable — needs VIX and "
                                        "SPY in stock_history.", parse_mode=H)


def _next_day_plan(conn):
    """Condensed whole-portfolio next-day plan: regime + Greeks + per-stock levels,
    expected move, StockTwits sentiment, per-leg actions, and a morning checklist."""
    L = ["🌅 <b>NEXT-DAY GAME PLAN</b>"]
    try:
        _mkt_rows = _plan_markets_rows()
        _mkt = _plan_markets_snapshot(_mkt_rows)
        if _mkt:
            L.append(_mkt)
            L.append("")
        try:
            _why = _fmt_move_writeups(_mkt_rows)
            if _why:
                L.append(_why); L.append("")
        except Exception:
            log.debug("move writeups failed", exc_info=True)
    except Exception:
        log.debug("plan markets snapshot failed", exc_info=True)
    try:
        rg = _risk_regime()
        L.append(f"{rg['emoji']} Regime <b>{rg['label']}</b> ({rg['score']:+d})")
    except Exception:
        pass
    try:
        tr = pd.read_sql("SELECT ticker,option_type,strike,quantity,expiry,entry_price,entry_iv "
                         "FROM trades WHERE status='OPEN' AND UPPER(option_type)<>'STOCK'", conn)
    except Exception:
        tr = pd.DataFrame()
    try:
        stk = pd.read_sql("SELECT ticker,quantity,entry_price,entry_date "
                          "FROM trades WHERE status='OPEN' AND UPPER(option_type)='STOCK'", conn)
    except Exception:
        stk = pd.DataFrame()
    if (tr is None or tr.empty) and (stk is None or stk.empty):
        L.append("No open positions.")
        return "\n".join(L)
    tr = tr if tr is not None else pd.DataFrame()
    R = 0.045
    by = {}
    for _, t in tr.iterrows():
        by.setdefault(str(t["ticker"]).upper(), []).append(t)
    stk_by = {}
    if stk is not None and not stk.empty:
        for _, s in stk.iterrows():
            stk_by.setdefault(str(s["ticker"]).upper(), []).append(s)
        for _stk_tk in stk_by:
            by.setdefault(_stk_tk, [])       # stock-only tickers still get a block
    net_dd = net_th = 0.0
    port_maxp = port_maxl = port_ev = spy_dd = 0.0
    port_up = port_dn = False
    gross_by = {}
    checklist, blocks = [], []
    for tk, legs in by.items():
        spot = _gex_spot(conn, tk) or _last_price(tk)
        if not spot:
            continue
        # after-hours stock (for the 'est. at open' re-price, user 2026-07-20)
        _ah = {}
        try:
            _ah = _get_spot_with_ah(tk)
        except Exception:
            pass
        ah_spot = float(_ah.get("spot_ext") or 0) if _ah.get("is_extended") else 0.0
        g = {}
        try:
            g = _compute_gex(tk, conn, spot)
        except Exception:
            pass
        cw, pw = g.get("call_wall"), g.get("put_wall")
        tk_dd = tk_th = 0.0
        ivs, leglines, tk_legs = [], [], []
        leg_rows, leg_acts, ah_rows = [], [], []   # option legs -> table; ah_rows -> est-open table
        for t in legs:
            typ = "call" if str(t["option_type"]).lower().startswith("c") else "put"
            K = float(t["strike"] or 0); qty = int(t["quantity"] or 0); exp = str(t["expiry"])
            dte = None
            for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%m-%d-%Y", "%Y/%m/%d"):
                try:
                    dte = (datetime.strptime(exp, fmt) - datetime.now()).days; break
                except Exception:
                    pass
            if dte is None or K <= 0 or qty == 0:
                continue
            T = max(dte, 0) / 365.0
            entry = float(t["entry_price"] or 0)
            prem = _plan_prem(conn, tk, K, exp, typ)
            bb = _bb_quote(conn, tk, K, exp, typ)
            if bb and bb["mid"] > 0:
                prem = bb["mid"]                 # OpenBB DB mid is PRIMARY (we run on BB now)
            else:
                # BB has no quote for this contract -> only THEN fall back to a live yfinance
                # option mid. Gated behind BB-missing 2026-07-19: the per-leg live chain download
                # was the /plan bottleneck (~17s cold / 8s warm); BB DB covers captured tickers,
                # so this rarely fires and /plan drops to ~1s.
                try:
                    _lm = _option_price_by_mode(tk, typ, K, exp, mode="mid", fallback=0.0)
                    if _lm and _lm > 0:
                        prem = _lm
                except Exception:
                    log.debug("live option mid failed", exc_info=True)
            iv = (bb["iv"] if (bb and bb.get("iv")) else None) or (
                _implied_vol_hp(prem, spot, K, T, R) if (prem and T > 0)
                else (float(t["entry_iv"] or 0) or 0.30))
            ivs.append(iv)
            gg = bs_greeks(spot, K, T, R, iv, typ) if T > 0 else {"delta": 0, "theta": 0, "price": (prem or entry)}
            cur = prem if prem else gg.get("price", entry)
            m = qty * 100
            tk_dd += gg["delta"] * m * spot * 0.01
            tk_th += gg["theta"] * m
            side = "short" if qty < 0 else "long"
            money = "ITM" if ((spot > K) if typ == "call" else (spot < K)) else "OTM"
            pnlp = ((cur - entry) / entry * 100 * (1 if qty > 0 else -1)) if entry else 0
            acts = []
            if dte <= 7: acts.append(f"{dte}DTE decide")
            elif dte <= 21: acts.append(f"{dte}DTE roll-plan")
            if side == "short" and money == "ITM": acts.append("ITM assign-risk")
            if pnlp >= 50: acts.append("take profit")
            elif pnlp <= -50: acts.append("cut/roll")
            a = "; ".join(acts) if acts else "hold"
            _side_em = "🟥" if side == "short" else "🟩"       # 🟩 long · 🟥 short
            leg_rows.append((_side_em, f"{K:.0f}{typ[0].upper()}", f"{dte}d", f"{pnlp:+.0f}%"))
            if ah_spot and iv and T > 0:
                _cur_ah = bs_greeks(ah_spot, K, T, R, iv, typ).get("price", cur)
                _ah_dp = ((_cur_ah - cur) / cur * 100) if cur else 0.0
                ah_rows.append((f"{K:.0f}{typ[0].upper()}", f"{cur:.2f}", f"{_cur_ah:.2f}", f"{_ah_dp:+.0f}%"))
            if acts:
                leg_acts.append(f"{_side_em} {K:.0f}{typ[0].upper()} {money} → {a}")
                checklist.append(f"{tk} ${K:.0f}{typ[0].upper()}: {a}")
            tk_legs.append({"K": K, "typ": typ, "entry": entry, "m": m, "iv": iv,
                            "dte": dte, "cur": cur, "side": side, "qty": qty, "exp": exp,
                            "ticker": tk, "spot": spot, "pnl": (cur - entry) * m})
        # STOCK legs: shares shown + counted in delta/gross, kept OUT of tk_legs
        # (the option analytics below assume K>0; shares are linear, no expiry).
        for s_ in stk_by.get(tk, []):
            sq = int(s_["quantity"] or 0); sep = float(s_["entry_price"] or 0)
            if not sq:
                continue
            tk_dd += sq * spot * 0.01                       # 1 delta per share
            spnl = (spot - sep) * sq
            spct = ((spot - sep) / sep * 100 * (1 if sq > 0 else -1)) if sep else 0
            held = ""
            try:
                _ed = str(s_.get("entry_date") or "")[:10]
                if _ed:
                    _hd = (datetime.now() - datetime.strptime(_ed, "%Y-%m-%d")).days
                    held = f" · held {_hd}d {'🟢LT' if _hd >= 365 else 'ST'}"
            except Exception:
                pass
            hedge_bits = []
            try:                                            # class match catches GOOG↔GOOGL
                _cls = tr[(tr["ticker"].astype(str).str.upper().str[:4] == tk[:4])
                          & (tr["ticker"].astype(str).str.len().sub(len(tk)).abs() <= 1)]
                if not _cls.empty:
                    _oc_ = _cls["option_type"].astype(str).str.lower().str[0]
                    if bool(((_oc_ == "c") & (_cls["quantity"] < 0)).any()):
                        hedge_bits.append("covered call")
                    if bool(((_oc_ == "p") & (_cls["quantity"] > 0)).any()):
                        hedge_bits.append("protective put (⚠️ tax clock — /tax)")
            except Exception:
                pass
            hedge = (" · 🛡 " + " + ".join(hedge_bits)) if hedge_bits else ""
            leglines.insert(0, f"  📦 {'long' if sq > 0 else 'short'} {abs(sq)} sh @${sep:.2f} "
                               f"{spct:+.0f}% (${spnl:,.0f}){held}{hedge}")
            gross_by[tk] = gross_by.get(tk, 0.0) + abs(spot * sq)
        net_dd += tk_dd; net_th += tk_th
        ivm = sorted(ivs)[len(ivs) // 2] if ivs else 0.30
        em = spot * ivm * (1 / 252.0) ** 0.5
        head = f"<b>{tk}</b> ${spot:.2f} · ±${em:.2f}/1d"
        lv = []
        if pw: lv.append(f"PW${pw:.0f}")
        if cw: lv.append(f"CW${cw:.0f}")
        if lv:
            head += " · " + " ".join(lv)
        # Sentiment consolidated to ONE labeled line (was 3 separate emoji-prefixed lines —
        # user 2026-07-18: too many different label-emoji with no grouping)
        sent_bits = []
        stt = _stocktwits_sentiment(tk)
        if stt:
            _es = "🟢" if "BULL" in stt["label"] else "🔴" if "BEAR" in stt["label"] else "🟡"
            sent_bits.append(f"{_es} StockTwits {stt['label']} ({stt['bull']}🟢/{stt['bear']}🔴)")
        fh = _finnhub_sentiment(tk)
        if fh:
            _ef = "🟢" if fh["bull_pct"] >= 60 else "🔴" if fh["bull_pct"] <= 40 else "🟡"
            sent_bits.append(f"{_ef} Finnhub {fh['label']} ({fh['bull_pct']:.0f}% bull)")
        rd = _reddit_sentiment(tk)
        if rd:
            _er = "🟢" if "BULL" in rd["label"] else "🔴" if "BEAR" in rd["label"] else "🟡"
            sent_bits.append(f"{_er} r/WSB {rd['label']} ({rd['bull']}🟢/{rd['bear']}🔴 of {rd['n']})")
        if sent_bits:
            head += "\n  <b>Sentiment</b>  " + " · ".join(sent_bits)
        ivr = _iv_rank(conn, tk)
        if ivr:
            hint = "cheap→buy" if ivr["rank"] < 30 else "rich→sell" if ivr["rank"] > 70 else "mid"
            head += f"\n  <b>IV Rank</b>  {ivr['rank']:.0f} ({ivr['iv']*100:.0f}%) {hint}"
        ea = _next_earnings(tk)
        if ea and ea["days"] <= 14:
            head += f"\n  <b>Earnings</b>  ⚠️ {ea['date']} ({ea['days']}d) — gap risk"
        extra = []
        _ofl = _plan_oi_flow(conn, tk, spot)
        if _ofl:
            extra.append(_ofl)
        _ptl = _plan_patterns(tk, spot, pw, cw)
        if _ptl:
            extra.append(_ptl)
        # Track record: real table + inference DERIVED from the backtested hit-rate + that
        # signal's current direction (user 2026-07-18: "high quality inference... build a
        # system and backtest") — never a free-standing prediction.
        _trust = _plan_trust(conn, tk)
        _ttbl, _tinfer = _plan_trust_render(_trust)
        if _ttbl:
            extra.append("  <b>Track record</b>\n" + _ttbl + "\n  " + _tinfer)
        _b = _pl_bounds(tk_legs, spot)
        _a = _pl_analytics(tk_legs, spot)
        if _b:
            port_maxp += _b["maxp"]; port_maxl += _b["maxl"]
            port_up = port_up or _b["up"]; port_dn = port_dn or _b["dn"]
        if _a:
            port_ev += _a["ev"]
        try:
            spy_dd += tk_dd * _pl_beta(conn, tk)
        except Exception:
            spy_dd += tk_dd
        for _l in tk_legs:
            _g = abs(_l["cur"] * _l["m"]) if _l["side"] == "long" else _l["entry"] * abs(_l["m"])
            gross_by[tk] = gross_by.get(tk, 0.0) + _g
        ana = []
        if _b:
            ana.append(f"  💰 MaxP {_pl_mp(_b)} · MaxL {_pl_ml(_b)}")
        if _a:
            _be = ", ".join(f"${x:.0f}" for x in _a["be"]) or "—"
            ana.append(f"  📈 POP {_a['pop']:.0f}% {_bar(_a['pop'])} · EV ${_a['ev']:,.0f} · B/E {_be}")
        _xs = [r for r in _pl_exit(tk_legs, spot) if r["sc"] > 0][:2]
        if _xs:
            ana.append("  🎯 Close first: " + " | ".join(
                f"{_kfb(r['l']['K'])}{r['l']['typ'][0].upper()} ({r['why']})" for r in _xs))
        for _t in _pl_tickets(tk_legs, spot, cw, pw)[:4]:
            ana.append("  🧾 " + _t)
        # Legs section: stock lines (📦, prose — hedge/held context) + option-leg TABLE
        # (user 2026-07-19) + action detail lines below it.
        _leg_block = "\n".join(leglines)      # stock 📦 lines (may be empty)
        if leg_rows:
            _lt = _pipe_table(("ST", "Leg", "DTE", "P&L"), leg_rows, right_cols={3},
                              legend="🟩 long · 🟥 short")
            _leg_block += ("\n" if _leg_block else "") + "  <b>Legs</b>\n" + _lt
            if leg_acts:
                _leg_block += "\n" + "\n".join("  " + x for x in leg_acts)
        if ah_rows:
            _aht = _pipe_table(("Leg", "Close", "Open", "Δ%"), ah_rows, right_cols={1, 2, 3})
            _leg_block += ("\n" if _leg_block else "") + (
                f"  <b>Est. at open</b> <i>(BS re-price from {_ah.get('ext_src','AH')} "
                f"${ah_spot:.2f}, {_ah.get('ext_chg_pct',0):+.1f}% vs close; IV held)</i>\n" + _aht)
        _inner = (("\n".join(extra) + "\n" if extra else "")
                  + _leg_block + ("\n" + "\n".join(ana) if ana else ""))
        # collapse the detail under the headline (tap to expand) — modern, scannable
        blocks.append(head + ("\n<blockquote expandable>" + _inner + "</blockquote>"
                              if _inner.strip() else ""))
    L.append(f"Net Δ/+1% <b>${net_dd:,.0f}</b> · Θ/day <b>${net_th:,.0f}</b>")
    L.append(f"📊 Port MaxP <b>{'∞' if port_up else f'${port_maxp:,.0f}'}</b> · "
             f"MaxL <b>{'∞' if port_dn else f'${port_maxl:,.0f}'}</b> · EV <b>${port_ev:,.0f}</b>")
    _conc = (f" · top {max(gross_by, key=gross_by.get)} "
             f"{gross_by[max(gross_by, key=gross_by.get)]/sum(gross_by.values())*100:.0f}%"
             if gross_by and sum(gross_by.values()) > 0 else "")
    L.append(f"📐 SPY-Δ <b>${spy_dd:,.0f}</b>/+1% SPY{_conc}")
    L.append("")
    L += blocks
    if checklist:
        L.append("")
        L.append("✅ <b>Tomorrow:</b>")
        for c in checklist[:8]:
            L.append("• " + c)
    # NEWS LAST (user 2026-08-07). At the top it pushed the market tables past Telegram's
    # 4096-char cap, so the COMMODITIES table fell off the end and read as deleted.
    # Market structure first, headlines after.
    try:
        _brk = _fmt_breaking(_breaking_for_book(conn))
        if _brk:
            L.append("")
            L.append(_brk)
    except Exception:
        log.debug("breaking block failed", exc_info=True)
    L.append("")
    L.append("<i>Educational, not advice.</i>")
    return "\n".join(L)

