def _wrap_severe_news(limit=20):
    """Scan world headlines for major war/attack/climate-disaster events (user ask
    2026-07-28: "important news like wars, bombings, climate severities"). Broader net
    than _country_instability_flags (ticker-supply-chain scoped) -- this is a general
    world-event scan for the wrap. Keyless, reuses _world_news_block. Returns
    [(category, headline, url)], deduped, capped at 5 -- [] on any failure."""
    try:
        news = _world_news_block(limit=limit)
    except Exception:
        return []
    out, seen = [], set()
    for hl, _src, url in news:
        h = hl.lower()
        for cat, kws in _WRAP_SEVERE_KEYWORDS.items():
            if any(kw in h for kw in kws):
                key = hl[:50].lower()
                if key not in seen:
                    out.append((cat, hl, url))
                    seen.add(key)
                break
    return out[:5]


def wrap_facts(conn, universe_cap=120):
    """Compute the structured fact pack for the market wrap."""
    F = {"ts": datetime.now(), "indices": [], "lead": None, "shape": None,
         "vix": None, "cross": [], "lev": [], "movers_up": [], "movers_dn": [],
         "breadth": None, "options": None, "book": None, "catalyst": None, "macro": None, "regime": None}

    for sym, name, cap in _WRAP_IDX:
        q = _wrap_quote(sym)
        if not q:
            continue
        d = {"sym": sym, "name": name, "cap": cap, **q}
        if cap:
            d["dollars"] = cap * (q["pct"] / 100.0)
        F["indices"].append(d)
    if F["indices"]:
        F["lead"] = max(F["indices"], key=lambda d: abs(d["pct"]))
        F["shape"] = _wrap_intraday_shape(F["lead"]["sym"])

    vq = _wrap_quote("^VIX")
    if vq:
        F["vix"] = vq

    F["macro"] = _wrap_macro()
    F["regime"] = _wrap_regime(F)

    for sym, name, kind in _WRAP_CROSS:
        q = _wrap_quote(sym)
        if q:
            F["cross"].append({"name": name, "kind": kind, **q})

    for sym, name, mult in _WRAP_LEV:
        q = _wrap_quote(sym)
        if q:
            F["lev"].append({"sym": sym, "name": name, "mult": mult, **q})

    try:
        tks = [r[0] for r in conn.execute("SELECT DISTINCT ticker FROM stock_daily").fetchall()][:universe_cap]
    except Exception:
        tks = []
    rows = []
    if tks:
        try:
            data = yf.download(tks, period="6d", interval="1d", group_by="ticker",
                               threads=True, progress=False)
            for t in tks:
                try:
                    c = data[t]["Close"].dropna() if len(tks) > 1 else data["Close"].dropna()
                    if len(c) >= 2 and float(c.iloc[-2]) > 0:
                        rows.append({"t": t, "pct": (float(c.iloc[-1]) / float(c.iloc[-2]) - 1) * 100,
                                     "last": float(c.iloc[-1])})
                except Exception:
                    continue
        except Exception:
            rows = []
    if not rows:  # DB EOD fallback
        sk = "trade_date"
        for t in tks:
            try:
                c = pd.read_sql(f"SELECT close FROM stock_daily WHERE ticker=? ORDER BY {sk} DESC LIMIT 2",
                                conn, params=(t,))
                v = pd.to_numeric(c["close"], errors="coerce").dropna().tolist()
                if len(v) >= 2 and v[1] > 0:
                    rows.append({"t": t, "pct": (v[0] / v[1] - 1) * 100, "last": v[0]})
            except Exception:
                continue
    if rows:
        up = sum(1 for r in rows if r["pct"] > 0); dn = sum(1 for r in rows if r["pct"] < 0)
        F["breadth"] = {"up": up, "dn": dn, "n": len(rows)}
        rows.sort(key=lambda r: r["pct"])
        F["movers_dn"] = rows[:5]
        F["movers_up"] = rows[-5:][::-1]

    cand = None
    if F["movers_dn"] or F["movers_up"]:
        cand = max(F["movers_dn"] + F["movers_up"], key=lambda r: abs(r["pct"]))["t"]
    if cand:
        try:
            for n in (yf.Ticker(cand).news or []):
                c = n.get("content", {}) or {}
                title = c.get("title") or n.get("title")
                if title:
                    # A9 (docs/PLAN.md, "narrative as links"): this quote used to drop the
                    # URL entirely -- same canonicalUrl/clickThroughUrl fields _position_news
                    # already reads, just never captured here.
                    url = (c.get("canonicalUrl") or {}).get("url") or \
                          (c.get("clickThroughUrl") or {}).get("url") or ""
                    F["catalyst"] = {"ticker": cand, "title": title, "url": url}
                    break
        except Exception:
            pass

    try:
        sk = "trade_date_now"
        snap = conn.execute(f"SELECT trade_date_now FROM options_change ORDER BY {sk} DESC LIMIT 1").fetchone()
        if snap:
            d0 = snap[0]
            agg = pd.read_sql(
                "SELECT ticker, SUM(change_OI_Call) cc, SUM(change_OI_Put) cp, "
                "SUM(openInt_Call_now) oc, SUM(openInt_Put_now) op "
                "FROM options_change WHERE trade_date_now=? GROUP BY ticker", conn, params=(d0,))
            if not agg.empty:
                agg = agg[~agg["ticker"].astype(str).str.startswith("^")]
                tc = float(agg["cc"].sum()); tp = float(agg["cp"].sum())
                oc = float(agg["oc"].sum()); op = float(agg["op"].sum())
                agg["net"] = agg["cp"].fillna(0) - agg["cc"].fillna(0)
                put_heavy = agg.reindex(agg["net"].sort_values(ascending=False).index).head(3)
                F["options"] = {"date": d0, "call_chg": tc, "put_chg": tp,
                                "pcr": (op / oc) if oc else None,
                                "put_heavy": list(put_heavy["ticker"])}
    except Exception:
        pass

    try:
        tr = pd.read_sql("SELECT ticker,option_type,quantity FROM trades WHERE status='OPEN' AND UPPER(option_type)<>'STOCK'", conn)
        if not tr.empty:
            mv = {r["t"]: r["pct"] for r in rows}
            bt = {}
            for _, t in tr.iterrows():
                tk = str(t["ticker"]).upper()
                pc = mv.get(tk)
                if pc is None:
                    q = _wrap_quote(tk); pc = q["pct"] if q else 0.0
                typ = "call" if str(t["option_type"]).lower().startswith("c") else "put"
                qty = int(t["quantity"] or 0)
                bt.setdefault(tk, {"pct": pc, "dir": 0})
                bt[tk]["dir"] += (1 if (typ == "call") == (qty > 0) else -1)
            F["book"] = {"tickers": [{"tk": k, "pct": v["pct"], "dir": v["dir"]} for k, v in bt.items()]}
    except Exception:
        pass

    return F


def wrap_narrative(F, html=True):
    """Render the fact pack into a punchy 'what just happened' write-up.

    Each section's PROSE body renders inside <blockquote expandable> (user 2026-07-24: long
    narrative paragraphs should collapse behind their header instead of always being fully
    expanded — same pattern /plan already uses per-position). Only the bold section header
    stays visible by default; tap to expand. Tables (levered-ETF) stay outside the blockquote —
    Telegram's <pre> grid inside a blockquote renders oddly on some clients."""
    b = (lambda s: f"<b>{s}</b>") if html else (lambda s: s)
    esc = (lambda s: str(s).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")) if html else (lambda s: s)

    def _sec(emoji, title, body):
        """One collapsible section: bold header (always visible) + expandable body."""
        if not body:
            return ""
        if not html:
            return f"\n{emoji} {title}\n{body}"
        return f"\n{emoji} <b>{title}</b>\n<blockquote expandable>{body}</blockquote>"

    L = []
    lead = F["lead"]; shape = F["shape"]
    seed = int(F["ts"].strftime("%Y%m%d"))

    if lead:
        d = lead["pct"]
        big_swing = bool(shape and abs(shape["dd_pct"]) >= 1.2 and shape["dd_mins"] > 0)
        if big_swing:
            op = (shape["open"] / lead["prev"] - 1) * 100
            dollar = f" — an estimated {_wrap_money(abs(lead['dollars']))} in value" if lead.get("dollars") else ""
            hooks = [
                f"In just {shape['dd_mins']} minutes, the {lead['name']} cratered {shape['dd_pct']:.1f}% from its "
                f"intraday peak{dollar}. It opened {op:+.1f}% and is now {d:+.1f}% — a violent round trip on the day.",
                f"A textbook volatility shock: the {lead['name']} ran to {op:+.1f}% at the open, then dumped "
                f"{shape['dd_pct']:.1f}% in {shape['dd_mins']} minutes{dollar}, settling {d:+.1f}% on the day."]
            L.append(_sec("⚡", "WHAT JUST HAPPENED", _wrap_pick(seed, hooks)))
        elif lead.get("dollars"):
            verb = "erased" if d < 0 else "added"
            hooks = [
                f"The {lead['name']} {verb} an estimated {_wrap_money(abs(lead['dollars']))} in market value today, "
                f"moving {d:+.1f}% ({lead['pts']:+,.0f} pts).",
                f"An estimated {_wrap_money(abs(lead['dollars']))} {('vanished from' if d<0 else 'flowed into')} the "
                f"{lead['name']} today as it moved {d:+.1f}% ({lead['pts']:+,.0f} pts)."]
            L.append(_sec("⚡", "WHAT JUST HAPPENED", _wrap_pick(seed, hooks)))
        else:
            risk = "sell-off" if d < 0 else "rally"
            L.append(_sec("⚡", "WHAT JUST HAPPENED",
                          f"The {lead['name']} is {('down' if d<0 else 'up')} {abs(d):.1f}% "
                          f"({lead['pts']:+,.0f} pts) in a session {risk}."))

    if shape and lead:
        op = (shape["open"] / lead["prev"] - 1) * 100
        L.append(_sec("🕘", "THE TIMELINE",
                      f"The {lead['name']} opened {op:+.1f}% vs the prior close, peaked near {shape['peak']:,.0f} at "
                      f"{_wrap_fmt_t(shape['t_peak'])}, then slid to {shape['trough']:,.0f} by {_wrap_fmt_t(shape['t_trough'])} "
                      f"({shape['dd_pct']:+.1f}%). It now trades at {shape['cur']:,.0f}."))

    # The same session facts as a GRID (user: "i asked to tabulate as much as you can").
    # The prose above stays — it explains; the table lets the numbers be compared without
    # re-reading a sentence to find them. Prose is the story, the table is the record.
    if lead:
        _sess = [("Prev close", f"{lead['prev']:,.0f}")] if lead.get("prev") else []
        if shape:
            _sess += [("Open", f"{(shape['open'] / lead['prev'] - 1) * 100:+.2f}%"),
                      ("Peak", f"{shape['peak']:,.0f}"),
                      ("Trough", f"{shape['trough']:,.0f}"),
                      ("Now", f"{shape['cur']:,.0f}"),
                      ("Peak→trough", f"{shape['dd_pct']:+.2f}%")]
        _sess += [("Day", f"{lead['pct']:+.2f}%"), ("Points", f"{lead['pts']:+,.0f}")]
        if lead.get("dollars"):
            _sess.append(("Value", _wrap_money(abs(lead["dollars"]))))
        L.append("\n" + _pipe_table(("Metric", "Value"), _sess, right_cols={1},
                                    title=f"📊 {str(lead['name'])[:14]} — SESSION"))

    # FOMC-today flag (user 2026-07-28: "where is today Fed meeting info, why that
    # missing" -- _FOMC_DATES already has the real schedule, the wrap just never checked
    # it against today's date). Mechanical facts only (announcement/press-conference
    # times) -- no rate-decision prediction, that's not something to fabricate.
    _today_iso = datetime.now().strftime("%Y-%m-%d")
    if _today_iso in _FOMC_DATES:
        L.append(_sec("🏛", "FOMC DECISION TODAY",
                      "Rate decision at 2:00pm ET, press conference 2:30pm ET. Historically the "
                      "highest-vol window of the session — expect wide intraday swings and a real "
                      "chance of a late-day reversal once the presser starts. Check /macro afterward."))

    # Full indices table -- "index is saying" (user 2026-07-28): the narrative above only
    # names the single biggest mover; the other 4 tracked indices were computed in F but
    # never actually shown anywhere.
    if F["indices"]:
        _idx_rows = [("🟢" if d["pct"] >= 0 else "🔴", d["name"], f"{d['last']:,.0f}", f"{d['pct']:+.2f}%")
                     for d in F["indices"]]
        L.append("\n" + _pipe_table(("", "Index", "Last", "Day%"), _idx_rows, right_cols={2, 3},
                                    title="📈 INDICES"))

    if F["catalyst"]:
        _cat_url = F["catalyst"].get("url")
        _cat_q = (f'<a href="{_cat_url}">"{esc(F["catalyst"]["title"])}"</a>' if _cat_url
                  else f'"{esc(F["catalyst"]["title"])}"')
        big = next((m for m in (F["movers_dn"] + F["movers_up"]) if m["t"] == F["catalyst"]["ticker"]), None)
        if big:
            line = (f"{big['t']} moved {big['pct']:+.1f}% — the session's standout — on the headline: "
                    f"{_cat_q}.")
        else:
            line = f"A key catalyst: {F['catalyst']['ticker']} — {_cat_q}."
        L.append(_sec("📰", "THE CATALYST", line))

    if F["vix"]:
        v = F["vix"]
        tone = "spiking — fear is back" if v["pct"] > 8 else "rising" if v["pct"] > 0 else "easing"
        L.append(_sec("🌪", "VOLATILITY",
                      f"The VIX is at {v['last']:.1f} ({v['pct']:+.1f}%), {tone}. "
                      + ("Above 20 signals real stress." if v["last"] >= 20 else "Still contained below 20.")))

    if F.get("macro"):
        m = F["macro"]
        bits = [f"{k} {m[k]['yoy']:.1f}% YoY ({m[k]['month']})" for k in ("CPI", "Core CPI") if k in m]
        if bits:
            hot = m.get("CPI", {}).get("yoy", 0)
            vs = "well above" if hot >= 3 else "above" if hot > 2.3 else "near"
            L.append(_sec("📅", "MACRO BACKDROP",
                          f"Inflation backdrop: {', '.join(bits)} — {vs} the Fed's 2% target."))

    if F.get("regime"):
        L.append(_sec("🧭", "MACRO REGIME", F["regime"] + "."))

    # Major world events -- war/attack/climate-disaster headlines (user 2026-07-28: "add
    # if anything else also helps, important news like wars, bombings, climate severities
    # etc"). Broader net than _country_instability_flags (which is ticker-supply-chain
    # scoped) -- this is a general world-event scan, keyless, reuses _world_news_block.
    try:
        _severe = _wrap_severe_news()
    except Exception:
        _severe = []
    if _severe:
        _sev_lines = [f'• <a href="{u}">{esc(hl[:110])}</a>' if u else f"• {esc(hl[:110])}"
                     for _cat, hl, u in _severe]
        L.append("\n🌍 " + b("MAJOR WORLD EVENTS") + "\n" + "\n".join(_sev_lines))

    if F["cross"]:
        parts = []
        for c in F["cross"]:
            if c["kind"] == "rates":
                parts.append(f"the 10Y yield {('rose' if c['pct']>0 else 'fell')} to {c['last']:.2f}%")
            else:
                parts.append(f"{c['name']} {c['pct']:+.1f}%")
        L.append(_sec("🌐", "CROSS-ASSET", "Contagion check — " + "; ".join(parts) + "."))
        # …and the same check as a grid, so the assets can be scanned side by side rather
        # than parsed out of a semicolon list.
        _xr = [("🟢" if c["pct"] > 0 else "🔴" if c["pct"] < 0 else "🟡",
                str(c["name"])[:9],
                (f"{c['last']:.2f}%" if c["kind"] == "rates" else f"{c['last']:,.2f}"),
                f"{c['pct']:+.2f}%") for c in F["cross"]]
        L.append("\n" + _pipe_table(("ST", "Asset", "Last", "Day%"), _xr,
                                    right_cols={2, 3}, title="🌐 CROSS-ASSET"))

    lev_lines = []
    _lev_tbl = ""
    if F["lev"]:
        # Levered ETFs as a TABLE, not prose (user 2026-07-23) — one row per fund reads far
        # faster than a sentence naming only the worst, and it shows the whole complex.
        _lr = [("🔴" if x["pct"] < 0 else "🟢", x["sym"][:5], f"{x['mult']}x",
                f"{x['pct']:+.2f}%") for x in sorted(F["lev"], key=lambda x: x["pct"])]
        _lev_tbl = _pipe_table(("ST", "ETF", "Lev", "Day%"), _lr, right_cols={3},
                               title="🎰 LEVERAGED ETFs",
                               legend="3x funds magnify every swing — record AUM means vol begets vol")
    if F["options"]:
        o = F["options"]
        flow = ("put-heavy (hedging/bearish)" if (o["put_chg"] or 0) > (o["call_chg"] or 0)
                else "call-heavy (bullish/chasing)")
        pcr = f", market PCR {o['pcr']:.2f}" if o.get("pcr") else ""
        ph = ", ".join(o["put_heavy"]) if o.get("put_heavy") else "—"
        lev_lines.append(f"Options flow is {flow}: net ΔOI calls {o['call_chg']:+,.0f} / puts {o['put_chg']:+,.0f}{pcr}. "
                         f"Heaviest put builds: {ph}.")
    if _lev_tbl:
        L.append("\n" + _lev_tbl)
    if lev_lines:
        L.append("\n🎰 " + b("POSITIONING") + "\n" + " ".join(lev_lines))

    if F["breadth"]:
        br = F["breadth"]
        tilt = "risk-off" if br["dn"] > br["up"] else "risk-on" if br["up"] > br["dn"] else "mixed"
        ups = ", ".join(f"{m['t']} {m['pct']:+.1f}%" for m in F["movers_up"][:3])
        dns = ", ".join(f"{m['t']} {m['pct']:+.1f}%" for m in F["movers_dn"][:3])
        L.append("\n📊 " + b("BREADTH & MOVERS") + "\n"
                 f"{br['up']}/{br['n']} names green, {br['dn']} red — a {tilt} tape. "
                 f"Leaders: {ups}. Laggards: {dns}.")

    if F["book"] and F["book"]["tickers"]:
        bl = []
        helped_n = 0
        for t in F["book"]["tickers"]:
            helped = (t["pct"] > 0) == (t["dir"] >= 0)
            helped_n += helped
            bl.append(f"{t['tk']} {t['pct']:+.1f}% ({'tailwind' if helped else 'headwind'})")
        L.append("\n💼 " + b("YOUR BOOK") + "\n"
                 f"Your open names today: {', '.join(bl)}. Net directional exposure is being "
                 + ("helped" if helped_n >= len(F["book"]["tickers"]) / 2 else "pressured") + " by the move.")

    closers = ["Volatility always comes with change.",
               "Record leverage + rising uncertainty = swings are here to stay.",
               "When everyone is positioned one way, the exit gets narrow.",
               "Opportunity lives in the broadening swings — if you respect the risk."]
    _closer_plain = {
        "Volatility always comes with change.":
            "Big moves mean the market is repricing something — expect more two-way swings and trade smaller.",
        "Record leverage + rising uncertainty = swings are here to stay.":
            "Lots of borrowed money in the market magnifies every move, so violent days like this get more frequent.",
        "When everyone is positioned one way, the exit gets narrow.":
            "When almost everyone is on the SAME side (all long, or all short), a reversal forces them all to sell at once — but there are few buyers left to sell to, so the drop is fast and steep. Translation: don't be the last one crowded into a popular trade.",
        "Opportunity lives in the broadening swings — if you respect the risk.":
            "Wider swings = bigger chances in both directions, but only worth taking if you cap your downside first.",
    }
    _cl = _wrap_pick(seed + 2, closers)
    L.append("\n— " + _cl)
    if _closer_plain.get(_cl):
        L.append("<i>💡 In plain terms: " + _closer_plain[_cl] + "</i>")
    return "\n".join(L)


def _wrap_chart_png(F):
    """Intraday line of the lead index with open / peak / trough markers."""
    lead = F.get("lead")
    if not lead:
        return None
    h = _wrap_hist(lead["sym"], "1d", "5m")
    if h is None or len(h) < 3:
        return None
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    sh = F.get("shape") or {}
    fig, ax = plt.subplots(figsize=(9, 4.4))
    ax.plot(h.index, h["Close"], color="#3d8bff", lw=1.8)
    ax.axhline(lead["prev"], color="gray", ls="--", lw=0.9, label=f"Prev close {lead['prev']:,.0f}")
    if sh.get("t_peak") is not None:
        ax.scatter([sh["t_peak"]], [sh["peak"]], color="#2e7d32", zorder=5, label=f"Peak {sh['peak']:,.0f}")
    if sh.get("t_trough") is not None:
        ax.scatter([sh["t_trough"]], [sh["trough"]], color="#c62828", zorder=5, label=f"Trough {sh['trough']:,.0f}")
    ax.fill_between(h.index, h["Close"], lead["prev"],
                    where=(h["Close"] >= lead["prev"]), alpha=0.15, color="green")
    ax.fill_between(h.index, h["Close"], lead["prev"],
                    where=(h["Close"] < lead["prev"]), alpha=0.15, color="red")
    ax.set_title(f"{lead['name']} — today ({lead['pct']:+.1f}%)", fontsize=11)
    ax.set_ylabel("Index level"); ax.grid(True, alpha=0.3); ax.legend(fontsize=8)
    import matplotlib.dates as mdates
    ax.xaxis.set_major_formatter(mdates.DateFormatter("%H:%M"))
    plt.tight_layout()
    buf = BytesIO(); fig.savefig(buf, format="png", dpi=110, bbox_inches="tight")
    plt.close(fig); buf.seek(0)
    return buf


def _kb_wrap():
    return InlineKeyboardMarkup([[InlineKeyboardButton("🔄 Refresh", callback_data="wrap_view"),
                                  InlineKeyboardButton("⬅️ Menu", callback_data="menu_main")]])


def _eod_digest(conn, max_news=5, max_uoa=8, max_plays=6, edition="evening"):
    """/digest — newsletter built ONLY from things this repo actually has.

    `edition` shifts the emphasis rather than the sources, because what is KNOWN differs
    by time of day (user 2026-08-03):
      morning  — overnight news + today's catalysts + the setups that qualify. Written
                 before the open, so it leads with what to watch, not what happened.
      midday   — what has actually moved and whether the morning read is holding. Skips
                 the setup list: the recs are built off EOD chains and do not change
                 intraday, so re-printing them at noon would imply a freshness they lack.
      evening  — the full EOD wrap (unchanged default).

    Modelled on the InsiderFinance EOD format (tracker ID 37). Four of its five sections
    are buildable here; the fifth ("AI Noteworthy Trades") needs a real-time options TAPE
    — individual prints with time and aggressor side — which no free source gives us, and
    faking it from EOD volume would be a different thing wearing its name. It is omitted
    rather than approximated.

    Every section states what it is worth. Rotation carries a measured result; unusual
    activity does NOT (scn_uoa hit 47.1%, i.e. noise) and says so; POP is model output,
    not a validated probability. See docs/ADOPTED.md Part 9.
    """
    _ed = str(edition).lower()
    _TITLES = {"morning": "☀️ MORNING EDGE", "midday": "🕛 MIDDAY CHECK",
               "evening": "📰 EOD DIGEST", "news": "🚨 NEWS BREAK"}
    _SUBS = {
        "morning": "Overnight news, today's catalysts, and what qualifies before the open.",
        "midday": "What has actually moved, and whether the morning read is holding.",
        "evening": "",
        "news": "Fired off a large move — context, not a recommendation.",
    }
    parts = [hdr(_TITLES.get(_ed, "📰 DIGEST")), ""]
    if _SUBS.get(_ed):
        parts.append(f"<i>{_SUBS[_ed]}</i>")
        parts.append("")

    # ── 1. headlines ──────────────────────────────────────────────────────────────
    try:
        news = _world_news_block(limit=max_news * 3) or []
    except Exception:
        news = []
    # The RSS mix carries MarketWatch/Yahoo personal-finance advice columns ("Can she claim
    # her late husband's Social Security...") alongside real market copy. In a MARKET digest
    # those are noise, so drop the obvious ones rather than pad the section with them.
    _PF = ("social security", "my husband", "my wife", "my girlfriend", "my boyfriend",
           "my son", "my daughter", "my mother", "my father", "should i tip", "in our 60s",
           "in our 70s", "retirement account", "dear ", "i'm ", "we're in our")
    news = [n for n in news
            if not any(w in str(n[0] if isinstance(n, (tuple, list)) else n).lower()
                       for w in _PF)]
    # WORLD section first: the US equity wires do not carry BoJ/yen intervention or strikes
    # on Ukraine, which is why the brief never mentioned them (user 2026-08-07, ID 92).
    try:
        _geo = _fmt_geo_news()
        if _geo:
            parts.append(_geo)
            parts.append("")
    except Exception:
        log.debug("geo news block failed", exc_info=True)
    parts.append(shdr("1 · What moved the tape"))
    if news:
        for n in news[:max_news]:
            # `_world_news_block` yields (headline, source, url) tuples — not dicts
            if isinstance(n, (tuple, list)):
                h = str(n[0] if len(n) > 0 else "").strip()
                src = str(n[1] if len(n) > 1 else "").strip()
                u = str(n[2] if len(n) > 2 else "").strip()
            elif isinstance(n, dict):
                h = str(n.get("headline") or n.get("title") or "").strip()
                src = str(n.get("source") or "").strip()
                u = str(n.get("url") or n.get("link") or "").strip()
            else:
                h, src, u = str(n).strip(), "", ""
            if not h:
                continue
            tag = f" <i>({src})</i>" if src else ""
            parts.append(f"• <a href=\"{u}\">{h[:110]}</a>{tag}" if u else f"• {h[:110]}{tag}")
    else:
        parts.append("<i>News feed unavailable right now.</i>")
    parts.append("")

    # ── 2. sector rotation ────────────────────────────────────────────────────────
    parts.append(shdr("2 · Where money is rotating"))
    try:
        _title, rows = _rotation_scan(conn, level="sector")
    except Exception:
        rows = []
    if rows:
        # _rotation_scan rows carry `name` (human label) and `tk` — there is no `item` key
        _q = {}
        for r in rows:
            _q.setdefault(str(r.get("quad", "?")), []).append(
                str(r.get("name") or r.get("tk") or "?"))
        trs = [(k, ", ".join(v[:5])[:44]) for k, v in _q.items()]
        parts.append(_pipe_table(("Quadrant", "Sectors"), trs))
        parts.append("<i>Backtested (1,542 obs): <b>Weakening</b> underperforms −1.6%/10d "
                     "vs SPY. That quadrant read is the only rotation claim that survived "
                     "re-testing — the momentum-axis IC claim was withdrawn.</i>")
    else:
        parts.append("<i>Not enough history for a rotation read.</i>")
    parts.append("")

    # ── 3. today's option setups ──────────────────────────────────────────────────
    parts.append(shdr("3 · Option setups on the board"))
    try:
        d0 = conn.execute("SELECT MAX(rec_date) FROM hiprob_recs WHERE src='LIVE'").fetchone()[0]
        recs = conn.execute(
            "SELECT ticker, strategy, legs, expiry, pop, net, capital FROM hiprob_recs "
            # capital>0: a handful of legacy CSP rows persisted capital 0 (the bug fixed in
            # 5c76fe7). A row showing "$0 capital" in a digest reads as a free trade.
            "WHERE rec_date=? AND src='LIVE' AND status='OPEN' AND capital>0 "
            "ORDER BY pop DESC LIMIT ?", (d0, max_plays)).fetchall() if d0 else []
    except Exception:
        d0, recs = None, []
    if recs:
        rr = [(str(t)[:6], str(l)[:11], f"{float(p or 0):.0f}%", f"${float(c or 0):,.0f}")
              for t, s, l, e, p, n, c in recs]
        parts.append(_pipe_table(("Tkr", "Legs", "POP", "Capital"), rr, right_cols={2, 3},
                                 title=f"Issued {d0}"))
        parts.append("<i>POP is Black-Scholes model output, NOT a validated probability, and "
                     "a high win rate is not an edge: a trade only pays if credit/width > "
                     "(1−POP). Credits are quoted at a realistic fill, not the mid.</i>")
    else:
        parts.append("<i>No live setups issued today.</i>")
    parts.append("")

    # ── 4. unusual activity ───────────────────────────────────────────────────────
    parts.append(shdr("4 · Unusual options activity"))
    try:
        u = _uoa_scan(conn, top=max_uoa)
        urows = u if isinstance(u, list) else (u.to_dict("records") if hasattr(u, "to_dict") else [])
    except Exception:
        urows = []
    if urows:
        # _uoa_scan rows: ticker / strike / side ('C'|'P') / ratio / notional
        ur = []
        for r in urows[:max_uoa]:
            if not isinstance(r, dict):
                continue
            ur.append((str(r.get("ticker", ""))[:6],
                       "CALL" if str(r.get("side", "")).upper().startswith("C") else "PUT",
                       f"{float(r.get('strike') or 0):g}",
                       f"{float(r.get('ratio') or 0):.1f}x",
                       f"${float(r.get('notional') or 0)/1e6:,.0f}M"))
        parts.append(_pipe_table(("Tkr", "Type", "Strike", "V/OI", "Notional"), ur,
                                 right_cols={2, 3, 4}))
        parts.append("<i>⚠️ Descriptive only — NOT predictive. The scn_uoa scanner hit 47.1% "
                     "(coin-flip) over 204 fires, and once same-day fires stop double-counting "
                     "there is no edge either way. Read it as what happened, never as a signal.</i>")
    else:
        parts.append("<i>No unusual activity above threshold.</i>")

    parts.append("")
    parts.append("<i>Omitted on purpose: a real-time 'noteworthy trades' tape. That needs "
                 "per-print time-and-sales with the aggressor side, which no free feed "
                 "provides — approximating it from EOD volume would be a different thing "
                 "wearing its name.</i>")
    return "\n".join(parts)



async def _digest_push(ctx, txt):
    """Send a digest to the configured chat, chunked to Telegram's limit."""
    try:
        _, chat_id = load_creds()
    except Exception:
        log.warning("digest push: no creds"); return
    for _part in _chunk_on_sections(txt):
        try:
            await ctx.bot.send_message(chat_id=int(chat_id), text=_part,
                                       parse_mode=H, disable_web_page_preview=True)
        except Exception:
            log.warning("digest push failed", exc_info=True); return


