def _rotation_scan(conn, level="sector", tickers=None, bench="SPY", long_win=63, short_win=21):
    """RRG-style rotation for any level. Universal (DB-first history, yfinance backfill).
    Returns list of dicts sorted by quadrant then strength."""
    if tickers:
        items = {t.upper(): t.upper() for t in tickers}
        title = "Stocks"
    else:
        title, items = _ROT_LEVELS.get(level, _ROT_LEVELS["sector"])
    bh = _daily_history(bench, 1, conn)
    if bh is None or len(bh) <= long_win + 1:
        return title, []
    bl = list(bh)
    bL = bl[-1] / bl[-long_win - 1] - 1
    bS = bl[-1] / bl[-short_win - 1] - 1
    rows = []
    for tk, name in items.items():
        h = _daily_history(tk, 1, conn)
        if h is None or len(h) <= long_win + 1:
            continue
        s = list(h)
        strength = (s[-1] / s[-long_win - 1] - 1) - bL          # 3mo excess vs benchmark
        short_exc = (s[-1] / s[-short_win - 1] - 1) - bS         # 1mo excess
        momentum = short_exc - strength / (long_win / short_win)  # recent pace vs trailing → improving?
        if strength >= 0 and momentum >= 0:
            quad, emoji = "Leading", "🟢"
        elif strength >= 0 and momentum < 0:
            quad, emoji = "Weakening", "🟡"
        elif strength < 0 and momentum >= 0:
            quad, emoji = "Improving", "🔵"
        else:
            quad, emoji = "Lagging", "🔴"
        rows.append({"tk": tk, "name": name, "strength": strength, "momentum": momentum,
                     "short_exc": short_exc, "quad": quad, "emoji": emoji})
    order = {"Improving": 0, "Leading": 1, "Weakening": 2, "Lagging": 3}
    rows.sort(key=lambda r: (order[r["quad"]], -r["strength"]))
    return title, rows


def _ensure_rotation_watch(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS rotation_watch (
        trade_date TEXT, level TEXT, item TEXT, quad TEXT, strength REAL, momentum REAL,
        PRIMARY KEY (trade_date, level, item))""")
    conn.commit()


def _rotation_track(conn, level, rows):
    """Log today's quadrants once/day; return items that just CHANGED quadrant (fresh rotation)."""
    import datetime as _dt
    _ensure_rotation_watch(conn)
    today = _dt.date.today().isoformat()
    prev = conn.execute("SELECT MAX(trade_date) FROM rotation_watch WHERE level=? AND trade_date<?",
                        (level, today)).fetchone()[0]
    prevq = {}
    if prev:
        prevq = {r[0]: r[1] for r in conn.execute(
            "SELECT item, quad FROM rotation_watch WHERE level=? AND trade_date=?", (level, prev)).fetchall()}
    changes = []
    for r in rows:
        if prevq.get(r["tk"]) and prevq[r["tk"]] != r["quad"]:
            changes.append((r["name"], prevq[r["tk"]], r["quad"]))
        try:
            conn.execute("INSERT OR REPLACE INTO rotation_watch "
                         "(trade_date, level, item, quad, strength, momentum) VALUES (?,?,?,?,?,?)",
                         (today, level, r["tk"], r["quad"], r["strength"], r["momentum"]))
        except Exception:
            pass
    conn.commit()
    return changes


def _fmt_rotation(title, rows, changes=None):
    """Mobile-safe rotation readout: IN/OUT calls + quadrant table."""
    if not rows:
        return f"🔄 <b>Rotation — {title}</b>\nNot enough history to compute."
    inn = [r for r in rows if r["quad"] == "Improving"]
    out = [r for r in rows if r["quad"] == "Weakening"]
    lead = [r for r in rows if r["quad"] == "Leading"]
    lag = [r for r in rows if r["quad"] == "Lagging"]
    rd = [(r["emoji"], r["name"], f"{r['strength']*100:+.0f}", f"{r['short_exc']*100:+.0f}") for r in rows]
    table = _pipe_table(("", "Name", "3mo", "1mo"), rd, right_cols={2, 3},
                        legend="vs SPY · 3mo=leadership · 1mo=recent · 🔵in 🟢lead 🟡out 🔴lag")
    parts = [f"🔄 <b>Rotation — {title}</b>  <i>(money flow vs SPY)</i>"]
    if title.startswith("Asset"):        # cross-asset risk-on/off tilt
        dfn = [r["short_exc"] for r in rows if r["tk"] in ("TLT", "GLD", "UUP")]
        off = [r["short_exc"] for r in rows if r["tk"] in ("QQQ", "IWM", "EEM", "HYG", "IBIT")]
        if dfn and off:
            tilt = ("🔴 RISK-OFF — defensives (bonds/gold/$) leading"
                    if sum(dfn) / len(dfn) > sum(off) / len(off)
                    else "🟢 RISK-ON — growth/credit/crypto leading")
            parts.append(f"⚖️ <b>Cross-asset tilt:</b> {tilt}")
    parts += [f"🔵 <b>Rotating IN</b> (gaining): {', '.join(r['name'] for r in inn) or '—'}",
              f"🟡 <b>Rotating OUT</b> (fading leaders): {', '.join(r['name'] for r in out) or '—'}",
              table]
    if changes:
        parts.append("↪️ <b>Just shifted:</b> " + " · ".join(f"{n} {a}→{b}" for n, a, b in changes[:6]))
    parts.append("<i>🔵 Improving=money entering · 🟡 Weakening=money leaving. Backtested: "
                 "Weakening underperforms (−1.6%/10d vs SPY, momentum IC +0.14, p&lt;1e-7). Not advice.</i>")
    return "\n\n".join(parts)


async def _do_rotation(msg, level, tickers=None):
    conn = get_conn()
    try:
        title, rows = _rotation_scan(conn, level, tickers)
        changes = _rotation_track(conn, level if not tickers else "stocks", rows) if rows else []
    finally:
        conn.close()
    kb = InlineKeyboardMarkup([
        [InlineKeyboardButton("🌐 Macro", callback_data="rot_macro"),
         InlineKeyboardButton("🏭 Sectors", callback_data="rot_sector"),
         InlineKeyboardButton("🎯 Themes", callback_data="rot_theme")],
        [InlineKeyboardButton("⬅️ Menu", callback_data="menu_main")]])
    await msg.reply_text(_fmt_rotation(title, rows, changes)[:4000], parse_mode=H, reply_markup=kb)


async def rotation_command(update, ctx):
    """/rotation [macro|sector|theme|TICKERS] — where money is rotating (RRG, high→low)."""
    args = [a for a in (getattr(ctx, "args", []) or [])]
    level = "sector"; tickers = None
    if args:
        a0 = args[0].lower()
        if a0 in _ROT_LEVELS:
            level = a0
        elif a0 in ("stock", "stocks"):
            tickers = [a.upper() for a in args[1:]] or _AB_UNIVERSE[:30]
        else:
            tickers = [a.upper() for a in args]
    await update.message.reply_text(f"🔄 Mapping rotation…", parse_mode=H)
    await _do_rotation(update.message, level, tickers)


async def rotation_view(query, level="sector"):
    await _do_rotation(query.message, level)


# ── Spreads scanner (Bull Call · Bear Call · Bear Put · Bull Put), composite-scored ──────
def _spreads_scan_bot(tickers, dte_lo=20, dte_hi=45, r=0.045, top_per=4):
    """Ranked vertical spreads. Returns list of structured dicts (rendered by _send_spreads)."""
    import datetime as _dt
    from scipy.stats import norm as _nm

    def _pa(S, X, T, iv):
        if min(S, X, T, iv) <= 0:
            return None
        return float(_nm.cdf((np.log(S / X) + (r - 0.5 * iv * iv) * T) / (iv * np.sqrt(T))))

    rows = []
    for tk in tickers:
        tk = str(tk).strip().upper()
        if not tk:
            continue
        try:
            t = yf.Ticker(tk)
            spot = _last_price(tk) or float(t.history(period="1d")["Close"].iloc[-1])
            if not spot:
                continue
            exp = dte = None
            for e in (t.options or []):
                try:
                    d = (_dt.datetime.strptime(e, "%Y-%m-%d").date() - _dt.date.today()).days
                except Exception:
                    continue
                if dte_lo <= d <= dte_hi:
                    exp, dte = e, d
                    break
            if not exp:
                continue
            T = max(dte, 1) / 365.0
            ch = t.option_chain(exp)
            calls = ch.calls.copy(); puts = ch.puts.copy()
            for df, _is_call in ((calls, True), (puts, False)):
                df["mid"] = ((df["bid"].fillna(0) + df["ask"].fillna(0)) / 2).where(
                    (df["bid"] > 0) & (df["ask"] > 0), df["lastPrice"])
                df["oi"] = df["openInterest"].fillna(0) if "openInterest" in df.columns else 0
                # A RECOMMENDED LEG MUST HAVE A LIVE TWO-SIDED MARKET (ID 300).
                #
                # The mid above falls back to lastPrice when a strike has no bid/ask, and for
                # deep-ITM strikes there often IS no market: measured on SPY 2026-09-11 with
                # spot 765, strikes 680/685/690/694 all had bid=0 ask=0, and their stale
                # lastPrice prints were 88.46 / 85.65 / 85.63 / 85.26 -- four strikes spanning
                # 14 points, all priced within 3 of each other, because each print is from a
                # different moment. Differencing two of those gave a 680/690 "debit" of 2.83
                # for a 10-wide payoff at ~100% POP: free money that does not exist. The POP
                # was correct; the price was fiction.
                #
                # An intrinsic-value floor does NOT catch this -- every one of those prints is
                # above intrinsic. The honest test is whether anyone is quoting the strike at
                # all. lastPrice stays fine for DISPLAY; it must never price a trade.
                _live = (df["bid"].fillna(0) > 0) & (df["ask"].fillna(0) > 0)
                # Belt and braces: a call can never trade below max(0, S-K), nor a put below
                # max(0, K-S). Anything that does is stale even with a quote present.
                _intr = ((spot - df["strike"]) if _is_call else (df["strike"] - spot)).clip(lower=0.0)
                _bad = (~_live) | (df["mid"] < _intr * 0.98)
                if _bad.any():
                    log.debug("spreads: dropped %d unquoted/stale %s leg(s) on %s %s",
                              int(_bad.sum()), "call" if _is_call else "put", tk, exp)
                df.loc[_bad, "mid"] = 0.0                    # falls out at the mid > 0.02 gate

            def _near(df):
                d = df[(df["mid"] > 0.02) & (df["strike"] >= spot * 0.85) & (df["strike"] <= spot * 1.15)]
                return d.sort_values("strike").reset_index(drop=True).to_dict("records")
            C = _near(calls); P = _near(puts)
            cand = []
            # yfinance per-strike IV is GARBAGE here (often ~1e-5 for OTM), which collapses the
            # POP calc to ~100% (audit 2026-07-21). Back a reliable vol out of the ATM call mid
            # (mids ARE reliable); HV/0.40 fallback; floor 0.10. Use it for ALL strikes' POP.
            iv_ref = 0.40
            try:
                _atmrow = min(C, key=lambda x: abs(x["strike"] - spot)) if C else None
                if _atmrow and _atmrow.get("mid", 0) > 0:
                    _iv = _implied_vol_hp(_atmrow["mid"], spot, _atmrow["strike"], T, r)
                    if _iv and 0.05 < _iv < 3.0:
                        iv_ref = _iv
            except Exception:
                pass
            iv_ref = max(iv_ref, 0.10)

            def add(strat, emoji, legs, net, width, be, pop, oi_min, direction):
                if net is None or net <= 0 or width <= 0 or pop is None or not (0 < pop < 1):
                    return
                maxp, maxl = (width - net, net) if direction == "debit" else (net, width - net)
                if maxp <= 0.05 or maxl <= 0.05:   # drop worthless far-OTM / zero-payoff legs
                    return
                if direction == "credit" and net / width < 0.05:   # collect >=5% of width
                    return
                rr = maxp / maxl
                if rr < 0.10:   # drop near-zero-reward degenerate spreads
                    return
                cushion = abs(be - spot) / spot
                sc = 100 * (0.40 * pop + 0.25 * min(rr, 2) / 2 + 0.20 * min(cushion, 0.10) / 0.10 + 0.15 * min(oi_min, 500) / 500)
                cand.append((sc, strat, {
                    "sc": sc, "strat": strat, "emoji": emoji, "tk": tk, "legs": legs,
                    "dte": dte, "pop": pop * 100, "rr": rr, "net": net,
                    "dir": direction, "be": be, "maxp": maxp, "maxl": maxl}))

            for i in range(len(C)):
                for j in range(i + 1, min(i + 5, len(C))):
                    a, b = C[i], C[j]
                    width = b["strike"] - a["strike"]
                    oi_min = min(a["oi"] or 0, b["oi"] or 0); net = a["mid"] - b["mid"]; be = a["strike"] + net
                    add("Bull Call", "🟢", f"{a['strike']:g}/{b['strike']:g}C", net, width, be, _pa(spot, be, T, iv_ref), oi_min, "debit")
                    pa = _pa(spot, be, T, iv_ref)
                    add("Bear Call", "🔴", f"{a['strike']:g}/{b['strike']:g}C", net, width, be, (None if pa is None else 1 - pa), oi_min, "credit")
            for i in range(len(P)):
                for j in range(i + 1, min(i + 5, len(P))):
                    a, b = P[i], P[j]
                    width = b["strike"] - a["strike"]
                    oi_min = min(a["oi"] or 0, b["oi"] or 0); net = b["mid"] - a["mid"]; be = b["strike"] - net
                    pa = _pa(spot, be, T, iv_ref)
                    add("Bear Put", "🟣", f"{b['strike']:g}/{a['strike']:g}P", net, width, be, (None if pa is None else 1 - pa), oi_min, "debit")
                    # Bull Put (put CREDIT spread) — the missing 4th vertical. Same two
                    # strikes as the Bear Put and the same breakeven, but sold instead of
                    # bought, so it profits when price stays ABOVE be => POP is `pa`
                    # itself, NOT 1-pa. The engine already produces these (80 rows of
                    # "Put credit spread" in hiprob_recs); only the scanner omitted them.
                    add("Bull Put", "🔵", f"{b['strike']:g}/{a['strike']:g}P", net, width, be,
                        pa, oi_min, "credit")

            cand.sort(key=lambda z: -z[0])
            seen = {}
            for sc, strat, row in cand:
                seen.setdefault(strat, 0)
                if seen[strat] < top_per:
                    rows.append((sc, row)); seen[strat] += 1
        except Exception:
            continue
    rows.sort(key=lambda z: -z[0])
    return [r for _, r in rows]


