# ── Wheel / CSP screener (annualized yield vs assignment risk) ────────────────
def _wheel_scan_bot(tickers, dte_lo=20, dte_hi=45, r=0.045, otm_max=0.18, conn=None):
    """Cash-secured-put income optimizer. Returns structured, ranked rows.
    Score blends POP (no assignment), annualized yield, credit cushion, and
    IV-rank (only worth selling when premium is rich). Flags earnings before
    expiry (gap/assignment risk) with a score haircut. `conn` enables the
    DB-based IV-rank + earnings enrichment; None degrades gracefully."""
    import datetime as _dt
    from scipy.stats import norm as _nm

    def _pa(S, X, T, iv):
        if min(S, X, T, iv) <= 0:
            return None
        return float(_nm.cdf((np.log(S / X) + (r - 0.5 * iv * iv) * T) / (iv * np.sqrt(T))))

    rows = []
    for tk in tickers:
        tk = str(tk).strip().upper()
        if not tk:
            continue
        try:
            t = yf.Ticker(tk)
            spot = _last_price(tk) or float(t.history(period="1d")["Close"].iloc[-1])
            if not spot:
                continue
            exp = dte = None
            for e in (t.options or []):
                try:
                    d = (_dt.datetime.strptime(e, "%Y-%m-%d").date() - _dt.date.today()).days
                except Exception:
                    continue
                if dte_lo <= d <= dte_hi:
                    exp, dte = e, d
                    break
            if not exp:
                continue
            # Per-ticker enrichment (once): IV-rank (rich premium?) + earnings window.
            ivr = None
            if conn is not None:
                try:
                    _ivr = _iv_rank(conn, tk)
                    ivr = _ivr.get("rank") if _ivr else None
                except Exception:
                    ivr = None
            earn_days = None
            try:
                _ne = _next_earnings(tk)
                earn_days = _ne.get("days") if _ne else None
            except Exception:
                earn_days = None
            earn_flag = earn_days is not None and earn_days <= dte

            T = max(dte, 1) / 365.0
            ch = t.option_chain(exp)
            puts = ch.puts.copy()
            puts["mid"] = ((puts["bid"].fillna(0) + puts["ask"].fillna(0)) / 2).where(
                (puts["bid"] > 0) & (puts["ask"] > 0), puts["lastPrice"])
            pl = puts[(puts["strike"] < spot) & (puts["strike"] >= spot * (1 - otm_max)) & (puts["mid"] > 0.03)]
            # reliable ATM vol — yfinance per-strike IV is garbage (~1e-5) which collapsed CSP POP
            # to ~100% (audit 2026-07-21). Back it out of the ATM put mid; floor 0.10.
            iv_ref = 0.40
            try:
                _at = puts.iloc[(puts["strike"] - spot).abs().argsort()[:1]]
                if len(_at) and float(_at["mid"].iloc[0]) > 0:
                    _iv = _implied_vol_hp(float(_at["mid"].iloc[0]), spot, float(_at["strike"].iloc[0]), T, r)
                    if _iv and 0.05 < _iv < 3.0:
                        iv_ref = _iv
            except Exception:
                pass
            iv_ref = max(iv_ref, 0.10)
            for _, row in pl.iterrows():
                K = float(row["strike"]); cr = float(row["mid"]); iv = iv_ref
                pop = _pa(spot, K, T, iv)
                if pop is None:
                    continue
                ann = (cr / K) * (365.0 / max(dte, 1))
                be = K - cr
                # Optimizer score: POP + annualized yield + cushion + IV-rank richness.
                sc = 100 * (0.40 * pop + 0.30 * min(ann, 1.0)
                            + 0.15 * min(cr / spot, 0.05) / 0.05
                            + 0.15 * (ivr if ivr is not None else 40) / 100)
                if earn_flag:
                    sc *= 0.85     # haircut: earnings before expiry = gap/assignment risk
                rows.append({
                    "score": sc, "ticker": tk, "strike": K, "dte": dte, "expiry": exp,
                    "credit": cr, "ann": ann, "pop": pop, "be": be,
                    "cushion": (spot - be) / spot, "capital": K * 100,
                    "ivr": ivr, "earn_days": earn_days, "earn_flag": earn_flag,
                })
        except Exception:
            continue
    rows.sort(key=lambda z: -z["score"])
    return rows


