    if not rows:
        await msg.reply_text("No covered calls passed the filters. Try <code>/cc NVDA AAPL MSFT</code>.", parse_mode=H)
        return
    _hdrs = ("ST", "Tkr", "Call", "Yr%", "POP")
    _data = []
