async def riskoff_alert(ctx: ContextTypes.DEFAULT_TYPE):
    """Auto Market Radar push — fires once on bot startup and daily post-close.
    Two gauges: TURBULENCE (index put-flow → move size; the backtested signal) +
    a soft DIRECTION lean. Startup run always sends; the daily run only pushes when
    move risk is above normal (turbulence ELEVATED/HIGH) to avoid quiet-day noise
    (gate via job.data['gate'])."""
    conn = get_conn()
    try:
        res = _riskoff_scan(conn)
    except Exception as e:
        log.warning(f"riskoff_alert scan failed: {e}")
        return
    finally:
        conn.close()
    gate = bool(getattr(getattr(ctx, "job", None), "data", None) or {})  # daily job passes {'gate':True}
    if gate and res["turbulence"]["level"] == "NORMAL":
        return
    # Dedup ONLY the startup (non-gated) push so frequent restarts don't spam. The
    # daily post-close run (gate=True) is scheduled once/day and must always fire —
    # a separate key so an earlier startup push can't suppress the fresh-EOD readout.
    today_str = datetime.now(timezone.utc).replace(tzinfo=None).strftime("%Y-%m-%d")
    if not gate:
        dconn = get_conn()
        try:
            _ensure_alert_dedup_table(dconn)
            if _alert_already_sent(dconn, today_str, "market_radar_startup", "riskoff"):
                return
        finally:
            dconn.close()
