async def building_alert(ctx: ContextTypes.DEFAULT_TYPE):
    """Scheduled positioning streamer: push NEW Increasing/Confirmed builds once
    per day (dedup by ticker|bias|stage). Market-hours / weekday gated."""
    now_utc = datetime.now(timezone.utc).replace(tzinfo=None)
    if now_utc.weekday() >= 5:
        return
    hour_min = now_utc.hour * 60 + now_utc.minute
    if not (14 * 60 + 30 <= hour_min <= 21 * 60):
        return
    _, chat_id = load_creds()
    conn = get_conn()
    try:
        _ensure_alert_dedup_table(conn)
        _update_scanner_outcomes(conn)          # mature scn_* fires -> actual_ret/correct
        rows = _positioning_scan(conn)
        today_str = _et_now().date().isoformat()   # DST-aware ET date
        fresh = [r for r in rows if r["stage"] in ("I", "C")
                 and not _alert_already_sent(
                     conn, today_str, f"{r['ticker']}|{r['bias']}|{r['stage']}", "building")]
    except Exception as e:
        log.warning(f"building_alert scan failed: {e}")
        conn.close(); return
    finally:
        conn.close()
    if not fresh:
        return
    longs = [r for r in fresh if r["bias"] == "LONG"][:8]
    shorts = [r for r in fresh if r["bias"] == "SHORT"][:8]

    def _tbl(rs, title):
        _data = [("🟢" if r["bias"] == "LONG" else "🔴", r["ticker"],
                  f"{r['build_pct']*100:.0f}", r["stage"], f"{r['ret5']*100:+.1f}") for r in rs]
        return _pipe_table(("ST", "Tkr", "OI+%", "Stg", "5d%"), _data, right_cols={2, 4}, title=title)

    now_et = _et_now().replace(tzinfo=None)   # DST-aware (was fixed UTC-5)
    parts = [hdr(f"🧭 POSITIONING BUILDING · {now_et.strftime('%H:%M ET')}"),
             f"<i>{len(fresh)} new build(s) · Stg I=increasing / C=confirmed</i>"]
    if longs:
        parts.append(_tbl(longs, "LONGS BUILDING"))
    if shorts:
        parts.append(_tbl(shorts, "SHORTS BUILDING"))
    try:
        await ctx.bot.send_message(chat_id=int(chat_id), text="\n\n".join(parts), parse_mode=H)
    except Exception as e:
        log.warning(f"building_alert send failed: {e}")


# ── PORTFOLIO RISK OPTIMIZER (Aladdin-style, native, no dependency) ─
def _optimize_portfolio(conn, tickers, method="sharpe", max_w=0.35, years=3, rf=0.045):
    """Long-only portfolio weights from the stock_history covariance.
    method: sharpe (tangency ∝ Σ⁻¹(μ−rf)) · minvar (∝ Σ⁻¹1) · riskparity
    (inverse-vol). Caps each weight at max_w (iterative redistribute). Returns
    weights + annualised μ/σ/Sharpe. Uses years of DB history (no API if cached)."""
    wide = _history_matrix(tickers, max(years + 1, 3), conn)
    if wide is None or wide.empty:
        return None
    rets = wide.pct_change().iloc[1:]              # drop first all-NaN row
    rets = rets.tail(int(years * 252))
    rets = rets.dropna(axis=1, how="any")          # keep tickers fully populated in window
    cols = [c for c in rets.columns]
    if len(cols) < 2 or len(rets) < 60:
        return None
    R = rets[cols].to_numpy()
    mu = R.mean(axis=0) * 252
    cov = np.cov(R, rowvar=False) * 252
    n = len(cols)
    try:
        inv = np.linalg.pinv(cov)
    except Exception:
        return None
    if method == "minvar":
        w = inv @ np.ones(n)
    elif method in ("riskparity", "rp"):
        vol = np.sqrt(np.clip(np.diag(cov), 1e-9, None))
        w = 1.0 / vol
    else:                                          # sharpe / tangency
        w = inv @ (mu - rf)
    w = np.where(np.isfinite(w) & (w > 0), w, 0.0)  # long-only
    if w.sum() <= 0:
        w = np.ones(n)
    w = w / w.sum()
    for _ in range(20):                            # enforce max weight cap
        over = w > max_w
        if not over.any():
            break
        spill = float((w[over] - max_w).sum())
        w[over] = max_w
        room = (~over) & (w > 0)
        if not room.any():
            break
        w[room] += spill * (w[room] / w[room].sum())
        w = w / w.sum()
    port_ret = float(w @ mu); port_vol = float(np.sqrt(max(w @ cov @ w, 0)))
    sharpe = (port_ret - rf) / port_vol if port_vol > 0 else 0.0
    avol = np.sqrt(np.clip(np.diag(cov), 0, None))
    assets = sorted([(cols[i], float(w[i]), float(avol[i]), float(mu[i])) for i in range(n)],
                    key=lambda x: -x[1])
    return {"method": method, "assets": assets, "port_ret": port_ret, "port_vol": port_vol,
            "sharpe": sharpe, "n": n, "years": years, "max_w": max_w}


