# ── VECTORBT SWEEP (vectorized universe backtest; needs `pip install vectorbt`) ─
def _vbt_reversal_sweep(conn, z_entry=2.0, hold=5, years=3):
    """vectorbt-powered backtest of the /zrev-style reversal rule across the whole
    universe at once: long when cross-sectional 5d-return z < -z_entry, exit after
    `hold` days. Returns per-ticker stats + aggregate. None if vectorbt missing."""
    try:
        import vectorbt as vbt
    except Exception:
        return None
    wide = _history_matrix(SCAN_UNIVERSE, years, conn)
    if wide is None or wide.empty:
        return None
    ret5 = wide.pct_change(5)
    z = ret5.sub(ret5.mean(axis=1), axis=0).div(ret5.std(axis=1), axis=0)
    entries = z < -z_entry
    exits = entries.shift(hold).fillna(False).astype(bool)
    try:
        pf = vbt.Portfolio.from_signals(wide, entries, exits, fees=0.0005, freq="1D")
        tot = pf.total_return()
        trades = pf.trades
        per = pd.DataFrame({"total_return": tot})
        try:
            per["win_rate"] = trades.win_rate()
            per["n_trades"] = trades.count()
        except Exception:
            pass
        per = per.dropna(subset=["total_return"]).sort_values("total_return", ascending=False)
        agg = {"tickers": int(len(per)), "avg_return": float(per["total_return"].mean()),
               "pct_positive": float((per["total_return"] > 0).mean()),
               "n_trades": int(per.get("n_trades", pd.Series(dtype=float)).sum() or 0)}
        return {"per": per, "agg": agg, "years": years, "rule": f"z<-{z_entry:g} hold {hold}d"}
    except Exception:
        log.debug("vbt sweep failed", exc_info=True)
        return None


# ── SCANNER FIRE PERSISTENCE (feeds signal_accuracy → hit-rates/weights) ─
def _persist_scanner_fires(conn, model_name, fires):
    """Record scanner fires (ticker, BULL/BEAR, prob) into signal_accuracy under
    'scn_<name>' so outcomes fill in later and hit-rates accumulate. Idempotent
    per (ticker, day, model). fires: iterable of (ticker, signal, prob)."""
    try:
        tod = datetime.now(timezone.utc).replace(tzinfo=None).strftime("%Y-%m-%d")
        conn.executemany(
            "INSERT OR REPLACE INTO signal_accuracy (ticker, trade_date, model_name, signal, prob)"
            " VALUES (?,?,?,?,?)",
            [(str(tk).upper(), tod, f"scn_{model_name}", sig, float(prob)) for tk, sig, prob in fires])
        conn.commit()
    except Exception:
        log.debug("persist_scanner_fires failed", exc_info=True)


def _update_scanner_outcomes(conn, horizon=5):
    """Fill actual_ret/correct for matured scn_* rows using stock_history closes
    (t -> t+horizon trading days). BULL correct if up, BEAR if down."""
    try:
        pend = pd.read_sql(
            "SELECT rowid, ticker, trade_date, signal FROM signal_accuracy"
            " WHERE model_name LIKE 'scn_%' AND actual_ret IS NULL", conn)
        if pend.empty:
            return 0
        n = 0
        for tk, grp in pend.groupby("ticker"):
            h = _daily_history(tk, 1, conn)
            if h is None or len(h) < horizon + 2:
                continue
            dates = [d.strftime("%Y-%m-%d") for d in h.index]
            for _, r in grp.iterrows():
                try:
                    i = dates.index(str(r["trade_date"]))
                except ValueError:
                    continue
                if i + horizon >= len(h):
                    continue                     # not matured yet
                ret = float(h.iloc[i + horizon] / h.iloc[i] - 1)
                sig = str(r["signal"])
                correct = _score_signal(sig, ret)
                if correct is None:
                    continue                   # unknown label — stays pending, not a miss
                conn.execute("UPDATE signal_accuracy SET actual_ret=?, correct=? WHERE rowid=?",
                             (ret, correct, int(r["rowid"])))
                n += 1
        conn.commit()
        return n
    except Exception:
        log.debug("update_scanner_outcomes failed", exc_info=True)
        return 0


# ── ACTION BOARD (consensus across independent scanners) ───────────
_BOARD_LABELS = {"revert": "Reversal", "zrev": "Z-Rev", "breakout": "52wk",
                 "building": "OI-Build", "uoa": "UOA", "riskoff": "Radar"}


def _action_board(conn, min_agree=2, freshen=True):
    """Consensus trade board: tally today's scn_* fires per ticker across INDEPENDENT
    DB-first scanners. LONG = net BULL votes, SHORT = net BEAR; a name only makes the
    board if ≥min_agree scanners agree on the winning side (net direction non-zero).
    freshen=True runs the cheap scanners first so the board is self-sufficient (and it
    refreshes the scn_* fires for later hit-rate scoring). Returns list of dicts."""
    if freshen:
        for fn in (_revert_scan, _zrev_scan, _breakout_scan, _positioning_scan, _uoa_scan):
            try:
                fn(conn)
            except Exception:
                log.debug(f"action_board freshen {getattr(fn,'__name__','?')} failed", exc_info=True)
    tod = datetime.now(timezone.utc).replace(tzinfo=None).strftime("%Y-%m-%d")
    try:
        df = pd.read_sql("SELECT ticker, model_name, signal, prob FROM signal_accuracy "
                         "WHERE model_name LIKE 'scn_%' AND trade_date=?", conn, params=(tod,))
    except Exception:
        return []
    if df.empty:
        return []
    board = {}
    for _, r in df.iterrows():
        tk = str(r["ticker"]).upper()
        model = str(r["model_name"]).replace("scn_", "")
        d = board.setdefault(tk, {"bull": set(), "bear": set(), "prob": []})
        (d["bull"] if str(r["signal"]) == "BULL" else d["bear"]).add(model)
        try:
            d["prob"].append(float(r["prob"]))
        except (TypeError, ValueError):
            pass
    rows = []
    for tk, d in board.items():
        nb, ns = len(d["bull"]), len(d["bear"])
        net = nb - ns
        if net == 0:
            continue                                    # split/tie → no consensus direction
        win = nb if net > 0 else ns                     # scanners on the winning side
        if win < min_agree:
            continue
        srcs = sorted(d["bull"] if net > 0 else d["bear"])
        rows.append({"tk": tk, "side": "LONG" if net > 0 else "SHORT", "net": net,
                     "win": win, "bull": nb, "bear": ns, "srcs": srcs,
                     "conf": (sum(d["prob"]) / len(d["prob"])) if d["prob"] else 0.0})
    rows.sort(key=lambda r: (-r["win"], -abs(r["net"]), -r["conf"]))
    return rows


def _fmt_action_board(rows, top=8):
    """Two mobile-safe _pipe_tables (longs/shorts). Narrow: ST·Tkr·#·Conf; sources listed
    compactly beneath each side (not in the table, to keep <pre> width ≤ mobile)."""
    if not rows:
        return None
    longs = [r for r in rows if r["side"] == "LONG"][:top]
    shorts = [r for r in rows if r["side"] == "SHORT"][:top]

    # LIVE price + % vs the EOD close for every listed name (the board previously showed no
    # price at all, so an "ready to act" list gave no idea where the name was actually trading).
    _px, _any_live = {}, False
    try:
        _c = get_conn()
        try:
            for _r in (longs + shorts):
                _tk = _r["tk"]
                if _tk in _px:
                    continue
                # TWO closes, not one. _cur_price() falls back to the EOD close when there
                # is no live quote, so `live/eod - 1` was exactly 0.00 by construction for
                # every row whenever the market was shut — which is most of the time this
                # board is read (reported 2026-08-03). Off-hours the meaningful change is
                # the LAST SESSION's: close vs the close before it.
                _h = pd.read_sql("SELECT close FROM stock_history WHERE ticker=? "
                                 "ORDER BY trade_date DESC LIMIT 2", _c, params=(_tk,))
                _eod = float(_h["close"].iloc[0]) if not _h.empty else 0.0
                _prev = float(_h["close"].iloc[1]) if len(_h) > 1 else 0.0
                _lv, _islive, _ = _cur_price(_tk, _eod)
                _lv = float(_lv or _eod)
                _any_live = _any_live or bool(_islive)
                if _islive and _eod:
                    _chg = (_lv / _eod - 1) * 100          # intraday vs today's open basis
                elif _prev:
                    _chg = (_eod / _prev - 1) * 100        # last completed session
                else:
                    _chg = 0.0
                _px[_tk] = (_lv, _chg)
        finally:
            _c.close()
    except Exception as e:
        log.debug(f"action_board prices: {e}")

    def _block(rs, emoji, title):
        data = [(emoji, r["tk"],
                 f"{_px.get(r['tk'], (0.0, 0.0))[0]:,.0f}",
                 f"{_px.get(r['tk'], (0.0, 0.0))[1]:+.1f}",
                 f"{r['conf']:.0f}") for r in rs]
        tbl = _pipe_table(("ST", "Tkr", "Px", "Chg%", "Conf"), data, right_cols={2, 3, 4})
        src = " · ".join(f"{r['tk']}:{'+'.join(_BOARD_LABELS.get(s, s) for s in r['srcs'])}"
                         for r in rs[:5])
        return f"<b>{title}</b>\n{tbl}\n<i>{src}</i>"

    parts = []
    if longs:
        parts.append(_block(longs, "🟢", "🟢 CONSENSUS LONGS"))
    if shorts:
        parts.append(_block(shorts, "🔴", "🔴 CONSENSUS SHORTS"))
    if parts:
        _stamp = (f"🟢 LIVE {_et_now().strftime('%H:%M ET')}" if _any_live else "EOD")
        parts.append(f"<i>Px = {_stamp} · Chg% = live vs today's close when trading, else the "
                     f"last completed session · <b>Conf = 0-100 agreement score, NOT a percent "
                     f"return and NOT a probability</b> — it is the average fire strength of the "
                     f"scanners that agreed. Signals are EOD (open interest publishes once daily).</i>")
    return "\n\n".join(parts) if parts else None


async def _send_action_board(msg, rows):
    body = _fmt_action_board(rows)
    if not body:
        await msg.reply_text("No consensus ideas right now (need 2+ scanners agreeing).",
                             parse_mode=H)
        return
    n_l = sum(1 for r in rows if r["side"] == "LONG")
    n_s = sum(1 for r in rows if r["side"] == "SHORT")
    txt = ("🎯 <b>Action Board — Consensus Ideas</b>\n"
           "<i>Names where ≥2 independent DB-first scanners agree on direction · not advice</i>\n\n"
           + body + f"\n\n<i>{n_l} longs · {n_s} shorts · #=scanners agreeing · Conf=avg fire prob</i>")
    await msg.reply_text(txt[:4000], parse_mode=H,
                         reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔄 Refresh", callback_data="board_view"),
                                                             InlineKeyboardButton("⬅️ Menu", callback_data="menu_main")]]))


