# ── DOWNSIDE SKEW & EXPECTED MOVE (live IV — direction + size + range) ─
_SKEW_DEFAULT = ["SPY", "QQQ", "SMH", "SOXX", "NVDA", "AMD", "MU", "LRCX"]


def _skew_analyze(tk, r=0.045):
    """Live IV-implied downside map for ONE ticker (yfinance chain, front ~30-DTE expiry).
    DIRECTION = 25Δ put−call IV skew (put skew = downside fear priced); SIZE = 1σ expected
    move; RANGE = 1σ/2σ down targets; plus P(≥5% down) to expiry. Universal / any optionable
    ticker. yfinance-only (OpenBB stays a parallel lane). Returns dict or None."""
    try:
        t = _yf_ticker(tk)
        h = t.history(period="1d")
        spot = float(h["Close"].iloc[-1]) if len(h) else None
        exps = list(t.options or [])
        if not spot or not exps:
            return None
        today = datetime.now().date()
        dted = [(e, (datetime.strptime(e, "%Y-%m-%d").date() - today).days) for e in exps]
        dted = [(e, d) for e, d in dted if d >= 7]            # skip 0DTE/weekly churn
        if not dted:
            return None
        exp, dte = min(dted, key=lambda x: abs(x[1] - 30))    # nearest to ~30 DTE
        T = max(dte, 1) / 365.0
        ch = t.option_chain(exp)
        calls = ch.calls.dropna(subset=["impliedVolatility"]).copy()
        puts = ch.puts.dropna(subset=["impliedVolatility"]).copy()
        calls = calls[calls.impliedVolatility > 0.01]
        puts = puts[puts.impliedVolatility > 0.01]
        if len(calls) < 3 or len(puts) < 3:
            return None
        ivc_atm = float(calls.iloc[(calls.strike - spot).abs().argmin()].impliedVolatility)
        ivp_atm = float(puts.iloc[(puts.strike - spot).abs().argmin()].impliedVolatility)
        atm_iv = (ivc_atm + ivp_atm) / 2.0

        def _iv_at_delta(df, opt, target):                    # true BS |delta| nearest target
            best, bestd = None, 1e9
            for _, row in df.iterrows():
                iv = float(row.impliedVolatility)
                if iv <= 0:
                    continue
                try:
                    dl = bs_greeks(spot, float(row.strike), T, r, iv, opt)["delta"]
                except Exception:
                    continue
                if abs(abs(dl) - target) < bestd:
                    bestd, best = abs(abs(dl) - target), iv
            return best
        ivp25 = _iv_at_delta(puts[puts.strike <= spot], "put", 0.25)
        ivc25 = _iv_at_delta(calls[calls.strike >= spot], "call", 0.25)
        skew = (ivp25 - ivc25) if (ivp25 and ivc25) else (ivp_atm - ivc_atm)
        sig1 = spot * atm_iv * np.sqrt(T)                     # 1σ expected move ($)
        em_pct = sig1 / spot * 100
        p_dn5 = float(norm.cdf(np.log(0.95) / (atm_iv * np.sqrt(T) + 1e-9))) * 100
        ed = _earnings_days(tk)
        earn_in = ed if (ed is not None and 0 <= ed <= dte) else None
        if skew >= 0.04:
            lean, emoji = "DOWN-skew", "🔴"
        elif skew <= -0.02:
            lean, emoji = "UP-skew", "🟢"
        else:
            lean, emoji = "two-sided", "🟡"
        return {"tk": tk.upper(), "spot": spot, "dte": dte, "atm_iv": atm_iv, "skew": skew,
                "em_pct": em_pct, "d1": spot - sig1, "d2": spot - 2 * sig1, "u1": spot + sig1,
                "p_dn5": p_dn5, "earn_in": earn_in, "lean": lean, "emoji": emoji}
    except Exception:
        log.debug(f"_skew_analyze {tk} failed", exc_info=True)
        return None


def _skew_scan(tickers):
    out = [r for r in (_skew_analyze(t) for t in tickers) if r]
    out.sort(key=lambda x: -x["skew"])                        # most downside-skewed first
    return out


def _fmt_skew(rows):
    if not rows:
        return None
    data = [(r["emoji"], r["tk"], f"{r['atm_iv']*100:.0f}", f"±{r['em_pct']:.0f}",
             f"{r['skew']*100:+.0f}") for r in rows]
    tbl = _pipe_table(("ST", "Tkr", "IV%", "EM%", "Skew"), data, right_cols={2, 3, 4})
    lines = []
    for r in rows:
        e = f" ⚠️earn{r['earn_in']}d" if r["earn_in"] is not None else ""
        lines.append(f"<b>{r['tk']}</b> {r['spot']:.0f} → 1σ↓ <b>{r['d1']:.0f}</b> "
                     f"({(r['d1']/r['spot']-1)*100:+.0f}%) · 2σ↓ {r['d2']:.0f} "
                     f"({(r['d2']/r['spot']-1)*100:+.0f}%) · P(≥5%↓) {r['p_dn5']:.0f}% · {r['dte']}DTE{e}")
    return tbl, "\n".join(lines)


async def _send_skew(msg, rows):
    fm = _fmt_skew(rows)
    if not fm:
        await msg.reply_text("No live option chains for those tickers.", parse_mode=H)
        return
    tbl, detail = fm
    txt = ("🎯 <b>Downside Skew &amp; Expected Move</b>\n"
           "<i>Live IV · direction = 25Δ put−call skew · size = 1σ move · range = 1σ/2σ down "
           "targets to the front ~30-DTE expiry · not advice</i>\n\n"
           + tbl + "\n\n" + detail +
           "\n\n<i>🔴 downside-skewed · 🟡 two-sided · 🟢 upside-skewed · IV%=ATM implied vol · "
           "EM%=±1σ move · post-crash IV runs hot, so ranges are wide</i>")
    await msg.reply_text(txt[:4000], parse_mode=H,
                         reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔄 Refresh", callback_data="skew_view"),
                                                             InlineKeyboardButton("⬅️ Menu", callback_data="menu_main")]]))


async def skew_command(update, ctx):
    """/skew [TICKERS] — live IV-implied downside: direction (skew) + size (1σ) + range (1σ/2σ)."""
    args = [a.upper() for a in (ctx.args or [])][:8]
    tickers = args or _SKEW_DEFAULT
    await update.message.reply_text("🎯 Computing IV-implied downside range…", parse_mode=H)
    await _send_skew(update.message, _skew_scan(tickers))


async def skew_view(query):
    await _send_skew(query.message, _skew_scan(_SKEW_DEFAULT))


# ── ANALYST RATINGS (yfinance upgrades/downgrades + price targets — keyless;
#    Yahoo-syndicated, largely Benzinga-sourced, so no paid Benzinga API needed) ─
_RATINGS_DEFAULT = _SKEW_DEFAULT


_FIRM_ABBR = {
    "B of A Securities": "BofA", "Bank of America": "BofA", "JP Morgan": "JPMorgan",
    "Wells Fargo & Company": "Wells Fargo", "Cantor Fitzgerald": "Cantor",
    "Keefe, Bruyette & Woods": "KBW", "Truist Securities": "Truist",
    "Wedbush Securities": "Wedbush", "Rosenblatt Securities": "Rosenblatt",
}


def _firm_short(name, limit=16):
    """Readable broker name for detail lines: known abbreviation, else cut at a WORD
    boundary within `limit` — never mid-word ('B of A Securitie' bug, 2026-07-18)."""
    name = str(name or "").strip()
    if name in _FIRM_ABBR:
        return _FIRM_ABBR[name]
    if len(name) <= limit:
        return name
    cut = name[:limit]
    return cut[:cut.rfind(" ")] if " " in cut else cut


def _ratings_default_tickers():
    """Open-position tickers first (what you actually hold), else the skew default universe."""
    try:
        with get_conn() as c:
            tks = [str(r[0]).upper() for r in c.execute(
                "SELECT DISTINCT ticker FROM trades WHERE status='OPEN'").fetchall()]
        if tks:
            return tks[:8]
    except Exception:
        pass
    return _RATINGS_DEFAULT


def _ratings_analyze(tk, days=45):
    """Analyst actions in the last `days` for ANY ticker (live yfinance, keyless):
    rating up/downgrades + price-target raises/cuts, median PT, latest few moves."""
    try:
        df = yf.Ticker(tk).upgrades_downgrades
        if df is None or df.empty:
            return None
        df = df.reset_index()
        dcol = df.columns[0]                                   # GradeDate
        df[dcol] = pd.to_datetime(df[dcol], errors="coerce", utc=True).dt.tz_localize(None)
        df = df[df[dcol] >= pd.Timestamp.now() - pd.Timedelta(days=days)].sort_values(dcol, ascending=False)
        if df.empty:
            return None
        act = df["Action"].astype(str).str.lower() if "Action" in df else pd.Series("", index=df.index)
        pta = (df["priceTargetAction"].astype(str).str.lower()
               if "priceTargetAction" in df else pd.Series("", index=df.index))
        ups, dns = int((act == "up").sum()), int((act == "down").sum())
        ptu, ptd = int((pta == "raises").sum()), int((pta == "lowers").sum())
        score = (ups - dns) + 0.5 * (ptu - ptd)                # PT moves count half a rating move
        emoji = "🟢" if score > 0 else "🔴" if score < 0 else "🟡"
        pts = pd.to_numeric(df.get("currentPriceTarget"), errors="coerce").dropna()
        med_pt = float(pts.median()) if len(pts) else None
        latest = []
        for _, r in df.head(3).iterrows():
            arrow = {"up": "⬆️", "down": "⬇️", "init": "🆕"}.get(str(r.get("Action", "")).lower(), "▪️")
            seg = f"{arrow}{r[dcol]:%m-%d} <b>{_firm_short(r.get('Firm', ''))}</b> {str(r.get('ToGrade', '') or '—')}"
            c0, p0 = r.get("currentPriceTarget"), r.get("priorPriceTarget")
            if pd.notna(c0) and pd.notna(p0) and p0:
                seg += f" · PT {p0:g}→{c0:g}"
            elif pd.notna(c0):
                seg += f" · PT {c0:g}"
            latest.append(seg)
        return {"tk": tk.upper(), "emoji": emoji, "ups": ups, "dns": dns, "ptu": ptu,
                "ptd": ptd, "score": score, "n": len(df), "med_pt": med_pt, "latest": latest}
    except Exception:
        return None


def _ratings_scan(tickers, days=45):
    out = [r for r in (_ratings_analyze(t, days) for t in tickers) if r]
    out.sort(key=lambda x: -x["score"])
    return out


def _fmt_ratings(rows):
    if not rows:
        return None
    data = [(r["emoji"], r["tk"], str(r["ups"]), str(r["dns"]), f"{r['ptu']}/{r['ptd']}",
             f"{r['score']:+.0f}") for r in rows]
    tbl = _pipe_table(("ST", "Tkr", "Up", "Dn", "PT±", "Net"), data, right_cols={2, 3, 4, 5})
    lines = []
    for r in rows:
        mp = f" · med PT <b>{r['med_pt']:.0f}</b>" if r["med_pt"] else ""
        lines.append(f"<b>{r['tk']}</b> {r['n']} actions{mp}\n" + "\n".join("  " + x for x in r["latest"]))
    return tbl, "\n\n".join(lines)


async def _send_ratings(msg, rows):
    fm = _fmt_ratings(rows)
    if not fm:
        await msg.reply_text("No analyst actions in the last 45 days for those tickers.", parse_mode=H)
        return
    tbl, detail = fm
    txt = ("⭐ <b>Analyst Ratings — last 45d</b>\n"
           "<i>Up/Dn = rating changes · PT± = target raises/cuts · Net = ups−downs + ½·PT moves "
           "(keyless Yahoo feed, largely Benzinga-sourced)</i>\n\n"
           + tbl + "\n\n" + detail +
           "\n\n<i>🟢 net positive · 🔴 net negative · post-upgrade drift is documented but "
           "validate vs history before trading · not advice</i>")
    await msg.reply_text(txt[:4000], parse_mode=H,
                         reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔄 Refresh", callback_data="ratings_view"),
                                                             InlineKeyboardButton("⬅️ Menu", callback_data="menu_main")]]))


async def ratings_command(update, ctx):
    """/ratings [TICKERS] — recent analyst upgrades/downgrades + price targets (keyless)."""
    args = [a.upper() for a in (ctx.args or [])][:8]
    tickers = args or _ratings_default_tickers()
    await update.message.reply_text("⭐ Fetching analyst actions…", parse_mode=H)
    await _send_ratings(update.message, _ratings_scan(tickers))


async def ratings_view(query):
    await _send_ratings(query.message, _ratings_scan(_ratings_default_tickers()))


# ── INTRADAY LANE (reads US_intraday.db written by NYSE_intraday.py: 1m bars
#    for open positions + ~30 leaders, 30-min CBOE chain snapshots for
#    positions). /live = minute-level writeup · /heat = heat-seeking/reversal
#    scan · heat_streamer_alert = 15-min job that pushes state CHANGES only.
#    OI updates once daily (OCC) — intraday edge is volume-pace / IV-shift /
#    price action ONLY. Volume pace uses a linear time-of-day norm (approx).
INTRADAY_DB = os.path.join(DATA_DIR, "US_intraday.db")


def _idb_conn():
    return sqlite3.connect(INTRADAY_DB, timeout=15) if os.path.exists(INTRADAY_DB) else None


def _intraday_frame():
    """Latest captured day's 1m bars → (day, {ticker: df}). (None, None) if lane never ran."""
    c = _idb_conn()
    if c is None:
        return None, None
    try:
        day = c.execute("SELECT MAX(trade_date) FROM intraday_bars").fetchone()[0]
        if not day:
            return None, None
        df = pd.read_sql_query(
            "SELECT ticker, ts, open, high, low, close, volume FROM intraday_bars "
            "WHERE trade_date=? ORDER BY ts", c, params=(day,))
    finally:
        c.close()
    if df.empty:
        return None, None
    return day, {tk: g.reset_index(drop=True) for tk, g in df.groupby("ticker")}


def _intraday_ref(conn, tk, day):
    """Daily reference from stock_daily (strictly before `day`): prev close, ATR20 as
    a fraction of price, 20d avg volume. None if the ticker isn't in the DB."""
    rows = conn.execute(
        "SELECT close, high, low, volume FROM stock_daily "
        "WHERE ticker=? AND trade_date<? ORDER BY trade_date DESC LIMIT 21",
        (tk, day)).fetchall()
    if not rows:
        return None
    rows = rows[::-1]                                # oldest → newest
    trs, vols, prev_c = [], [], None
    for cl, hi, lo, vol in rows:
        if hi and lo and cl:
            tr = hi - lo
            if prev_c:
                tr = max(tr, abs(hi - prev_c), abs(lo - prev_c))
            trs.append(tr / cl)
        if vol:
            vols.append(float(vol))
        prev_c = cl
    return {"prev_close": rows[-1][0],
            "atr_pct": sum(trs[-20:]) / len(trs[-20:]) if trs else None,
            "avg_vol": sum(vols[-20:]) / len(vols[-20:]) if vols else None}


def _intraday_metrics(bars, ref):
    """Minute-level metrics for one ticker: day move, VWAP dislocation, volume pace
    vs 20d norm, 15m burst, ATR-paced move z-score, bar age. Pure computation."""
    px = bars["close"].astype(float)
    v = bars["volume"].astype(float)
    last = float(px.iloc[-1])
    cumv = float(v.sum())
    vwap = float((px * v).sum() / cumv) if cumv > 0 else last
    t0 = datetime.strptime(bars["ts"].iloc[0][:10] + " 09:30", "%Y-%m-%d %H:%M")
    tn = datetime.strptime(bars["ts"].iloc[-1], "%Y-%m-%d %H:%M")
    elapsed = min(max((tn - t0).total_seconds() / 60.0, 5.0), 390.0) / 390.0
    pc = (ref or {}).get("prev_close") or float(bars["open"].iloc[0])
    day_ret = last / pc - 1 if pc else 0.0
    atr = (ref or {}).get("atr_pct")
    move_z = day_ret / (atr * elapsed ** 0.5) if atr else None
    avg_v = (ref or {}).get("avg_vol")
    pace = cumv / (avg_v * elapsed) if avg_v else None
    burst15 = float(px.iloc[-1] / px.iloc[-16] - 1) if len(px) > 16 else day_ret
    last30 = float(px.iloc[-1] / px.iloc[-31] - 1) if len(px) > 31 else burst15
    # bar timestamps are exchange-local (ET); tz offset is 4h (EDT) or 5h (EST) —
    # take whichever offset yields the smaller age so staleness works year-round
    now_u = datetime.now(timezone.utc).replace(tzinfo=None)
    age_min = min(abs((now_u - (tn + timedelta(hours=off))).total_seconds()) / 60.0
                  for off in (4, 5))
    return {"last": last, "prev_close": pc, "day_ret": day_ret, "vwap": vwap,
            "vwap_dev": last / vwap - 1 if vwap else 0.0, "move_z": move_z,
            "pace": pace, "burst15": burst15, "last30": last30,
            "elapsed": elapsed, "age_min": age_min}


def _heat_state(m):
    """FADE = stretched (>2σ pace-adjusted) AND stalling/low-fuel → reversal candidate.
    HEAT = strong paced move (≥1.5σ) on ≥1.5× volume, still trending. Else None."""
    z = m.get("move_z")
    if z is None:
        return None
    trending = (m.get("last30") or 0.0) * m["day_ret"] >= 0
    if abs(z) >= 2.0 and (not trending or (m.get("pace") or 9) < 1.0):
        return "FADE"
    if abs(z) >= 1.5 and (m.get("pace") or 0) >= 1.5 and trending:
        return "HEAT"
    return None


def _heat_scan():
    """(day, metric rows sorted by |z|) over every ticker in today's intraday bars."""
    day, frames = _intraday_frame()
    if not frames:
        return None, None
    conn = get_conn()
    rows = []
    try:
        for tk, b in frames.items():
            try:
                m = _intraday_metrics(b, _intraday_ref(conn, tk, day))
            except Exception:
                continue
            m["tk"] = tk
            m["state"] = _heat_state(m)
            rows.append(m)
    finally:
        conn.close()
    rows.sort(key=lambda m: -abs(m["move_z"] or 0))
    return day, rows


def _iv_drift(day):
    """{ticker: {iv, first_iv, pcr}} from today's 30-min chain snapshots."""
    c = _idb_conn()
    if c is None:
        return {}
    try:
        cur = c.execute("SELECT ticker, atm_iv, pcr_vol FROM intraday_chain "
                        "WHERE trade_date=? ORDER BY ts_utc", (day,)).fetchall()
    finally:
        c.close()
    out = {}
    for tk, iv, pcr in cur:
        d = out.setdefault(tk, {"first_iv": iv, "iv": iv, "pcr": pcr})
        if iv is not None:
            d["iv"] = iv
            if d["first_iv"] is None:
                d["first_iv"] = iv
        if pcr is not None:
            d["pcr"] = pcr
    return out


# Neutral state: plain "-" not a white circle (user 2026-07-18: "white doesn't mean
# anything") — only 🔥/🌀 are real signals, so neutral rows get NO emoji at all,
# making the two real states stand out instead of looking like a missed color.
_HEAT_EMO = {"HEAT": "🔥", "FADE": "🌀", None: "-"}


def _fmt_heat(rows, day, title="🔥 Heat-Seeker · intraday"):
    data = [(_HEAT_EMO.get(m["state"], "-"), m["tk"], f"{m['day_ret']:+.1%}",
             f"{m['move_z']:+.1f}" if m["move_z"] is not None else "—",
             f"{m['pace']:.1f}x" if m["pace"] else "—") for m in rows[:12]]
    return _pipe_table(("ST", "Tkr", "Day%", "z", "Pace"), data, right_cols={2, 3, 4},
                       title=f"{title} {day}",
                       legend="z = move ÷ ATR20·√elapsed · Pace = vol vs 20d norm · "
                              "🔥 paced+fueled trend · 🌀 stretched >2σ + stalling (fade watch) · "
                              "OI is daily — this is volume/price/IV only, not advice")


def _live_writeup(tickers=None):
    """Minute-level market writeup from the intraday lane. None if lane never ran."""
    day, rows = _heat_scan()
    if not rows:
        return None
    by = {m["tk"]: m for m in rows}
    ivm = _iv_drift(day)
    want = [t for t in (tickers or _ratings_default_tickers() + ["SPY", "QQQ"]) if t in by]
    seen = set()
    want = [t for t in want if not (t in seen or seen.add(t))][:8]
    if not want:
        return None
    up_vwap = sum(1 for m in rows if m["vwap_dev"] > 0)
    spy, qqq = by.get("SPY"), by.get("QQQ")
    parts = [hdr(f"📶 LIVE · {day}")]
    mk = []
    if spy:
        mk.append(f"SPY {spy['day_ret']:+.1%}")
    if qqq:
        mk.append(f"QQQ {qqq['day_ret']:+.1%}")
    mk.append(f"breadth {up_vwap}/{len(rows)} above VWAP")
    parts.append("<i>" + " · ".join(mk) + "</i>")
    stale = max(by[t]["age_min"] for t in want)
    if stale > 20:
        parts.append(f"⚠️ <i>bars are ~{stale:.0f} min old — live only while "
                     f"NYSE_intraday.py is running</i>")
    for tk in want:
        m = by[tk]
        e = "🟢" if m["day_ret"] >= 0 else "🔴"
        side = "above" if m["vwap_dev"] >= 0 else "below"
        l1 = (f"{e} <b>{tk}</b> {m['last']:,.2f} ({m['day_ret']:+.1%}) · "
              f"{side} VWAP {m['vwap_dev']:+.1%}")
        bits = []
        if m["pace"]:
            bits.append(f"pace {m['pace']:.1f}x")
        bits.append(f"15m {m['burst15']:+.1%}")
        if m["move_z"] is not None:
            bits.append(f"z {m['move_z']:+.1f}")
        if m["state"]:
            bits.append(f"{_HEAT_EMO[m['state']]} <b>{m['state']}</b>")
        l2 = "  " + " · ".join(bits)
        blk = l1 + "\n" + l2
        iv = ivm.get(tk)
        if iv and iv.get("iv"):
            drift = ((iv["iv"] - iv["first_iv"]) * 100) if iv.get("first_iv") else 0.0
            pcr = f" · PCR-vol {iv['pcr']:.2f}" if iv.get("pcr") is not None else ""
            blk += f"\n  ATM IV {iv['iv']:.0%} ({drift:+.1f}pt today){pcr}"
        parts.append(blk)
    hot = [m for m in rows if m["state"] and m["tk"] not in want][:4]
    if hot:
        parts.append("<b>▸ Elsewhere</b>\n" + "\n".join(
            f"  {_HEAT_EMO[m['state']]} {m['tk']} {m['day_ret']:+.1%} "
            f"(z {m['move_z']:+.1f}) {m['state']}" for m in hot))
    parts.append("<i>1m bars + 30-min chain snapshots (15-min delayed) · "
                 "volume/price/IV only, OI is daily · not advice</i>")
    return "\n\n".join(parts)


async def live_command(update, ctx):
    """/live [TICKERS] — minute-level intraday writeup (defaults: positions + SPY/QQQ)."""
    args = [a.upper() for a in (ctx.args or [])][:8]
    txt = _live_writeup(args or None)
    if not txt:
        await update.message.reply_text(
            "📶 Intraday lane has no data yet — it auto-starts during market hours "
            "(bot supervises it). Manual start anytime:\n"
            "<code>python NYSE_intraday.py</code>", parse_mode=H)
        return
    await update.message.reply_text(txt[:4000], parse_mode=H)


async def heat_command(update, ctx):
    """/heat — heat-seeking / reversal scan over the intraday focus universe."""
    day, rows = _heat_scan()
    if not rows:
        await update.message.reply_text(
            "🔥 Intraday lane has no data yet — it auto-starts during market hours "
            "(bot supervises it).", parse_mode=H)
        return
    await update.message.reply_text(_fmt_heat(rows, day)[:4000], parse_mode=H)


def _lane_heartbeat_age():
    """Seconds since the capture loop's last heartbeat; None if DB/row missing."""
    c = _idb_conn()
    if c is None:
        return None
    try:
        row = c.execute("SELECT val FROM lane_meta WHERE key='heartbeat'").fetchone()
    except sqlite3.OperationalError:
        return None
    finally:
        c.close()
    if not row:
        return None
    try:
        ts = datetime.strptime(row[0], "%Y-%m-%dT%H:%M:%S")
    except (ValueError, TypeError):
        return None
    return (datetime.now(timezone.utc).replace(tzinfo=None) - ts).total_seconds()


_LAST_LANE_SPAWN = 0.0         # epoch of the last NYSE_intraday.py spawn (duplicate guard)


async def intraday_lane_supervisor(ctx: ContextTypes.DEFAULT_TYPE):
    """5-min job: keep NYSE_intraday.py alive during market hours (same auto-launch
    pattern as the dashboard). Heartbeat-gated → a manual start is never duplicated;
    crash isolation and the bot's async loop stay untouched (separate process)."""
    now_utc = datetime.now(timezone.utc).replace(tzinfo=None)
    if now_utc.weekday() >= 5:
        return
    hm = now_utc.hour * 60 + now_utc.minute
    if not (13 * 60 + 25 <= hm <= 20 * 60 + 55):    # EDT/EST union session window
        return
    age = _lane_heartbeat_age()
    if age is not None and age < 180:
        return                                       # lane alive (manual or spawned)
    # Spawn cooldown. The heartbeat gate alone is NOT enough: a just-spawned lane has not
    # written its first heartbeat yet, and a batched yf.download across the universe easily
    # takes longer than the 180s staleness window — so the next 5-min tick saw "stale" and
    # spawned a SECOND copy. Observed 2026-07-22: two NYSE_intraday.py at 09:28:20 and
    # 09:33:20, both sweeping 1m bars, doubling rate-limit load on a lane /live and /heat
    # depend on. Cooldown must exceed worst-case time-to-first-heartbeat.
    global _LAST_LANE_SPAWN
    if time.time() - _LAST_LANE_SPAWN < 900:
        return
    here = os.path.dirname(os.path.abspath(__file__))
    script = os.path.join(here, "NYSE_intraday.py")
    if not os.path.exists(script):
        return
    try:
        logs = os.path.join(here, "logs")
        os.makedirs(logs, exist_ok=True)
        out = open(os.path.join(logs, "intraday_lane.log"), "a")
        subprocess.Popen([sys.executable, script], cwd=here,
                         stdout=out, stderr=subprocess.STDOUT,
                         creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        _LAST_LANE_SPAWN = time.time()
        log.info("intraday lane heartbeat stale/missing - spawned NYSE_intraday.py")
    except Exception as e:
        log.warning(f"intraday lane spawn failed: {e}")


def _script_running_proc(script_name, require_arg=None):
    """psutil-free fallback: read /proc directly. Linux only; returns True (assume running)
    anywhere it cannot tell, so a missing dependency can never cause a respawn loop."""
    if not os.path.isdir("/proc"):
        return True
    try:
        pids = [d for d in os.listdir("/proc") if d.isdigit()]
    except Exception:
        return True
    me = str(os.getpid())
    for pid in pids:
        if pid == me:
            continue
        try:
            with open(f"/proc/{pid}/cmdline", "rb") as fh:
                argv = [a.decode("utf-8", "replace") for a in fh.read().split(b"\0") if a]
        except Exception:
            continue                              # process vanished mid-scan, or not ours
        if not argv or not os.path.basename(argv[0]).lower().startswith("python"):
            continue
        if not any(os.path.basename(a) == script_name for a in argv):
            continue
        if require_arg and require_arg not in argv:
            continue
        return True
    return False


def _script_running(script_name, require_arg=None):
    """Is a PYTHON process actually running `script_name`?

    Deliberately strict. The first version asked whether any process's command line CONTAINED
    the filename, which matched a shell that merely mentioned it -- a py_compile command in an
    admin console was enough to convince the bot the watchdog was already up, so it never
    spawned one (caught 2026-08-08). A stray grep must never suppress a supervisor.

    It used to return False when psutil was NOT INSTALLED -- i.e. "no watchdog running" -- so
    the bot spawned one on every start. The watchdog then restarts the bot, the new bot is
    equally blind, and the two spawn each other forever: on the Oracle VM that produced a chain
    of 15 processes in ~40 seconds and 6.45 GB of 12 GB before it was killed (2026-08-28).

    So: psutil when present, a /proc scan on Linux when not, and if NEITHER can answer, report
    True. That is deliberately the opposite of the old default. Failing to spawn a supervisor
    is a degraded state you can notice; a spawn loop takes the whole host down.
    """
    try:
        import psutil
    except ImportError:
        return _script_running_proc(script_name, require_arg)
    for p in psutil.process_iter(["name", "cmdline"]):
        try:
            if not (p.info["name"] or "").lower().startswith("python"):
                continue
            argv = p.info["cmdline"] or []
            if not any(os.path.basename(a) == script_name for a in argv):
                continue
            if require_arg and require_arg not in argv:
                continue
            return True
        except Exception:
            continue
    return False


def _spawn_watchdog():
    """Start bot_watchdog.py --loop DETACHED, so it survives this process dying.

    Replaces the TelegramBotWatchdog scheduled task, which cannot be recreated: on this
    machine Register-ScheduledTask returns Access denied even for a task the user authored,
    and even in a user subfolder (verified 2026-08-08). DETACHED_PROCESS is the whole point --
    a normal child would die with the bot and could not restart it.

    The watchdog dedupes itself, so calling this on every start is safe.
    """
    here = os.path.dirname(os.path.abspath(__file__))
    script = os.path.join(here, "bot_watchdog.py")
    if not os.path.exists(script):
        return
    if _script_running("bot_watchdog.py", require_arg="--loop"):
        return                                   # already supervising
    try:
        subprocess.Popen(
            [sys.executable, script, "--loop"], cwd=here,
            creationflags=(getattr(subprocess, "CREATE_NO_WINDOW", 0)
                           | getattr(subprocess, "DETACHED_PROCESS", 0)),
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            stdin=subprocess.DEVNULL)
        log.info("watchdog loop spawned (detached) - covers this bot dying")
    except Exception as e:
        log.warning(f"watchdog spawn failed: {e}")


_LAST_EOD_SPAWN = 0.0


def _eod_captured(day):
    """True if the OpenBB capture already landed for `day`. Same test run_all_offhours uses
    for its own fallback decision (bb_capture_ok, >=300 distinct tickers) — deliberately the
    SAME bar, so the bot and the EOD chain can never disagree about whether a day is done."""
    try:
        conn = get_conn()
        try:
            n = conn.execute("SELECT COUNT(DISTINCT ticker) FROM options_openbb "
                             "WHERE trade_date=?", (day.strftime("%Y-%m-%d"),)).fetchone()[0]
        finally:
            conn.close()
        return n >= 300
    except Exception:
        return False        # unknown -> let the chain run and decide for itself


async def eod_lane_supervisor(ctx: ContextTypes.DEFAULT_TYPE):
    """15-min job: make the EOD download independent of Windows Task Scheduler.

    WHY THIS EXISTS (2026-08-08). The EOD chain was launched solely by the scheduled task
    NYSE_OffHours_Chain, which is a single point of failure that has now failed twice: it was
    silently disabled, and its ACL is damaged so even its own author cannot re-enable it
    without elevation. The bot is already an always-on user process that supervises the
    intraday lane, so it can cover the EOD lane the same way and the download stops depending
    on a task nobody can fix from here.

    This does NOT replace the scheduled task — it backstops it. Ordering is deliberate:

      * fires at 17:30 ET, AFTER the task's own 17:00 slot, so a working task always wins
      * skips entirely when options_openbb already holds >=300 tickers for the target day,
        which is exactly what a successful task run leaves behind
      * skips when a run_all_offhours.py process is already alive

    Any one of those three is enough to prevent a double run; all three have to miss before
    this spawns anything.
    """
    global _LAST_EOD_SPAWN
    now_et = _et_now()
    if now_et.weekday() >= 5:
        return
    hm = now_et.hour * 60 + now_et.minute
    if not (17 * 60 + 30 <= hm <= 23 * 60):
        return
    if _eod_captured(now_et.date()):
        return                                   # the task did its job, or an earlier spawn did
    if time.time() - _LAST_EOD_SPAWN < 3 * 3600:
        return                                   # a chain run takes a long while; do not stack
    if _script_running("run_all_offhours.py"):
        return                                   # already running (task-launched or ours)
    here = os.path.dirname(os.path.abspath(__file__))
    script = os.path.join(here, "run_all_offhours.py")
    if not os.path.exists(script):
        return
    try:
        logs = os.path.join(here, "logs")
        os.makedirs(logs, exist_ok=True)
        out = open(os.path.join(logs, "eod_lane.log"), "a")
        subprocess.Popen([sys.executable, script], cwd=here,
                         stdout=out, stderr=subprocess.STDOUT,
                         creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
        _LAST_EOD_SPAWN = time.time()
        log.warning("EOD capture missing for %s - spawned run_all_offhours.py "
                    "(scheduled task did not deliver)", now_et.date())
        # SAY SO. Until 2026-09-01 this path only wrote to a log, so the backstop
        # covering for a dead scheduled task was invisible: the capture kept landing
        # and nothing ever reported that the primary launcher had stopped working.
        # A fallback that silently becomes the only mechanism is how you end up with
        # ONE mechanism and not know it. Once per day, deduped like every other alert.
        try:
            _c = get_conn()
            try:
                _ensure_alert_dedup_table(_c)
                _dup = _alert_already_sent(_c, now_et.date().isoformat(),
                                           str(now_et.date()), "eod_spawn")
            finally:
                _c.close()
            if not _dup:
                _, _cid = load_creds()
                await ctx.bot.send_message(
                    chat_id=_cid, parse_mode=H,
                    text=("🛟 <b>EOD capture: backstop fired</b>\n\n"
                          f"The scheduled task did not deliver {now_et.date()} by 17:30 ET, "
                          "so the bot launched the chain itself. <b>Your data is being "
                          "captured</b> — this is not a data loss.\n\n"
                          "It does mean the Windows task <code>NYSE_OffHours_Chain</code> is "
                          "not running, and the download now rests on this bot staying up. "
                          "Re-enable it from an <b>admin</b> PowerShell:\n"
                          "<code>Enable-ScheduledTask -TaskName NYSE_OffHours_Chain</code>"))
        except Exception as _ne:
            log.warning(f"EOD spawn notice failed: {_ne}")
    except Exception as e:
        log.warning(f"EOD lane spawn failed: {e}")


async def heat_streamer_alert(ctx: ContextTypes.DEFAULT_TYPE):
    """15-min job: push heat/fade STATE CHANGES only (one alert per ticker|state per
    day via alert_dedup). Market-hours gated; silently no-ops if the lane is off."""
    now_utc = datetime.now(timezone.utc).replace(tzinfo=None)
    if now_utc.weekday() >= 5:
        return
    hm = now_utc.hour * 60 + now_utc.minute
    if not (13 * 60 + 40 <= hm <= 21 * 60):      # EDT/EST union session window
        return
    try:
        day, rows = _heat_scan()
    except Exception as e:
        log.warning(f"heat streamer scan failed: {e}")
        return
    if not rows:
        return
    hot = [m for m in rows if m["state"] and m["age_min"] <= 20]   # fresh bars only
    if not hot:
        return
    conn = get_conn()
    try:
        _ensure_alert_dedup_table(conn)
        fresh = [m for m in hot if not _alert_already_sent(
            conn, day, f"{m['tk']}|{m['state']}", "heat_stream")]
    finally:
        conn.close()
    if not fresh:
        return
    _, chat_id = load_creds()
    try:
        await ctx.bot.send_message(
            chat_id=chat_id, parse_mode=H,
            text=_fmt_heat(fresh, day, title="🔥 HEAT-SEEKER · new state")[:4000])
        log.info(f"heat streamer: pushed {len(fresh)} state change(s)")
    except Exception as e:
        log.warning(f"heat streamer send failed: {e}")


# ── TAX ADVISOR (US federal; approximations for PLANNING — not tax advice) ──
# Defaults = user's situation (MFJ, ~$200K taxable income). /tax [income] overrides.
# 2026 approx MFJ brackets (TCJA rates, thresholds ≈ inflation-adjusted). Update yearly.
_TAX_MFJ = {
    "st": [(0, .10), (24_800, .12), (100_800, .22), (211_400, .24),
           (403_550, .32), (512_450, .35), (768_700, .37)],   # ordinary income marginal
    "lt": [(0, .00), (98_700, .15), (613_000, .20)],           # long-term cap gains
    "niit_over": 250_000,                                      # +3.8% NIIT above this MAGI
}


def _tax_marginal(brackets, income):
    r = brackets[0][1]
    for thr, rate in brackets:
        if income >= thr:
            r = rate
    return r


def _tax_scan(conn, income=200_000):
    """Open STOCK lots: holding period, ST→LT flip date, est. tax if sold today, hedge
    interactions (protective put = clock reset; qualified covered call = clock keeps running),
    wash-sale flags; plus realized YTD ST/LT from closed trades. US federal, MFJ approx."""
    st_rate = _tax_marginal(_TAX_MFJ["st"], income)
    lt_rate = _tax_marginal(_TAX_MFJ["lt"], income)
    niit = 0.038 if income > _TAX_MFJ["niit_over"] else 0.0
    today = datetime.now().date()
    out = {"lots": [], "advice": [], "realized_st": 0.0, "realized_lt": 0.0,
           "st_rate": st_rate, "lt_rate": lt_rate, "niit": niit, "income": income}
    tr = pd.read_sql("SELECT * FROM trades WHERE status='OPEN'", conn)   # stock INCLUDED here
    cl = pd.read_sql("SELECT * FROM trades WHERE status='CLOSED'", conn)
    if not tr.empty:
        _ot = tr["option_type"].astype(str).str.upper()
        stk, opts = tr[_ot.str.startswith("S")], tr[~_ot.str.startswith("S")]
        for _, r in stk.iterrows():
            tk = str(r["ticker"]).upper(); qty = int(r["quantity"] or 0)
            ep = float(r["entry_price"] or 0)
            try:
                ed = datetime.strptime(str(r["entry_date"])[:10], "%Y-%m-%d").date()
            except Exception:
                out["advice"].append(f"⚠️ <b>{tk}</b>: missing/invalid entry_date — fix it "
                                     "(Portfolio → Edit leg) or every tax number for it is wrong")
                continue
            # Pub 550 clock reset: a LONG put opened while the lot was <1y (incl. near-identical
            # class, e.g. GOOG↔GOOGL) WIPES the holding period; the clock restarts the day
            # after the put is GONE. Scan open AND closed puts so history is honored.
            eff_ed, frozen, reset_note, frozen_exp = ed, False, None, None
            try:
                _hist = pd.concat([opts, cl], ignore_index=True)
                _puts = []
                for _, p in _hist.iterrows():
                    _ptk = str(p["ticker"]).upper()
                    if not (_ptk[:4] == tk[:4] and abs(len(_ptk) - len(tk)) <= 1):
                        continue
                    if not str(p["option_type"]).lower().startswith("p") or int(p["quantity"] or 0) <= 0:
                        continue
                    try:
                        p_open = datetime.strptime(str(p["entry_date"])[:10], "%Y-%m-%d").date()
                    except Exception:
                        continue
                    p_gone = None
                    if str(p.get("status", "")).upper() != "OPEN":
                        for _c in (str(p.get("exit_date") or "")[:10], str(p.get("expiry") or "")[:10]):
                            try:
                                p_gone = datetime.strptime(_c, "%Y-%m-%d").date(); break
                            except Exception:
                                continue
                        if p_gone is None:
                            continue
                    _puts.append((p_open, p_gone, str(p.get("expiry") or "")[:10]))
                # Chronological, and each put is judged against the RUNNING clock (eff_ed):
                # a put bought after an earlier reset can re-wipe a still-<1y lot (Pub 550).
                for p_open, p_gone, p_exp in sorted(_puts, key=lambda x: x[0]):
                    if p_open < eff_ed or (p_open - eff_ed).days > 365:
                        continue                    # lot already long-term at THIS put's purchase → no reset
                    if p_gone is None:              # put still on → period wiped AND frozen right now
                        frozen, frozen_exp = True, p_exp
                    elif p_gone + timedelta(days=1) > eff_ed:
                        eff_ed = p_gone + timedelta(days=1)
                        reset_note = (f"⏮️ clock was RESET by a protective put (Pub 550); "
                                      f"restarted {eff_ed} — broker labels may be wrong")
            except Exception:
                pass
            held = 0 if frozen else (today - eff_ed).days   # wiped + not accruing while frozen
            is_lt = (not frozen) and held > 365    # sale must be MORE than 1 year after (restarted) start
            lt_date = eff_ed + timedelta(days=366)
            if frozen and frozen_exp:               # estimate: put held to expiry → restart next day
                try:
                    lt_date = datetime.strptime(frozen_exp, "%Y-%m-%d").date() + timedelta(days=367)
                except ValueError:
                    pass
            spot = _last_price(tk) or 0.0
            unreal = (spot - ep) * qty if spot > 0 else None
            eff = (lt_rate if is_lt else st_rate) + (niit if income > _TAX_MFJ["niit_over"] else 0)
            est_tax = unreal * eff if (unreal or 0) > 0 else 0.0
            save = (unreal * (st_rate - lt_rate)) if (unreal or 0) > 0 and not is_lt else 0.0
            flags = []
            if frozen:
                flags.append("🧊 clock FROZEN by an open protective put (Pub 550) — restarts the day "
                             "after it's gone" + (f"; held to expiry {frozen_exp} → LT ≈ {lt_date}"
                                                  if frozen_exp else ""))
            _htk = opts["ticker"].astype(str).str.upper()
            h = opts[(_htk.str[:4] == tk[:4]) & (_htk.str.len().sub(len(tk)).abs() <= 1)]   # class match (GOOG↔GOOGL)
            for _, o in h.iterrows():
                o_t = str(o["option_type"]).lower(); o_q = int(o["quantity"] or 0)
                o_k = float(o["strike"] or 0)
                try:
                    o_dte = (datetime.strptime(str(o["expiry"])[:10], "%Y-%m-%d").date() - today).days
                except Exception:
                    o_dte = None
                if o_t.startswith("p") and o_q > 0 and qty > 0 and not is_lt:
                    flags.append("🛑 protective PUT on a <1y lot — LT clock RESET while the put is held "
                                 "(straddle rules); clock restarts only after the put is gone")
                if o_t.startswith("c") and o_q < 0 and qty > 0:
                    if spot > 0 and o_k >= spot and (o_dte or 0) > 30:
                        flags.append("✅ short call ≈ Qualified Covered Call (OTM, >30 DTE) — LT clock keeps running")
                    elif spot > 0 and o_k < spot:
                        flags.append("⚠️ short ITM call — likely NOT qualified: suspends the LT clock, straddle rules apply")
            if reset_note:
                flags.append(reset_note)
            out["lots"].append({"tk": tk, "qty": qty, "entry": ep, "entry_date": str(ed),
                                "held": held, "is_lt": is_lt,
                                "lt_date": (f"frozen → ~{lt_date}" if frozen else str(lt_date)),
                                "days_to_lt": (9999 if frozen else max((lt_date - today).days, 0)),
                                "spot": spot, "unreal": unreal, "eff_rate": eff,
                                "est_tax": est_tax, "lt_saves": save, "flags": flags})
            if not is_lt and (unreal or 0) > 0 and 0 < (lt_date - today).days <= 120 and not any("RESET" in f for f in flags):
                out["advice"].append(f"⏳ <b>{tk}</b>: hold {(lt_date - today).days} more days (→ {lt_date}) "
                                     f"and the gain goes LT — saves ≈ <b>${save:,.0f}</b> at your bracket")
    # realized YTD (stock: ST/LT by held days; options: ST unless held >1y)
    if not cl.empty:
        yr = str(today.year)
        for _, r in cl.iterrows():
            if not str(r.get("exit_date", "")).startswith(yr):
                continue
            pnl = pd.to_numeric(r.get("pnl"), errors="coerce")
            pnl = 0.0 if pd.isna(pnl) else float(pnl)     # nan is truthy — `or 0` didn't catch it
            try:
                d0 = datetime.strptime(str(r["entry_date"])[:10], "%Y-%m-%d").date()
                d1 = datetime.strptime(str(r["exit_date"])[:10], "%Y-%m-%d").date()
                lt = (d1 - d0).days > 365
            except Exception:
                lt = False
            out["realized_lt" if lt else "realized_st"] += pnl
        # wash-sale: stock closed at a LOSS within 30d of an OPEN same-ticker lot entry
        _cl_ot = cl["option_type"].astype(str).str.upper()
        for _, r in cl[_cl_ot.str.startswith("S")].iterrows():
            pnl = pd.to_numeric(r.get("pnl"), errors="coerce")
            pnl = 0.0 if pd.isna(pnl) else float(pnl)     # NaN would pass the loss check below
            if pnl >= 0:
                continue
            try:
                xd = datetime.strptime(str(r["exit_date"])[:10], "%Y-%m-%d").date()
            except Exception:
                continue
            for lot in out["lots"]:
                if lot["tk"] == str(r["ticker"]).upper():
                    try:
                        od = datetime.strptime(lot["entry_date"], "%Y-%m-%d").date()
                        if abs((od - xd).days) <= 30:
                            out["advice"].append(f"🚫 <b>{lot['tk']}</b>: WASH SALE — loss ${-pnl:,.0f} realized "
                                                 f"{xd} within 30d of buying the open lot ({od}); loss is "
                                                 "disallowed and added to the new lot's basis")
                    except Exception:
                        pass
    return out


def _fmt_tax(res):
    lots = res["lots"]
    hdr = (f"🧾 <b>Tax Advisor</b> — US federal, MFJ, income ≈ ${res['income']:,.0f}\n"
           f"<i>ST rate {res['st_rate']*100:.0f}% · LT rate {res['lt_rate']*100:.0f}%"
           + (f" · +3.8% NIIT" if res["niit"] else "")
           + " · approximations, not tax advice</i>\n\n")
    if not lots and not res["advice"]:
        return hdr + "No open stock lots. Add shares with an entry date (Portfolio → Add, Type=STOCK)."
    body = ""
    if lots:
        rows = [("🟢" if l["is_lt"] else "🟡", l["tk"], f"{l['held']}d",
                 ("LT" if l["is_lt"] else "🧊" if l["days_to_lt"] >= 9999 else f"{l['days_to_lt']}d"),
                 (f"{l['unreal']:+,.0f}" if l["unreal"] is not None else "—"),
                 f"{l['est_tax']:,.0f}") for l in lots]
        body += _pipe_table(("ST", "Tkr", "Held", "→LT", "Unrl$", "Tax$"), rows, right_cols={2, 3, 4, 5}) + "\n"
        for l in lots:
            for f in l["flags"]:
                body += f"\n{l['tk']}: {f}"
        body += "\n"
    body += (f"\n💰 <b>Realized {datetime.now().year}</b>: ST ${res['realized_st']:+,.0f} "
             f"(taxed ~{res['st_rate']*100:.0f}%) · LT ${res['realized_lt']:+,.0f} "
             f"(~{res['lt_rate']*100:.0f}%)")
    if res["advice"]:
        body += "\n\n" + "\n".join(res["advice"])
    body += ("\n\n<i>Rules encoded: &gt;1y = LT · protective put on a &lt;1y lot resets the clock · "
             "qualified covered calls (OTM, &gt;30 DTE) don't · wash sale = loss + rebuy within ±30d · "
             "options P&amp;L is ST unless held &gt;1y. Federal only; no state tax.</i>")
    return hdr + body


def _app_setting(conn, key, default=None):
    """Universal key/value settings in the DB (app_settings) — user profile facts like
    tax income live HERE, not hardcoded and not in Claude memory."""
    try:
        conn.execute("CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, val TEXT)")
        row = conn.execute("SELECT val FROM app_settings WHERE key=?", (key,)).fetchone()
        return row[0] if row else default
    except Exception:
        return default


def _set_app_setting(conn, key, val):
    conn.execute("CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, val TEXT)")
    conn.execute("INSERT OR REPLACE INTO app_settings VALUES (?, ?)", (key, str(val)))
    conn.commit()


# A10 (docs/PLAN.md, "ALERT CONSOLIDATION"): fold routine recurring status into ONE
# message edited in place per trading day, instead of a fresh push every tick. Scoped to
# ONLY the two jobs that ALWAYS fire on schedule regardless of content (position_monitor,
# intraday_alert) -- heat_streamer_alert/wan_streamer_alert/building_alert are trigger-only
# (one push per NEW state-change/signal, already deduped), which is exactly the "genuine
# news... should interrupt" case the plan says must stay separate, not routine status.
_STATUS_SECTIONS_ORDER = [
    ("position_monitor", "💼 Positions"),
    ("intraday_alert", "⚡ Intraday"),
]
_LAST_STATUS_EDIT = 0.0


_STATUS_LIMIT = 4000        # Telegram hard limit is 4096; leave room for the header + tags


def _status_fit(live, limit=_STATUS_LIMIT):
    """Fit [[key, title, body], ...] into one Telegram message, trimming only what must be.

    Short sections keep every character and hand their unused allowance to the long ones,
    so a 300-char intraday note is not charged the same budget as a 1.9k positions card.
    Only a section that is still over its share after redistribution gets cut, and it is cut
    with _tg_cut so HTML entities stay closed.
    """
    overhead = 60 + sum(len(t) + 46 for _k, t, _b in live)   # header + blockquote wrappers
    budget = max(limit - overhead, 400)
    if sum(len(b) for _k, _t, b in live) <= budget:
        return live
    share, out, n = budget // max(len(live), 1), [], len(live)
    spare = sum(share - len(b) for _k, _t, b in live if len(b) < share)
    over = [i for i, (_k, _t, b) in enumerate(live) if len(b) > share] or [0]
    bonus = spare // len(over)
    for i, (k, t, b) in enumerate(live):
        allow = share + (bonus if i in over else 0)
        out.append([k, t, _tg_cut(b, allow) if len(b) > allow else b])
    return out


async def _status_push(ctx, section_key, body_html, cap=None):
    """Update one section of the consolidated status message and push the combined
    result (new message on a new trading day, else an in-place edit of the same one).

    Sections persist in app_settings; only sections stamped with TODAY's date are
    included in the rebuild, so yesterday's content naturally drops off at the first
    call of a new day rather than needing an explicit reset.

    Sections are stored WHOLE and trimmed only if the assembled message would exceed
    Telegram's limit (user 2026-08-10: "why are messages truncated, fix all of them").
    The old fixed `cap=1400` per section cut 33% off the positions card on every single
    tick -- the NEWS block never survived -- while the finished message came to roughly
    3.4k of the 4096 allowed, so a third of the content was being thrown away to respect
    a budget that was never actually tight. `cap` is honoured if a caller passes one,
    but nothing sets it now.
    """
    global _LAST_STATUS_EDIT
    _, chat_id = load_creds()
    conn = get_conn()
    try:
        today = _et_now().date().isoformat()
        if cap and len(body_html) > cap:
            body_html = _tg_cut(body_html, cap)
        _set_app_setting(conn, f"status_sec_{section_key}", body_html)
        _set_app_setting(conn, f"status_sec_{section_key}_date", today)

        live = []
        for key, title in _STATUS_SECTIONS_ORDER:
            sec = _app_setting(conn, f"status_sec_{key}")
            sec_date = _app_setting(conn, f"status_sec_{key}_date")
            if sec and sec_date == today:
                live.append([key, title, sec])
        if not live:
            return
        blocks = [f"<blockquote expandable><b>{t}</b>\n{sec}</blockquote>"
                  for _k, t, sec in _status_fit(live)]

        now_et = _et_now().replace(tzinfo=None)
        combined = _tg_balance(hdr(f"📟 STATUS · {now_et.strftime('%H:%M ET')}")
                               + "\n\n" + "\n\n".join(blocks))

        msg_date = _app_setting(conn, "status_msg_date")
        msg_id = _app_setting(conn, "status_msg_id")
        is_new_day = (msg_date != today) or not msg_id

        if not is_new_day:
            if (time.time() - _LAST_STATUS_EDIT) < 5:
                # Telegram edit-rate guard (plan's own note: ~1/5s per chat) -- content is
                # already persisted above, the next call's edit will carry it.
                return
            try:
                await ctx.bot.edit_message_text(chat_id=int(chat_id), message_id=int(msg_id),
                                                text=combined, parse_mode=H)
                _LAST_STATUS_EDIT = time.time()
                return
            except Exception as e:
                if "not modified" in str(e).lower():
                    return  # identical content -- nothing to do, not an error
                log.debug(f"status edit failed, sending fresh: {e}")

        m = await ctx.bot.send_message(chat_id=int(chat_id), text=combined, parse_mode=H)
        _set_app_setting(conn, "status_msg_id", m.message_id)
        _set_app_setting(conn, "status_msg_date", today)
        _LAST_STATUS_EDIT = time.time()
    finally:
        conn.close()


