    """/zrev — single-name mean reversion: price z-score vs its own 20d mean."""
    await update.message.reply_text("↕️ Scanning z-score extremes…", parse_mode=H)
    conn = get_conn()
    try:
        rows = _zrev_scan(conn)
    finally:
        conn.close()
    await _send_zrev(update.message, rows)


