# ── COMPOSITE RISK-OFF RADAR (multi-pillar EOD downside warning) ──
# ETFs whose bearish flow / gamma is a market-level (not single-name) tell.
_RISKOFF_INDEX = {"SPY", "QQQ", "IWM", "DIA", "SMH", "SOXX", "SOXL", "XLK", "XLF",
                  "XLE", "XLI", "XLRE", "EEM", "FXI", "KWEB", "TLT", "GLD",
                  "TQQQ", "UPRO", "SPXL"}


def _riskoff_scan(conn):
    """Composite EOD 'risk-off' radar: fuses 5 plain-English downside warning lights
    into a 0-100 score (0 = calm, 100 = danger). Catches the froth/complacency setup
    that precedes selloffs while trend/momentum models still read bullish. Lights:
      1 Crash-insurance buying  — big traders buying index/ETF puts (UOA put flow)
      2 Hot stocks overstretched— crowd favorites ran too far (zrev overbought)
      3 Market too calm         — options cheap vs actual moves (negative VRP)
      4 Broad weakness          — share of stocks rolling over (% below 20d mean)
      5 No shock absorbers       — dealer hedging amplifies drops (negative gamma)
    Each light is 0-20 pts. Returns plain 'pillars' (dicts), plus headline/action text.
    Persists an SPY BEAR fire when RED so it self-scores vs forward returns."""
    import numpy as _np
    pillars = []            # dicts: emoji, label, reading, pts, why
    raw = {"putfires": 0, "putnames": "", "froth": 0, "negvrp": 0,
           "breadth": 0.0, "neggamma": 0, "gammanames": ""}
    def _emoji(pts):
        return "🔴" if pts >= 12 else ("🟡" if pts >= 5 else "🟢")
    def _add(pts, label, reading, why):
        pillars.append({"emoji": _emoji(pts), "label": label, "reading": reading,
                        "pts": pts, "why": why})

    # 1) Crash-insurance buying (index put flow via UOA)
    try:
        uoa = _uoa_scan(conn, top=40)
        ib = [r for r in uoa if r["side"] == "P" and r["ticker"] in _RISKOFF_INDEX]
        names = ", ".join(dict.fromkeys(r["ticker"] for r in ib))
        raw["putfires"] = len(ib); raw["putnames"] = names
        pts = min(20.0, len(ib) * 4.0)
        _add(pts, "Crash-insurance buying", f"{len(ib)} bets",
             f"Big traders loading downside bets on {names}" if names
             else "No unusual downside bets — calm")
    except Exception:
        _add(0.0, "Crash-insurance buying", "n/a", "Data unavailable")

    # 2) Hot stocks overstretched (zrev overbought)
    try:
        shorts = [r for r in _zrev_scan(conn) if r["side"] == "SHORT"]
        names = ", ".join(r["ticker"] for r in shorts[:6])
        raw["froth"] = len(shorts)
        pts = min(20.0, len(shorts) * 2.5)
        _add(pts, "Hot stocks overstretched", f"{len(shorts)} names",
             f"{names} ran too far, too fast — snap-back risk" if names
             else "No crowd favorites look overstretched")
    except Exception:
        _add(0.0, "Hot stocks overstretched", "n/a", "Data unavailable")

    # 3) Market too calm (negative VRP: index IV below realized moves)
    try:
        neg = []
        for tk in ("SPY", "QQQ", "IWM"):
            ivr = _iv_rank(conn, tk); iv = (ivr or {}).get("iv")
            h = _daily_history(tk, 1, conn)
            if not iv or iv <= 0 or h is None or len(h) < 22:
                continue
            r = h.pct_change().dropna().tail(20)
            mad = float((r - r.median()).abs().median())
            rv = 1.4826 * mad * _np.sqrt(252)
            if rv > 0 and (iv - rv) < 0:
                neg.append(tk)
        raw["negvrp"] = len(neg)
        pts = min(20.0, len(neg) * 7.0)
        _add(pts, "Market too calm", f"{len(neg)} of 3",
             f"Options cheap vs how much {', '.join(neg)} is actually moving" if neg
             else "Options fairly priced for the moves")
    except Exception:
        _add(0.0, "Market too calm", "n/a", "Data unavailable")

    # 4) Broad weakness (% of universe below its 20d mean)
    try:
        below = tot = 0
        for tk in SCAN_UNIVERSE:
            h = _daily_history(tk, 1, conn)
            if h is None or len(h) < 21:
                continue
            tot += 1
            if float(h.iloc[-1]) < float(h.tail(20).mean()):
                below += 1
        pct = (below / tot * 100) if tot else 0.0
        raw["breadth"] = pct
        pts = max(0.0, min(20.0, (pct - 40) / 40 * 20))     # 40%→0, 80%→20
        _add(pts, "Broad weakness", f"{pct:.0f}% soft",
             f"{pct:.0f}% of stocks already rolling over under the surface")
    except Exception:
        _add(0.0, "Broad weakness", "n/a", "Data unavailable")

    # 5) No shock absorbers (negative dealer gamma on the index complex)
    try:
        negg = []
        for tk in ("SPY", "QQQ", "IWM"):
            spot = _gex_spot(conn, tk) or _last_price(tk)
            if not spot:
                continue
            if (_compute_gex(tk, conn, spot).get("total_gex") or 0) < 0:
                negg.append(tk)
        raw["neggamma"] = len(negg); raw["gammanames"] = ", ".join(negg)
        pts = min(20.0, len(negg) * 7.0)
        _add(pts, "No shock absorbers", f"{len(negg)} of 3",
             f"Dealer hedging now amplifies drops on {', '.join(negg)}" if negg
             else "Dealer hedging still cushions moves")
    except Exception:
        _add(0.0, "No shock absorbers", "n/a", "Data unavailable")

    score = sum(p["pts"] for p in pillars)      # kept for the context lights only

    # ── TURBULENCE gauge (the one that actually backtests: index put-flow → move
    # SIZE; QQQ t+5 Spearman +0.37, p<0.001). Predicts a big move, NOT its sign. ──
    # RECALIBRATED 2026-08-08 after the user said the alert gave them no confidence. They
    # were right, and measuring it showed why: the old rule was `fires >= 5`, which fired on
    # 89% OF ALL DAYS (134 of 151). A warning that is on nearly every day carries no
    # information, and the forward week after it was indistinguishable from any other week
    # (SPY median |5d| 1.18% vs 1.18% baseline, p=0.243).
    #
    # Two things came out of the re-test:
    #   1. The threshold has to be a PERCENTILE of the signal's own history, not an absolute
    #      count -- the same mistake as reading a dealer's raw net instead of its percentile.
    #   2. The effect is QQQ-SPECIFIC. Measured over 151 days, put-flow vs |forward move|:
    #         QQQ  3d +0.213 (p=0.008) | 5d +0.315 (p=0.00008) | 10d +0.240 (p=0.004)
    #         SPY  5d +0.112 (p=0.17)  | IWM 5d -0.096 (p=0.24)  -- nothing
    #      Three adjacent horizons on QQQ all positive, and only on SIZE: signed direction is
    #      ~0 everywhere (5d rho +0.015, p=0.85). So it predicts MAGNITUDE, never side.
    #
    # Thresholds are the 60th/80th percentile of fire count over that sample. Recalibrate if
    # the universe or the UOA rule changes -- tools/ scripts in the 2026-08-08 session.
    _TURB_P80, _TURB_P60 = 17, 13
    fires = raw["putfires"]
    turb_score = min(100.0, fires * 15.0)
    # Rendered through the house signal template (_signal_writeup, ID 241) rather than
    # hand-typed prose. The HIGH block below reproduces the wording the user set as the
    # standard; the value is that the direction verdict is now COMPUTED, so this block
    # cannot drift back into claiming a side.
    _TURB_OUTCOME = "a >2% Nasdaq week"
    if fires >= _TURB_P80:
        turb_lvl, turb_emoji = "HIGH", "🔴"
        turb_txt = _signal_writeup(
            "Index put-flow is in the TOP 20% of its own history.",
            "favour long premium, widen stops, cut size on short-vol",
            outcome=_TURB_OUTCOME, n=151, hit=0.62, base=0.38,
            median=0.0226, median_base=0.0155, p=0.012, dir_up=0.53)
    elif fires >= _TURB_P60:
        turb_lvl, turb_emoji = "ELEVATED", "🟡"
        turb_txt = _signal_writeup(
            "Index put-flow is in the 60-80th percentile of its own history.",
            "keep size sensible and stops a touch wider — this sits close to the HIGH band",
            outcome=_TURB_OUTCOME, n=38, hit=0.61, base=0.38)
    else:
        turb_lvl, turb_emoji = "NORMAL", "🟢"
        turb_txt = _signal_writeup(
            "Index put-flow is in the BOTTOM 60% of its own history — the calm band.",
            "size normally — but 38% is not zero, so keep stops in place",
            outcome=_TURB_OUTCOME, n=81, hit=0.38, base=0.38)

    # ── DIRECTION lean (soft, low confidence: dealer gamma + breadth; correctly
    # signed but NOT statistically significant in ~6mo history — a hint, not a trigger). ──
    dir_pts = 0
    dir_pts += 1 if raw["neggamma"] >= 2 else (-1 if raw["neggamma"] == 0 else 0)
    dir_pts += 1 if raw["breadth"] >= 60 else (-1 if raw["breadth"] <= 45 else 0)
    if dir_pts >= 2:
        dir_lean, dir_emoji = "DOWN", "🔴"
        dir_txt = (f"Slight downside tilt — dealers short gamma ({raw['gammanames'] or 'none'}) "
                   f"and {raw['breadth']:.0f}% of stocks soft. Low confidence.")
    elif dir_pts <= -2:
        dir_lean, dir_emoji = "UP", "🟢"
        dir_txt = "Slight upside tilt — dealer gamma cushions and breadth is firm. Low confidence."
    else:
        dir_lean, dir_emoji = "NEUTRAL", "🟡"
        dir_txt = "No directional edge — coin-flip either way. Let price pick the side."

    # headline/action driven by TURBULENCE (proven) first, direction second
    # Bottom line now leads with the BASE RATE rather than an adjective. "Expect a large move"
    # told the user nothing they could size a trade against; "62% vs 38%" does.
    if turb_lvl == "HIGH":
        remoji, headline = turb_emoji, "Big move brewing"
        action = (f"{_signal_odds_phrase(_TURB_OUTCOME, 0.62, 0.38)}, measured on 151 days. "
                  f"Size down, widen stops, prefer long premium over short. "
                  f"Direction {dir_lean} — historically 53% up after this reading, i.e. no side.")
    elif turb_lvl == "ELEVATED":
        remoji, headline = turb_emoji, "Stay nimble"
        action = (f"{_signal_odds_phrase(_TURB_OUTCOME, 0.61, 0.38)}. Keep size sensible. "
                  f"Direction {dir_lean} — no measured edge either way.")
    else:
        remoji, headline = dir_emoji if dir_lean != "NEUTRAL" else "🟢", "Routine conditions"
        action = (f"{_signal_odds_phrase(_TURB_OUTCOME, 0.38, 0.38)} — the calm band, though "
                  f"still not zero. Normal sizing. Direction {dir_lean}.")

    if turb_lvl == "HIGH":     # self-score the turbulence call vs SPY forward |move|
        _persist_scanner_fires(conn, "riskoff", [("SPY", "BEAR" if dir_lean == "DOWN" else "BULL",
                                                  min(99.0, 50 + turb_score / 2))])
    return {"score": score, "remoji": remoji, "headline": headline, "action": action,
            "turbulence": {"level": turb_lvl, "score": turb_score, "emoji": turb_emoji,
                           "text": turb_txt, "fires": fires, "names": raw["putnames"]},
            "direction": {"lean": dir_lean, "emoji": dir_emoji, "text": dir_txt},
            "pillars": pillars, "nextday": _riskoff_nextday(conn, score)}


def _riskoff_nextday(conn, score):
    """Plain next-session game plan for SPY, anchored to dealer gamma walls + the
    20d trend. Combines the risk-off score, price vs gamma-flip (stable above /
    amplified below), and price vs 20d mean into a lean (up/down/chop) with concrete
    hold-vs-lose trigger levels. Returns None if SPY spot/levels unavailable."""
    try:
        import numpy as _np
        spot = _gex_spot(conn, "SPY") or _last_price("SPY")
        if not spot:
            return None
        g = _compute_gex("SPY", conn, spot)
        flip = g.get("zero_gamma")
        support = g.get("put_wall")
        resist = g.get("call_wall")
        h = _daily_history("SPY", 1, conn)
        mean20 = float(_np.mean(list(h.tail(20)))) if (h is not None and len(h) >= 20) else spot
        if not support or support >= spot:      # need a level below price
            support = round(mean20)
        if not resist or resist <= spot:         # need a level above price
            resist = round(spot * 1.012)
        down2 = round(support * 0.985)           # next stop if support breaks (~1.5% lower)
        tilt = 0
        if flip:
            tilt += 1 if spot >= flip else -1    # above gamma-flip = dampened/stable
        tilt += 1 if spot >= mean20 else -1      # above/below 20d trend
        tilt += (-1 if score >= 55 else (1 if score < 30 else 0))
        if tilt >= 2:
            lean, lemoji = "Lean UP — relief / bounce", "🟢"
        elif tilt <= -2:
            lean, lemoji = "Lean DOWN — more downside risk", "🔴"
        else:
            lean, lemoji = "Choppy — range-bound, no clear edge", "🟡"
        flip_txt = f" (flip {flip:.0f})" if flip else ""
        text = (f"SPY ~{spot:.0f}. Holds {support:.0f} → bounce toward {resist:.0f}{flip_txt}; "
                f"loses {support:.0f} → downside opens toward ~{down2:.0f}.")
        return {"lean": lean, "emoji": lemoji, "spot": spot, "support": support,
                "resist": resist, "flip": flip, "down2": down2, "text": text}
    except Exception:
        return None


def _riskoff_message(res):
    """Plain-English Telegram body shared by /riskoff and the auto alert.
    Two gauges: TURBULENCE (proven — predicts move size) + DIRECTION (soft lean)."""
    t = res["turbulence"]; d = res["direction"]
    # Compact table uses SHORT complete tags (never mid-word truncation), with the full
    # pillar name + why spelled out in per-row detail lines below (scanner-format standard).
    _short = {
        "Crash-insurance buying": "Put flow",
        "Hot stocks overstretched": "Froth",
        "Market too calm": "Low VRP",
        "Broad weakness": "Breadth",
        "No shock absorbers": "Neg gamma",
    }
    pillars_tbl = _pipe_table(
        ("ST", "Pillar", "Reading"),
        [(p["emoji"], _short.get(p["label"], p["label"])[:10], p["reading"][:10])
         for p in res["pillars"]])
    pillars_detail = "\n".join(
        f"{p['emoji']} <b>{p['label']}</b> — {p['reading']}: {p['why']}"
        for p in res["pillars"])
    nd = res.get("nextday")
    nd_block = (f"\n\n📅 <b>Next session — {nd['lean']}</b>\n{nd['text']}") if nd else ""
    return (f"{res['remoji']} <b>MARKET RADAR — {res['headline']}</b>\n\n"
            f"🌪️ <b>Big-move risk (next ~week): {t['level']}</b> {t['emoji']}\n{t['text']}\n\n"
            f"🧭 <b>Direction lean: {d['lean']}</b> {d['emoji']}\n{d['text']}\n\n"
            f"👉 <b>Bottom line:</b> {res['action']}"
            f"{nd_block}\n\n"
            f"<i>Backtested: put-flow predicts move SIZE (p&lt;0.01); direction is a weak hint only. "
            f"Context below · not advice.</i>\n"
            f"{pillars_tbl}\n"
            f"{pillars_detail}")


