# Keywords that map a live headline to a macro event in MACRO_EVENT_MAP.
_EVENT_NEWS_KW = {
    "iran":           ["iran", "tehran", "sanction", "nuclear deal", "jcpoa"],
    "war":            ["war", "missile", "airstrike", "attack", "conflict", "escalat",
                       "invasion", "gaza", "israel", "ukraine", "strike on"],
    "oil_spike":      ["oil", "crude", "opec", "hormuz", "brent", "wti", "barrel"],
    "fed_cut":        ["rate cut", "dovish", "fed cut", "cut rates", "easing", "pivot"],
    "fed_hike":       ["rate hike", "hawkish", "hike rates", "raise rates", "tightening"],
    "china_stimulus": ["china", "beijing", "stimulus", "pboc", "yuan", "reopening"],
    "usd_up":         ["dollar", "dxy", "greenback"],
}

# Primary tracking instrument + expected direction per event (for the journal).
_EVENT_TRACK = {
    "iran":           ("USO", "SHORT"),
    "oil_spike":      ("XLE", "LONG"),
    "fed_cut":        ("TLT", "LONG"),
    "fed_hike":       ("TLT", "SHORT"),
    "war":            ("GLD", "LONG"),
    "china_stimulus": ("FXI", "LONG"),
    "usd_up":         ("UUP", "LONG"),
}

_NSE_SYMS = None      # NSE symbol set, read once from India_data.db
_SYM_ALIAS = {}       # bare symbol -> Yahoo symbol (or None when there is no alias)


def _yf_alias(tk):
    """Bare symbol that nothing quotes in the US -> its foreign Yahoo symbol.

    User 2026-08-10: MOTHERSON was added from the NSE without the `.NS` suffix, so every
    price lane came back empty and the grid fell back to the ENTRY price — a position that
    looked flat forever. Yahoo needs MOTHERSON.NS.

    Only reached AFTER the US lanes have all failed, so a US ticker never pays for this. The
    NSE check is a local set lookup against India_data.db, not a network call, which is what
    makes it safe to try: a symbol that collides with a US ticker (BSE, TITAN) already got a
    US quote and never arrives here. The answer is cached in `ticker_country`, and resolving
    one also fixes its flag — an NSE-quoted symbol is Indian by definition."""
    global _NSE_SYMS, _SYM_ALIAS, _FLAG_DB
    tk = str(tk or "").upper().strip()
    if not tk or "." in tk:
        return None
    if tk in _SYM_ALIAS:
        return _SYM_ALIAS[tk]
    # A symbol that DOES quote in the US has no alias, full stop. Without this guard the
    # function was callable from anywhere and got INFY wrong: Infosys lists on the NSE too,
    # so INFY resolved to INFY.NS and its currency came back INR — but the ADR the user
    # would hold trades in New York, in dollars. (_spot_price is 60s-cached, so the extra
    # call is free on the path that already looked the price up.)
    try:
        if _spot_price(tk) > 0:
            _SYM_ALIAS[tk] = None
            return None
    except Exception:
        pass
    alias = None
    try:
        conn = get_conn()
        _flag_setup(conn)
        cols = [d[1] for d in conn.execute("PRAGMA table_info(ticker_country)")]
        if "yahoo" not in cols:
            conn.execute("ALTER TABLE ticker_country ADD COLUMN yahoo TEXT")
            conn.commit()
        row = conn.execute("SELECT yahoo FROM ticker_country WHERE ticker=?", (tk,)).fetchone()
        if row and row[0]:
            _SYM_ALIAS[tk] = row[0]
            conn.close()
            return row[0]
        if _NSE_SYMS is None:
            try:
                ic = _india_conn()
                _NSE_SYMS = {r[0].upper() for r in
                             ic.execute("SELECT DISTINCT symbol FROM india_daily")}
                ic.close()
            except Exception:
                _NSE_SYMS = set()
        if tk in _NSE_SYMS:
            cand = f"{tk}.NS"
            px = 0.0
            try:
                px = _spot_price(cand)
                if not px:
                    h = yf.Ticker(cand).history(period="5d")
                    px = float(h["Close"].iloc[-1]) if h is not None and len(h) else 0.0
            except Exception:
                px = 0.0
            if px and px > 0:
                alias = cand
                conn.execute(
                    "INSERT OR REPLACE INTO ticker_country (ticker, flag, country, resolved, "
                    "yahoo) VALUES (?,?,?,?,?)",
                    (tk, "🇮🇳", "India", datetime.now().strftime("%Y-%m-%d"), cand))
                conn.commit()
                _FLAG_DB = None          # so the flag picks up 🇮🇳 on the next read
        conn.close()
    except Exception:
        log.debug("alias resolve failed for %s", tk, exc_info=True)
    _SYM_ALIAS[tk] = alias
    return alias


def _last_price(ticker):
    """Live-first (shares _spot_price 60s cache); history/stooq fallback."""
    px = _spot_price(ticker)
    if px > 0:
        return px
    try:
        h = yf.Ticker(ticker).history(period="5d")
        if len(h) >= 1 and float(h["Close"].iloc[-1]) > 0:
            return float(h["Close"].iloc[-1])
    except Exception:
        pass
    px = _stooq_price(ticker)
    if px and px > 0:
        return px
    # Nothing quotes it in the US — it may be a bare foreign symbol (see _yf_alias).
    alt = _yf_alias(ticker)
    if alt:
        px = _spot_price(alt)
        if px > 0:
            return px
        try:
            h = yf.Ticker(alt).history(period="5d")
            if len(h) >= 1 and float(h["Close"].iloc[-1]) > 0:
                return float(h["Close"].iloc[-1])
        except Exception:
            pass
    return 0.0

def _fetch_macro_headlines(limit=40):
    """Pull recent macro headlines from Yahoo RSS (no API key). Returns list of
    (title, link, when)."""
    try:
        import feedparser, html as _h, time as _t
    except Exception:
        return []
    feeds = ["CL=F", "^VIX", "SPY", "GLD", "^TNX", "DX=F", "XLE", "FXI"]
    seen, out = set(), []
    for sym in feeds:
        try:
            fp = feedparser.parse(
                f"https://feeds.finance.yahoo.com/rss/2.0/headline?s={sym}&region=US&lang=en-US")
            for e in fp.entries[:6]:
                title = _h.unescape(e.get("title", "")).strip()
                if not title or len(title) < 20:
                    continue
                k = title[:55].lower()
                if k in seen:
                    continue
                seen.add(k)
                pp = e.get("published_parsed", None)
                when = (_t.strftime("%d%b %H:%M", pp).lstrip("0") if pp else "")
                out.append((title, e.get("link", "").strip(), when))
        except Exception:
            continue
        if len(out) >= limit:
            break
    return out

def _event_news_matches(headlines, keys=None):
    """Map each event key to its most recent matching headline. {key: (title, link, when)}."""
    keys = keys or list(_EVENT_NEWS_KW)
    res = {}
    for title, link, when in headlines:
        tl = title.lower()
        for k in keys:
            if k in res:
                continue
            if any(kw in tl for kw in _EVENT_NEWS_KW.get(k, [])):
                res[k] = (title, link, when)
    return res

def _setup_event_journal(conn):
    try:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS event_journal ("
            "id INTEGER PRIMARY KEY AUTOINCREMENT, event_key TEXT, ticker TEXT,"
            " direction TEXT, entry_price REAL, entry_date TEXT,"
            " status TEXT DEFAULT 'OPEN', exit_price REAL, note TEXT)")
        conn.commit()
    except Exception:
        pass

def event_journal_log(conn, event_key, ticker=None, direction=None, note=""):
    """Log an event-driven idea so its outcome can be tracked. Defaults to the
    event's primary tracking instrument."""
    _setup_event_journal(conn)
    ev = event_trade_map(event_key)
    if not ev:
        return None
    real_key = next((k for k in MACRO_EVENT_MAP if MACRO_EVENT_MAP[k] is ev), event_key)
    if not ticker or not direction:
        t_def = _EVENT_TRACK.get(real_key, (None, "LONG"))
        ticker = ticker or t_def[0]
        direction = (direction or t_def[1]).upper()
    if not ticker:
        return None
    px = _last_price(ticker)
    today = datetime.now().strftime("%Y-%m-%d")
    try:
        conn.execute(
            "INSERT INTO event_journal (event_key, ticker, direction, entry_price, entry_date, status, note)"
            " VALUES (?,?,?,?,?, 'OPEN', ?)",
            (real_key, ticker.upper(), direction.upper(), px, today, note))
        conn.commit()
    except Exception:
        return None
    return {"event": real_key, "ticker": ticker.upper(), "direction": direction.upper(),
            "entry": px, "date": today}

def _fmt_journal_review(conn):
    _setup_event_journal(conn)
    try:
        df = pd.read_sql("SELECT * FROM event_journal ORDER BY id DESC", conn)
    except Exception:
        return "Event journal empty. Log one with <code>/logevent iran</code>."
    if df.empty:
        return ("\U0001F4D3 <b>EVENT JOURNAL</b>\nNo entries yet.\n"
                "Log an event idea: <code>/logevent iran</code>")
    lines = ["\U0001F4D3 <b>EVENT JOURNAL REVIEW</b>", ""]
    wins = total = 0
    for _, r in df.iterrows():
        tkr = str(r["ticker"]); direction = str(r["direction"])
        entry = float(r["entry_price"] or 0)
        cur = _last_price(tkr)
        move = (cur - entry) / entry * 100 if entry > 0 else 0.0
        working = (move > 0 and direction == "LONG") or (move < 0 and direction == "SHORT")
        edge = move if direction == "LONG" else -move
        total += 1
        if edge > 0:
            wins += 1
        ico = "\U0001F7E2" if working else "\U0001F534"
        lines.append(f"{ico} <b>{str(r['event_key'])}</b> {direction} {tkr}")
        lines.append(f"   entry ${entry:.2f} → ${cur:.2f}  ({move:+.1f}%, edge {edge:+.1f}%)  {str(r['entry_date'])}")
    hit = (wins / total * 100) if total else 0
    _k = _kelly_fraction(wins / total, 1.0) if total else 0.0
    lines += ["", f"<b>Track record:</b> {wins}/{total} working ({hit:.0f}%)",
              f"<b>Suggested size:</b> ~{_k*50:.0f}% of risk budget (half-Kelly)",
              "<i>Edge = move in your direction. This is YOUR realised history, not a prediction.</i>"]
    return "\n".join(lines)

