# ═══════════════════════════════════════════════════════════════════
# ── /gex POSITION-AWARE GAMMA  +  GOOGLE-NEWS PER-EVENT
# ═══════════════════════════════════════════════════════════════════
_EVENT_NEWS_QUERY = {
    "iran":           "Iran sanctions oil nuclear deal",
    "war":            "Middle East war conflict escalation",
    "oil_spike":      "oil price OPEC crude Hormuz",
    "fed_cut":        "Federal Reserve interest rate cut",
    "fed_hike":       "Federal Reserve interest rate hike",
    "china_stimulus": "China stimulus economy PBOC",
    "usd_up":         "US dollar DXY strength",
}

def _event_news_google(keys=None):
    """Targeted per-event headlines from Google News RSS (no key). {key:(title,link,when)}."""
    keys = keys or list(_EVENT_NEWS_QUERY)
    try:
        import feedparser, html as _h, time as _t, urllib.parse as _u
    except Exception:
        return {}
    res = {}
    for k in keys:
        q = _EVENT_NEWS_QUERY.get(k) or k
        try:
            fp = feedparser.parse(
                "https://news.google.com/rss/search?q=" + _u.quote(q) + "&hl=en-US&gl=US&ceid=US:en")
            for e in fp.entries[:1]:
                title = _h.unescape(e.get("title", "")).strip()
                if not title:
                    continue
                pp = e.get("published_parsed", None)
                when = _t.strftime("%d%b %H:%M", pp).lstrip("0") if pp else ""
                res[k] = (title, e.get("link", "").strip(), when)
        except Exception:
            continue
    return res

def _gex_spot(conn, tk):
    """Spot for GEX/co-pilot maths — LIVE first, EOD only as a fallback.

    Was EOD-first: _opex_spot() reads the last captured close, so during the session the
    co-pilot priced GOOG at 356.65 while it actually traded 367.65 -- 3% stale, which
    silently invalidates every "distance to a level" test built on it (user 2026-08-03).
    """
    live = 0.0
    try:                       # freshest: our own 1m intraday lane
        _b = _intraday_last(tk)
        if _b and _b[0] and (_b[1] is None or _b[1] <= 90):   # bar no older than ~90 min
            live = float(_b[0])
    except Exception:
        pass
    if live <= 0:
        try:
            live = float(_last_price(tk) or 0)
        except Exception:
            live = 0.0
    if live > 0:
        return live
    s = _opex_spot(conn, tk)
    if s <= 0:
        s = _last_price(tk)
    return s

def _gex_trend(conn, tk):
    """Daily 9/21/50 EMA stack — the co-pilot's macro direction filter.

    Bullish 9>21>50 (longs only) · Bearish 9<21<50 (shorts only) · anything else Tangled
    (no trades). Returns (label, emoji, dict of the three EMAs).
    """
    h = _daily_history(tk, 2, conn)
    if h is None or len(h) < 60:
        return "Unknown", "⚪", {}
    s = pd.Series([float(x) for x in h])
    e9, e21, e50 = (s.ewm(span=n, adjust=False).mean().iloc[-1] for n in (9, 21, 50))
    d = {"9": e9, "21": e21, "50": e50}
    if e9 > e21 > e50:
        return "Bullish", "🟢", d
    if e9 < e21 < e50:
        return "Bearish", "🔴", d
    return "Tangled", "🟡", d


def _gex_pick_expiry(conn, tk, want=None):
    """Resolve an expiry preference to a real captured expiry.

    The framework leans on 0DTE/weekly walls, but `_compute_gex` defaults to the monthly
    (~21 DTE), which is a different structure entirely. `want`: None/'monthly' = default,
    '0dte' = nearest, 'weekly' = nearest beyond today.
    """
    if not want:
        return None
    try:
        rows = [r[0] for r in conn.execute(
            "SELECT DISTINCT expiry_date FROM options_openbb WHERE ticker=? AND "
            "trade_date=(SELECT MAX(trade_date) FROM options_openbb WHERE ticker=?) "
            "ORDER BY expiry_date", (tk.upper(), tk.upper()))]
    except Exception:
        return None
    if not rows:
        return None
    w = str(want).lower()
    if w in ("0dte", "today", "nearest"):
        return _exp_iso(rows[0])
    if w in ("weekly", "week"):
        return _exp_iso(rows[1] if len(rows) > 1 else rows[0])
    return None


def _gex_levels(conn, tk, spot, expiry=None):
    """The structural map: gamma flip, call/put wall, control node (highest-OI strike)."""
    g = _compute_gex(tk, conn, spot, expiry=expiry) or {}
    node = None
    try:
        sig = analyze_inst_signals(tk, conn) or {}
        walls = sig.get("gamma_walls") or []
        # anchor to SPOT: analyze_inst_signals bands its walls around the median strike, so
        # on a wide chain the biggest-OI strike can sit far from where price actually is
        # (SPY returned a $550 "control node" against a $756 spot). A magnet 27% away is
        # not a magnet, so only strikes within +/-10% of spot qualify.
        near = [w for w in walls if abs(float(w.get("strike", 0)) - spot) <= spot * 0.10]
        if near:
            node = float(max(near, key=lambda w: w.get("total_oi", 0))["strike"])
        mp = sig.get("max_pain")
        if node is None and mp:
            _m = float(mp[0]["strike"]) if isinstance(mp, list) and mp else None
            node = _m if (_m and abs(_m - spot) <= spot * 0.10) else None
    except Exception:
        pass
    return {"flip": g.get("zero_gamma"), "call_wall": g.get("call_wall"),
            "put_wall": g.get("put_wall"), "node": node,
            "regime": g.get("gex_signal"), "gex_m": g.get("total_gex_m", 0.0),
            "expiry": g.get("expiry"), "dte": g.get("dte")}


def _gex_confirm(tk, lookback=20):
    """Legs 2 and 3 of the confirmation triad, verified from real 1-minute bars.

    The source framework requires THREE things before an entry: price at a mapped level
    (structure), a price-action trigger, and a localized volume surge. Structure we can
    always check. Until now the other two were only PRINTED as requirements, which meant a
    GREEN LIGHT could fire on structure alone — weaker than the framework intends.

    US_intraday.db carries 1m OHLCV, so both are now measured:
      volume  — last bar vs the mean of the prior `lookback` bars (>=1.5x = surge)
      action  — rejection candle (long wick, close in the top/bottom third of the range)
                or a close back through the 9-EMA of the 1m series

    Returns None when the ticker is not in the intraday lane (32 tickers, from 2026-07-15),
    and the caller then reports UNVERIFIED rather than silently passing the leg.
    """
    import os as _os, sqlite3 as _sql
    try:
        p = _os.path.join(DATA_DIR, "US_intraday.db")
        if not _os.path.exists(p):
            return None
        ic = _sql.connect(p, timeout=15)
        df = pd.read_sql(
            "SELECT ts, open, high, low, close, volume FROM intraday_bars WHERE ticker=? AND "
            "trade_date=(SELECT MAX(trade_date) FROM intraday_bars WHERE ticker=?) "
            "ORDER BY ts", ic, params=(tk, tk))
        day = ic.execute("SELECT MAX(trade_date) FROM intraday_bars WHERE ticker=?",
                         (tk,)).fetchone()
        ic.close()
    except Exception:
        return None
    if df is None or len(df) < lookback + 2:
        return None
    # The most recent 1m row is often a PARTIAL bar still being filled: volume 0 while the
    # minute is in progress. Scoring it made the surge check read "0.0x its 20-bar average"
    # and fail the volume leg for everything, all session (2026-08-03).
    if len(df) > lookback + 2 and float(df["volume"].iloc[-1] or 0) <= 0:
        df = df.iloc[:-1]
    last = df.iloc[-1]
    prior = df.iloc[-(lookback + 1):-1]
    avg_v = float(prior["volume"].mean() or 0)
    vol_x = (float(last["volume"]) / avg_v) if avg_v > 0 else 0.0

    o, h, l, c = (float(last[k]) for k in ("open", "high", "low", "close"))
    rng = max(h - l, 1e-9)
    pos = (c - l) / rng                       # 1.0 = closed on the high, 0.0 = on the low
    ema9 = float(df["close"].ewm(span=9, adjust=False).mean().iloc[-1])
    prev_c = float(df["close"].iloc[-2])
    rejection_up = pos >= 0.66 and (min(o, c) - l) / rng >= 0.33      # long lower wick
    rejection_dn = pos <= 0.34 and (h - max(o, c)) / rng >= 0.33      # long upper wick
    reclaim_up = prev_c < ema9 <= c
    reclaim_dn = prev_c > ema9 >= c
    return {"day": (day or [None])[0], "bars": len(df), "vol_x": vol_x,
            "vol_ok": vol_x >= 1.5, "close": c, "ema9": ema9,
            "pa_up": bool(rejection_up or reclaim_up),
            "pa_dn": bool(rejection_dn or reclaim_dn),
            "why": ("rejection candle" if (rejection_up or rejection_dn)
                    else ("9-EMA reclaim" if (reclaim_up or reclaim_dn) else "no trigger"))}


_GEX_HONESTY = ("<i>⚠️ <b>Direction:</b> no edge — the `gex` model hit 40.2% over 107 fires "
                "(p=0.21 de-overlapped). Don't trade these levels for direction. "
                "<b>Volatility:</b> measured 2026-08-02, SPY's own high-GEX days were "
                "followed by 10.2% realised vol vs 14.0% after low-GEX days (QQQ 16.6% vs "
                "23.6%) — correctly signed and economically large, but n=12 per bucket, "
                "p≈0.06–0.09, NOT significant. So treat GEX as a regime read (chop vs "
                "velocity) that suits sizing and strategy choice, never as an entry signal. "
                "The FILTER below is what's actually worth following. See ADOPTED.md Part 10.</i>")


def _gex_blueprint(conn, tk, want_exp=None):
    """MODE 1 — pre-market structural map, auto-filled from our own capture.

    The source prompt has you paste levels in by hand from SpotGamma/Tradytics. We already
    compute all four from the captured chain, so this reads them straight out of the DB.
    """
    tk = tk.upper()
    spot = _gex_spot(conn, tk)
    if not spot:
        return f"📐 <b>{tk}</b>: no price available."
    L = _gex_levels(conn, tk, spot, _gex_pick_expiry(conn, tk, want_exp))
    trend, temoji, emas = _gex_trend(conn, tk)
    flip, cw, pw, node = L["flip"], L["call_wall"], L["put_wall"], L["node"]
    f = lambda v: (f"${v:,.2f}" if isinstance(v, (int, float)) and v else "n/a")

    out = [hdr(f"🔎 GEX BLUEPRINT — {tk}"), ""]
    out.append(_pipe_table(("Level", "Value"), [
        ("Spot", f(spot)),
        ("Trend filter", f"{temoji} {trend}"),
        ("Gamma flip", f(flip)),
        ("Call wall", f(cw)),
        ("Put wall", f(pw)),
        ("Control node", f(node)),
        ("Net GEX", f"{L['gex_m']:+,.0f}M"),
        ("Expiry", f"{L['expiry']} ({L['dte']}d)"),
    ]))
    if emas:
        out.append(f"<i>EMA 9 {emas['9']:.2f} · 21 {emas['21']:.2f} · 50 {emas['50']:.2f}</i>")
    out.append("")

    if trend == "Tangled":
        out.append("🟡 <b>NO-TRADE — moving averages are tangled.</b> The framework's own "
                   "first rule is to sit in cash when the daily stack is not clean. "
                   "Everything below is context only.")
        out.append("")

    above = bool(flip) and spot >= flip
    out.append(shdr("📈 Scenario A — above the flip (+GEX)"))
    out.append(f"• Condition: holds above {f(flip)}")
    out.append("• Dealer effect: they buy dips / sell rallies — moves get DAMPENED. "
               "Expect chop and mean reversion, not clean breakouts.")
    if trend == "Bearish":
        out.append("• ⛔ <b>PASS</b> — longs here fight a bearish daily stack.")
    else:
        out.append(f"• Play: bounce off {f(flip)} or {f(node)} <b>on a volume surge</b> → "
                   f"target {f(cw)}. Cut if a candle closes back under {f(flip)}.")
    out.append("")
    out.append(shdr("📉 Scenario B — below the flip (−GEX)"))
    out.append(f"• Condition: breaks and holds below {f(flip)}")
    out.append("• Dealer effect: they sell into weakness — moves get AMPLIFIED. "
               "Velocity expands; trail stops tighter.")
    if trend == "Bullish":
        out.append("• ⛔ <b>PASS</b> — shorts here fight a bullish daily stack. "
                   "Sit out rather than trade against your own filter.")
    else:
        out.append(f"• Play: retest of {f(flip)} from underneath, or breakdown under "
                   f"{f(node)} → target {f(pw)}.")
    out.append("")
    out.append(f"<b>Now:</b> price is {'ABOVE' if above else 'BELOW'} the flip → "
               f"{'+GEX / mean-reverting' if above else '−GEX / expansion'} regime.")
    out.append("")
    out.append(_GEX_HONESTY)
    return "\n".join(out)


def _gex_check(conn, tk, side, want_exp=None):
    """MODE 2 — live execution filter. Gates a PROPOSED trade against the 3-part checklist."""
    tk, side = tk.upper(), (side or "").lower()
    want_long = side.startswith("c") or side in ("long", "buy", "bull")
    spot = _gex_spot(conn, tk)
    if not spot:
        return f"📐 <b>{tk}</b>: no price available."
    L = _gex_levels(conn, tk, spot, _gex_pick_expiry(conn, tk, want_exp))
    trend, temoji, _ = _gex_trend(conn, tk)
    flip, cw, pw, node = L["flip"], L["call_wall"], L["put_wall"], L["node"]
    f = lambda v: (f"${v:,.2f}" if isinstance(v, (int, float)) and v else "n/a")
    above = bool(flip) and spot >= flip

    aligned = (trend == "Bullish" and want_long) or (trend == "Bearish" and not want_long)
    regime_ok = (want_long and above) or ((not want_long) and not above)
    # nearest mapped level, and how far price sits from it in %
    lv = [(n, v) for n, v in (("gamma flip", flip), ("call wall", cw),
                              ("put wall", pw), ("control node", node)) if v]
    near, dist = ("none mapped", None)
    if lv:
        n_, v_ = min(lv, key=lambda x: abs(spot - x[1]))
        near, dist = n_, abs(spot - v_) / spot * 100

    cf = _gex_confirm(tk)                      # legs 2+3 from real 1m bars
    if cf:
        pa_ok = cf["pa_up"] if want_long else cf["pa_dn"]
        pa_txt = f"{cf['why']} on {cf['day']}"
        vol_ok, vol_txt = cf["vol_ok"], f"last bar {cf['vol_x']:.1f}x its 20-bar average"
    else:
        # not in the intraday lane -> report UNVERIFIED and fail the leg. A checklist that
        # passes what it cannot see is worse than one that admits the gap.
        pa_ok = vol_ok = False
        pa_txt = vol_txt = "no 1m bars for this ticker (intraday lane covers 32 names)"

    checks = [
        ("Macro trend", aligned,
         f"daily stack {trend}, you want {'CALLS' if want_long else 'PUTS'}"),
        ("GEX regime", regime_ok,
         f"price {'above' if above else 'below'} flip → "
         f"{'+GEX dampening' if above else '−GEX expansion'}"),
        ("At a level", dist is not None and dist <= 0.75,
         f"nearest is {near}" + (f", {dist:.2f}% away" if dist is not None else "")),
        ("Price action", pa_ok, pa_txt),
        ("Volume surge", vol_ok, vol_txt),
    ]
    go = all(ok for _, ok, _ in checks)
    out = [hdr(f"🚦 {'GREEN LIGHT' if go else 'RED LIGHT — PASS'} · {tk} "
               f"{'CALLS' if want_long else 'PUTS'}"), ""]
    out.append(_pipe_table(("Check", "", "Detail"),
                           [(n, "✅" if ok else "❌", d[:40]) for n, ok, d in checks]))
    out.append("")
    if go:
        tgt = cw if want_long else pw
        stop = flip if flip else node
        out.append(f"• <b>Entry trigger CONFIRMED:</b> {pa_txt} with {vol_txt} — "
                   f"all three legs of the checklist verified, not assumed.")
        out.append(f"• <b>Stop:</b> just beyond {f(stop)} (behind the level being defended)")
        out.append(f"• <b>Target:</b> {f(tgt)}")
        out.append("• <b>Abort</b> if volume dries up or price stalls at the level.")
    else:
        fails = [n for n, ok, _ in checks if not ok]
        out.append(f"• <b>Blocked by:</b> {', '.join(fails)}")
        if not aligned:
            out.append(f"• Taking {'calls' if want_long else 'puts'} against a {trend} daily "
                       f"stack is the exact trade this framework exists to stop.")
        if not regime_ok and want_long and not above:
            out.append(f"• Below the flip dealers must SELL into weakness — buying calls here "
                       f"is catching a falling knife. Reclaim {f(flip)} on volume first.")
        out.append("• No entry authorised. Stand down.")
    out.append("")
    out.append(_GEX_HONESTY)
    return "\n".join(out)


