def _screen_masters(conn, model="graham", tickers=None, top=15, min_pass=None):
    """Score a universe against one master's checklist. Returns list of dicts, best first.

    Ranked by tests passed, then by cheapness (P/E) so ties break toward margin of safety.
    """
    m = _SCREEN_MODELS.get(str(model).lower())
    if not m:
        return []
    tks = [str(t).upper() for t in (tickers or _screen_universe(conn))]
    fund = _screen_fundamentals(conn, tks)
    n_tests = len(m["tests"])
    if min_pass is None:
        min_pass = max(3, n_tests - 3)          # allow a few misses; perfection is rare
    rows = []
    for tk, f in fund.items():
        if not f:
            continue
        passed = []
        for name, fn in m["tests"]:
            try:
                if fn(f):
                    passed.append(name)
            except Exception:
                pass
        if len(passed) < min_pass:
            continue
        rows.append({
            "ticker": tk, "name": str(f.get("shortName") or "")[:22],
            "sector": str(f.get("sector") or "")[:14],
            "score": len(passed), "of": n_tests, "passed": passed,
            "failed": [n for n, _ in m["tests"] if n not in passed],
            "pe": _sc_num(f.get("trailingPE")), "pb": _sc_num(f.get("priceToBook")),
            "roe": _sc_num(f.get("returnOnEquity")), "de": _sc_num(f.get("debtToEquity")),
            "gm": _sc_num(f.get("grossMargins")), "mcap": _sc_num(f.get("marketCap")),
        })
    rows.sort(key=lambda r: (-r["score"], r["pe"] if r["pe"] else 9e9))
    return rows[:top]


def _screen_universe(conn, limit=300):
    """Liquid, optionable names we already track — biggest by market cap first."""
    try:
        rows = [r[0] for r in conn.execute(
            "SELECT ticker FROM daily_fundamentals WHERE market_cap IS NOT NULL "
            "ORDER BY market_cap DESC LIMIT ?", (limit,))]
        if rows:
            return rows
    except Exception:
        pass
    return list(_hiprob_default_tickers())


def _fmt_screen(rows, model):
    m = _SCREEN_MODELS.get(str(model).lower(), {})
    if not rows:
        return (f"{hdr('MASTER SCREEN')}\nNo names cleared the {model} bar. "
                "That is a normal outcome — these are demanding checklists.")
    parts = [hdr(f"🎓 {m.get('label', model).upper()}"), f"<i>{m.get('note','')}</i>", ""]
    tbl = [(r["ticker"][:6], f"{r['score']}/{r['of']}",
            f"{r['pe']:.0f}" if r["pe"] else "-",
            f"{r['roe']*100:.0f}%" if r["roe"] is not None else "-",
            f"{r['de']:.0f}" if r["de"] is not None else "-") for r in rows]
    parts.append(_pipe_table(("Ticker", "Score", "P/E", "ROE", "D/E"), tbl,
                             right_cols={1, 2, 3, 4}))
    for r in rows[:6]:
        miss = ("misses: " + ", ".join(r["failed"][:2])) if r["failed"] else "clears every test"
        parts.append(f"<b>{r['ticker']}</b> {r['name']} · {r['sector']} — "
                     f"{r['score']}/{r['of']} · {miss}")
    parts.append("")
    parts.append("<i>⚠️ NOT BACKTESTED and not backtestable here: a real test needs "
                 "point-in-time fundamentals, and scoring past prices with today's numbers "
                 "is look-ahead bias. This is a research filter for further reading, not a "
                 "validated signal. Fundamentals are quarterly and cached 7 days.</i>")
    return "\n".join(parts)


async def screen_command(update, ctx):
    """/screen graham|fisher|munger [N] — master-investor fundamental screens."""
    arg = (ctx.args[0].lower() if ctx.args else "graham")
    if arg not in _SCREEN_MODELS:
        await update.message.reply_text(
            "Usage: <code>/screen graham</code> · <code>/screen fisher</code> · "
            "<code>/screen munger</code>\n\n"
            + "\n".join(f"<b>{k}</b> — {v['label']}" for k, v in _SCREEN_MODELS.items()),
            parse_mode=H)
        return
    top = 15
    if len(ctx.args) > 1 and str(ctx.args[1]).isdigit():
        top = max(3, min(30, int(ctx.args[1])))
    msg = await update.message.reply_text(
        f"🎓 Screening for <b>{_SCREEN_MODELS[arg]['label']}</b>… "
        "(first run downloads fundamentals, then it is cached)", parse_mode=H)
    conn = get_conn()
    try:
        rows = _screen_masters(conn, arg, top=top)
        txt = _fmt_screen(rows, arg)
    finally:
        conn.close()
    try:
        await msg.delete()
    except Exception:
        pass
    for _part in _chunk_on_sections(txt):
        await update.message.reply_text(_part, parse_mode=H)


def _fmt_gex_report(g, tk, spot, pos=None):
    if not g or not g.get("total_gex"):
        return f"📐 <b>{tk} GEX</b>: no options data in DB for this ticker."
    reg = g.get("gex_signal", "?")
    flip = g.get("zero_gamma"); cw = g.get("call_wall"); pw = g.get("put_wall")
    gm = g.get("total_gex_m", 0.0)
    lines = [f"📐 <b>{tk} GAMMA / GEX</b>  spot ${spot:.2f}",
             f"Regime: <b>{reg}</b>  · exp {g.get('expiry','?')} ({g.get('dte','?')}d)",
             f"Total GEX: {gm:+.1f}M"]
    wl = []
    if pw:   wl.append(("🟩", "Put wall (supp)", f"${pw:.0f}"))
    if flip: wl.append(("⚖️", "Gamma flip", f"${flip:.0f}"))
    if cw:   wl.append(("🟥", "Call wall (res)", f"${cw:.0f}"))
    if wl:
        lines.append(_pipe_table(("ST", "Level", "Px"), wl, right_cols={2}))
    if reg == "TRENDING":
        lines.append("⚡ <b>Negative gamma:</b> dealers amplify moves — expect bigger swings/trends. "
                     "Favors LONG options & breakouts; risky to sell premium.")
    elif reg == "PINNING":
        lines.append("🧲 <b>Positive gamma:</b> dealers dampen moves — range-bound/pinned. "
                     "Favors selling premium (iron condor / credit spreads) near the walls.")
    if flip and spot:
        lines.append(f"Spot is <b>{'above' if spot >= flip else 'below'}</b> the flip "
                     + ("→ stabilising bias." if spot >= flip else "→ volatile / trend bias."))
    if pos is not None and not pos.empty:
        dte = g.get("dte")
        lines.append("<b>Your legs vs gamma — suggested actions:</b>")
        for _, p in pos.iterrows():
            ot = str(p["option_type"]).upper()[:1]
            k = float(p["strike"] or 0)
            q = int(p.get("quantity", 1) or 1)
            side = "short" if q < 0 else "long"
            ref = cw if ot == "C" else pw
            loc = ((("above" if k >= ref else "below") + f" {'call' if ot=='C' else 'put'} wall ${ref:.0f}")
                   if ref else "no wall nearby")
            acts = []
            if ot == "C" and side == "short":
                acts.append("low assignment risk — let theta work, take ~50% profit" if (cw and k >= cw)
                            else (f"capped near wall — watch for breakout, roll up if spot clears ${cw:.0f}" if cw
                                  else "watch upside"))
                if reg == "TRENDING":
                    acts.append("neg-gamma can spike through; a cheap long-call hedge caps risk")
            elif ot == "C" and side == "long":
                acts.append("trend tailwind above flip — hold/trail" if (reg == "TRENDING" and flip and spot >= flip)
                            else ("pinning caps upside — take profit or roll out" if reg == "PINNING"
                                  else "hold vs call wall"))
            elif ot == "P" and side == "long":
                acts.append("spot at/below put wall — hedge paying, monetize part" if (pw and spot <= pw)
                            else (f"protection intact; support at put wall ${pw:.0f}" if pw else "protection intact"))
            elif ot == "P" and side == "short":
                acts.append("below flip — downside risk, roll down or close" if (reg == "TRENDING" and flip and spot < flip)
                            else ("lower assignment risk — hold" if (pw and k <= pw) else "monitor downside"))
            if isinstance(dte, (int, float)) and dte <= 21:
                acts.append(f"{int(dte)}DTE — gamma rising, manage per 21-DTE rule")
            lines.append(f"• {side} {ot} ${k:.0f} ({loc})")
            lines.append(f"   ↳ {'; '.join(acts) if acts else 'hold & monitor'}")
        ov = []
        if reg == "TRENDING":
            ov.append("neg-gamma regime → bigger swings; favor defined-risk longs, avoid naked shorts")
        elif reg == "PINNING":
            ov.append("pos-gamma regime → range/pin; premium-selling near walls favored")
        if flip and spot:
            ov.append(("spot above flip" if spot >= flip else "spot below flip") + f" ${flip:.0f}")
        if ov:
            lines.append("📋 <b>Overall:</b> " + "; ".join(ov) + ".")
    return "\n".join(lines)

def _kb_gex():
    return InlineKeyboardMarkup([
        [InlineKeyboardButton("🔄 Refresh", callback_data="gex_refresh"),
         InlineKeyboardButton("📌 Bookmark", callback_data="bm|gex|positions")]])

def _fmt_squeeze_inline(sq):
    """One-line short-interest / days-to-cover / covering tag for position views."""
    if not sq or sq.get("short_pct") is None:
        return "Short interest: n/a (no float data)"
    parts = [f"Short {sq['short_pct']:.0f}% float"]
    if sq.get("dtc"):
        parts.append(f"DTC {sq['dtc']:.1f}")
    if sq.get("si_chg_pct") is not None:
        parts.append(f"SI {sq['si_chg_pct']:+.0f}% MoM")
    tag = f"{sq.get('emoji','')} squeeze {sq.get('score',0)}/5 {sq.get('stage','')}"
    rec = ""
    if sq.get("score", 0) >= 3:
        rec = " - covering/squeeze risk: bullish, trim shorts"
    elif sq.get("si_chg_pct") is not None and sq["si_chg_pct"] < -5:
        rec = " - shorts already covering"
    return "🩳 <b>" + " . ".join(parts) + "</b>  [" + tag + "]" + rec


def _exp_iso(s):
    """Normalize any expiry string to ISO YYYY-MM-DD (the DB standard), or None.
    (Renamed from _to_mdy — it has returned ISO since the 07-14 migration.)"""
    for f in ("%Y-%m-%d", "%m/%d/%Y", "%m-%d-%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(str(s)[:10], f).strftime("%Y-%m-%d")
        except ValueError:
            continue
    return None


def _gex_reports(conn, tickers=None, position_aware=True):
    out = []
    tks = list(tickers) if tickers else []
    if not tks:
        try:
            _pf = pd.read_sql("SELECT DISTINCT ticker FROM trades WHERE status='OPEN'", conn)
            tks = [str(t).upper() for t in _pf["ticker"].tolist()] if not _pf.empty else []
        except Exception:
            tks = []
        if not tks:
            tks = ["SPY"]
    for tk in tks[:6]:
        spot = _gex_spot(conn, tk)
        pos = None
        if position_aware:
            try:
                pos = pd.read_sql(
                    "SELECT option_type, strike, quantity, expiry FROM trades"
                    " WHERE status='OPEN' AND UPPER(option_type)<>'STOCK' AND ticker=?", conn, params=(tk.upper(),))
            except Exception:
                pos = None
        exps = [None]
        if pos is not None and not pos.empty:
            _e = []
            for ev in sorted(pos["expiry"].dropna().astype(str).unique()):
                m = _exp_iso(ev)
                if m and m not in _e:
                    _e.append(m)
            if _e:
                exps = _e
        for exp in exps:
            g = _compute_gex(tk, conn, spot, expiry=exp)
            legs = pos
            if pos is not None and not pos.empty and exp is not None:
                legs = pos[pos["expiry"].astype(str).apply(lambda x: _exp_iso(x) == exp)]
            rep = _fmt_gex_report(g, tk, spot, legs)
            try:
                rep += chr(10) + _fmt_squeeze_inline(short_squeeze_signal(tk, conn))
            except Exception:
                pass
            try:
                _vc = _compute_vanna_charm(tk, conn, spot, want_exp=exp)
                if _vc.get("vex"):
                    rep += chr(10) + "🌀 Vanna " + ("+" if _vc["vex"] > 0 else "") + f"{_vc['vex']/1e6:.1f}M — " + _vc["note"]
            except Exception:
                pass
            out.append(rep)
    return out

async def gex_command(update, ctx):
    """/gex [TICKERS] - gamma walls/flip/regime + position-aware notes. No arg = open positions."""
    args = list(getattr(ctx, "args", []) or [])
    conn = get_conn()
    try:
        if args:
            tks = [a.upper() for a in args]
        else:
            try:
                df = pd.read_sql("SELECT DISTINCT ticker FROM trades WHERE status='OPEN'", conn)
                tks = [str(t).upper() for t in df["ticker"].tolist()] if not df.empty else []
            except Exception:
                tks = []
            if not tks:
                tks = ["SPY"]
        msgs = _gex_reports(conn, tks)
    finally:
        conn.close()
    await update.message.reply_text("\n\n".join(msgs) if msgs else "No GEX data.",
                                    parse_mode=H, reply_markup=_kb_gex())

async def gex_view(query):
    conn = get_conn()
    try:
        try:
            df = pd.read_sql("SELECT DISTINCT ticker FROM trades WHERE status='OPEN'", conn)
            tks = [str(t).upper() for t in df["ticker"].tolist()] if not df.empty else ["SPY"]
        except Exception:
            tks = ["SPY"]
        msgs = _gex_reports(conn, tks)
    finally:
        conn.close()
    await query.message.reply_text("\n\n".join(msgs) if msgs else "No GEX data.",
                                   parse_mode=H, reply_markup=_kb_gex())


