# ── Dedicated Vanna / Charm view ──
def _fmt_vanna_report(ticker, conn, spot):
    vc = _compute_vanna_charm(ticker, conn, spot)
    if not vc or not vc.get("vex"):
        return f"🌀 <b>{ticker} VANNA/CHARM</b>: no options data in DB."
    lines = [f"🌀 <b>{ticker} VANNA / CHARM</b>  spot ${spot:.2f}", ""]

    # ── plain English first. These two greeks describe what DEALERS are forced to do,
    # which is why they read as a background current rather than a signal.
    # Plain-language first. The greek names mean nothing to most readers, and the previous
    # one-liner still assumed you knew what "hedging current" meant (user 2026-08-03).
    _chm_now = vc.get("charm", 0.0) or 0.0
    _vex_now = vc.get("vex", 0.0) or 0.0
    lines.append("<b>In plain English</b>")
    lines.append("• Market makers sold you these options. To stay neutral they must keep "
                 "buying and selling the stock. That forced buying/selling is a CURRENT "
                 "under the price.")
    lines.append("• <b>Charm</b> = the current caused by TIME passing. Every day that ticks "
                 "by, they must adjust — and it gets stronger as expiry nears.")
    lines.append(f"   → right now that current pushes <b>{'UP' if _chm_now > 0 else 'DOWN'}</b>.")
    lines.append("• <b>Vanna</b> = the current caused by FEAR moving. When volatility "
                 "falls (calm), they must trade one way; when it spikes, the other.")
    lines.append(f"   → right now, if things get calmer they must "
                 f"<b>{'BUY' if _vex_now > 0 else 'SELL'}</b>.")
    lines.append("• <b>It is a tide, not a forecast.</b> It says which way the water is "
                 "moving. You can still swim against it — it is just harder.")
    lines.append("")

    # ── per-expiry table: the single-expiry view hid where the pressure actually sits ──
    try:
        _ld = pd.read_sql("SELECT trade_date_now FROM options_change WHERE ticker=? "
                          "ORDER BY trade_date_now DESC LIMIT 1", conn, params=(ticker,))
        _ds = _ld["trade_date_now"].iloc[0] if not _ld.empty else None
        _ref = datetime.strptime(_ds, "%Y-%m-%d").date() if _ds else None
        _ex = pd.read_sql("SELECT expiry_date, SUM(openInt_Call_now)+SUM(openInt_Put_now) oi "
                          "FROM options_change WHERE ticker=? AND trade_date_now=? "
                          "GROUP BY expiry_date", conn, params=(ticker, _ds)) if _ds else None
    except Exception:
        _ref = None; _ex = None

    _rows = []
    if _ref is not None and _ex is not None and not _ex.empty:
        # DTE must be measured from TODAY, not from the capture date. Off by even two days
        # this showed an already-EXPIRED contract as "0d / strong pull" (2026-08-03).
        _today = _et_now().date()
        _cands = []
        for _, e in _ex.iterrows():
            ed = _opex_parse_date(e["expiry_date"])
            if not ed:
                continue
            d = (ed - _today).days
            if 0 <= d <= 90:
                _cands.append((d, float(e["oi"] or 0), str(e["expiry_date"])))
        _cands.sort(key=lambda c: c[0])
        _pick = _cands[:5]
        # always include the next monthly OpEx, even when five weeklies come first --
        # it is where the open interest and therefore the hedging pressure actually sits
        _opx = next((c for c in _cands
                     if _opex_parse_date(c[2]) and _is_opex_date(_opex_parse_date(c[2]))), None)
        if _opx and _opx not in _pick:
            _pick = _pick[:4] + [_opx]
        for d, _oi, exp in _pick:
            v = _compute_vanna_charm(ticker, conn, spot, want_exp=exp)
            if not v:
                continue
            _vex, _chm = v.get("vex", 0.0) or 0.0, v.get("charm", 0.0) or 0.0
            # Charm is a decay effect: it barely matters at 60 DTE and dominates in the
            # last week, so weight the READ by how close expiry is.
            _bite = "strong" if d <= 7 else ("building" if d <= 21 else "weak")
            _ed = _opex_parse_date(exp)
            _tag = " OPEX" if (_ed and _is_opex_date(_ed)) else ""
            _rows.append(("🟢" if _chm > 0 else ("🔴" if _chm < 0 else "🟡"),
                          _exp_iso(exp)[5:10] + _tag, f"{d}d",
                          f"{_vex/1e6:+.1f}", f"{_chm/1e6:+.1f}", _bite))
    if _rows:
        lines.append(_pipe_table(("ST", "Expiry", "DTE", "Vanna", "Charm", "Pull"), _rows,
                                 right_cols={2, 3, 4},
                                 legend="M$ per 1pt vol / per day · Pull = how hard charm "
                                        "bites at that DTE (it accelerates into expiry)"))
        lines.append("")
    else:
        lines.append(f"<i>nearest expiry {vc.get('expiry','?')}</i>")
        lines.append(f"Vanna <b>{vc['vex']/1e6:+.1f}M</b> · Charm <b>{vc['charm']/1e6:+.1f}M</b>")
        lines.append("")

    _v, _c = vc["vex"], vc["charm"]
    lines.append("🌀 <b>Vanna:</b> " + vc["note"])
    lines.append("⏳ <b>Charm:</b> " + ("positive — dealer hedging adds upward drift into expiry "
                                        "(the OpEx melt-up)."
                                        if _c > 0 else
                                        "negative — charm flow leans on the downside into expiry."))
    lines.append("")

    # ── what to actually do with it, split by how far out you are trading ──
    _near = [r for r in _rows if r[2].rstrip("d").isdigit() and int(r[2].rstrip("d")) <= 7]
    _ideas = ["<b>▶ HOW TO TRADE IT</b>"]
    if _c > 0:
        _ideas.append("• <b>Charm +</b> → the drift into expiry is UP. Short puts / put credit "
                      "spreads expiring on that date trade WITH the current. Fading the rally "
                      "with short calls trades against it.")
    else:
        _ideas.append("• <b>Charm −</b> → the drift into expiry is DOWN. Be wary of short puts "
                      "at that expiry; put debit spreads or call credit spreads sit with the "
                      "current instead.")
    if _v > 0:
        _ideas.append("• <b>Vanna +</b> → if VOL FALLS, dealers must BUY. A calm tape is a "
                      "tailwind, so long calls / call spreads get a second engine when VIX "
                      "drops. A vol SPIKE reverses it into selling.")
    else:
        _ideas.append("• <b>Vanna −</b> → a vol drop makes dealers SELL. Rallies into falling "
                      "vol lack that support; do not lean on a melt-up here.")
    if _near:
        _ideas.append("• <b>0–7 DTE</b> is where charm bites hardest — that expiry's pin is the "
                      "dominant force this week. Weeklies at that strike are a pin play, not a "
                      "direction play.")
    else:
        _ideas.append("• <b>Nothing inside 7 DTE</b> — charm is weak right now, so this is "
                      "background, not a reason to trade today. Revisit in OpEx week.")
    _ideas.append("• <b>Size for the current, not on it</b>: these flows explain WHY a tape "
                  "grinds or slips, they do not tell you it will.")
    lines.append("\n".join(_ideas))

    # ── YOUR BOOK: does this hedging current run with or against what is actually open? ──
    try:
        _pos = pd.read_sql(
            "SELECT strike, option_type, expiry, quantity FROM trades "
            "WHERE status='OPEN' AND ticker=?", conn, params=(ticker.upper(),))
    except Exception:
        _pos = None
    if _pos is not None and not _pos.empty:
        _pl = [f"<b>▶ YOUR {ticker} POSITIONS vs THIS FLOW</b>"]
        _tdy = _et_now().date()
        _bad = _ok = 0
        for _, q in _pos.iterrows():
            _typ = str(q.get("option_type") or "").lower()
            if _typ == "stock":
                _pl.append(f"⚪ <b>STOCK</b> {int(float(q.get('quantity') or 0))} sh — charm and "
                           f"vanna do not act on shares, but they move the underlying you hold.")
                continue
            _K = float(q.get("strike") or 0)
            _exp = _exp_iso(str(q.get("expiry") or ""))
            _qty = float(q.get("quantity") or 0)
            _short = _qty < 0
            try:
                _dd = (datetime.strptime(_exp, "%Y-%m-%d").date() - _tdy).days
            except Exception:
                _dd = None
            _wants_up = (_typ == "call" and not _short) or (_typ == "put" and _short)
            _with = (_c > 0) == _wants_up
            _ok += _with; _bad += (not _with)
            _urg = ("bites hardest NOW" if (_dd is not None and _dd <= 7)
                    else ("building" if (_dd is not None and _dd <= 21) else "still weak"))
            _pl.append(f"{'🟢' if _with else '🔴'} <b>{'SHORT' if _short else 'LONG'} "
                       f"{_K:g}{_typ[:1].upper()}</b> {_exp} ({_dd}d) — charm runs "
                       f"<b>{'WITH' if _with else 'AGAINST'}</b> this leg, {_urg}")
        if _bad or _ok:
            if _bad > _ok:
                _pl.append(f"<b>Assessment:</b> {_bad} of {_bad + _ok} option legs sit AGAINST the "
                           f"charm drift — a headwind on top of your directional thesis. Not a "
                           f"reason to close, but size and stops should assume the current pushes "
                           f"the other way into expiry.")
            elif _ok > _bad:
                _pl.append(f"<b>Assessment:</b> {_ok} of {_bad + _ok} legs run WITH the drift. The "
                           f"flow is helping — do not mistake that tailwind for the thesis being right.")
            else:
                _pl.append("<b>Assessment:</b> the book is balanced against this flow; charm is "
                           "not the deciding factor here.")
        lines.append("\n".join(_pl))
        lines.append("")
    lines.append("")
    lines.append("<i>⚠️ Structural read, NOT a validated signal. Computed from EOD open "
                 "interest with a modelled IV — dealer positioning is inferred, not observed. "
                 "No backtest supports trading these numbers on their own.</i>")
    return "\n".join(lines)

