def _earnvol_scan(conn, tickers, within_days=EARNVOL_WITHIN_DAYS):
    """Rank names reporting within `within_days` by an IV-crush score
    (rich IV rank + fat implied move = better short-premium candidate)."""
    out = []
    for tk in tickers:
        tk = str(tk).upper()
        ne = _next_earnings(tk)            # cached (2h) yfinance next-earnings
        dte_e = ne.get("days") if ne else None
        if dte_e is None or dte_e > within_days:
            continue
        try:
            sp = pd.read_sql(
                "SELECT close FROM stock_daily WHERE ticker=?"
                " ORDER BY trade_date DESC LIMIT 1", conn, params=(tk,))
            spot = float(sp["close"].iloc[0]) if not sp.empty else 0.0
        except Exception:
            spot = 0.0
        em_pct, straddle, dte = _earnvol_em(conn, tk, spot)
        ivr_res = _iv_rank(conn, tk)       # DB-based {iv, rank}; no network
        ivr = ivr_res.get("rank") if ivr_res else None
        if ivr is None and em_pct is None:
            continue
        # IV-crush score: weight IV-rank richness + implied move size.
        crush = 0.6 * (ivr or 0) + 0.4 * min((em_pct or 0) * 4, 100)
        if (ivr or 0) >= 60:
            play, emoji = "SELL vol · IC/strangle", "🔴"
        elif (ivr if ivr is not None else 100) <= 30:
            play, emoji = "BUY straddle · cheap", "🟢"
        else:
            play, emoji = "Wait · mid IV", "🟡"
        out.append({
            "ticker": tk, "dte_e": dte_e, "ed_date": (ne.get("date") if ne else None),
            "ivr": ivr, "em_pct": em_pct,
            "straddle": straddle, "spot": round(spot, 2),
            "play": play, "emoji": emoji, "crush": crush,
        })
    out.sort(key=lambda r: r["crush"], reverse=True)
    return out


def _earnvol_table(rows):
    """Render the earnings-vol scan as a uniform _pipe_table."""
    _hdrs = ("ST", "Tkr", "ED", "IVR", "EM%")
    _data = []
    for r in rows:
        ivr_s = f"{r['ivr']:.0f}" if r["ivr"] is not None else "--"
        em_s  = f"{r['em_pct']:.1f}" if r["em_pct"] is not None else "--"
        _data.append((r["emoji"], r["ticker"], f"{r['dte_e']}d", ivr_s, em_s))
    # Headers stay short because Telegram <pre> is capped at 28 display cells; the fix for
    # "I don't understand the headers" is a real key, not wider columns (user 2026-08-08).
    return _pipe_table(_hdrs, _data, right_cols={2, 3, 4},
                       legend=("<b>ED</b> = trading days until it reports · "
                               "<b>IVR</b> = IV Rank 0-100, how expensive this stock's options "
                               "are versus its OWN past year (69 = pricier than 69% of the "
                               "year) · <b>EM%</b> = the move the options are pricing for the "
                               "report itself\n"
                               "🔴 IV rich — the market is paying up for this event, so "
                               "SELLING premium is the favoured side · 🟢 IV cheap — buying "
                               "it is\n"
                               "Why it matters: IV almost always collapses the morning "
                               "after a report (the 'crush'), so a short-premium trade can win "
                               "on vol even if the stock barely moves. The risk is the "
                               "opposite tail — if the stock moves MORE than EM%, the crush "
                               "will not save you. Treat EM% as your break-even, not a "
                               "forecast."))


async def earnvol_command(update, ctx: ContextTypes.DEFAULT_TYPE):
    """/earnvol [TICKERS…] — pre-earnings IV-crush scanner. Ranks names
    reporting soon by IV-rank + expected move (short-premium vs long-vol)."""
    args = list(getattr(ctx, "args", []) or [])
    tickers = [a.upper() for a in args] if args else EARNVOL_UNIVERSE
    within = EARNVOL_WITHIN_DAYS if not args else 60  # explicit tickers: wider window
    msg = await update.message.reply_text("📅 Scanning earnings vol…", parse_mode=H)
    conn = get_conn()
    try:
        rows = _earnvol_scan(conn, tickers, within_days=within)
    except Exception as e:
        await msg.edit_text(f"⚠️ earnvol scan failed: {e}")
        conn.close(); return
    finally:
        conn.close()
    if not rows:
        await msg.edit_text(
            f"📅 <b>EARNINGS VOL</b>\nNo earnings within {within}d for the scanned set.",
            parse_mode=H)
        return
    parts = [hdr("📅 EARNINGS VOL — IV crush"), _earnvol_table(rows[:15]),
             "<i>High IVR → sell premium (crush after report). "
             "Low IVR → buy straddle. Non-directional; size for a gap.</i>"]
    await msg.edit_text("\n".join(parts), parse_mode=H)


# ── WAN-STREAMER ─────────────────────────────────────────────────
# "Wide-Area Network" signal streamer: continuously polls the 24-model
# ensemble across the watchlist and streams each newly-fired actionable
# signal to Telegram. Deduped per calendar day via alert_dedup so each
# distinct TICKER|SIGNAL|CONF fires at most once/day (survives restarts).
WAN_STREAM_TICKERS = DEFAULT_TICKERS          # compact watchlist (engine reads DB only)
WAN_MIN_PROB       = 70.0                     # don't stream low-conviction noise
WAN_OK_CONF        = ("HIGH", "MEDIUM")       # confidence gate


def _wan_scan(conn, spy_ret=0.0):
    """Run the ensemble across WAN_STREAM_TICKERS; return actionable signals
    (BULL/BEAR, conf in WAN_OK_CONF, prob >= WAN_MIN_PROB) sorted by prob desc.
    Pure read of the DB — no network. Shared by the streamer job and /wan."""
    out = []
    for tk in WAN_STREAM_TICKERS:
        try:
            r = high_prob_signals_engine(tk, conn, spy_ret)
        except Exception:
            log.debug("wan scan failed for %s", tk, exc_info=True)
            continue
        if (r.get("signal") in ("BULL", "BEAR")
                and r.get("conf") in WAN_OK_CONF
                and float(r.get("prob", 0)) >= WAN_MIN_PROB):
            out.append(r)
    out.sort(key=lambda r: float(r.get("prob", 0)), reverse=True)
    return out


def _wan_spy_ret(conn):
    """SPY 1-day return (%) for the ensemble market overlay; 0.0 on failure."""
    try:
        spy = pd.read_sql(
            "SELECT close FROM stock_daily WHERE ticker='SPY'"
            " ORDER BY trade_date DESC LIMIT 2", conn)
        if len(spy) >= 2:
            return (float(spy["close"].iloc[0]) / float(spy["close"].iloc[1]) - 1) * 100
    except Exception:
        log.debug("wan spy_ret failed", exc_info=True)
    return 0.0


# Shared snapshot cache — written by the streamer job / /wan, read by AI chat.
_WAN_SNAPSHOT = {"ts": None, "signals": []}


def _wan_get_snapshot(conn, spy_ret=0.0, max_age_sec=900):
    """Return the cached actionable-signal snapshot, recomputing if stale/empty.
    Keeps AI chat instant on warm cache; the streamer refreshes it every 15 min."""
    now = datetime.now(timezone.utc).replace(tzinfo=None)
    ts = _WAN_SNAPSHOT["ts"]
    if ts is not None and (now - ts).total_seconds() < max_age_sec:
        return _WAN_SNAPSHOT["signals"]
    sigs = _wan_scan(conn, spy_ret)
    _WAN_SNAPSHOT["ts"] = now
    _WAN_SNAPSHOT["signals"] = sigs
    return sigs


def _wan_ai_context(signals):
    """Compact text summary of live signals for the AI chat system prompt,
    incl. which models agree so the assistant can explain *why*.

    r['spot'] comes straight from high_prob_signals_engine, which is memoised per
    (ticker, latest trade_date) and reads stock_daily's close -- i.e. it is the LAST EOD
    CLOSE, not a live quote, by design (recomputing the 24-model ensemble on every chat
    turn would be pure waste). Labeled explicitly below so the assistant doesn't state it
    as a current price (verified bug 2026-07-24: engine spot can be visibly stale
    intraday, e.g. showing yesterday's close while the stock has since moved several %)."""
    if not signals:
        return "WAN-streamer: no actionable ensemble signals right now."
    lines = ["Live WAN-streamer ensemble signals (the bot's current actionable setups). "
             "NOTE: 'spot' below is the last EOD close used by the signal engine, NOT a "
             "live quote -- if asked for current price, say so and use a live source instead."]
    for r in signals:
        models = r.get("models", {}) or {}
        agree = [n for n, m in models.items() if m.get("signal") == r["signal"]]
        lines.append(
            f"- {r['ticker']}: {r['signal']} ({r['conf']} conf), prob {float(r['prob']):.0f}%, "
            f"EOD close ${r['spot']} (engine input, not live). Strategy: {str(r.get('strategy',''))[:90]}. "
            f"Bull votes {r.get('bull_v','?')}/{r.get('total_m','?')}, bear {r.get('bear_v','?')}. "
            f"Models agreeing: {', '.join(agree[:8]) if agree else 'n/a'}.")
    return "\n".join(lines)


def _wan_table(rows):
    """Render actionable signals as a uniform _pipe_table. Emoji in col 0."""
    _hdrs = ("ST", "Tkr", "Dir", "Cf", "Pr%")
    _data = []
    for r in rows:
        emoji = "🟢" if r["signal"] == "BULL" else "🔴"
        cf    = "H" if r["conf"] == "HIGH" else "M"
        _data.append((emoji, r["ticker"], r["signal"], cf, f"{float(r['prob']):.0f}"))
    return _pipe_table(_hdrs, _data, right_cols={4},
                       legend="🟢 bull · 🔴 bear · Cf H=high/M=med")


_AI_RISK_CACHE = {}


def _ai_risk_check(conn, sig):
    """Debate-gate (TradingAgents-style, ONE cheap call): bull case vs bear case built ONLY
    from our DB evidence + the ensemble's own votes, then a PROCEED/CAUTION verdict.
    The LLM is the reviewer, never the signal source. Fail-soft: any problem -> None and
    the alert goes out unchanged. Cached per ticker|side|day so repeats cost nothing."""
    tk = str(sig["ticker"]).upper(); side = sig["signal"]
    key = f"{tk}|{side}|{datetime.now(timezone.utc).strftime('%Y-%m-%d')}"
    if key in _AI_RISK_CACHE:
        return _AI_RISK_CACHE[key]
    api_key = _load_ai_key()
    if not api_key:
        return None
    try:
        oi = pd.read_sql(
            "SELECT SUM(change_OI_Call) cc, SUM(change_OI_Put) cp FROM options_change "
            "WHERE ticker=? AND trade_date_now=(SELECT MAX(trade_date_now) FROM options_change)",
            conn, params=(tk,))
        sd = pd.read_sql(
            "SELECT close, pcr_oi FROM stock_daily WHERE ticker=? "
            "ORDER BY trade_date DESC LIMIT 6",
            conn, params=(tk,))
        ev = [f"Ensemble: {side} conf {sig.get('conf')} prob {float(sig.get('prob', 0)):.0f}% "
              f"(bull votes {sig.get('bull_v', '?')}/{sig.get('total_m', '?')}, bear {sig.get('bear_v', '?')})",
              f"Suggested strategy: {str(sig.get('strategy', ''))[:80]}"]
        if len(oi) and oi.iloc[0]["cc"] is not None:
            ev.append(f"Today's OI delta: calls {oi.iloc[0]['cc']:+,.0f}, puts {oi.iloc[0]['cp']:+,.0f}")
        if len(sd):
            px = pd.to_numeric(sd["close"], errors="coerce")
            if len(px) >= 6 and px.iloc[5]:
                ev.append(f"5-day price change: {(px.iloc[0] / px.iloc[5] - 1) * 100:+.1f}%")
            _pcr = sd.iloc[0]["pcr_oi"]
            if _pcr is not None and not pd.isna(_pcr):
                ev.append(f"PCR(OI): {float(_pcr):.2f}")
        # Free no-training lane first (ID 275) — this prompt carries signal/position context.
        out, _who = _llm_ask(
            f"Signal on {tk} ({side}).\n" + "\n".join(ev), max_tokens=160,
            system=("You are the risk manager reviewing a quant signal before it is traded. "
                    "Using ONLY the evidence given (never invent numbers), reply in EXACTLY 3 lines:\n"
                    "BULL: <strongest bullish point, <=15 words>\n"
                    "BEAR: <strongest bearish point, <=15 words>\n"
                    "VERDICT: PROCEED or CAUTION - <reason, <=12 words>"))
        out = (out or "").strip()
        if "VERDICT:" not in out.upper():
            return None
        out = (out.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                  .replace("VERDICT: PROCEED", "✅ PROCEED").replace("VERDICT: CAUTION", "⚠️ CAUTION"))
        _AI_RISK_CACHE[key] = out
        if len(_AI_RISK_CACHE) > 400:
            _AI_RISK_CACHE.clear()
        return out
    except Exception:
        log.debug("ai risk-check failed", exc_info=True)
        return None


async def wan_streamer_alert(ctx: ContextTypes.DEFAULT_TYPE):
    """Streamer job: push newly-fired actionable ensemble signals to Telegram.
    Market-hours / weekday gated. One alert per TICKER|SIGNAL|CONF per day."""
    now_utc = datetime.now(timezone.utc).replace(tzinfo=None)
    if now_utc.weekday() >= 5:
        return
    hour_min = now_utc.hour * 60 + now_utc.minute
    if not (14 * 60 + 30 <= hour_min <= 21 * 60):
        return

    _, chat_id = load_creds()
    conn = get_conn()
    try:
        _ensure_alert_dedup_table(conn)
        spy_ret = _wan_spy_ret(conn)
        # Force a fresh scan and refresh the shared cache for AI chat.
        _WAN_SNAPSHOT["ts"] = None
        signals = _wan_get_snapshot(conn, spy_ret)
        today_str = _et_now().date().isoformat()   # DST-aware ET date
        fresh = [r for r in signals
                 if not _alert_already_sent(
                     conn, today_str, f"{r['ticker']}|{r['signal']}|{r['conf']}", "wan_stream")]
        # 🤖 debate-gate: AI second opinion on the top fresh signals (cap 3 = cost control;
        # cached per ticker/side/day; fail-soft so alerts never depend on the API)
        risk_notes = []
        for r in fresh[:3]:
            v = _ai_risk_check(conn, r)
            if v:
                emoji = "🟢" if r["signal"] == "BULL" else "🔴"
                risk_notes.append(f"{emoji} <b>{r['ticker']}</b>\n<i>{v}</i>")
    except Exception as e:
        log.warning(f"wan_streamer scan failed: {e}")
        conn.close(); return
    finally:
        conn.close()

    if not fresh:
        return

    now_et = _et_now().replace(tzinfo=None)   # DST-aware (was fixed UTC-5)
    parts = [hdr(f"📡 WAN-STREAMER · {now_et.strftime('%H:%M ET')}"),
             f"<i>{len(fresh)} new signal(s)</i>",
             _wan_table(fresh)]
    if risk_notes:
        parts.append("🤖 <b>AI risk-check</b> <i>(reviewer, not signal)</i>\n" + "\n".join(risk_notes))
    try:
        await ctx.bot.send_message(chat_id=int(chat_id), text="\n".join(parts), parse_mode=H)
    except Exception as e:
        log.warning(f"wan_streamer send failed: {e}")


async def wan_command(update, ctx: ContextTypes.DEFAULT_TYPE):
    """/wan — on-demand snapshot of the current actionable signal stream
    (ignores dedup; shows everything live)."""
    msg = await update.message.reply_text("📡 Scanning watchlist…", parse_mode=H)
    conn = get_conn()
    try:
        _WAN_SNAPSHOT["ts"] = None  # force fresh + refresh cache for AI chat
        signals = _wan_get_snapshot(conn, _wan_spy_ret(conn))
    except Exception as e:
        await msg.edit_text(f"⚠️ WAN scan failed: {e}")
        conn.close(); return
    finally:
        conn.close()

    if not signals:
        await msg.edit_text("📡 <b>WAN-STREAMER</b>\nNo actionable signals right now.", parse_mode=H)
        return
    parts = [hdr("📡 WAN-STREAMER · live"), _wan_table(signals)]
    await msg.edit_text("\n".join(parts), parse_mode=H)


